data EnvBinding = EnvBinding
  { ebSchemeInfo :: SchemeInfo,
    ebSchemeType :: ElabType,
    ebIdentityDetails :: IdDetails,
    ebRuntimeName :: VarName,
    ebTransparentMediator :: Maybe TransparentMediatorKind,
    ebAliasTarget :: Maybe BindingKey,
    ebExplicitRecursiveParam :: Bool
  }

data TransparentMediatorKind
  = DirectIdentityMediator
  | EtaTransparentMediator !Int
  deriving (Eq)

-- | A source-proven application that reaches its result through a transparent
-- eta mediator.  The two endpoints stay together because the same proof fixes
-- both sides of Figure 15.3.5: the argument topology used by the two child
-- computations and the result bound consumed by the enclosing Gamma.
data MediatedApplicationConstruction = MediatedApplicationConstruction
  { macArgumentType :: !ElabType,
    macResultType :: !ElabType
  }

data IdentityWrapperAlias
  = IdentityWrapperRoot
  | IdentityWrapperMediator

data ConstructionGammaCoverage
  = RequiredGammaOnly
  | OwnerLocalAndRequiredGamma
  | CompleteSchemeAndRequiredGamma

-- | One owner-local Gamma construction, including both the binders emitted by
-- this boundary and exact ambient routes inherited by its requirements.
data ConstructionGammaPlan = ConstructionGammaPlan
  { cgpBinders :: ![(TypeBinderRef, Maybe BoundType)],
    cgpAmbientAliases :: !(IntMap.IntMap TypeBinderRef),
    cgpRequirementBoundRenames :: ![(TypeBinderRef, TypeBinderRef)],
    cgpValidatedLocalRequirementRefs :: ![TypeBinderRef]
  }
  deriving (Eq, Show)

-- | Graph routing produced for one construction Gamma.  Every requirement
-- needs replay aliases, but only a route backed by a binder emitted here or by
-- an exact ambient declaration is a construction capability.  Keep those maps
-- distinct so prepared substitution metadata cannot accidentally suppress a
-- source-derived application endpoint.
data ConstructionGammaAliases = ConstructionGammaAliases
  { cgaRoutingAliases :: !(IntMap.IntMap TypeBinderRef)
  , cgaAuthorityAliases :: !(IntMap.IntMap TypeBinderRef)
  }
  deriving (Eq, Show)

data ConsumerBoundOwnership
  = ConsumerBoundOwnedLocally !TypeBinderRef
  | ConsumerBoundOwnedByEnclosingGamma !TypeBinderRef !ElabType
  | ConsumerBoundEliminatedAtAmbientBound !TypeBinderRef !ElabType
  | ConsumerBoundOwnedByRootGamma !TypeBinderRef
  | ConsumerBoundOwnedByRequiredGamma !EdgeId

-- | Construction authorized by an enclosing Gamma for one packet consumer.
-- The edge carried by the packet decides which term boundary consumes that
-- authority.  When it is this lambda's body edge, the already-open ambient
-- binder authorizes the terminal @Hyp@ in the body computation.  Otherwise
-- the enclosing edge consumes the completed lambda itself.  Keeping those
-- cases distinct prevents a body endpoint from being used as an expected type
-- for the whole lambda.
data EnclosingConsumerConstruction
  = EnclosingBodyConsumerConstruction
      !EnclosingBodyConsumerCertificate
  | EnclosingCompletedLambdaConstruction
      !LocalGammaOwner
      !EdgeId
      !ElabType
  deriving (Eq, Show)

-- | Complete construction evidence for a body endpoint whose declaration is
-- owned by an enclosing lambda Gamma.  The recursively checked source may be
-- more general than the declaration bound: Figure 15.3.5 then specializes it
-- at the already-open ambient binder before the terminal Hyp.  Store that
-- computation with the exact edge/refinement authority so later elaboration
-- consumes a proved construction instead of reconstructing a binder-spine
-- guess from the two endpoint types.
data EnclosingBodyConsumerCertificate =
  EnclosingBodyConsumerCertificate
    { ebccEdgeId :: !EdgeId
    , ebccConsumerRef :: !TypeBinderRef
    , ebccCompletedBound :: !ElabType
    , ebccAmbientDependencies :: ![(TypeBinderRef, ElabType)]
    , ebccSourceSpecialization :: !Instantiation
    , ebccBoundRefinement :: !BodyConsumerBoundRefinementCertificate
    }
  deriving (Eq, Show)

-- | Positive construction evidence for a topology result whose declaration
-- remains in the enclosing Gamma.  The checked body must first construct the
-- declaration's exact bound before Figure 15.3.5 can apply the terminal Hyp.
-- Keep the owner, edge, and result identity with that computation so it cannot
-- be reused at a merely type-shaped lambda boundary.
data AmbientTopologyResultConstructionCertificate
  = AmbientTopologyResultConstructionCertificate
      { atrcOwner :: !LocalGammaOwner
      , atrcBodyEdge :: !EdgeId
      , atrcResultRef :: !TypeBinderRef
      , atrcSourceType :: !ElabType
      , atrcResultBound :: !ElabType
      , atrcInstantiation :: !Instantiation
      }
  deriving (Eq, Show)

data LambdaConsumerConstructionPlan = LambdaConsumerConstructionPlan
  { lccOwner :: !LocalGammaOwner
  , lccSourceType :: !ElabType
  , lccSchemeInfo :: !(Maybe SchemeInfo)
  , lccLocalBodyConsumerBoundRefinement
      :: !(Maybe BodyConsumerBoundRefinementCertificate)
  , lccAmbientTopologyResultConstruction
      :: !(Maybe AmbientTopologyResultConstructionCertificate)
  , lccEnclosingConsumerConstruction
      :: !(Maybe EnclosingConsumerConstruction)
  , lccEnclosingOwnedBinderRefs :: ![TypeBinderRef]
  , lccConsumerWithoutLocalBinder :: !(Maybe PacketConsumerWithoutLocalBinder)
  }

lccEnclosingBodyConsumer
  :: LambdaConsumerConstructionPlan
  -> Maybe EnclosingBodyConsumerCertificate
lccEnclosingBodyConsumer plan =
  case lccEnclosingConsumerConstruction plan of
    Just (EnclosingBodyConsumerConstruction certificate) ->
      Just certificate
    _ -> Nothing

lccExpectedCompletedLambda
  :: LambdaConsumerConstructionPlan
  -> Maybe (EdgeId, ElabType)
lccExpectedCompletedLambda plan =
  case lccEnclosingConsumerConstruction plan of
    Just
      ( EnclosingCompletedLambdaConstruction
          enclosingOwner
          edgeId
          expectedTy
        )
        | enclosingOwner == lccOwner plan ->
        Just (edgeId, expectedTy)
    _ -> Nothing

-- | The exact semantic-to-construction route for the Gamma consumer of one
-- lambda body edge.  The semantic endpoint is always the requirement's
-- exterior graph identity; the construction endpoint must come from the
-- direct alias installed for that same exterior.  Keeping the edge, owner,
-- and exterior with both refs prevents later construction from treating a
-- quotient representative or a type-shaped peer as consumer authority.
-- | Move a completed lambda-consumer plan into the identity domain selected
-- by its exact body packet.  The plan is materialized after the child has been
-- checked, so an enclosing Gamma bound can still carry the source identity
-- that the child packet has just quotiented to its construction identity.
-- Apply that proved quotient before constructing the outgoing computation;
-- otherwise the resulting Hyp is checked against a stale source-domain bound.
applyLambdaConsumerConstructionPlanRefRenames
  :: [(TypeBinderRef, TypeBinderRef)]
  -> LambdaConsumerConstructionPlan
  -> LambdaConsumerConstructionPlan
applyLambdaConsumerConstructionPlanRefRenames renames plan =
  plan
    { lccSourceType =
        applyTypeVarRefRenames renames (lccSourceType plan)
    , lccSchemeInfo =
        applySchemeInfoRefRenames renames
          <$> lccSchemeInfo plan
    , lccLocalBodyConsumerBoundRefinement =
        renameBodyConsumerBoundRefinementCertificate renames
          <$> lccLocalBodyConsumerBoundRefinement plan
    , lccAmbientTopologyResultConstruction =
        applyAmbientTopologyResultConstructionRefRenames renames
          <$> lccAmbientTopologyResultConstruction plan
    , lccEnclosingConsumerConstruction =
        renameEnclosingConsumerConstruction
          <$> lccEnclosingConsumerConstruction plan
    , lccEnclosingOwnedBinderRefs =
        map (applyRefRenames renames) (lccEnclosingOwnedBinderRefs plan)
    , lccConsumerWithoutLocalBinder =
        alignConsumerWithoutLocalBinder
          <$> lccConsumerWithoutLocalBinder plan
    }
  where
    alignConsumerWithoutLocalBinder consumer =
      case consumer of
        PacketConsumerInheritedFree ref ->
          PacketConsumerInheritedFree (applyRefRenames renames ref)
        PacketConsumerEliminatedAtAmbientBound ref bound ->
          PacketConsumerEliminatedAtAmbientBound
            (applyRefRenames renames ref)
            (applyTypeVarRefRenames renames bound)
        PacketConsumerEliminatedByEqFree ref ->
          PacketConsumerEliminatedByEqFree
            (applyRefRenames renames ref)
        PacketConsumerRefinedAmbient completedBound certificate ->
          PacketConsumerRefinedAmbient
            (applyTypeVarRefRenames renames completedBound)
            (renameBodyConsumerBoundRefinementCertificate renames certificate)

    renameEnclosingConsumerConstruction construction =
      case construction of
        EnclosingBodyConsumerConstruction certificate ->
          EnclosingBodyConsumerConstruction
            certificate
              { ebccConsumerRef =
                  applyRefRenames renames (ebccConsumerRef certificate)
              , ebccCompletedBound =
                  applyTypeVarRefRenames
                    renames
                    (ebccCompletedBound certificate)
              , ebccAmbientDependencies =
                  [ ( applyRefRenames renames ref
                    , applyTypeVarRefRenames renames bound
                    )
                  | (ref, bound) <-
                      ebccAmbientDependencies certificate
                  ]
              , ebccSourceSpecialization =
                  applyInstantiationRefRenames
                    renames
                    (ebccSourceSpecialization certificate)
              , ebccBoundRefinement =
                  renameBodyConsumerBoundRefinementCertificate
                    renames
                    (ebccBoundRefinement certificate)
              }
        EnclosingCompletedLambdaConstruction
          enclosingOwner
          edgeId
          expectedTy ->
          EnclosingCompletedLambdaConstruction
            enclosingOwner
            edgeId
            (applyTypeVarRefRenames renames expectedTy)

applyAmbientTopologyResultConstructionRefRenames
  :: [(TypeBinderRef, TypeBinderRef)]
  -> AmbientTopologyResultConstructionCertificate
  -> AmbientTopologyResultConstructionCertificate
applyAmbientTopologyResultConstructionRefRenames renames certificate =
  certificate
    { atrcResultRef =
        applyRefRenames renames (atrcResultRef certificate)
    , atrcSourceType =
        applyTypeVarRefRenames renames (atrcSourceType certificate)
    , atrcResultBound =
        applyTypeVarRefRenames renames (atrcResultBound certificate)
    , atrcInstantiation =
        applyInstantiationRefRenames
          renames
          (atrcInstantiation certificate)
    }

installLambdaConsumerBoundaryRefinements
  :: LambdaConsumerConstructionPlan
  -> Env
  -> Either ElabError Env
installLambdaConsumerBoundaryRefinements plan env =
  do
    installedBindings <-
      installDescendantBodyConsumerBoundRefinements
        (envLocalGammaClosures env)
        boundaryCertificates
        (envTypeBindings env)
    (installedAliases, installedRenames) <-
      installBodyConsumerConstructionRoutes
        boundaryCertificates
        (envConstructionGammaAliases env)
        (envConstructionBinderRenames env)
        installedBindings
    pure
      env
        { envTypeBindings = installedBindings
        , envConstructionGammaAliases = installedAliases
        , envConstructionBinderRenames = installedRenames
        }
  where
    boundaryCertificates =
      maybeToList ambientPacketGammaRefinement
        ++ maybeToList
          ( ebccBoundRefinement
              <$> lccEnclosingBodyConsumer plan
          )
    ambientPacketGammaRefinement =
      case lccConsumerWithoutLocalBinder plan of
        Just (PacketConsumerRefinedAmbient _ certificate) ->
          Just certificate
        _ -> Nothing

installElaboratedBodyConsumerRefinements
  :: ElaboratedTerm
  -> Env
  -> Either ElabError Env
installElaboratedBodyConsumerRefinements elaboration env = do
  bindings <-
    case
        installDescendantBodyConsumerBoundRefinements
          (envLocalGammaClosures env)
          (elaboratedBodyConsumerBoundRefinements elaboration)
          (envTypeBindings env)
      of
        Right installed -> pure installed
        Left cause ->
          Left
            ( ValidationFailed
                [ "descendant body-consumer refinements do not fit the enclosing construction environment"
                , "  local Gamma closures: "
                    ++ show (envLocalGammaClosures env)
                , "  child owner construction: "
                    ++ show
                      (elaboratedOwnerFinalConstruction elaboration)
                , "  cause: " ++ show cause
                ]
            )
  pure env {envTypeBindings = bindings}

-- | Re-enter the exact ambient declarations used by a checked child before
-- its parent constructs an edge or combined term.  Binder ownership has
-- already been decided at this point, so installing these declarations
-- cannot suppress a parent-local Gen(Gamma, tau); it only preserves the
-- bounds under which the child was actually checked.
installElaboratedOwnerFinalAmbientConstruction
  :: IntMap.IntMap TypeBinderRef
  -> ElaboratedTerm
  -> Env
  -> Either ElabError (ElaboratedTerm, Env)
installElaboratedOwnerFinalAmbientConstruction sourceBinderRefs elaboration env =
  case elaboratedOwnerFinalConstruction elaboration of
    Nothing -> pure (elaboration, env)
    Just certificate -> do
      (completedCertificate, inheritedEnv) <-
        inheritOwnerFinalAmbientConstructionForTerm
        sourceBinderRefs
        (elaboratedTerm elaboration)
        certificate
        env
      pure
        ( elaboration
            { elaboratedOwnerFinalConstruction =
                Just completedCertificate
            }
        , inheritedEnv
        )

-- | Close a set of locally owned identities through declarations whose bounds
-- depend on them.  Such a declaration cannot remain ambient outside the local
-- type abstraction: doing so would leave its bound open after the abstraction
-- is hidden.
locallyOwnedTypeBinderRefs
  :: Map.Map TypeBinderRef ElabType
  -> [TypeBinderRef]
  -> [TypeBinderRef]
locallyOwnedTypeBinderRefs bindings = close . distinctBinderRefs
  where
    close refs =
      let refs' =
            distinctBinderRefs
              ( refs
                  ++ [ ref
                     | (ref, bound) <- Map.toList bindings
                     , any
                         (\dependency ->
                           any
                             (typeBinderRefsSameIdentity dependency)
                             refs
                         )
                         (freeTypeVarRefsType bound)
                     ]
              )
       in if length refs' == length refs then refs else close refs'

-- | A binder emitted by a checked child is internal to that value's explicit
-- type abstraction, not ambient in the parent construction.  Apply this
-- lexical ownership when the parent combines its children, after all child
-- edge computations have been built but before the combined term is
-- typechecked.
--
-- Gamma declarations are dependency ordered.  If a provisional ambient
-- declaration has a bound that mentions a child-local binder, that
-- declaration is child-local as well: retaining it would leave the parent's
-- Gamma open after hiding the binder.  Close the hidden set through those
-- bound dependencies, then remove the corresponding aliases so a later edge
-- cannot canonicalize an occurrence back into a hidden local declaration.
hideLocallyEmittedTypeBinders
  :: [TypeBinderRef]
  -> Env
  -> Env
hideLocallyEmittedTypeBinders emittedRefs env =
  env
    { envTypeBindings =
        Map.filterWithKey
          (\ref _ -> not (isHiddenRef ref))
          (envTypeBindings env),
      envConstructionGammaAliases =
        IntMap.filterWithKey
          ( \nodeKey outwardRef ->
              IntSet.notMember nodeKey hiddenNodeKeys
                && not (isHiddenRef outwardRef)
          )
          (envConstructionGammaAliases env),
      envGammaCopiedBinderRoutes =
        Map.filterWithKey
          ( \targetIdentity _ ->
              not
                ( isHiddenRef
                    ( typeBinderRefFromIdentity
                        targetIdentity
                        (typeBinderIdentityStableName targetIdentity)
                    )
                )
          )
          (envGammaCopiedBinderRoutes env),
      envSourceRefinedGammaBounds =
        Map.filterWithKey
          ( \ref bound ->
              not (isHiddenRef ref)
                && not (typeMentionsHiddenRef bound)
          )
          (envSourceRefinedGammaBounds env),
      envConstructionBinderRenames =
          filter
            ( \(sourceRef, outwardRef) ->
                not (isHiddenRef sourceRef)
                  && not (isHiddenRef outwardRef)
            )
            (envConstructionBinderRenames env)
    }
  where
    hiddenRefs =
      locallyOwnedTypeBinderRefs
        (envTypeBindings env)
        emittedRefs

    isHiddenRef ref =
      any (typeBinderRefsSameIdentity ref) hiddenRefs
    typeMentionsHiddenRef =
      any isHiddenRef . freeTypeVarRefsType
    hiddenNodeKeys =
      IntSet.fromList
        [ getNodeId node
        | ref <- hiddenRefs
        , Just node <- [typeBinderRefNode ref]
        ]

-- | Remove occurrence routes whose outward identity is lexically declared by
-- a recursively constructed child.  The enclosing packet may still retain
-- its own binders and body, but it cannot use a child's local declaration as
-- an ambient graph alias.
hideLocallyEmittedSchemeInfoRoutes
  :: [TypeBinderRef]
  -> SchemeInfo
  -> SchemeInfo
hideLocallyEmittedSchemeInfoRoutes emittedRefs schemeInfo =
  rebuildSchemeInfoFromRefSubst
    schemeInfo
    (siScheme schemeInfo)
    (IntMap.filter (not . isHiddenRef) (siSubstRefs schemeInfo))
  where
    isHiddenRef ref =
      any (typeBinderRefsSameIdentity ref) emittedRefs

-- | Exact lexical type binders introduced by an xMLF construction.  This is
-- a scope projection of the term syntax, not a type-shape recovery oracle:
-- it is used only to keep a parent's ambient type-checking environment from
-- reintroducing identities that are visibly bound inside either child.
--
-- A higher-rank term binder owns the forall declarations in its declared
-- type just as an 'ETyAbsRef' owns its explicit abstraction.  In particular,
-- the @a@ in a parameter of type @forall a. a -> a@ is not an enclosing
-- application-Gamma declaration merely because the graph reused its source
-- identity.
lexicallyBoundTypeBinderRefsTerm :: XmlfTerm -> [TypeBinderRef]
lexicallyBoundTypeBinderRefsTerm = distinctRefs . go
  where
    go term =
      case term of
        ETyAbsRef ref _ body -> ref : go body
        ELam resolved body ->
          typeBinderDeclarationRefs (resolvedVarType resolved)
            ++ go body
        EApp fun arg -> go fun ++ go arg
        ELet resolved scheme rhs body ->
          typeBinderDeclarationRefs (resolvedVarType resolved)
            ++ typeBinderDeclarationRefs (schemeToType scheme)
            ++ go rhs
            ++ go body
        ETyInst body _ -> go body
        ERoll _ body -> go body
        EUnroll body -> go body
        EVarNode {} -> []
        ELit {} -> []

    distinctRefs =
      foldl'
        ( \refs ref ->
            if any (typeBinderRefsSameIdentity ref) refs
              then refs
              else refs ++ [ref]
        )
        []

installElaboratedBodyConsumerConstruction
  :: LocalGammaOwner
  -> [BodyConsumerBoundRefinementCertificate]
  -> ElaboratedTerm
  -> [(TypeBinderRef, Maybe BoundType)]
  -> Env
  -> Env
  -> Either
      ElabError
      ([(TypeBinderRef, Maybe BoundType)], Env, Env)
installElaboratedBodyConsumerConstruction
  owner
  ownerCertificates
  elaboration
  binders
  constructionEnv
  ambientEnv = do
    refinedConstructionEnv <-
      advanceEnvThroughOwnedBodyConsumerConstructions
        owner
        certificates
        constructionEnv
    refinedAmbientEnv <-
      installBodyConsumerRefinements
        ambientCertificates
        ambientEnv
    refinedBinders <-
      traverse
        (refineBinder refinedConstructionEnv)
        binders
    pure
      ( refinedBinders
      , refinedConstructionEnv
      , refinedAmbientEnv
      )
  where
    certificates =
      ownerCertificates
        ++ elaboratedBodyConsumerBoundRefinements elaboration
    ambientCertificates =
      filter
        (not . bodyConsumerBoundRefinementEmittedBy owner)
        certificates

    installBodyConsumerRefinements refinements env = do
      bindings <-
        installDescendantBodyConsumerBoundRefinements
          (envLocalGammaClosures env)
          refinements
          (envTypeBindings env)
      pure env {envTypeBindings = bindings}

    refineBinder refinedConstructionEnv binder@(ref, _)
      | not
          ( any
              (bodyConsumerBoundRefinementTargetsAny [ref])
              certificates
          ) =
          pure binder
      | otherwise =
          case
              [ bound
              | (candidateRef, bound) <-
                  Map.toList
                    ( envTypeBindings
                        refinedConstructionEnv
                    )
              , typeBinderRefsSameIdentity candidateRef ref
              ]
            of
              [completedBound] ->
                case elabToBound completedBound of
                  Right bound -> pure (ref, Just bound)
                  Left cause ->
                    refinementFailure
                      ref
                      [ "completed construction is not a legal Gamma bound"
                      , "  completed bound: " ++ show completedBound
                      , "  cause: " ++ cause
                      ]
              [] ->
                refinementFailure
                  ref
                  [ "completed declaration is absent from constructed Gamma" ]
              matches ->
                refinementFailure
                  ref
                  [ "completed declaration occurs more than once"
                  , "  matches: " ++ show matches
                  ]

    refinementFailure ref details =
      Left
        ( ValidationFailed
            ( [ "cannot publish descendant body-consumer refinement"
              , "  binder: " ++ show ref
              ]
                ++ details
            )
        )

-- | Advance the exact construction environment at the owner that will emit
-- the retained declaration.  Descendants check against the completed bound,
-- while the owner's outer environment can still carry the provisional graph
-- presentation.  The refinement certificate is the sole authority for that
-- state transition; the later strict Gamma extension merely verifies that the
-- constructed declaration is already present at the same bound.
advanceEnvThroughOwnedBodyConsumerConstructions
  :: LocalGammaOwner
  -> [BodyConsumerBoundRefinementCertificate]
  -> Env
  -> Either ElabError Env
advanceEnvThroughOwnedBodyConsumerConstructions owner certificates env = do
  completedBindings <-
    installOwnedBodyConsumerBoundRefinementsWithClosures
      owner
      (envLocalGammaClosures env)
      certificates
      (envTypeBindings env)
  pure env {envTypeBindings = completedBindings}

-- | Proof that a packet-owned consumer needs no binder at the current lambda.
-- The distinction is construction-relevant: an inherited free occurrence is
-- already part of the current scheme, whereas a vacuous packet consumer is
-- introduced only by the outgoing Hyp and obtains its bound from ambient
-- Gamma.  Treating both as a generic "missing binder" loses that ownership
-- evidence and makes valid ground-result packets indistinguishable from an
-- accidentally dropped declaration.
data PacketConsumerWithoutLocalBinder
  = PacketConsumerInheritedFree !TypeBinderRef
  | PacketConsumerEliminatedAtAmbientBound !TypeBinderRef !ElabType
  | PacketConsumerEliminatedByEqFree !TypeBinderRef
  | PacketConsumerRefinedAmbient
      !ElabType
      !BodyConsumerBoundRefinementCertificate

packetConsumerEliminationRef
  :: PacketConsumerWithoutLocalBinder -> Maybe TypeBinderRef
packetConsumerEliminationRef resolution =
  case resolution of
    PacketConsumerEliminatedAtAmbientBound ref _ -> Just ref
    PacketConsumerEliminatedByEqFree ref -> Just ref
    PacketConsumerInheritedFree _ -> Nothing
    PacketConsumerRefinedAmbient _ _ -> Nothing

data StructuralRecursiveCandidate
  = StructuralRecursiveCandidateFromHelper ElabType
  | StructuralRecursiveCandidateFromDirectCarrier ElabType

type StructuralRecursiveCandidateSelection = CandidateSelection StructuralRecursiveCandidate

pattern NoStructuralRecursiveCandidate :: StructuralRecursiveCandidateSelection
pattern NoStructuralRecursiveCandidate = NoCandidateSelection

pattern UniqueStructuralRecursiveCandidate :: StructuralRecursiveCandidate -> StructuralRecursiveCandidateSelection
pattern UniqueStructuralRecursiveCandidate candidate = UniqueCandidateSelection candidate

pattern AmbiguousStructuralRecursiveCandidate :: StructuralRecursiveCandidateSelection
pattern AmbiguousStructuralRecursiveCandidate = AmbiguousCandidateSelection

{-# COMPLETE NoStructuralRecursiveCandidate, UniqueStructuralRecursiveCandidate, AmbiguousStructuralRecursiveCandidate #-}

data AdministrativeLambdaBodyConstruction =
  AdministrativeLambdaBodyConstruction
    { albcGammaBinders :: [(TypeBinderRef, Maybe BoundType)],
      albcBodyType :: ElabType
    }
  deriving (Show)

administrativeLambdaBodyConstructionScheme
  :: AdministrativeLambdaBodyConstruction
  -> ElabScheme
administrativeLambdaBodyConstructionScheme construction =
  mkElabSchemeWithRefs
    (albcGammaBinders construction)
    (albcBodyType construction)

administrativeLambdaBodyConstructionFromScheme
  :: ElabScheme
  -> AdministrativeLambdaBodyConstruction
administrativeLambdaBodyConstructionFromScheme scheme =
  AdministrativeLambdaBodyConstruction
    { albcGammaBinders = schemeBinderRefs scheme,
      albcBodyType = schemeBody scheme
    }

administrativeLambdaBodyConstructionBoundaryType
  :: AdministrativeLambdaBodyConstruction
  -> ElabType
administrativeLambdaBodyConstructionBoundaryType construction =
  schemeToType
    ( mkElabSchemeWithRefs
        (albcGammaBinders construction)
        (TArrow TBottom (albcBodyType construction))
    )

administrativeLambdaBodyConstructionFromBoundaryType
  :: ElabType
  -> Maybe AdministrativeLambdaBodyConstruction
administrativeLambdaBodyConstructionFromBoundaryType boundaryTy = do
  TArrow TBottom bodyTy <- pure (schemeBody boundaryScheme)
  pure
    AdministrativeLambdaBodyConstruction
      { albcGammaBinders = schemeBinderRefs boundaryScheme
      , albcBodyType = bodyTy
      }
  where
    boundaryScheme = schemeFromType boundaryTy

mapAdministrativeLambdaBodyConstruction
  :: (ElabType -> ElabType)
  -> AdministrativeLambdaBodyConstruction
  -> Maybe AdministrativeLambdaBodyConstruction
mapAdministrativeLambdaBodyConstruction f construction = do
  -- Keep the administrative Gamma/body boundary explicit while applying a
  -- whole-type identity transformation.  Converting the bare scheme to a
  -- type and immediately calling 'schemeFromType' would absorb every
  -- leading forall owned by the body into the enclosing Gamma.
  administrativeLambdaBodyConstructionFromBoundaryType
    (f (administrativeLambdaBodyConstructionBoundaryType construction))

-- | An enclosing constructor can pass a type downward for two distinct
-- purposes.  A checking expectation guides recursive construction but owns no
-- operational xMLF endpoint.  An exact construction expectation is backed by
-- the source constructor (for example an annotation) or by a prepared
-- consumer that owns the outgoing computation.  Keeping that distinction in
-- the environment prevents an inferred graph placeholder from being promoted
-- later into an 'ApplicationResultEndpoint'.
data ExpectedTermEndpoint
  = CheckingExpectedTerm !ElabType
  | ExactConstructionExpectedTerm !ElabType
  -- A bare source lambda selected as an exact application value owns the
  -- Var-Abs for its parameter identity.  Keep that ownership with the
  -- downward endpoint so the lambda emits the declaration together with its
  -- ordinary Gamma, before any N/Hyp computation consumes later binders.
  | SourceLambdaValueExpectedTerm
      !SourceLambdaValueConstruction
      !ElabType
  -- A prepared administrative source lambda owns its complete construction
  -- before Typ(body).  This variant marks the exact codomain projected from
  -- that certificate, so the first returned lambda can consume it as a
  -- construction target instead of replacing it with its already-built body
  -- type.  Transparent result terms preserve the marker; projection through
  -- the returned lambda consumes it back to an ordinary exact endpoint.
  | AdministrativeLambdaBodyExpectedTerm
      !AdministrativeLambdaBodyConstruction
      !ElabType
  deriving (Show)

data SourceLambdaValueConstruction = SourceLambdaValueConstruction
  { slvcOwner :: !LocalGammaOwner
  , slvcParameterBinder :: !(TypeBinderRef, Maybe BoundType)
  }
  deriving (Eq, Show)

-- | The certificate that selected an application's exact function/result
-- endpoint.  Direct lambda packets are retained as typed evidence because an
-- enclosing-consumer Eq-Free construction also proves the nested lambda
-- parameter spine before the function child is checked.  Ordinary and
-- owner-confirmed administrative endpoints do not carry that authority.
data ApplicationExactConstructionAuthority
  = OrdinaryApplicationExactConstruction
  | DirectLambdaApplicationExactConstruction
      !DirectLambdaApplicationResultConstruction
  | DirectAdministrativeLambdaApplicationExactConstruction
  deriving (Eq, Show)

-- | Provenance for one exact endpoint competing at a lambda constructor.
-- The same endpoint type can occur at several construction stages, so the
-- type alone cannot say which certificate may advance it.  In particular, a
-- completed body-owner endpoint must not regain the prepared packet's source
-- authority merely because it is alpha-equivalent to an earlier packet view.
data ExactLambdaEndpointOrigin
  = InheritedLambdaEndpoint
  | PreparedAdministrativeLambdaEndpoint
  | PreparedAdministrativeBodyEndpoint
  | PreparedOpaqueLambdaEndpoint
  | BodyOwnerPreparedLambdaEndpoint
  | BodyOwnerIncomingLambdaEndpoint
  | IncomingLambdaEndpoint
  deriving (Eq, Show)

data ExactLambdaEndpointCandidate = ExactLambdaEndpointCandidate
  { exactLambdaEndpointOrigin :: !ExactLambdaEndpointOrigin,
    exactLambdaEndpointType :: !ElabType
  }
  deriving (Show)

expectedTermEndpointType :: ExpectedTermEndpoint -> ElabType
expectedTermEndpointType endpoint =
  case endpoint of
    CheckingExpectedTerm ty -> ty
    ExactConstructionExpectedTerm ty -> ty
    SourceLambdaValueExpectedTerm _ ty -> ty
    AdministrativeLambdaBodyExpectedTerm _ ty -> ty

exactConstructionExpectedType :: ExpectedTermEndpoint -> Maybe ElabType
exactConstructionExpectedType endpoint =
  case endpoint of
    CheckingExpectedTerm _ -> Nothing
    ExactConstructionExpectedTerm ty -> Just ty
    SourceLambdaValueExpectedTerm _ ty -> Just ty
    AdministrativeLambdaBodyExpectedTerm _ ty -> Just ty

-- | Turn an exact source-operated endpoint into Var-Abs authority only when
-- the annotated source constructor and the endpoint name the same bare
-- parameter identity.  The endpoint shape validates source ownership; it
-- never selects the identity on its own.
sourceLambdaValueExpectedTermFor
  :: AnnExpr
  -> ElabType
  -> ExpectedTermEndpoint
sourceLambdaValueExpectedTermFor ann endpoint =
  maybe
    (ExactConstructionExpectedTerm endpoint)
    (`SourceLambdaValueExpectedTerm` endpoint)
    (sourceLambdaValueConstructionFor ann endpoint)

sourceLambdaValueConstructionFor
  :: AnnExpr
  -> ElabType
  -> Maybe SourceLambdaValueConstruction
sourceLambdaValueConstructionFor ann endpoint =
  case ann of
    ALam _ _ parameterNode lambdaScope _ bodyEdge lambdaNode
      | TForallRef parameterRef Nothing
          (TArrow (TVarRef domainRef) _) <- endpoint
      , typeBinderRefIdentity parameterRef
          == typeBinderIdentityFromNode parameterNode
      , typeBinderRefsSameIdentity parameterRef domainRef ->
          Just
            ( SourceLambdaValueConstruction
              { slvcOwner =
                  LocalGammaOwner
                    { lgoConstructor = LocalLambdaGamma
                    , lgoBoundaryEdge = bodyEdge
                    , lgoTermNode = lambdaNode
                    , lgoScope = GenRef lambdaScope
                    }
              , slvcParameterBinder = (parameterRef, Nothing)
              }
            )
    _ -> Nothing

mapExpectedTermEndpoint
  :: (ElabType -> ElabType)
  -> ExpectedTermEndpoint
  -> ExpectedTermEndpoint
mapExpectedTermEndpoint f endpoint =
  case endpoint of
    CheckingExpectedTerm ty -> CheckingExpectedTerm (f ty)
    ExactConstructionExpectedTerm ty ->
      ExactConstructionExpectedTerm (f ty)
    SourceLambdaValueExpectedTerm construction ty ->
      case f (TVarRef (fst (slvcParameterBinder construction))) of
        TVarRef mappedRef ->
          SourceLambdaValueExpectedTerm
            construction
              { slvcParameterBinder = (mappedRef, Nothing)
              }
            (f ty)
        _ -> ExactConstructionExpectedTerm (f ty)
    AdministrativeLambdaBodyExpectedTerm construction ty ->
      case mapAdministrativeLambdaBodyConstruction f construction of
        Just mappedConstruction ->
          AdministrativeLambdaBodyExpectedTerm mappedConstruction (f ty)
        Nothing -> ExactConstructionExpectedTerm (f ty)

projectExpectedTermEndpoint
  :: (ElabType -> Maybe ElabType)
  -> ExpectedTermEndpoint
  -> Maybe ExpectedTermEndpoint
projectExpectedTermEndpoint project endpoint =
  case project (expectedTermEndpointType endpoint) of
    Nothing -> Nothing
    Just projectedTy -> Just (projectEndpoint projectedTy endpoint)
  where
    projectEndpoint projectedTy currentEndpoint =
      case currentEndpoint of
        CheckingExpectedTerm _ -> CheckingExpectedTerm projectedTy
        ExactConstructionExpectedTerm _ ->
          ExactConstructionExpectedTerm projectedTy
        SourceLambdaValueExpectedTerm _ _ ->
          -- Projection enters the lambda body, so this constructor has
          -- consumed the source-owned Var-Abs boundary.
          ExactConstructionExpectedTerm projectedTy
        AdministrativeLambdaBodyExpectedTerm construction _ ->
          -- Lambda projection changes only the current endpoint.  The full
          -- prepared Gamma remains the certificate consumed by that lambda
          -- after its recursively checked body has finalized refinements.
          AdministrativeLambdaBodyExpectedTerm construction projectedTy

-- | Select one downward expectation without allowing list order to assign
-- construction authority.  Exact endpoints are source/packet certificates:
-- they dominate checking-only guidance.  Distinct exact certificates are
-- compatible only when the explicit leading-binder construction proves one
-- common, most-specialized endpoint; this covers a packet's @forall a. b@
-- followed by the enclosing edge's exact @b@ without equating the two types.
-- Checking expectations remain advisory, so when there is no exact
-- certificate the first available checking view is enough.
selectExpectedTermEndpoint
  :: (ElabType -> ElabType -> Bool)
  -> String
  -> [Maybe ExpectedTermEndpoint]
  -> Either ElabError (Maybe ExpectedTermEndpoint)
selectExpectedTermEndpoint typesAgree owner candidates =
  selectExpectedTermEndpointBy
    typesAgree
    constructsExactEndpoint
    owner
    candidates
  where
    constructsExactEndpoint sourceTy targetTy =
      typesAgree sourceTy targetTy
        || isJust
          (planExactBinderSpine typesAgree sourceTy targetTy)
        || any
          (administrativeConstructionConstructs sourceTy targetTy)
          candidates

    -- An administrative marker owns both the exact body endpoint and the
    -- Gamma in which that endpoint is constructed.  Use that Gamma to prove a
    -- terminal Hyp/abstraction computation from a peer exact certificate;
    -- leading-forall planning alone cannot relate a ground annotation to its
    -- already-open flexible result declaration.
    administrativeConstructionConstructs sourceTy targetTy endpoint =
      fromMaybe False $ do
        AdministrativeLambdaBodyExpectedTerm construction administrativeTy <-
          endpoint
        guard (typesAgree administrativeTy targetTy)
        let constructionTypeEnv =
              foldr
                ( \(ref, mbBound) typeEnv ->
                    TypeCheck.insertTypeBindingRef
                      ref
                      (maybe TBottom tyToElab mbBound)
                      typeEnv
                )
                (TypeCheck.mkTypeCheckEnvWithResolvedTerms [] Map.empty)
                (albcGammaBinders construction)
        _ <-
          constructExactInstantiation
          constructionTypeEnv
          typesAgree
          sourceTy
          targetTy
        pure True

-- | Variant used when the term constructor itself supplies a stronger exact
-- construction relation than leading type application alone.  Keep endpoint
-- equality separate from construction direction: the latter selects the most
-- specialized certificate, while the former verifies that the selection is
-- unique up to the caller's exact equality.
selectExpectedTermEndpointBy
  :: (ElabType -> ElabType -> Bool)
  -> (ElabType -> ElabType -> Bool)
  -> String
  -> [Maybe ExpectedTermEndpoint]
  -> Either ElabError (Maybe ExpectedTermEndpoint)
selectExpectedTermEndpointBy typesAgree constructsExactEndpoint owner candidates =
  case mostSpecializedExactTypes of
    exactTy : remainingExactTypes
      | all (typesAgree exactTy) remainingExactTypes ->
          pure (Just (selectedExactEndpoint exactTy))
      | otherwise -> conflictingExactEndpoints
    []
      | not (null exactTypes) -> conflictingExactEndpoints
    [] ->
      pure
        ( case checkingTypes of
            checkingTy : _ -> Just (CheckingExpectedTerm checkingTy)
            [] -> Nothing
        )
  where
    conflictingExactEndpoints =
      Left
        ( ValidationFailed
            [ owner ++ " has conflicting exact construction endpoints"
            , "  exact endpoints: " ++ show exactTypes
            ]
        )
    endpoints = catMaybes candidates
    exactTypes =
      [ ty
      | endpoint <- endpoints
      , ty <- maybeToList (exactConstructionExpectedType endpoint)
      ]
    selectedExactEndpoint exactTy =
      case
          find (administrativeEndpointMatchesExact exactTy) endpoints
            <|> find (administrativeEndpointAgrees exactTy) endpoints
        of
        Just (AdministrativeLambdaBodyExpectedTerm construction _) ->
          AdministrativeLambdaBodyExpectedTerm construction exactTy
        _ ->
          case
              find (sourceLambdaEndpointMatchesExact exactTy) endpoints
                <|> find (sourceLambdaEndpointAgrees exactTy) endpoints
            of
            Just (SourceLambdaValueExpectedTerm construction _) ->
              SourceLambdaValueExpectedTerm construction exactTy
            _ -> ExactConstructionExpectedTerm exactTy
    administrativeEndpointMatchesExact exactTy endpoint =
      case endpoint of
        AdministrativeLambdaBodyExpectedTerm _ administrativeTy ->
          alphaEqTypePreservingStructuralBinders exactTy administrativeTy
        _ -> False
    administrativeEndpointAgrees exactTy endpoint =
      case endpoint of
        AdministrativeLambdaBodyExpectedTerm _ administrativeTy ->
          typesAgree exactTy administrativeTy
        _ -> False
    sourceLambdaEndpointMatchesExact exactTy endpoint =
      case endpoint of
        SourceLambdaValueExpectedTerm _ sourceLambdaTy ->
          alphaEqTypePreservingStructuralBinders exactTy sourceLambdaTy
        _ -> False
    sourceLambdaEndpointAgrees exactTy endpoint =
      case endpoint of
        SourceLambdaValueExpectedTerm _ sourceLambdaTy ->
          typesAgree exactTy sourceLambdaTy
        _ -> False
    mostSpecializedExactTypes =
      [ targetTy
      | targetTy <- exactTypes
      , all (`constructsExactEndpoint` targetTy) exactTypes
      ]
    checkingTypes =
      [ ty
      | CheckingExpectedTerm ty <- endpoints
      ]

-- | Select a common most-constructed exact endpoint while retaining the
-- certificate provenance needed by the construction relation.  The ordinary
-- expected-term selector above can operate on types because its certificates
-- are carried by the endpoint constructors themselves.  Lambda finalization
-- combines several independently produced certificates whose types can be
-- alpha-equivalent at different stages, so erasing their origins first would
-- make a directional completion appear reversible.
selectExactConstructionCandidateBy
  :: (candidate -> ElabType)
  -> (ElabType -> ElabType -> Bool)
  -> (candidate -> candidate -> Bool)
  -> String
  -> [candidate]
  -> Either ElabError (Maybe candidate)
selectExactConstructionCandidateBy
  candidateType
  typesAgree
  constructsExactEndpoint
  owner
  candidates =
    case mostSpecializedCandidates of
      candidate : remainingCandidates
        | all
            ( typesAgree (candidateType candidate)
                . candidateType
            )
            remainingCandidates ->
              pure (Just candidate)
        | otherwise -> conflictingExactEndpoints
      []
        | not (null candidates) -> conflictingExactEndpoints
      [] -> pure Nothing
  where
    conflictingExactEndpoints =
      Left
        ( ValidationFailed
            [ owner ++ " has conflicting exact construction endpoints"
            , "  exact endpoints: " ++ show (map candidateType candidates)
            ]
        )
    mostSpecializedCandidates =
      [ target
      | target <- candidates
      , all (`constructsExactEndpoint` target) candidates
      ]

-- | Whether a type contains an explicitly bounded forall at any depth.
-- Such a binder remains owned by its annotation or packet construction and
-- cannot be projected through an enclosing lambda solely from the packet's
-- operated Gamma bound.
containsExplicitForallBound :: ElabType -> Bool
containsExplicitForallBound ty =
  case ty of
    TForallRef _ (Just _) _ -> True
    TForallRef _ Nothing bodyTy -> containsExplicitForallBound bodyTy
    TArrow domainTy codomainTy ->
      containsExplicitForallBound domainTy
        || containsExplicitForallBound codomainTy
    TConWithIdentity _ _ args -> any containsExplicitForallBound args
    TVarAppRef _ args -> any containsExplicitForallBound args
    TMuRef _ bodyTy -> containsExplicitForallBound bodyTy
    TVarRef _ -> False
    TBaseWithIdentity _ _ -> False
    TBottom -> False

-- | Figure 15.3.5 constructs a nested lambda from the outside in.  Two exact
-- certificates can therefore share an alpha-equivalent lambda prefix while a
-- deeper bounded forall in the source certificate is specialized by the
-- enclosing consumer.  Prove that relationship one constructor at a time:
-- each lambda prefix must be the same exact identity-bearing prefix, and the
-- only non-equality step is an explicit binder-spine computation at the
-- eventual codomain.  This is the downward construction used while building
-- the term, not an after-the-fact function coercion.
exactLambdaSpineConstructsEndpoint
  :: ElabType
  -> ElabType
  -> Bool
exactLambdaSpineConstructsEndpoint sourceTy targetTy =
  exactLambdaEndpointTypesAgree sourceTy targetTy
    || isJust
      ( planExactBinderSpine
          exactLambdaEndpointTypesAgree
          sourceTy
          targetTy
      )
    || matchingForallPrefixConstructsBody
    || exactAmbientOpeningConstructsEndpoint
    || matchingLambdaPrefixConstructsCodomain
  where
    sourceScheme = schemeFromType sourceTy
    targetScheme = schemeFromType targetTy
    sourceBinders = schemeBinderRefs sourceScheme
    targetBinders = schemeBinderRefs targetScheme
    targetFreeRefs = freeTypeVarRefsType targetTy
    -- An enclosing Gamma can own the same identity that a source certificate
    -- presents under an unbounded closure.  Opening that closure is exact only
    -- when each peeled identity is already free at the consumer endpoint or
    -- is vacuous in the remaining source construction.  The latter is the
    -- ordinary exact elimination of an unused forall; it does not equate the
    -- binder with an unrelated target identity.  Bounded binders are
    -- deliberately excluded: their own identity cannot be used as the
    -- argument that escapes their forall.
    exactAmbientOpeningConstructsEndpoint =
      not (null sourceBinders)
        && all (isNothing . snd) sourceBinders
        && sourceBindersCanOpen sourceBinders
        && exactLambdaSpineConstructsEndpoint
          (schemeBody sourceScheme)
          targetTy
    sourceBindersCanOpen [] = True
    sourceBindersCanOpen ((sourceRef, _) : remainingBinders) =
      ( any
          (typeBinderRefsSameIdentity sourceRef)
          targetFreeRefs
          || not
            ( any
                (typeBinderRefsSameIdentity sourceRef)
                ( freeTypeVarRefsType
                    ( schemeToType
                        ( mkElabSchemeWithRefs
                            remainingBinders
                            (schemeBody sourceScheme)
                        )
                    )
                )
            )
      )
        && sourceBindersCanOpen remainingBinders
    -- Retain one exact declaration before recursively opening or
    -- specializing the construction beneath it.  In particular,
    -- @forall alpha. forall beta. tau@ can construct
    -- @forall alpha. tau@ under an enclosing Gamma that already owns the
    -- same @beta@ identity.  This is the scoped counterpart of InstUnder;
    -- it never turns a binder into an unrelated free variable.
    matchingForallPrefixConstructsBody =
      case (sourceTy, targetTy) of
        ( TForallRef sourceRef sourceBound sourceBody
          , TForallRef targetRef targetBound targetBody
          )
            | retainedBoundsAgree
                alignedSourceBound
                targetBound ->
                exactLambdaSpineConstructsEndpoint
                  alignedSourceBody
                  targetBody
          where
            binderRename = [(sourceRef, targetRef)]
            alignedSourceBound =
              renameBoundTypeBinderRefPayloads binderRename
                <$> sourceBound
            alignedSourceBody =
              renameTypeBinderRefPayloads binderRename sourceBody
        _ -> False
    retainedBoundsAgree Nothing Nothing = True
    retainedBoundsAgree (Just sourceBound) (Just targetBound) =
      exactLambdaEndpointTypesAgree
        (tyToElab sourceBound)
        (tyToElab targetBound)
    retainedBoundsAgree _ _ = False
    matchingLambdaPrefixConstructsCodomain =
      case (schemeBody sourceScheme, schemeBody targetScheme) of
        ( TArrow sourceDomain sourceCodomain
          , TArrow targetDomain targetCodomain
          )
            | length sourceBinders == length targetBinders
            , let sourcePrefix =
                    schemeToType
                      ( mkElabSchemeWithRefs
                          sourceBinders
                          (TArrow sourceDomain TBottom)
                        )
                  targetPrefix =
                    schemeToType
                      ( mkElabSchemeWithRefs
                          targetBinders
                          (TArrow targetDomain TBottom)
                          )
            , exactLambdaEndpointTypesAgree sourcePrefix targetPrefix ->
                exactLambdaSpineConstructsEndpoint
                  ( renameTypeBinderRefPayloads
                      (zip (map fst sourceBinders) (map fst targetBinders))
                      sourceCodomain
                  )
                  targetCodomain
        _ -> False

-- | A prepared source-lambda certificate can be frozen before an enclosing
-- constructor distributes its leading Gamma declarations across a returned
-- value-lambda spine.  Validate that distribution against the actual resolved
-- lambda syntax: both presentations must carry the same ordered declarations,
-- construct the same parameter domains, and finish at the same result.  The
-- only permitted difference is where that one declaration sequence is split
-- between successive Var-Abs boundaries.
--
-- This is deliberately not a general type-shape equivalence.  Callers use it
-- only after a packet has named the exact source-lambda node being entered.
certifiedSourceLambdaSpinePlacementConstructs
  :: (ElabType -> ElabType -> Bool)
  -> AnnExpr
  -> ElabType
  -> ElabType
  -> Bool
certifiedSourceLambdaSpinePlacementConstructs typesAgree lambdaAnn sourceTy targetTy =
  case (lambdaSpineTrace sourceTy lambdaAnn, lambdaSpineTrace targetTy lambdaAnn) of
    ( Just (sourceGroups, sourceBinders, sourceDomains, sourceResult)
      , Just (targetGroups, targetBinders, targetDomains, targetResult)
      )
        | not (null sourceDomains)
        , sourceGroups /= targetGroups
        , length sourceBinders == length targetBinders
        , length sourceDomains == length targetDomains ->
            let binderRenames =
                  zip (map fst sourceBinders) (map fst targetBinders)
                alignSourceType =
                  renameTypeBinderRefPayloads binderRenames
                alignSourceBound =
                  fmap
                    (renameBoundTypeBinderRefPayloads binderRenames)
             in and
                  ( zipWith
                      (\(_, sourceBound) (_, targetBound) ->
                        boundsAgree
                          (alignSourceBound sourceBound)
                          targetBound
                      )
                      sourceBinders
                      targetBinders
                  )
                  && and
                    ( zipWith
                        (typesAgree . alignSourceType)
                        sourceDomains
                        targetDomains
                    )
                  && typesAgree
                    (alignSourceType sourceResult)
                    targetResult
    _ -> False
  where
    boundsAgree Nothing Nothing = True
    boundsAgree (Just sourceBound) (Just targetBound) =
      typesAgree (tyToElab sourceBound) (tyToElab targetBound)
    boundsAgree _ _ = False

    lambdaSpineTrace currentTy currentAnn =
      let currentScheme = schemeFromType currentTy
          currentBinders = schemeBinderRefs currentScheme
          currentBodyTy = schemeBody currentScheme
       in case stripAnnExpr currentAnn of
            ALam _ _ _ _ nestedBody _ _ ->
              case currentBodyTy of
                TArrow domainTy codomainTy -> do
                  ( nestedGroups
                    , nestedBinders
                    , nestedDomains
                    , nestedResult
                    ) <- lambdaSpineTrace codomainTy nestedBody
                  pure
                    ( length currentBinders : nestedGroups
                    , currentBinders ++ nestedBinders
                    , domainTy : nestedDomains
                    , nestedResult
                    )
                _ -> Nothing
            _ ->
              pure
                ( [length currentBinders]
                , currentBinders
                , []
                , currentBodyTy
                )

data Env = Env
  { envBindingsByIdentity :: Map.Map EnvBindingIdentityKey EnvBinding,
    envTypeBindings :: Map.Map TypeBinderRef ElabType,
    envConstructionGammaAliases :: IntMap.IntMap TypeBinderRef,
    -- | Copy provenance owned by an exact construction-Gamma declaration.
    -- The outer identity names the declaration whose bound received a
    -- prepared packet; each inner route records the packet binder and the
    -- fresh declaration copied into that bound.  Keeping this next to
    -- 'envTypeBindings' lets a nested Figure 15.3.5 lambda construct the
    -- exact enclosing binder spine without guessing from names or shapes.
    envGammaCopiedBinderRoutes ::
      Map.Map
        TypeBinderIdentity
        [(TypeBinderIdentity, TypeBinderRef)],
    -- | Exact Gamma bounds refined from a source-mediated application before
    -- its body is constructed.  This is a capability map, not a cache: only
    -- these declarations may override the packet's provisional opened bound
    -- when an application selects its active consumer endpoint.
    envSourceRefinedGammaBounds :: Map.Map TypeBinderRef ElabType,
    -- | Parameter types fixed by the construction that owns an enclosing
    -- RHS.  In particular, a recursive let publishes a contractive @mu@
    -- scheme before its RHS is elaborated; unfolding that scheme fixes the
    -- leading lambda domains.  Carrying those domains by binder identity
    -- lets the lambda be built with the recursive carrier directly, instead
    -- of first assigning a graph placeholder and trying to equate it with
    -- the carrier at an application use site.
    envConstructedLambdaParamTypes :: Map.Map EnvBindingIdentityKey ElabType,
    -- | Direct Figure 15.3.5 parameter endpoints proved by an already
    -- checked application argument.  This is a strict subset of
    -- 'envConstructedLambdaParamTypes'; the separate provenance lets the
    -- lambda boundary discard a provisional graph-root alias instead of
    -- treating its stale lower bound as authority over the checked value.
    envExactApplicationLambdaParamSchemes ::
      Map.Map EnvBindingIdentityKey SchemeInfo,
    -- | Exact parameter boundaries currently in lexical scope.  Prepared
    -- packets intentionally retain an open graph view; consumers complete
    -- that view through these certificates before constructing terms.
    envLambdaParamBoundaryCertificates ::
      [LambdaParamBoundaryCertificate],
    -- | Every source-to-graph quotient that is active while constructing the
    -- current term.  Compiler-exact routes are a subset of these routes, but
    -- source-expected packet routes are construction-only: they must align
    -- local terms and bounds without claiming authority to republish the
    -- source ABI.
    envConstructionBinderRenames :: [(TypeBinderRef, TypeBinderRef)],
    -- | The accumulated quotient from compiler-exact source binders to the
    -- graph identities that construct the current term.  Packet ownership is
    -- nested, but its identity domain is lexical: descendants must retain all
    -- enclosing routes after 'envActiveSubtermConstruction' advances to the
    -- innermost packet.
    envCompilerExactBinderRenames :: [(TypeBinderRef, TypeBinderRef)],
    envActiveSubtermConstruction :: Maybe PreparedSubtermGeneralization,
    envLocalGammaClosures :: IntMap.IntMap LocalGammaClosure,
    -- | Checked sibling-edge endpoints in the frozen witness domain.  These
    -- certificates let a later Graft consume the exact constructed type
    -- without re-reading a coarser final graph representative.
    envFrozenEndpointCertificates :: FrozenEndpointCertificates,
    -- | Expected endpoint supplied by the enclosing constructor, retaining
    -- whether it is checking-only or exact construction authority.
    envExpectedTermEndpoint :: Maybe ExpectedTermEndpoint,
    -- | When the current term is itself the source of one of Figure 15.3.5's
    -- application edges, retain which edge occurrence consumes it.  An
    -- application in either position must publish its prepared Gamma even
    -- when the resulting forall is vacuous; only an argument occurrence may
    -- publish a bound-matching exact specialization as derived @InstApp@.
    envApplicationSourceOccurrence :: Maybe ApplicationOccurrence
  }

-- | Project only the free ambient declarations named by an inherited exact
-- endpoint.  Its leading forall spine remains lexically owned by the child
-- term; unlike a prepared packet, the incoming endpoint does not authorize
-- installing those declarations in the current Gamma.
enterExactEndpointAmbientSourceBounds
  :: Set.Set TypeBinderIdentity
  -> [(TypeBinderRef, Maybe BoundType)]
  -> (NodeId -> NodeId)
  -> IntMap.IntMap TypeBinderRef
  -> Maybe ExpectedTermEndpoint
  -> Env
  -> Either ElabError Env
enterExactEndpointAmbientSourceBounds =
  enterExactEndpointSourceBounds False

-- | Source-project declarations that are about to enter Gamma as part of an
-- exact construction.  Unlike an inherited endpoint, this construction owns
-- its leading forall spine, so those declarations must normalize any existing
-- graph presentation before strict Gamma extension compares their bounds.
enterExactConstructionSourceBounds
  :: Set.Set TypeBinderIdentity
  -> [(TypeBinderRef, Maybe BoundType)]
  -> (NodeId -> NodeId)
  -> IntMap.IntMap TypeBinderRef
  -> Maybe ExpectedTermEndpoint
  -> Env
  -> Either ElabError Env
enterExactConstructionSourceBounds =
  enterExactEndpointSourceBounds True

enterExactEndpointSourceBounds
  :: Bool
  -> Set.Set TypeBinderIdentity
  -> [(TypeBinderRef, Maybe BoundType)]
  -> (NodeId -> NodeId)
  -> IntMap.IntMap TypeBinderRef
  -> Maybe ExpectedTermEndpoint
  -> Env
  -> Either ElabError Env
enterExactEndpointSourceBounds includeOwnedBinders sourceIdentities sourceDeclarations representative sourceBinderRefs mbEndpoint env =
  case mbEndpoint >>= exactConstructionExpectedType of
    Nothing -> pure env
    Just endpointTy -> do
      projectedTypeBindings <-
        traverseEndpointBindings
          "type Gamma"
          (envTypeBindings env)
      projectedSourceBindings <-
        traverseEndpointBindings
          "source-refined Gamma"
          (envSourceRefinedGammaBounds env)
      completedSourceBindingsWithFreeEndpoints <-
        foldM
          recordCompletedSourceDeclaration
          projectedSourceBindings
          (Map.toList projectedTypeBindings)
      pure
        env
          { envTypeBindings = projectedTypeBindings
          , envSourceRefinedGammaBounds =
              completedSourceBindingsWithFreeEndpoints
          }
      where
        ambientEndpointRefs =
          freeTypeVarRefsType endpointTy
            ++ if includeOwnedBinders
              then map fst (schemeBinderRefs (schemeFromType endpointTy))
              else []

        sourceOwnsResolvedRef ref =
          Set.member
            (typeBinderRefIdentity ref)
            sourceIdentities
            && any
              (typeBinderRefsSameIdentity ref)
              (IntMap.elems sourceBinderRefs)

        sourceDeclaresBound ref =
          any
            ( \(sourceRef, mbBound) ->
                isJust mbBound
                  && typeBinderRefsSameIdentity ref sourceRef
            )
            sourceDeclarations

        endpointUsesResolvedRef ref =
          sourceOwnsResolvedRef ref
            && sourceDeclaresBound ref
            && endpointCarriesResolvedRef ref

        endpointCarriesResolvedRef ref =
          any (typeBinderRefsSameIdentity ref) ambientEndpointRefs

        endpointUsesAmbientRef ref =
          sourceOwnsResolvedRef ref
            && sourceDeclaresBound ref
            && any
              (typeBinderRefsSameIdentity ref)
              ambientEndpointRefs

        resolveEndpointBindingRef owner =
          resolveConstructionGammaAlias
            ("exact endpoint source-bound " ++ owner)
            (envConstructionGammaAliases env)

        traverseEndpointBindings owner bindings = do
          sourceOccurrenceRenames <-
            either
              ( \cause ->
                  Left
                    ( ValidationFailed
                        [ "exact endpoint has ambiguous source-to-construction occurrence routes"
                        , "  owner: " ++ owner
                        , "  endpoint: " ++ show endpointTy
                        , "  cause: " ++ cause
                        ]
                    )
              )
              pure
              exactSourceOccurrenceRenames
          Map.traverseWithKey
            ( \ref bound -> do
                resolvedRef <- resolveEndpointBindingRef owner ref
                if endpointCarriesResolvedRef resolvedRef
                  then
                    case
                        projectSourceBinderDeclarationsInBound
                          sourceIdentities
                          representative
                          sourceBinderRefs
                          ( resolveSourceBinderAliasesInType
                              representative
                              exactSourceBinderRefs
                              ( applyTypeVarRefRenames
                                  sourceOccurrenceRenames
                                  bound
                              )
                          )
                      of
                        Left cause ->
                          Left
                            ( ValidationFailed
                                [ "exact endpoint has ambiguous source-bound Gamma construction"
                                , "  owner: " ++ owner
                                , "  endpoint: " ++ show endpointTy
                                , "  declaration: " ++ show ref
                                , "  bound: " ++ show bound
                                , "  cause: " ++ cause
                                ]
                            )
                        Right projectedBound ->
                          if endpointUsesResolvedRef resolvedRef
                            then
                              completeSourceDeclarationBound
                                owner
                                resolvedRef
                                projectedBound
                            else pure projectedBound
                  else pure bound
            )
            bindings

        -- The exact endpoint can own a graph declaration whose bound contains
        -- a free occurrence of a nested source binder.  Normalize that
        -- occurrence before strict Gamma insertion compares the declaration
        -- bounds.  Restrict the sidecar to the lexical source identities of
        -- this endpoint, and only visit declarations retained by the exact
        -- endpoint, so an unrelated ambient graph variable cannot acquire a
        -- source identity through representative equality alone.
        exactSourceBinderRefs =
          IntMap.filter
            ( (`Set.member` sourceIdentities)
                . typeBinderRefIdentity
            )
            sourceBinderRefs

        -- Source annotation and construction Gamma retain the same graph
        -- occurrence key on opposite sides of the quotient.  Compose those
        -- maps explicitly, then orient the result from the already-installed
        -- construction identity back to the source identity used by the
        -- certified endpoint bound.  Reject a construction identity reached
        -- by two distinct source declarations instead of selecting one by
        -- traversal order.
        exactSourceOccurrenceRenames = do
          sourceConstructionRenames <-
            sourceBinderConstructionRenamesRetainingAmbiguousSources
              representative
              exactSourceBinderRefs
              (envConstructionIdentityRoutes env)
          foldM invertSourceConstructionRoute [] sourceConstructionRenames

        invertSourceConstructionRoute
          renames
          (sourceRef, constructionRef) =
            case
                [ existingSourceRef
                | (existingConstructionRef, existingSourceRef) <- renames
                , typeBinderRefsSameIdentity
                    existingConstructionRef
                    constructionRef
                ]
              of
              [] -> pure ((constructionRef, sourceRef) : renames)
              existingSources
                | all
                    (typeBinderRefsSameIdentity sourceRef)
                    existingSources ->
                    pure renames
              existingSources ->
                Left
                  ( "construction identity has multiple source authorities: construction="
                      ++ show constructionRef
                      ++ ", sources="
                      ++ show (sourceRef : existingSources)
                  )

        completeSourceDeclarationBound owner ref incomingBound =
          case
              [ tyToElab sourceBound
              | (sourceRef, Just sourceBound) <- sourceDeclarations
              , typeBinderRefsSameIdentity ref sourceRef
              ]
            of
              [] -> pure incomingBound
              sourceBound : remainingBounds
                | not
                    ( all
                        (operationalEndpointTypesAgree sourceBound)
                        remainingBounds
                    ) ->
                    Left
                      ( ValidationFailed
                          [ "exact endpoint source identity has conflicting declared bounds"
                          , "  owner: " ++ owner
                          , "  endpoint: " ++ show endpointTy
                          , "  declaration: " ++ show ref
                          , "  source bounds: "
                              ++ show (sourceBound : remainingBounds)
                          ]
                      )
                | operationalEndpointTypesAgree incomingBound sourceBound ->
                    pure sourceBound
                | Just _ <-
                    constructExactInstantiation
                      (typeCheckEnvFrom env)
                      operationalEndpointTypesAgree
                      incomingBound
                      sourceBound ->
                    -- The exact source annotation supplies the target bound;
                    -- the checked xMLF construction supplies the M/N proof
                    -- that the frozen packet presentation reaches it.
                    pure sourceBound
                | otherwise ->
                    Left
                      ( ValidationFailed
                          [ "exact endpoint Gamma bound cannot construct its declared source bound"
                          , "  owner: " ++ owner
                          , "  endpoint: " ++ show endpointTy
                          , "  declaration: " ++ show ref
                          , "  frozen bound: " ++ show incomingBound
                          , "  source bound: " ++ show sourceBound
                          ]
                      )

        -- A selected exact endpoint can mention an ambient source binder
        -- freely rather than bind it in its leading forall spine.  The type
        -- Gamma projection above has nevertheless checked the frozen bound
        -- against that source declaration.  Publish the same proof in the
        -- capability map now, so transparent parent owners carry one exact
        -- declaration instead of later merging the projected source bound
        -- with a stale child graph presentation.
        recordCompletedSourceDeclaration bindings (existingRef, bound) = do
          resolvedRef <-
            resolveEndpointBindingRef
              "completed source-refined Gamma"
              existingRef
          if endpointUsesAmbientRef resolvedRef
            then insertSourceRefinement resolvedRef bound bindings
            else pure bindings

        insertSourceRefinement ref bound bindings =
          case
              [ (existingRef, existingBound)
              | (existingRef, existingBound) <- Map.toList bindings
              , typeBinderRefsSameIdentity ref existingRef
              ]
            of
              [] -> pure (Map.insert ref bound bindings)
              existing
                | all
                    (operationalEndpointTypesAgree bound . snd)
                    existing ->
                    pure
                      ( Map.insert ref bound
                          ( Map.mapWithKey
                              ( \existingRef existingBound ->
                                  if
                                      typeBinderRefsSameIdentity
                                        ref
                                        existingRef
                                    then bound
                                    else existingBound
                              )
                              bindings
                          )
                      )
                | otherwise ->
                    Left
                      ( ValidationFailed
                          [ "exact endpoint produced conflicting source-refined Gamma declarations"
                          , "  endpoint: " ++ show endpointTy
                          , "  declaration: " ++ show ref
                          , "  completed bound: " ++ show bound
                          , "  existing declarations: " ++ show existing
                          ]
                      )

-- | Complete the source-owned declarations in one exact downward endpoint.
-- The graph packet is frozen before source forall occurrences have necessarily
-- entered one representative class, so its bound may still use a purely graph
-- presentation.  The source declaration supplies the target presentation,
-- while the existing type-checking environment must construct an exact M/N
-- computation from the frozen bound to that target.  This happens before the
-- endpoint is installed in a child Gamma; no checked result is inspected.
completeExactEndpointSourceDeclarationBounds
  :: [(TypeBinderRef, Maybe BoundType)]
  -> Env
  -> ElabType
  -> Either ElabError ElabType
completeExactEndpointSourceDeclarationBounds sourceDeclarations env endpointTy = do
  completedBinders <- traverse completeBinder endpointBinders
  pure
    ( schemeToType
        ( mkElabSchemeWithRefs
            completedBinders
            (schemeBody endpointScheme)
        )
    )
  where
    endpointScheme = schemeFromType endpointTy
    endpointBinders = schemeBinderRefs endpointScheme

    completeBinder binder@(endpointRef, mbEndpointBound) =
      case
          [ sourceBound
          | (sourceRef, Just sourceBound) <- sourceDeclarations
          , typeBinderRefsSameIdentity endpointRef sourceRef
          ]
        of
          [] -> pure binder
          sourceBound : remainingBounds
            | not
                ( all
                    ( operationalEndpointTypesAgree
                        (tyToElab sourceBound)
                        . tyToElab
                    )
                    remainingBounds
                ) ->
                failure
                  endpointRef
                  [ "source identity has conflicting declared bounds"
                  , "  source bounds: "
                      ++ show (sourceBound : remainingBounds)
                  ]
            | otherwise -> do
                let sourceBoundTy = tyToElab sourceBound
                    frozenBoundTy = maybe TBottom tyToElab mbEndpointBound
                if
                    operationalEndpointTypesAgree
                      frozenBoundTy
                      sourceBoundTy
                  then pure (endpointRef, Just sourceBound)
                  else
                    case
                        constructExactInstantiation
                          (typeCheckEnvFrom env)
                          operationalEndpointTypesAgree
                          frozenBoundTy
                          sourceBoundTy
                      of
                        Just _ -> pure (endpointRef, Just sourceBound)
                        Nothing ->
                          failure
                            endpointRef
                            [ "frozen endpoint bound cannot construct the declared source bound"
                            , "  frozen bound: " ++ show frozenBoundTy
                            , "  source bound: " ++ show sourceBoundTy
                            ]

    failure ref details =
      Left
        ( ValidationFailed
            ( [ "exact endpoint cannot enter its source declaration"
              , "  endpoint: " ++ show endpointTy
              , "  declaration: " ++ show ref
              ]
                ++ details
            )
        )

type EnvBindingIdentityKey = ResolvedTermIdentityKey

data ElabOut = ElabOut
  { elabDetailed :: Env -> Either ElabError ElaboratedTerm,
    elabStripped :: Env -> Either ElabError XmlfTerm
  }

-- | Construction-time evidence published by the source constructor that
-- owns a completed local Gamma.  The exact binder spine is captured from the
-- construction input before the term is checked; the checked type then
-- validates that input.  Root generalization may use it to select among its
-- already planned binders, but must not infer new equalities from the final
-- type.
-- | Exact construction of a value returned beneath another constructor's
-- term-level result boundary.  In particular, a lambda body can already have
-- emitted a leading forall spine even though those declarations occur inside
-- the enclosing lambda's arrow codomain.  Keeping this narrow certificate
-- separate from 'OwnerFinalConstruction' prevents that nested spine from
-- being mistaken for declarations leading the enclosing term itself.
data ExactResultConstruction = ExactResultConstruction
  { ercOwner :: !LocalGammaOwner,
    ercConstructedType :: !ElabType,
    ercConstructedBinders :: ![(TypeBinderRef, Maybe BoundType)],
    ercBinderRoutes :: !(IntMap.IntMap TypeBinderRef),
    ercTypeAbstractionRefs :: ![TypeBinderRef],
    -- | Type identities introduced by value-lambda parameters on the exact
    -- returned-value path which remain open at this construction boundary.
    -- The originating lambda records these identities while its parameter
    -- type and checked term are both available; enclosing constructors only
    -- transport that positive evidence.
    ercOpenValueLambdaParameterRefs :: ![TypeBinderRef],
    ercReturnedResultConstruction :: !(Maybe ExactResultConstruction)
  }
  deriving (Eq, Show)

-- | An application result computation that has already been checked at the
-- exact owner boundary.  This is the positive evidence for carrying a child
-- result through an enclosing flexible result variable (the paper's outgoing
-- Hyp step); a type-environment equality alone is not construction evidence.
data CheckedResultEndpointConstruction = CheckedResultEndpointConstruction
  { crecOwner :: !LocalGammaOwner,
    crecSourceType :: !ElabType,
    crecComputation :: !Instantiation,
    crecTargetType :: !ElabType
  }
  deriving (Eq, Show)

-- | A provisional exact endpoint superseded while constructing and checking
-- one source constructor.  The source is not reconstructed from the checked
-- type: it is the directional endpoint supplied to that constructor before
-- its child was built.  The completed endpoint is the type actually published
-- by the checked constructor.  Enclosing constructors may replace only this
-- exact source, which keeps completion compositional without treating an
-- arbitrary final-type equality as construction authority.
data ExactEndpointCompletion = ExactEndpointCompletion
  { eecOwner :: !LocalGammaOwner,
    eecSourceEndpoint :: !ElabType,
    eecCompletedEndpoint :: !ElabType
  }
  deriving (Eq, Show)

data OwnerFinalConstruction = OwnerFinalConstruction
  { ofcOwner :: !LocalGammaOwner,
    -- | Enclosing owners that construction proved result-transparent while
    -- forwarding this exact checked result.  These owners may discharge
    -- their own local Gamma slots, but they do not acquire credit for the
    -- binders emitted by 'ofcOwner'.
    ofcTransparentResultOwners :: ![LocalGammaOwner],
    ofcConstructedType :: !ElabType,
    -- | The exact provisional endpoint replaced by this checked construction,
    -- when construction changed it.  This is deliberately separate from the
    -- owner's final type and from transparent-result ownership: neither one
    -- alone proves which earlier endpoint was superseded.
    ofcExactEndpointCompletion :: !(Maybe ExactEndpointCompletion),
    -- | Exact declarations emitted by the owner's checked term.  These are
    -- post-typecheck construction evidence, not a projection of
    -- 'ofcConstructedType': a transparent result coercion may consume an
    -- emitted forall while preserving the checked owner certificate.
    ofcLocallyEmittedBinders :: ![(TypeBinderRef, Maybe BoundType)],
    -- | Exact declarations emitted by this owner and then consumed by its
    -- checked completion computation.  They are no longer part of
    -- 'ofcConstructedType' or 'ofcConstructedBinderSpine', but an enclosing
    -- provisional packet must still know that the declaration was consumed
    -- rather than retained unbounded.
    ofcConsumedLocalBinders :: ![(TypeBinderRef, Maybe BoundType)],
    -- | Graph-node provenance for locally emitted binders.  A local
    -- constructor may publish a copied construction identity rather than the
    -- root planner's candidate identity; this route proves which planned
    -- graph occurrence that emitted binder discharges without quotienting the
    -- two identities globally.
    ofcLocalBinderRoutes :: !(IntMap.IntMap TypeBinderRef),
    -- | Leading declarations already emitted by the exact result child and
    -- carried through this owner.  They are part of the checked result spine,
    -- but they are not declarations emitted by this owner's local Gamma.
    -- Keeping this provenance separate prevents an enclosing identity
    -- application or transparent let from taking credit for a child's
    -- binder merely because it appears in the final type.
    ofcCarriedResultBinders :: ![(TypeBinderRef, Maybe BoundType)],
    -- | Exact graph-occurrence routes inherited with
    -- 'ofcCarriedResultBinders'.  These routes are captured from the child
    -- certificate before the enclosing term is checked; root closure never
    -- reconstructs them from the completed type.
    ofcCarriedResultBinderRoutes :: !(IntMap.IntMap TypeBinderRef),
    -- | Carried declarations whose exact outward identity is witnessed by
    -- an explicit type abstraction in the checked xMLF construction.  A
    -- source-owned binder has no graph node, so this evidence is deliberately
    -- disjoint from 'ofcCarriedResultBinderRoutes'.  Recording it here keeps
    -- root publication from accepting every node-less binder merely because
    -- it appears in the final type.
    ofcCarriedResultTypeAbstractionRefs :: ![TypeBinderRef],
    -- | Construction of the exact value returned beneath this owner's
    -- term-level boundary.  A direct lambda application can expose this value
    -- as its own result and promote the certificate without reconstructing a
    -- forall spine from the application type.
    ofcReturnedResultConstruction :: !(Maybe ExactResultConstruction),
    ofcUsedAmbientBinderRefs :: ![TypeBinderRef],
    -- | Exact source-sidecar occurrences proving that selected used ambient
    -- identities come from nested source annotations.  These routes authorize
    -- inheritance into an enclosing construction Gamma; they never authorize
    -- a local Gamma binder.  Keep them on the owner-final certificate so a
    -- zero-local application does not have to publish an otherwise unrelated
    -- local-Gamma certificate merely to preserve source provenance.
    ofcUsedSourceBinderAuthorities :: !(IntMap.IntMap SourceBinderAuthority),
    -- | Exact declarations available for ambient identities used by the
    -- checked owner construction.  Free graph candidates without a local
    -- declaration remain the ordinary generalizer's responsibility.  A later
    -- root may adopt only a published declaration whose identity is absent
    -- from its own incoming Gamma, so it never reconstructs a bound from a
    -- residual free variable.
    ofcAmbientDeclarationAuthorities :: ![AmbientGammaAuthority],
    -- | Ambient declarations selected by an exact enclosing construction
    -- packet.  Unlike an ordinary inherited authority, these may replace a
    -- provisional graph-shaped declaration carried by a child: the packet
    -- fixes both the identity and the source-owned bound before the child is
    -- specialized.  Transparent owners propagate this evidence unchanged.
    ofcAuthoritativeAmbientDeclarations :: ![AmbientGammaAuthority],
    -- | Exact source/application parameter boundaries carried by this
    -- checked result.  They justify substituting a stable graph parameter
    -- node by the exact type installed before its lambda body was checked
    -- when an enclosing Gamma declaration is completed.
    ofcLambdaParamBoundaryCertificates
      :: ![LambdaParamBoundaryCertificate],
    -- | Parameter boundary installed by this owner when the owner is a
    -- value lambda.  The aggregate list above is intentionally transitive;
    -- keeping the immediate certificate separate lets an enclosing Var-Abs
    -- construction validate a specific returned source lambda by owner and
    -- parameter identity without guessing from list position or type shape.
    ofcOwnLambdaParamBoundaryCertificate
      :: !(Maybe LambdaParamBoundaryCertificate),
    -- | Type identities occurring in a checked value-lambda parameter which
    -- remain open in this exact returned value.  This is constructor-time
    -- provenance for the paper's commuting Var-Abs step: an enclosing
    -- @Lambda(Gamma)@ may abstract one of these identities only when its
    -- prepared endpoint names that same identity.  It is deliberately not
    -- reconstructed from the final arrow type.
    ofcOpenValueLambdaParameterRefs :: ![TypeBinderRef],
    -- | Exact provisional ambient declarations completed while checking this
    -- owner's body.  Root planning consumes only these proof-bearing
    -- refinements; it never rediscovers a bound from the final term.
    ofcBodyConsumerBoundRefinements :: ![BodyConsumerBoundRefinementCertificate]
  }
  deriving (Eq, Show)

-- | Project the two disjoint construction-provenance domains onto the
-- declarations that the checked owner actually emitted.  A source-owned
-- forall has no graph identity of its own, while a graph-owned forall has no
-- source declaration authority.  Once either declaration is emitted, root
-- closure needs one uniform graph-occurrence route to that exact outward
-- identity.  Conflicting claims for one occurrence are rejected here, while
-- both authorities are still available, instead of being repaired from the
-- final type.  A graph-owned declaration intrinsically supplies its own
-- node-to-binder route; requiring a second alias entry would discard exact
-- declarations selected directly by an enclosing lambda plan.
ownerFinalLocalBinderRoutes
  :: String
  -> [TypeBinderRef]
  -> IntMap.IntMap TypeBinderRef
  -> IntMap.IntMap TypeBinderRef
  -> Either ElabError (IntMap.IntMap TypeBinderRef)
ownerFinalLocalBinderRoutes role emittedRefs graphRoutes sourceRoutes =
  if null missingEmittedRefs
    then pure projectedRoutes
    else
      Left
        ( ValidationFailed
            [ "owner-final construction loses binder provenance while projecting graph and source routes"
            , "  role: " ++ role
            , "  missing emitted binders: " ++ show missingEmittedRefs
            , "  emitted binders: " ++ show emittedRefs
            , "  graph routes: " ++ show graphRoutes
            , "  source routes: " ++ show sourceRoutes
            , "  projected routes: " ++ show projectedRoutes
            ]
        )
  where
    selectedGraphRoutes =
      IntMap.filter emitted graphRoutes
    selectedSourceRoutes =
      IntMap.filter emitted sourceRoutes
    emitted ref =
      any (typeBinderRefsSameIdentity ref) emittedRefs

    -- A delegated declaration can use one graph key in two different proof
    -- domains: the local Gamma route points from that key to the declaration
    -- whose bound contains the dependency, while the exact source sidecar
    -- identifies the dependency itself.  The source identity owns that exact
    -- occurrence.  The Gamma binder remains valid only when another graph
    -- route still proves its own emitted declaration; the completeness check
    -- below rejects a projection that would discard its sole authority.
    projectedRoutes =
      IntMap.union
        selectedSourceRoutes
        (IntMap.union selectedGraphRoutes intrinsicGraphRoutes)

    intrinsicGraphRoutes =
      IntMap.fromList
        [ (getNodeId node, emittedRef)
        | emittedRef <- emittedRefs
        , node <- maybeToList (typeBinderRefNode emittedRef)
        ]

    missingEmittedRefs =
      [ emittedRef
      | emittedRef <- emittedRefs
      , not
          ( any
              (typeBinderRefsSameIdentity emittedRef)
              (IntMap.elems projectedRoutes)
          )
      ]

ofcLocallyEmittedBinderRefs :: OwnerFinalConstruction -> [TypeBinderRef]
ofcLocallyEmittedBinderRefs =
  map fst . ofcLocallyEmittedBinders

ofcCarriedResultBinderRefs :: OwnerFinalConstruction -> [TypeBinderRef]
ofcCarriedResultBinderRefs =
  map fst . ofcCarriedResultBinders

-- | Open value-parameter identities whose originating constructor is still
-- on the exact returned-value path.  A wrapper can specialize or close a
-- child construction, so project the stored constructor evidence onto the
-- currently checked endpoint before exposing it to an enclosing lambda.
-- This filtering can discard stale evidence but cannot create new authority.
ownerFinalOpenValueLambdaParameterRefs
  :: OwnerFinalConstruction
  -> [TypeBinderRef]
ownerFinalOpenValueLambdaParameterRefs certificate =
  retainOpenValueLambdaParameterRefs
    (ofcConstructedType certificate)
    ( ofcOpenValueLambdaParameterRefs certificate
        ++ [ parameterRef
           | boundaryCertificate <-
               ofcLambdaParamBoundaryCertificates certificate
           , TVarRef parameterRef <-
               [ lambdaParamBoundaryConstructedType
                   boundaryCertificate
               ]
           ]
    )

-- | Open immutable source identities still used by the owner's exact checked
-- endpoint.  The source-authority map proves their origin; projecting it
-- through the constructed type discards routes already consumed by a child
-- specialization without inventing authority from the remaining type shape.
ownerFinalOpenSourceBinderRefs
  :: OwnerFinalConstruction
  -> [TypeBinderRef]
ownerFinalOpenSourceBinderRefs certificate =
  distinctBinderRefs
    [ sourceRef
    | sourceRef <- sourceAuthorityRefs ++ parameterBoundarySourceRefs
    , any
        (typeBinderRefsSameIdentity sourceRef)
        constructedOccurrenceRefs
    ]
  where
    sourceAuthorityRefs =
      map
        sourceBinderAuthorityConstructionRef
        (IntMap.elems (ofcUsedSourceBinderAuthorities certificate))
    parameterBoundarySourceRefs =
      concatMap
        lambdaParamBoundarySourceBinderRefs
        (ofcLambdaParamBoundaryCertificates certificate)
    constructedOccurrenceRefs =
      typeBinderDeclarationRefs (ofcConstructedType certificate)
        ++ freeTypeVarRefsType (ofcConstructedType certificate)

retainOpenValueLambdaParameterRefs
  :: ElabType
  -> [TypeBinderRef]
  -> [TypeBinderRef]
retainOpenValueLambdaParameterRefs constructedTy =
  distinctBinderRefs
    . filter
      ( \parameterRef ->
          any
            (typeBinderRefsSameIdentity parameterRef)
            (freeTypeVarRefsType constructedTy)
      )

-- | Complete leading binder spine certified by construction.  Local Gamma
-- binders surround the exact result child's already-constructed spine.
ofcConstructedBinderSpine
  :: OwnerFinalConstruction
  -> [(TypeBinderRef, Maybe BoundType)]
ofcConstructedBinderSpine certificate =
  ofcLocallyEmittedBinders certificate
    ++ ofcCarriedResultBinders certificate

-- | Complete route map paired with 'ofcConstructedBinderSpine'.  Constructors
-- validate colliding keys while composing certificates; the left-biased union
-- here merely preserves the enclosing owner's route presentation.
ofcConstructedBinderRoutes
  :: OwnerFinalConstruction
  -> IntMap.IntMap TypeBinderRef
ofcConstructedBinderRoutes certificate =
  IntMap.union
    (ofcLocalBinderRoutes certificate)
    (ofcCarriedResultBinderRoutes certificate)

-- | Complete declarations already present in an enclosing lambda endpoint
-- from the exact construction of its result owner.  A result-transparent let
-- can return a child lambda whose local @Gen(Gamma,tau)@ binder is the same
-- declaration that the enclosing packet exposed provisionally.  In that
-- case the paper construction does not nest the child's forall below the
-- enclosing arrow: it completes the matching declaration in the enclosing
-- binder spine.
--
-- The completed bound comes only from 'ofcConstructedBinderSpine'.  The
-- checked owner type validates that removing its leading binder spine reaches
-- the incoming codomain, while the recursively checked body validates that
-- this certificate belongs to the exact result being constructed.  Thus no
-- binder or bound is recovered from type shape after elaboration.
completeEnclosingLambdaEndpointFromResultOwnerConstruction
  :: (ElabType -> ElabType -> Bool)
  -> ElabType
  -> ElabType
  -> ElabType
  -> ElabType
  -> OwnerFinalConstruction
  -> Maybe ElabType
completeEnclosingLambdaEndpointFromResultOwnerConstruction typesAgree parameterTy bodySourceTy bodyResultTy incomingTy certificate = do
  let ownerTy = ofcConstructedType certificate
  guard
    ( typesAgree ownerTy bodySourceTy
        && typesAgree ownerTy bodyResultTy
    )
  let incomingScheme = schemeFromType incomingTy
      ownerScheme = schemeFromType ownerTy
      incomingBinders = schemeBinderRefs incomingScheme
      ownerBinders = schemeBinderRefs ownerScheme
      certifiedBinders = ofcConstructedBinderSpine certificate
  (incomingDomain, incomingCodomain) <-
    case schemeBody incomingScheme of
      TArrow domainTy codomainTy -> Just (domainTy, codomainTy)
      _ -> Nothing
  guard (typesAgree incomingDomain parameterTy)
  let resultOwnerCompletion =
        completeResultOwnerBinder incomingBinders incomingCodomain
  guard
    ( typesAgree (schemeBody ownerScheme) incomingCodomain
        || isJust resultOwnerCompletion
    )
  certifiedCompletedBinders <-
    traverse
      (completeCertifiedBinder ownerBinders incomingBinders)
      certifiedBinders
  guard
    ( case resultOwnerCompletion of
        Nothing -> True
        Just (resultRef, resultBound) ->
          all
            ( \(certifiedRef, certifiedBound) ->
                not
                  (typeBinderRefsSameIdentity resultRef certifiedRef)
                  || boundsAgree resultBound certifiedBound
            )
            certifiedCompletedBinders
    )
  let completedBinders =
        case resultOwnerCompletion of
          Nothing -> certifiedCompletedBinders
          Just resultBinder ->
            resultBinder
              : filter
                ( not
                    . typeBinderRefsSameIdentity (fst resultBinder)
                    . fst
                )
                certifiedCompletedBinders
  let completedIncomingBinders =
        map (completeIncomingBinder completedBinders) incomingBinders
  pure
    ( schemeToType
        ( mkElabSchemeWithRefs
            completedIncomingBinders
            (TArrow incomingDomain incomingCodomain)
        )
    )
  where
    boundsAgree leftBound rightBound =
      typesAgree
        (maybe TBottom tyToElab leftBound)
        (maybe TBottom tyToElab rightBound)

    -- An application body can finish at a concrete type while its enclosing
    -- lambda packet still names that result by the graph declaration allocated
    -- for the application node.  The owner identity is the construction-time
    -- link between those two views: it is stronger than a coincidental type
    -- match and survives after the result variable has disappeared from the
    -- checked term.  Complete only that exact, unambiguous declaration, and
    -- reject a circular or non-bound endpoint.
    completeResultOwnerBinder incomingBinders incomingCodomain =
      completeOwnedResultBinder
        (ofcOwner certificate)
        (ofcConstructedType certificate)
        incomingCodomain
        <|> do
          returnedConstruction <- ofcReturnedResultConstruction certificate
          completeReturnedResultBinderAlong
            incomingCodomain
            (schemeBody (schemeFromType (ofcConstructedType certificate)))
            returnedConstruction
      where
        -- A value-lambda owner can return a result whose own application/let
        -- owner is the graph identity retained by the enclosing packet.  Walk
        -- only the exact returned-result chain recorded by the owner-final
        -- certificate, and only through matching value-arrow codomains.  This
        -- completes the declaration where it is born; no result type is
        -- recovered from the checked lambda after construction.
        completeReturnedResultBinderAlong
          incomingView
          constructedView
          returnedConstruction
            | typesAgree
                constructedView
                (ercConstructedType returnedConstruction) =
                completeOwnedResultBinder
                  (ercOwner returnedConstruction)
                  (ercConstructedType returnedConstruction)
                  incomingView
                  <|> do
                    nestedConstruction <-
                      ercReturnedResultConstruction returnedConstruction
                    completeReturnedResultBinderAlong
                      incomingView
                      constructedView
                      nestedConstruction
            | otherwise = do
                TArrow incomingDomain incomingResult <- pure incomingView
                TArrow constructedDomain constructedResult <- pure constructedView
                guard (typesAgree incomingDomain constructedDomain)
                completeReturnedResultBinderAlong
                  incomingResult
                  constructedResult
                  returnedConstruction

        completeOwnedResultBinder resultOwner constructedBoundTy incomingView = do
          resultRef <-
            case incomingView of
              TVarRef ref -> Just ref
              _ -> Nothing
          resultNode <- typeBinderRefNode resultRef
          guard (resultNode == lgoTermNode resultOwner)
          completeResultBinder resultRef constructedBoundTy

        completeResultBinder resultRef constructedBoundTy = do
          [(incomingRef, incomingBound)] <-
            pure
              [ binder
              | binder@(candidateRef, _) <- incomingBinders
              , typeBinderRefsSameIdentity resultRef candidateRef
              ]
          guard
            ( not
                ( any
                    (typeBinderRefsSameIdentity incomingRef)
                    ( typeBinderDeclarationRefs constructedBoundTy
                        ++ freeTypeVarRefsType constructedBoundTy
                    )
                )
            )
          constructedBound <-
            either (const Nothing) Just (elabToBound constructedBoundTy)
          completedBound <-
            case incomingBound of
              Nothing -> Just constructedBound
              Just bound
                | typesAgree (tyToElab bound) constructedBoundTy -> Just bound
              _ -> Nothing
          pure (incomingRef, Just completedBound)

    completeCertifiedBinder ownerBinders incomingBinders (certifiedRef, certifiedBound) = do
      [(incomingRef, incomingBound)] <-
        pure
          [ binder
          | binder@(candidateRef, _) <- incomingBinders
          , typeBinderRefsSameIdentity certifiedRef candidateRef
          ]
      (_, ownerBound) <-
        case
          [ binder
          | binder@(ownerRef, _) <- ownerBinders
          , typeBinderRefsSameIdentity certifiedRef ownerRef
          ]
        of
          [ownerBinder] -> Just ownerBinder
          _ -> Nothing
      guard (boundsAgree certifiedBound ownerBound)
      completedBound <-
        case (incomingBound, certifiedBound) of
          (Nothing, Just bound) -> Just (Just bound)
          _
            | boundsAgree incomingBound certifiedBound ->
                Just incomingBound
            | otherwise -> Nothing
      pure (incomingRef, completedBound)

    completeIncomingBinder completedBinders binder@(incomingRef, _) =
      case
          [ completedBinder
          | completedBinder@(completedRef, _) <- completedBinders
          , typeBinderRefsSameIdentity incomingRef completedRef
          ]
        of
        [completedBinder] -> completedBinder
        _ -> binder

-- | Remove provisional enclosing declarations which the checked result owner
-- emitted and then consumed in its exact completion computation.  The
-- consumed-declaration certificate supplies identity and bound authority;
-- the incoming endpoint supplies only the lexical slot to discharge.
completeEnclosingLambdaEndpointFromConsumedResultConstruction
  :: (ElabType -> ElabType -> Bool)
  -> ElabType
  -> ElabType
  -> ElabType
  -> ElabType
  -> OwnerFinalConstruction
  -> Maybe ElabType
completeEnclosingLambdaEndpointFromConsumedResultConstruction typesAgree parameterTy bodySourceTy bodyResultTy incomingTy certificate = do
  let ownerTy = ofcConstructedType certificate
      incomingScheme = schemeFromType incomingTy
      incomingBinders = schemeBinderRefs incomingScheme
      ownerRefs =
        typeBinderDeclarationRefs ownerTy
          ++ freeTypeVarRefsType ownerTy
      matchingConsumedBinders =
        [ (incomingRef, incomingBound, consumedRef, consumedBound)
        | (incomingRef, incomingBound) <- incomingBinders
        , (consumedRef, consumedBound) <- ofcConsumedLocalBinders certificate
        , typeBinderRefsSameIdentity incomingRef consumedRef
        ]
  guard
    ( typesAgree ownerTy bodySourceTy
        && typesAgree ownerTy bodyResultTy
        && not (null matchingConsumedBinders)
    )
  (incomingDomain, incomingCodomain) <-
    case schemeBody incomingScheme of
      TArrow domainTy codomainTy -> Just (domainTy, codomainTy)
      _ -> Nothing
  guard (typesAgree incomingDomain parameterTy)
  guard (exactLambdaSpineConstructsEndpoint incomingCodomain ownerTy)
  guard
    ( all
        ( \(_, incomingBound, consumedRef, consumedBound) ->
            not
              ( any
                  (typeBinderRefsSameIdentity consumedRef)
                  ownerRefs
              )
              && case incomingBound of
                Nothing -> True
                Just _ ->
                  typesAgree
                    (maybe TBottom tyToElab incomingBound)
                    (maybe TBottom tyToElab consumedBound)
        )
        matchingConsumedBinders
    )
  let consumedRefs =
        [ consumedRef
        | (_, _, consumedRef, _) <- matchingConsumedBinders
        ]
      retainedBinders =
        [ binder
        | binder@(incomingRef, _) <- incomingBinders
        , not
            ( any
                (typeBinderRefsSameIdentity incomingRef)
                consumedRefs
            )
        ]
  pure
    ( schemeToType
        ( mkElabSchemeWithRefs
            retainedBinders
            (TArrow incomingDomain incomingCodomain)
        )
    )

-- | Replace a provisional enclosing codomain by the exact value construction
-- returned by the checked body owner.  This is the term-level counterpart of
-- carrying a child's leading forall spine through a direct lambda
-- application: the prepared endpoint and the checked result may arrange the
-- same construction identities differently, but only the child certificate
-- owns the emitted binders, routes, and type abstractions.
--
-- The replacement is deliberately identity-exact.  Both codomains must name
-- precisely the same declaration/free-reference identities, at least one of
-- those identities must be anchored by the returned construction, and no
-- enclosing binder may be captured by the returned value.  Thus this cannot
-- turn an unrelated same-shaped body type into an enclosing endpoint.
completeEnclosingLambdaEndpointFromReturnedResultConstruction
  :: (ElabType -> ElabType -> Bool)
  -> ElabType
  -> ElabType
  -> ElabType
  -> ElabType
  -> OwnerFinalConstruction
  -> Maybe ElabType
completeEnclosingLambdaEndpointFromReturnedResultConstruction typesAgree parameterTy bodySourceTy bodyResultTy incomingTy certificate = do
  returnedConstruction <- ofcReturnedResultConstruction certificate
  let returnedTy = ercConstructedType returnedConstruction
  guard
    ( typesAgree returnedTy bodySourceTy
        && typesAgree returnedTy bodyResultTy
    )
  let incomingScheme = schemeFromType incomingTy
      incomingBinders = schemeBinderRefs incomingScheme
  (incomingDomain, incomingCodomain) <-
    case schemeBody incomingScheme of
      TArrow domainTy codomainTy -> Just (domainTy, codomainTy)
      _ -> Nothing
  guard (typesAgree incomingDomain parameterTy)
  let routeReturnedConstructionRef ref =
        fromMaybe ref $ do
          node <- typeBinderRefNode ref
          IntMap.lookup
            (getNodeId node)
            (ercBinderRoutes returnedConstruction)
      incomingCodomainRefs = constructionIdentityRefs incomingCodomain
      routedIncomingCodomainRefs =
        map routeReturnedConstructionRef incomingCodomainRefs
      returnedRefs = constructionIdentityRefs returnedTy
      returnedAnchors =
        distinctBinderRefs
          ( IntMap.elems (ercBinderRoutes returnedConstruction)
              ++ ercTypeAbstractionRefs returnedConstruction
          )
      enclosingRefs = map fst incomingBinders
  guard (not (null returnedAnchors))
  guard (sameIdentitySet routedIncomingCodomainRefs returnedRefs)
  guard
    ( all
        (`refOccursIn` returnedRefs)
        returnedAnchors
    )
  guard
    ( all
        (not . (`refOccursIn` returnedRefs))
        enclosingRefs
    )
  pure
    ( schemeToType
        ( mkElabSchemeWithRefs
            incomingBinders
            (TArrow incomingDomain returnedTy)
        )
    )
  where
    constructionIdentityRefs ty =
      distinctBinderRefs
        (typeBinderDeclarationRefs ty ++ freeTypeVarRefsType ty)

    refOccursIn ref =
      any (typeBinderRefsSameIdentity ref)

    sameIdentitySet left right =
      all (`refOccursIn` right) left
        && all (`refOccursIn` left) right

forwardOwnerFinalConstructionThrough
  :: LocalGammaOwner
  -> OwnerFinalConstruction
  -> OwnerFinalConstruction
forwardOwnerFinalConstructionThrough transparentOwner certificate
  | transparentOwner == ofcOwner certificate = certificate
  | transparentOwner `elem` ofcTransparentResultOwners certificate = certificate
  | otherwise =
      certificate
        { ofcTransparentResultOwners =
            transparentOwner : ofcTransparentResultOwners certificate
        }

-- | Add the exact forall declarations constructed by a source annotation to
-- the checked child's result provenance.  These declarations are neither a
-- local @Gen(Gamma,tau)@ emission nor ambient: the annotation's explicit
-- xMLF abstraction owns them.  Match them against the checked result while
-- both the source scheme and constructed term endpoint are available, so a
-- transparent owner never has to recover them from final type shape.
carrySourceAnnotationResultBinders
  :: String
  -> ElabScheme
  -> ElabType
  -> OwnerFinalConstruction
  -> Either ElabError OwnerFinalConstruction
carrySourceAnnotationResultBinders role annotationScheme checkedType certificate
  | null annotationBinders = pure certificate
  | otherwise = do
      checkedAnnotationBinders <- traverse checkedAnnotationBinder annotationBinders
      carriedBinders <-
        foldM insertCarriedBinder existingCarried checkedAnnotationBinders
      let orderedCarriedBinders =
            [ checkedBinder
            | checkedBinder <- checkedBinders
            , any
                (constructionBindersAgree checkedBinder)
                carriedBinders
            ]
          constructionInputBinders =
            localBinders ++ orderedCarriedBinders
          checkedConstructionPrefix =
            take (length constructionInputBinders) checkedBinders
      unless
        ( length orderedCarriedBinders == length carriedBinders
            && length checkedConstructionPrefix
              == length constructionInputBinders
            && and
              ( zipWith
                  constructionBindersAgree
                  constructionInputBinders
                  checkedConstructionPrefix
              )
        )
        ( constructionFailure
            [ "annotation result binder order disagrees with the checked construction"
            , "  construction input: " ++ show constructionInputBinders
            , "  checked prefix: " ++ show checkedConstructionPrefix
            ]
        )
      carriedRoutes <-
        mergeOwnerFinalConstructedBinderRoutes
          role
          (ofcCarriedResultBinderRoutes certificate)
          ( IntMap.fromList
              [ (getNodeId node, ref)
              | (ref, _) <- orderedCarriedBinders
              , node <- maybeToList (typeBinderRefNode ref)
              ]
          )
      pure
        certificate
          { ofcCarriedResultBinders = orderedCarriedBinders
          , ofcCarriedResultBinderRoutes = carriedRoutes
          , ofcCarriedResultTypeAbstractionRefs =
              distinctBinderRefs
                ( ofcCarriedResultTypeAbstractionRefs certificate
                    ++ [ ref
                       | (ref, _) <- checkedAnnotationBinders
                       , not
                           ( any
                               (typeBinderRefsSameIdentity ref . fst)
                               localBinders
                           )
                       ]
                )
          }
  where
    annotationBinders = schemeBinderRefs annotationScheme
    checkedBinders = schemeBinderRefs (schemeFromType checkedType)
    localBinders = ofcLocallyEmittedBinders certificate
    existingCarried = ofcCarriedResultBinders certificate

    checkedAnnotationBinder annotationBinder =
      case filter (constructionBindersAgree annotationBinder) checkedBinders of
        [checkedBinder] -> pure checkedBinder
        matches ->
          constructionFailure
            [ "source annotation binder has no unique checked declaration"
            , "  annotation binder: " ++ show annotationBinder
            , "  matches: " ++ show matches
            ]

    insertCarriedBinder carried incoming@(incomingRef, incomingBound)
      | any
          (typeBinderRefsSameIdentity incomingRef . fst)
          localBinders =
          pure carried
      | otherwise =
          case find (typeBinderRefsSameIdentity incomingRef . fst) carried of
            Nothing -> pure (carried ++ [incoming])
            Just (_, existingBound)
              | boundsAgree existingBound incomingBound -> pure carried
              | otherwise ->
                  constructionFailure
                    [ "source annotation conflicts with an existing carried declaration"
                    , "  incoming: " ++ show incoming
                    , "  existing bound: " ++ show existingBound
                    ]

    constructionBindersAgree
      (leftRef, leftBound)
      (rightRef, rightBound) =
        typeBinderRefsSameIdentity leftRef rightRef
          && boundsAgree leftBound rightBound

    boundsAgree left right =
      operationalEndpointTypesAgree
        (maybe TBottom tyToElab left)
        (maybe TBottom tyToElab right)

    constructionFailure :: [String] -> Either ElabError a
    constructionFailure details =
      Left
        ( ValidationFailed
            ( [ "cannot carry source annotation result construction through "
                  ++ role
              , "  annotation scheme: " ++ show annotationScheme
              , "  checked type: " ++ show checkedType
              , "  child owner: " ++ show (ofcOwner certificate)
              ]
                ++ details
            )
        )

-- | Preserve the still-leading binder spine of an exact result child beneath
-- declarations emitted by an enclosing owner.  Both halves are construction
-- inputs: @enclosingBinders@ is the spine wrapped around the term, while the
-- child certificate records the declarations already present in the returned
-- value.  The checked result is used only to validate their composition and
-- any explicit leading-forall elimination; it never creates binder authority.
carryOwnerFinalResultBindersThrough
  :: String
  -> [(TypeBinderRef, Maybe BoundType)]
  -> [TypeBinderRef]
  -> ElabType
  -> OwnerFinalConstruction
  -> Either
      ElabError
      ( [(TypeBinderRef, Maybe BoundType)]
      , [(TypeBinderRef, Maybe BoundType)]
      , IntMap.IntMap TypeBinderRef
      , [TypeBinderRef]
      )
carryOwnerFinalResultBindersThrough role enclosingBinders explicitTypeAbstractionRefs completedType childCertificate =
  carryExactResultBindersThrough
    role
    enclosingBinders
    explicitTypeAbstractionRefs
    completedType
    []
    (exactResultConstructionFromOwner childCertificate)

exactResultConstructionFromOwner
  :: OwnerFinalConstruction
  -> ExactResultConstruction
exactResultConstructionFromOwner certificate =
  ExactResultConstruction
    { ercOwner = ofcOwner certificate
    , ercConstructedType = ofcConstructedType certificate
    , ercConstructedBinders = ofcConstructedBinderSpine certificate
    , ercBinderRoutes = ofcConstructedBinderRoutes certificate
    , ercTypeAbstractionRefs =
        distinctBinderRefs
          ( ofcLocallyEmittedBinderRefs certificate
              ++ ofcCarriedResultTypeAbstractionRefs certificate
          )
    , ercOpenValueLambdaParameterRefs =
        ownerFinalOpenValueLambdaParameterRefs certificate
    , ercReturnedResultConstruction =
        ofcReturnedResultConstruction certificate
    }

-- | Exact result-owner endpoints reachable through the checked owner's
-- returned-value chain.  The chain itself is construction provenance stored
-- on 'OwnerFinalConstruction'; callers use this projection only to match a
-- separately prepared source-lambda authority by owner identity.
ownerFinalReturnedResultEndpoints
  :: OwnerFinalConstruction
  -> [(LocalGammaOwner, ElabType)]
ownerFinalReturnedResultEndpoints certificate =
  go (ofcReturnedResultConstruction certificate)
  where
    go Nothing = []
    go (Just resultConstruction) =
      ( ercOwner resultConstruction
      , ercConstructedType resultConstruction
      )
        : go (ercReturnedResultConstruction resultConstruction)

-- | Project a child owner certificate into the exact value returned by an
-- enclosing term constructor.  The child certificate, not the returned type,
-- supplies every binder and route; the returned endpoint only validates that
-- this is the same construction.
exactReturnedResultConstruction
  :: ElabType
  -> OwnerFinalConstruction
  -> Maybe ExactResultConstruction
exactReturnedResultConstruction returnedType certificate =
  ( do
      guard
        ( operationalEndpointTypesAgree
            (ercConstructedType baseConstruction)
            returnedType
        )
      retainExactConstruction baseConstruction
  )
    <|> do
      plan <-
        planExactBinderSpine
          operationalEndpointTypesAgree
          (ercConstructedType baseConstruction)
          returnedType
      let alignedConstruction =
            renameExactResultConstructionBinderRefPayloads
              (exactBinderSpineRenames plan)
              baseConstruction
      reachedType <-
        either
          (const Nothing)
          Just
          ( applyInstantiation
              (ercConstructedType alignedConstruction)
              (exactBinderSpineInstantiation plan)
          )
      guard
        ( operationalEndpointTypesAgree
            reachedType
            returnedType
        )
      retainExactConstruction alignedConstruction
  where
    baseConstruction = exactResultConstructionFromOwner certificate
    returnedBinders = schemeBinderRefs (schemeFromType returnedType)

    retainExactConstruction construction = do
      certifiedReturnedBinders <-
        traverse
          (uniqueCertifiedBinder construction)
          returnedBinders
      let returnedRefs = map fst certifiedReturnedBinders
          retainedRoutes =
            IntMap.filter
              ( \ref ->
                  any
                    (typeBinderRefsSameIdentity ref)
                    returnedRefs
              )
              (ercBinderRoutes construction)
          retainedTypeAbstractionRefs =
            [ ref
            | ref <- ercTypeAbstractionRefs construction
            , any
                (typeBinderRefsSameIdentity ref)
                returnedRefs
            ]
          retainedOpenValueLambdaParameterRefs =
            [ ref
            | ref <- ercOpenValueLambdaParameterRefs construction
            , any
                (typeBinderRefsSameIdentity ref)
                (freeTypeVarRefsType returnedType)
            ]
      pure
        construction
          { ercConstructedType = returnedType
          , ercConstructedBinders = certifiedReturnedBinders
          , ercBinderRoutes = retainedRoutes
          , ercTypeAbstractionRefs = retainedTypeAbstractionRefs
          , ercOpenValueLambdaParameterRefs =
              retainedOpenValueLambdaParameterRefs
          }

    uniqueCertifiedBinder construction returnedBinder = do
      [certifiedBinder] <-
        pure
          ( filter
              (constructionBindersAgree returnedBinder)
              (ercConstructedBinders construction)
          )
      pure certifiedBinder

    constructionBindersAgree
      (leftRef, leftBound)
      (rightRef, rightBound) =
        typeBinderRefsSameIdentity leftRef rightRef
          && operationalEndpointTypesAgree
            (maybe TBottom tyToElab leftBound)
            (maybe TBottom tyToElab rightBound)

-- | Extend a checked child-result certificate through the exact type
-- abstractions that an enclosing value lambda inserted around its body.  The
-- abstraction list and graph routes come from the selected construction plan,
-- before the enclosing lambda is checked; the checked returned type only
-- validates that those declarations still form its complete leading spine.
-- This is the construction evidence needed when a direct lambda application
-- exposes a polymorphic value that was open in the recursively checked child.
constructReturnedResultThroughBodyAbstractions
  :: String
  -> LocalGammaOwner
  -> [(TypeBinderRef, Maybe BoundType)]
  -> IntMap.IntMap TypeBinderRef
  -> ElabType
  -> OwnerFinalConstruction
  -> Either ElabError (Maybe ExactResultConstruction)
constructReturnedResultThroughBodyAbstractions role owner bodyAbstractions bodyAbstractionRoutes returnedType childCertificate
  | null bodyAbstractions = pure Nothing
  | not constructionMatchesReturnedType = pure Nothing
  | otherwise = do
      combinedRoutes <-
        mergeOwnerFinalConstructedBinderRoutes
          role
          bodyAbstractionRoutes
          (ercBinderRoutes childConstruction)
      pure
        ( Just
            ExactResultConstruction
              { ercOwner = owner
              , ercConstructedType = returnedType
              , ercConstructedBinders = returnedBinders
              , ercBinderRoutes = combinedRoutes
              , ercTypeAbstractionRefs =
                  distinctBinderRefs
                    ( map fst bodyAbstractions
                        ++ ercTypeAbstractionRefs childConstruction
                    )
              , ercOpenValueLambdaParameterRefs =
                  retainOpenValueLambdaParameterRefs
                    returnedType
                    (ercOpenValueLambdaParameterRefs childConstruction)
              , ercReturnedResultConstruction = Just childConstruction
              }
        )
  where
    childConstruction = exactResultConstructionFromOwner childCertificate
    constructedType =
      schemeToType
        ( mkElabSchemeWithRefs
            bodyAbstractions
            (ercConstructedType childConstruction)
        )
    constructedBinders =
      bodyAbstractions ++ ercConstructedBinders childConstruction
    returnedBinders = schemeBinderRefs (schemeFromType returnedType)
    constructionMatchesReturnedType =
      operationalEndpointTypesAgree constructedType returnedType
        && length constructedBinders == length returnedBinders
        && and
          ( zipWith
              constructionBindersAgree
              constructedBinders
              returnedBinders
          )
        && null (duplicateBinderDeclarations constructedBinders)

    constructionBindersAgree
      (leftRef, leftBound)
      (rightRef, rightBound) =
        typeBinderRefsSameIdentity leftRef rightRef
          && operationalEndpointTypesAgree
            (maybe TBottom tyToElab leftBound)
            (maybe TBottom tyToElab rightBound)

carryExactResultBindersThrough
  :: String
  -> [(TypeBinderRef, Maybe BoundType)]
  -> [TypeBinderRef]
  -> ElabType
  -> [CheckedResultEndpointConstruction]
  -> ExactResultConstruction
  -> Either
      ElabError
      ( [(TypeBinderRef, Maybe BoundType)]
      , [(TypeBinderRef, Maybe BoundType)]
      , IntMap.IntMap TypeBinderRef
      , [TypeBinderRef]
      )
carryExactResultBindersThrough role enclosingBinders explicitTypeAbstractionRefs completedType endpointConstructions resultConstruction = do
  unless
    ( and
        ( zipWith
            constructionBindersAgree
            enclosingBinders
            checkedEnclosingBinders
        )
        && length checkedEnclosingBinders == length enclosingBinders
    )
    ( constructionFailure
        [ "enclosing binder prefix does not match the checked result"
        , "  expected prefix: " ++ show enclosingBinders
        , "  checked prefix: " ++ show checkedEnclosingBinders
        ]
    )
  let enclosingBinderMatches =
        [ (binder, filter (constructionBindersAgree binder) certifiedChildBinders)
        | binder <- enclosingBinders
        ]
      duplicateEnclosingClaims =
        [ (binder, matches)
        | (binder, matches) <- enclosingBinderMatches
        , length matches > 1
        ]
  unless (null duplicateEnclosingClaims) $
    constructionFailure
      [ "enclosing binder has duplicate child construction certificates"
      , "  duplicate claims: " ++ show duplicateEnclosingClaims
      ]
  let localEnclosingBinders =
        [ binder
        | (binder, matches) <- enclosingBinderMatches
        , null matches
        ]
      delegatedChildBinders =
        [ certifiedBinder
        | (_, [certifiedBinder]) <- enclosingBinderMatches
        ]
      carriedResultType =
        schemeToType
          ( mkElabSchemeWithRefs
              (delegatedChildBinders ++ carriedBinders)
              (schemeBody completedScheme)
          )
      childConstructsCarriedResult =
        operationalEndpointTypesAgree childType carriedResultType
          || isJust
            ( planExactBinderSpine
                operationalEndpointTypesAgree
                childType
                carriedResultType
            )
          || any
            (checkedEndpointConstructionReaches carriedResultType)
            endpointConstructions
  unless childConstructsCarriedResult $
    constructionFailure
      [ "child construction does not reach the carried result endpoint"
      , "  child type: " ++ show childType
      , "  carried result type: " ++ show carriedResultType
      ]
  certifiedTrailingBinders <-
    catMaybes <$> traverse selectCertifiedCarriedBinder carriedBinders
  let certifiedCarriedBinders =
        delegatedChildBinders ++ certifiedTrailingBinders
      carriedRefs = map fst certifiedCarriedBinders
      carriedTypeAbstractionRefs =
        distinctBinderRefs
          [ ref
          | ref <- carriedRefs
          , any
              (typeBinderRefsSameIdentity ref)
              ( explicitTypeAbstractionRefs
                  ++ ercTypeAbstractionRefs resultConstruction
              )
          ]
      childCarriedRoutes =
        IntMap.filter
          ( \routedRef ->
              any
                (typeBinderRefsSameIdentity routedRef)
                carriedRefs
          )
          (ercBinderRoutes resultConstruction)
      intrinsicCarriedRoutes =
        IntMap.fromList
          [ (getNodeId node, ref)
          | ref <- carriedRefs
          , node <- maybeToList (typeBinderRefNode ref)
          ]
  carriedRoutes <-
    mergeOwnerFinalConstructedBinderRoutes
      role
      childCarriedRoutes
      intrinsicCarriedRoutes
  let
      missingRoutes =
        [ ref
        | ref <- carriedRefs
        , isJust (typeBinderRefNode ref)
        , not
            ( any
                (typeBinderRefsSameIdentity ref)
                (IntMap.elems carriedRoutes)
            )
        ]
  unless (null missingRoutes) $
    constructionFailure
      [ "carried result binder has no child construction route"
      , "  missing binders: " ++ show missingRoutes
      , "  child routes: "
          ++ show (ercBinderRoutes resultConstruction)
      ]
  pure
    ( localEnclosingBinders
    , certifiedCarriedBinders
    , carriedRoutes
    , carriedTypeAbstractionRefs
    )
  where
    completedScheme = schemeFromType completedType
    completedBinders = schemeBinderRefs completedScheme
    checkedEnclosingBinders =
      take (length enclosingBinders) completedBinders
    carriedBinders =
      drop (length enclosingBinders) completedBinders
    childType = ercConstructedType resultConstruction
    checkedEndpointConstructionReaches targetType construction =
      operationalEndpointTypesAgree
        childType
        (crecSourceType construction)
        && operationalEndpointTypesAgree
          targetType
          (crecTargetType construction)
        && case
          applyInstantiation
            (crecSourceType construction)
            (crecComputation construction)
          of
            Right reachedType ->
              operationalEndpointTypesAgree
                reachedType
                (crecTargetType construction)
            Left _ -> False
    certifiedChildBinders = ercConstructedBinders resultConstruction

    selectCertifiedCarriedBinder checkedBinder =
      case filter (constructionBindersAgree checkedBinder) certifiedChildBinders of
        [certifiedBinder] -> pure (Just certifiedBinder)
        -- A checked result may also start with source-annotation binders.
        -- They remain owned by the source ABI and are deliberately absent
        -- from the child owner's construction certificate; root annotation
        -- publication handles them through its separate source provenance.
        []
          | any
              (typeBinderRefsSameIdentity (fst checkedBinder))
              explicitTypeAbstractionRefs ->
              -- The checked xMLF term itself contains this exact ETyAbs.
              -- Source annotations can construct such a binder without a
              -- graph route or a child local-Gamma certificate; the explicit
              -- declaration plus the successful checked result is its
              -- construction authority.
              pure (Just checkedBinder)
          | otherwise -> pure Nothing
        matches ->
          constructionFailure
            [ "checked result binder has duplicate child construction certificates"
            , "  checked binder: " ++ show checkedBinder
            , "  matches: " ++ show matches
            ]

    constructionBindersAgree
      (leftRef, leftBound)
      (rightRef, rightBound) =
        typeBinderRefsSameIdentity leftRef rightRef
          && boundsAgree leftBound rightBound

    boundsAgree left right =
      let leftTy = maybe TBottom tyToElab left
          rightTy = maybe TBottom tyToElab right
       in operationalEndpointTypesAgree leftTy rightTy

    constructionFailure :: [String] -> Either ElabError a
    constructionFailure details =
      Left
        ( ValidationFailed
            ( [ "cannot carry an exact child result construction through "
                  ++ role
              , "  child owner: " ++ show (ercOwner resultConstruction)
              , "  completed type: " ++ show completedType
              , "  enclosing binders: " ++ show enclosingBinders
              , "  child binders: "
                  ++ show (ercConstructedBinders resultConstruction)
              , "  checked endpoint constructions: "
                  ++ show endpointConstructions
              ]
                ++ details
            )
        )

mergeOwnerFinalConstructedBinderRoutes
  :: String
  -> IntMap.IntMap TypeBinderRef
  -> IntMap.IntMap TypeBinderRef
  -> Either ElabError (IntMap.IntMap TypeBinderRef)
mergeOwnerFinalConstructedBinderRoutes role localRoutes carriedRoutes =
  foldM insertRoute localRoutes (IntMap.toList carriedRoutes)
  where
    insertRoute routes (nodeKey, incomingRef) =
      case IntMap.lookup nodeKey routes of
        Nothing -> pure (IntMap.insert nodeKey incomingRef routes)
        Just existingRef
          | typeBinderRefsSameIdentity existingRef incomingRef -> pure routes
          | otherwise ->
              Left
                ( ValidationFailed
                    [ "owner-final construction has conflicting binder routes"
                    , "  role: " ++ role
                    , "  graph node: " ++ show nodeKey
                    , "  local binder: " ++ show existingRef
                    , "  carried binder: " ++ show incomingRef
                    ]
                )

-- | Inherit exact ambient declarations used by a checked result child before
-- constructing its enclosing owner.  A free source annotation variable is
-- ambient to the child that first checks it, but an enclosing lambda still
-- needs that same declaration in Gamma while constructing its own
-- @Gen(Gamma,tau)@ result.  The child certificate supplies the declaration
-- and bound; the direct source sidecar supplies the graph-occurrence routes.
-- Neither a residual free variable nor a failed closure check is used to
-- invent either half.
advanceEnvThroughFinalizedBodyConsumerConstruction
  :: OwnerFinalConstruction
  -> Env
  -> Either ElabError Env
advanceEnvThroughFinalizedBodyConsumerConstruction certificate env = do
  projectedTypeBindings <-
    consumeCertifiedBodyConsumerConstructionBindings
      bodyConsumerCertificates
      boundaryCompletedTypeBindings
  let projectedRefs = Map.keys projectedTypeBindings
      consumedIdentities =
        Set.fromList
          [ typeBinderRefIdentity ref
          | ref <- Map.keys boundaryCompletedTypeBindings
          , not
              ( any
                  (typeBinderRefsSameIdentity ref)
                  projectedRefs
              )
          ]
  projectedSourceRefinedGammaBounds <-
    foldM
      (projectSourceRefinement consumedIdentities projectedTypeBindings)
      Map.empty
      (Map.toList (envSourceRefinedGammaBounds env))
  projectedExpectedEndpoint <-
    traverse
      (projectExpectedEndpoint consumedIdentities)
      (envExpectedTermEndpoint env)
  pure
    env
      { envTypeBindings = projectedTypeBindings
      , envConstructionGammaAliases =
          IntMap.filterWithKey
            (retainConstructionAlias consumedIdentities)
            (envConstructionGammaAliases env)
      , envGammaCopiedBinderRoutes =
          Map.mapMaybeWithKey
            (retainCopiedBinderRoutes consumedIdentities)
            (envGammaCopiedBinderRoutes env)
      , envSourceRefinedGammaBounds =
          projectedSourceRefinedGammaBounds
      , envConstructionBinderRenames =
          filter (retainConstructionRename consumedIdentities)
            (envConstructionBinderRenames env)
      , envCompilerExactBinderRenames =
          filter (retainConstructionRename consumedIdentities)
            (envCompilerExactBinderRenames env)
      , envExpectedTermEndpoint = projectedExpectedEndpoint
      }
  where
    bodyConsumerCertificates =
      ofcBodyConsumerBoundRefinements certificate

    boundaryCertificates =
      nub
        ( ofcLambdaParamBoundaryCertificates certificate
            ++ envLambdaParamBoundaryCertificates env
        )

    rawTypeBindings = envTypeBindings env
    lexicalTypeRefs = Map.keys rawTypeBindings
    completeTargetDeclarationBound lexicalRefs ref bound
      | any
          (bodyConsumerBoundRefinementTargetsAny [ref])
          bodyConsumerCertificates =
          completeLambdaParamBoundaryDeclarationBoundInScope
            boundaryCertificates
            lexicalRefs
            ref
            bound
      | otherwise = bound
    boundaryCompletedTypeBindings =
      Map.mapWithKey
        (completeTargetDeclarationBound lexicalTypeRefs)
        rawTypeBindings

    completeTargetScheme scheme =
      mkElabSchemeWithRefs
        [ ( ref
          , fmap
              ( mapBoundType
                  (completeTargetDeclarationBound schemeRefs ref)
              )
              mbBound
          )
        | (ref, mbBound) <- binders
        ]
        (schemeBody scheme)
      where
        binders = schemeBinderRefs scheme
        schemeRefs = map fst binders

    refWasConsumed consumedIdentities ref =
      Set.member (typeBinderRefIdentity ref) consumedIdentities

    typeMentionsConsumedRef consumedIdentities =
      any (refWasConsumed consumedIdentities) . freeTypeVarRefsType

    matchingProjectedBinding projectedTypeBindings ref =
      case
          [ bound
          | (projectedRef, bound) <- Map.toList projectedTypeBindings
          , typeBinderRefsSameIdentity ref projectedRef
          ]
        of
          [bound] -> Just bound
          _ -> Nothing

    projectSourceRefinement consumedIdentities projectedTypeBindings projected (ref, bound)
      | refWasConsumed consumedIdentities ref = pure projected
      | typeMentionsConsumedRef consumedIdentities bound =
          case matchingProjectedBinding projectedTypeBindings ref of
            Just completedBound ->
              pure (Map.insert ref completedBound projected)
            Nothing ->
              transitionFailure
                [ "a source-refined Gamma bound retains a consumed declaration"
                , "  declaration: " ++ show ref
                , "  bound: " ++ show bound
                ]
      | otherwise = pure (Map.insert ref bound projected)

    projectExpectedEndpoint consumedIdentities endpoint =
      case endpoint of
        AdministrativeLambdaBodyExpectedTerm construction currentTy -> do
          let boundaryCompletedConstructionScheme =
                completeTargetScheme
                  (administrativeLambdaBodyConstructionScheme construction)
          projectedScheme <-
            consumeCertifiedBodyConsumerConstructionScheme
              bodyConsumerCertificates
              boundaryCompletedConstructionScheme
          projectedCurrentTy <-
            if typeMentionsConsumedRef consumedIdentities currentTy
              then
                schemeBody
                  <$> consumeCertifiedBodyConsumerConstructionScheme
                    bodyConsumerCertificates
                    ( mkElabSchemeWithRefs
                        (schemeBinderRefs boundaryCompletedConstructionScheme)
                        currentTy
                    )
              else pure currentTy
          pure
            ( AdministrativeLambdaBodyExpectedTerm
                ( administrativeLambdaBodyConstructionFromScheme
                    projectedScheme
                )
                projectedCurrentTy
            )
        CheckingExpectedTerm ty ->
          retainUnconsumedEndpoint consumedIdentities endpoint ty
        ExactConstructionExpectedTerm ty ->
          retainUnconsumedEndpoint consumedIdentities endpoint ty
        SourceLambdaValueExpectedTerm _ ty ->
          retainUnconsumedEndpoint consumedIdentities endpoint ty

    retainUnconsumedEndpoint consumedIdentities endpoint ty
      | typeMentionsConsumedRef consumedIdentities ty = do
          projectedTy <-
            consumeCertifiedBodyConsumerConstructionType
              bodyConsumerCertificates
              boundaryCompletedTypeBindings
              ty
          pure
            ( case endpoint of
                CheckingExpectedTerm _ -> CheckingExpectedTerm projectedTy
                ExactConstructionExpectedTerm _ ->
                  ExactConstructionExpectedTerm projectedTy
                SourceLambdaValueExpectedTerm construction _ ->
                  SourceLambdaValueExpectedTerm construction projectedTy
                AdministrativeLambdaBodyExpectedTerm {} -> endpoint
            )
      | otherwise = pure endpoint

    retainConstructionAlias consumedIdentities nodeKey outwardRef =
      not (refWasConsumed consumedIdentities outwardRef)
        && not
          ( refWasConsumed consumedIdentities
              ( typeBinderRefFromIdentity
                  (typeBinderIdentityFromNode (NodeId nodeKey))
                  ("t" ++ show nodeKey)
              )
          )

    retainCopiedBinderRoutes consumedIdentities identity routes
      | Set.member identity consumedIdentities = Nothing
      | otherwise =
          Just
            [ route
            | route@(_, ref) <- routes
            , not (refWasConsumed consumedIdentities ref)
            ]

    retainConstructionRename consumedIdentities (sourceRef, targetRef) =
      not
        ( refWasConsumed consumedIdentities sourceRef
            || refWasConsumed consumedIdentities targetRef
        )

    transitionFailure details =
      Left
        ( ValidationFailed
            ( "cannot advance enclosing Gamma through finalized body-consumer construction"
                : details
            )
        )

inheritOwnerFinalAmbientConstruction
  :: IntMap.IntMap TypeBinderRef
  -> OwnerFinalConstruction
  -> Env
  -> Either ElabError Env
inheritOwnerFinalAmbientConstruction sourceBinderRefs certificate env = do
  completedEnv <-
    advanceEnvThroughFinalizedBodyConsumerConstruction certificate env
  fst
    <$> inheritOwnerFinalAmbientConstructionWhere
      Nothing
      (const True)
      (const False)
      sourceBinderRefs
      certificate
      completedEnv

-- | Term-bearing variant used at a parent constructor boundary.  If the
-- parent's prepared Gamma has already completed one of the child's unbounded
-- ambient declarations, the checked child itself is the only sufficient
-- proof that the stronger declaration preserves this construction.  Keeping
-- that proof here avoids either reopening the stale Bottom declaration or
-- accepting a bound transition from type shape alone.
inheritOwnerFinalAmbientConstructionForTerm
  :: IntMap.IntMap TypeBinderRef
  -> XmlfTerm
  -> OwnerFinalConstruction
  -> Env
  -> Either ElabError (OwnerFinalConstruction, Env)
inheritOwnerFinalAmbientConstructionForTerm sourceBinderRefs term certificate env = do
  completedEnv <-
    advanceEnvThroughFinalizedBodyConsumerConstruction certificate env
  (inheritedEnv, completedAuthorities) <-
    inheritOwnerFinalAmbientConstructionWhere
      (Just term)
      (const True)
      (const False)
      sourceBinderRefs
      certificate
      completedEnv
  pure
    ( adoptCompletedAmbientAuthorities
        completedAuthorities
        certificate
    , inheritedEnv
    )
  where
    adoptCompletedAmbientAuthorities completedAuthorities ownerCertificate =
      ownerCertificate
        { ofcAmbientDeclarationAuthorities =
            map adoptAuthority
              (ofcAmbientDeclarationAuthorities ownerCertificate)
        , ofcAuthoritativeAmbientDeclarations =
            foldr installAuthoritative
              (ofcAuthoritativeAmbientDeclarations ownerCertificate)
              completedAuthorities
        }
      where
        adoptAuthority authority =
          fromMaybe authority
            ( find
                ( typeBinderRefsSameIdentity
                    (agaExactRef authority)
                    . agaExactRef
                )
                completedAuthorities
            )
        installAuthoritative authority authorities =
          authority
            : filter
              ( not
                  . typeBinderRefsSameIdentity
                    (agaExactRef authority)
                  . agaExactRef
              )
              authorities

-- | Inherit only declarations whose semantic identity is supplied either by
-- the enclosing direct source-binder sidecar or by the checked child's exact
-- used-source authority.  These are lexical annotation existentials that
-- remain outside the current lambda's local @Gen(Gamma,tau)@.  A graph
-- declaration merely ambient to the child has neither authority and remains a
-- candidate for this lambda to emit.
inheritOwnerFinalSourceAmbientConstruction
  :: Set.Set TypeBinderIdentity
  -> IntMap.IntMap TypeBinderRef
  -> OwnerFinalConstruction
  -> Env
  -> Either ElabError Env
inheritOwnerFinalSourceAmbientConstruction ownerSourceIdentities directSourceRefs certificate env = do
  completedEnv <-
    advanceEnvThroughFinalizedBodyConsumerConstruction certificate env
  fst
    <$> inheritOwnerFinalAmbientConstructionWhere
      Nothing
      isSourceAuthority
      isInheritedSourceAuthority
      sourceAuthorityRefs
      certificate
      completedEnv
  where
    inheritedSourceAuthorities =
      IntMap.filter
        ( (`Set.notMember` ownerSourceIdentities)
            . typeBinderRefIdentity
            . sourceBinderAuthoritySidecarRef
        )
        (ofcUsedSourceBinderAuthorities certificate)
    inheritedSourceAuthorityRefs =
      IntMap.map
        sourceBinderAuthorityConstructionRef
        inheritedSourceAuthorities
    directSourceAuthorityRefs =
      IntMap.filter
        ( (`Set.notMember` ownerSourceIdentities)
            . typeBinderRefIdentity
        )
        directSourceRefs
    sourceAuthorityRefs =
      IntMap.union inheritedSourceAuthorityRefs directSourceAuthorityRefs
    inheritedSourceRefs = IntMap.elems inheritedSourceAuthorityRefs
    directSourceRefs0 = IntMap.elems directSourceAuthorityRefs
    authoritativeRefs =
      map agaExactRef (ofcAuthoritativeAmbientDeclarations certificate)
    isSourceAuthority authority =
      isInheritedSourceAuthority authority
        || ( hasIdentityIn directSourceRefs0 authority
              && not (hasIdentityIn authoritativeRefs authority)
           )
    -- Preserve the established direct-sidecar rule: an authoritative packet
    -- declaration can still be local to the enclosing owner.  Only a source
    -- occurrence carried exclusively by the checked child adds the missing
    -- evidence needed to override that provisional classification.
    isInheritedSourceAuthority authority =
      hasIdentityIn inheritedSourceRefs authority
        && not (hasIdentityIn directSourceRefs0 authority)
    hasIdentityIn refs authority =
      any
        (typeBinderRefsSameIdentity (agaExactRef authority))
        refs

inheritOwnerFinalAmbientConstructionWhere
  :: Maybe XmlfTerm
  -> (AmbientGammaAuthority -> Bool)
  -> (AmbientGammaAuthority -> Bool)
  -> IntMap.IntMap TypeBinderRef
  -> OwnerFinalConstruction
  -> Env
  -> Either ElabError (Env, [AmbientGammaAuthority])
inheritOwnerFinalAmbientConstructionWhere mbConstructedTerm selectAuthority overridesLocalExclusion directSourceRefs certificate env = do
  peerRenames <-
    fmap catMaybes (traverse certifyPeerRename authorities)
  alignedEnv <-
    alignEnvToNestedConstructionBinderRenames
      (peerRenames ++ sourceRouteRenames)
      env
  let alignedAuthorities =
        map
          (alignAuthority (envConstructionBinderRenames alignedEnv))
          structuralAuthorities
  authoritySelections <-
    traverse (selectInstallableAuthority alignedEnv) alignedAuthorities
  let installableAuthorities = mapMaybe fst authoritySelections
      completedAuthorities = mapMaybe snd authoritySelections
  authorityBinders <- traverse authorityBinder installableAuthorities
  mapM_
    (validateAliasRoute alignedEnv)
    (IntMap.toList sourceRoutes)
  pure
    ( extendEnvTypeScopeWithAliases
        sourceRoutes
        authorityBinders
        alignedEnv
    , completedAuthorities
    )
  where
    authorities =
      filter
        ( \authority ->
            selectAuthority authority
              && ( not (excludedByLocalRefinement authority)
                    || ( overridesLocalExclusion authority
                          && not (reservedForFutureOwner authority)
                          && absentFromEnclosingGamma authority
                       )
                 )
        )
        (ofcAmbientDeclarationAuthorities certificate)
    excludedByLocalRefinement authority =
      any
        ( bodyConsumerBoundRefinementExcludesAmbientRef
            (agaExactRef authority)
        )
        (ofcBodyConsumerBoundRefinements certificate)
    -- Exact source provenance may show that a source forall classified as
    -- private by the provisional operated packet actually survives freely in
    -- the checked child.  It cannot, however, steal a declaration that the
    -- refinement explicitly reserves for a future local owner.
    reservedForFutureOwner authority =
      any
        ( \refinement ->
            bodyConsumerBoundRefinementRequiresOwnerEmission refinement
              && bodyConsumerBoundRefinementTargetsAny
                [agaExactRef authority]
                refinement
        )
        (ofcBodyConsumerBoundRefinements certificate)
    absentFromEnclosingGamma authority =
      not
        ( any
            (typeBinderRefsSameIdentity (agaExactRef authority))
            (Map.keys (envTypeBindings env))
        )
    structuralAuthorities =
      filter
        ( \authority ->
            case agaBound authority of
              TVarRef _ -> False
              _ -> True
        )
        authorities
    sourceRoutes =
      IntMap.mapMaybeWithKey exactUsedSourceRoute directSourceRefs
    -- A source identity can have several graph occurrences, some owned by a
    -- surrounding application and some used by this checked child.  The
    -- child certificate records the exact occurrence keys it consumed; only
    -- those keys may enter the inherited Gamma quotient.  Filtering merely
    -- by outward identity would import every same-source sidecar occurrence
    -- and could collapse an independently bounded application result into a
    -- lexical source forall.
    exactUsedSourceRoute nodeKey suppliedRef = do
      sourceAuthority <-
        IntMap.lookup
          nodeKey
          (ofcUsedSourceBinderAuthorities certificate)
      guard
        ( typeBinderRefsSameIdentity
            suppliedRef
            (sourceBinderAuthoritySidecarRef sourceAuthority)
            || typeBinderRefsSameIdentity
              suppliedRef
              (sourceBinderAuthorityConstructionRef sourceAuthority)
        )
      let constructionRef =
            sourceBinderAuthorityConstructionRef sourceAuthority
      guard
        ( any
            (typeBinderRefsSameIdentity constructionRef . agaExactRef)
            authorities
        )
      pure constructionRef

    -- Compose each exact occurrence route before validating or installing
    -- the inherited Gamma entries.  Otherwise an enclosing provisional graph
    -- alias and the already-constructed source identity are compared as
    -- unrelated answers for the same node.
    sourceRouteRenames =
      [ (graphRef, constructionRef)
      | (nodeKey, constructionRef) <- IntMap.toList sourceRoutes
      , let graphRef =
              typeBinderRefFromIdentity
                (typeBinderIdentityFromNode (NodeId nodeKey))
                ("t" ++ show nodeKey)
      , not (typeBinderRefsSameIdentity graphRef constructionRef)
      ]

    -- A bare variable is not an xMLF bound.  Section 15.6.2 represents this
    -- completed declaration by quotienting the pending identity to the exact
    -- ambient peer instead of trying to emit an illegal @a >= b@ binder.  The
    -- target must already be in the enclosing Gamma; otherwise the child
    -- declaration would leak one of its locally bound identities.
    certifyPeerRename authority =
      case agaBound authority of
        TVarRef peerRef
          | typeBinderRefsSameIdentity
              (agaExactRef authority)
              peerRef ->
              inheritanceFailure
                [ "child ambient declaration has an invalid self-variable bound"
                , "  declaration: " ++ show authority
                ]
          | otherwise ->
              case
                  [ ambientRef
                  | ambientRef <- Map.keys (envTypeBindings env)
                  , typeBinderRefsSameIdentity ambientRef peerRef
                  ]
                of
                  [ambientPeerRef] ->
                    pure
                      ( Just
                          (agaExactRef authority, ambientPeerRef)
                      )
                  [] ->
                    inheritanceFailure
                      [ "child ambient peer is absent from enclosing Gamma"
                      , "  declaration: " ++ show authority
                      ]
                  matches ->
                    inheritanceFailure
                      [ "child ambient peer is ambiguous in enclosing Gamma"
                      , "  declaration: " ++ show authority
                      , "  matching peers: " ++ show matches
                      ]
        _ -> pure Nothing

    alignAuthority renames authority =
      AmbientGammaAuthority
        { agaExactRef =
            applyRefRenames renames (agaExactRef authority)
        , agaBound =
            applyTypeVarRefRenames renames (agaBound authority)
        }

    authorityBinder authority =
      case agaBound authority of
        TBottom -> pure (agaExactRef authority, Nothing)
        bound ->
          case elabToBound bound of
            Right boundTy ->
              pure (agaExactRef authority, Just boundTy)
            Left cause ->
              inheritanceFailure
                [ "child ambient declaration is not a legal Gamma bound"
                , "  declaration: " ++ show authority
                , "  cause: " ++ cause
                ]

    -- A child can use a specialization of an enclosing polymorphic
    -- declaration without replacing that declaration.  The exact
    -- binder-spine plan is the construction proof: retain the enclosing
    -- Gamma entry and inherit only the source route.  Equal declarations and
    -- provisional Bottom entries still install normally.  Compare both sides
    -- in the completed parameter-boundary domain: an enclosing declaration
    -- can predate the certificate that closes its opened parameter view,
    -- while the recursively constructed child already carries the completed
    -- bound.  The child authority then replaces that stale enclosing payload.
    selectInstallableAuthority validationEnv authority =
      case
          [ (ref, bound)
          | (ref, bound) <-
              Map.toList completedValidationBindings
          , typeBinderRefsSameIdentity ref (agaExactRef completedAuthority)
          ]
        of
          [] -> pure (Just completedAuthority, Nothing)
          matches
            | all
                ( \(_, bound) ->
                    operationalEndpointTypesAgree
                      (agaBound completedAuthority)
                      bound
                      || operationalEndpointTypesAgree
                        bound
                        TBottom
                )
                matches ->
                pure (Just completedAuthority, Nothing)
            | all
                ( \(_, enclosingBound) ->
                    completeUnboundedForallSpecializesTo
                      enclosingBound
                      (agaBound completedAuthority)
                      || isJust
                        ( planExactBinderSpine
                            operationalEndpointTypesAgree
                            enclosingBound
                            (agaBound completedAuthority)
                        )
                )
                matches ->
                pure (Nothing, Nothing)
            | Just completedEnclosingAuthority <-
                uniqueCompletedEnclosingAuthority matches
            , childConstructionChecksUnderCompletedGamma
                validationEnv
                completedAuthority
                completedEnclosingAuthority ->
                -- The child may have constructed a more general exact source
                -- declaration before a parent application completed a
                -- bounded presentation of the same ambient identity.  Retain
                -- the parent's entry only when the child's declaration has
                -- an exact xMLF construction to that presentation and the
                -- actual child term rechecks at its certified type in the
                -- completed Gamma.  Neither Bottom nor compatible shape alone
                -- authorizes the transition.
                pure (Nothing, Just completedEnclosingAuthority)
            | otherwise ->
                inheritanceFailure
                  [ "child ambient declaration conflicts with enclosing Gamma"
                  , "  declaration: " ++ show completedAuthority
                  , "  enclosing bindings: " ++ show matches
                  , "  child refinements: "
                      ++ show
                        (ofcBodyConsumerBoundRefinements certificate)
                  , "  owner-emission target matches: "
                      ++ show
                        [ bodyConsumerBoundRefinementRequiresOwnerEmission
                            refinement
                        | refinement <-
                            ofcBodyConsumerBoundRefinements certificate
                        , bodyConsumerBoundRefinementExcludesAmbientRef
                            (agaExactRef authority)
                            refinement
                        ]
                  ]
      where
        boundaryCertificates =
          ofcLambdaParamBoundaryCertificates certificate
            ++ envLambdaParamBoundaryCertificates validationEnv
        lexicalRefs = Map.keys (envTypeBindings validationEnv)
        completeBound ref =
          completeLambdaParamBoundaryDeclarationBoundInScope
            boundaryCertificates
            lexicalRefs
            ref
        completedAuthority =
          authority
            { agaBound =
                completeBound
                  (agaExactRef authority)
                  (agaBound authority)
            }
        completedValidationBindings =
          Map.mapWithKey completeBound (envTypeBindings validationEnv)
        uniqueCompletedEnclosingAuthority matches =
          case matches of
            [] -> Nothing
            (firstRef, firstBound) : remaining
              | all
                  ( operationalEndpointTypesAgree firstBound
                      . snd
                  )
                  remaining ->
                  Just
                    AmbientGammaAuthority
                      { agaExactRef = firstRef
                      , agaBound = firstBound
                      }
            _ -> Nothing
        childConstructionChecksUnderCompletedGamma
          completedEnv
          childAuthority
          enclosingAuthority =
          isJust
            ( constructExactInstantiation
                (typeCheckEnvFrom completedEnv)
                operationalEndpointTypesAgree
                (agaBound childAuthority)
                (agaBound enclosingAuthority)
            )
            && any
              (typeBinderRefsSameIdentity (agaExactRef childAuthority))
              (ofcUsedAmbientBinderRefs certificate)
            && case mbConstructedTerm of
              Nothing -> False
              Just constructedTerm ->
                let constructionRenames =
                      envConstructionBinderRenames completedEnv
                    alignedTerm =
                      renameTermTypeBinderRefPayloads
                        constructionRenames
                        constructedTerm
                    alignedConstructedType =
                      applyTypeVarRefRenames
                        constructionRenames
                        (ofcConstructedType certificate)
                    completedGammaEnv =
                      completedEnv
                        { envTypeBindings = completedValidationBindings
                        }
                 in case
                      typeCheckConstructedOpenTermWithBaseEnv
                        (typeCheckEnvFrom completedGammaEnv)
                        alignedTerm
                    of
                      Right checkedType ->
                        operationalEndpointTypesAgree
                          checkedType
                          alignedConstructedType
                      Left _ -> False

    validateAliasRoute validationEnv (nodeKey, sourceRef) =
      case
          IntMap.lookup
            nodeKey
            (envConstructionGammaAliases validationEnv)
        of
        Nothing -> pure ()
        Just existingRef
          | typeBinderRefsSameIdentity
              existingRef
              ( applyRefRenames
                  (envConstructionBinderRenames validationEnv)
                  sourceRef
              ) ->
              pure ()
          | otherwise ->
              inheritanceFailure
                [ "child ambient source route conflicts with enclosing construction"
                , "  graph node: " ++ show (NodeId nodeKey)
                , "  child source ref: " ++ show sourceRef
                , "  enclosing route: " ++ show existingRef
                ]

    inheritanceFailure :: [String] -> Either ElabError a
    inheritanceFailure details =
      Left
        ( ValidationFailed
            ( [ "cannot inherit child owner-final ambient construction"
              , "  child owner: " ++ show (ofcOwner certificate)
              ]
                ++ details
            )
        )

-- | Reify the exact source scheme already constructed by an owner certificate.
-- The checked owner-final type fixes the order of its complete outer forall
-- spine, including binders inherited from a recursively constructed child.
-- Its exact routes are therefore construction-order authority even when a
-- binder's graph @<P@ key no longer survives at an enclosing edge.  Local
-- emission routes additionally retain aliases for binders introduced by this
-- owner.
ownerFinalConstructionSchemeInfo
  :: IntMap.IntMap TypeBinderRef
  -> OwnerFinalConstruction
  -> ElabScheme
  -> SchemeInfo
ownerFinalConstructionSchemeInfo sourceBinderRefs certificate constructedScheme =
  publishSourceBinderOrderFromProvenance
    sourceBinderRefs
    constructedInfo
      { siConstructionBinderOrderRefs =
          IntMap.union
            emittedConstructionOrderRefs
            ( IntMap.union
                certifiedConstructionOrderRefs
                (siConstructionBinderOrderRefs constructedInfo)
            )
      }
  where
    constructedBinderRefs =
      map fst (schemeBinderRefs constructedScheme)
    certifiedConstructionOrderRefs =
      IntMap.filter
        ( \routedRef ->
            any
              (typeBinderRefsSameIdentity routedRef)
              constructedBinderRefs
        )
        (schemeInfoBinderRefSubst constructedInfo)
    emittedRefs = map fst (ofcConstructedBinderSpine certificate)
    emittedConstructionOrderRefs =
      IntMap.union
        ( IntMap.fromList
            [ (getNodeId node, ref)
            | ref <- emittedRefs
            , Just node <- [typeBinderRefNode ref]
            ]
        )
        ( IntMap.filter
            ( \routedRef ->
                any
                  (typeBinderRefsSameIdentity routedRef)
                  emittedRefs
            )
            (ofcConstructedBinderRoutes certificate)
        )
    constructedInfo =
      schemeInfoFromRefSubst
        constructedScheme
        (ofcConstructedBinderRoutes certificate)

-- | The exact bound constructed for a compiler-exact source result by the
-- lambda that owns its outgoing Hyp.  Packet preparation necessarily happens
-- before Typ(body) is known and may therefore retain only a provisional
-- opened bound.  Carry the checked construction result forward with its
-- lexical owner, boundary edge, and binder identity so the exact boundary can
-- install the declaration without rediscovering it from the completed term.
data CompilerExactResultBoundCertificate =
  CompilerExactResultBoundCertificate
    { cerbcOwner :: !ResolvedTermIdentityKey,
      cerbcBoundary :: !EdgeId,
      cerbcResultRef :: !TypeBinderRef,
      cerbcBound :: !ElabType
    }
  deriving (Eq, Show)

-- | Internal detailed elaboration result.  The public elaborator keeps its
-- term-only projection; the pipeline consumes the optional owner certificate
-- in the same pass so construction is never repeated merely to recover type
-- metadata.
data ElaboratedTerm = ElaboratedTerm
  { elaboratedTerm :: !XmlfTerm,
    elaboratedOwnerFinalConstruction :: !(Maybe OwnerFinalConstruction),
    elaboratedLocalGammaConstructionCertificates :: ![LocalGammaConstructionCertificate],
    elaboratedCompilerExactResultBoundCertificates :: ![CompilerExactResultBoundCertificate],
    -- Descendant body-consumer refinements are construction effects, not
    -- result-owner metadata.  Keep them in their own accumulating channel so
    -- an application or let RHS cannot discard a certificate merely because
    -- a different child supplies the enclosing term's final result owner.
    elaboratedBodyConsumerBoundRefinements
      :: ![BodyConsumerBoundRefinementCertificate]
  }
  deriving (Eq, Show)

-- | Select the one source-owned result certificate for a nested application.
-- A non-empty local Gamma is the stronger construction and therefore wins
-- when present.  Otherwise the nested application must publish an exact
-- zero-local final construction for the same owner.  The smart constructors
-- reject malformed local spines, wrong owners, and zero-local claims that
-- secretly carry local binders or routes.
selectNestedApplicationResidualCertificate
  :: LocalGammaOwner
  -> ElaboratedTerm
  -> Either ElabError NestedApplicationResidualCertificate
selectNestedApplicationResidualCertificate expectedOwner elaboration =
  case localMatches of
    [certificate] ->
      nestedApplicationResidualFromLocalGamma
        expectedOwner
        certificate
    [] ->
      case elaboratedOwnerFinalConstruction elaboration of
        Just ownerConstruction ->
          nestedApplicationResidualFromZeroLocalConstruction
            expectedOwner
            (ofcOwner ownerConstruction)
            (ofcConstructedType ownerConstruction)
            (ofcLocallyEmittedBinderRefs ownerConstruction)
            (ofcLocalBinderRoutes ownerConstruction)
        Nothing ->
          selectionFailure
            [ "  local Gamma matches: []",
              "  final construction: Nothing"
            ]
    matches ->
      selectionFailure
        [ "  local Gamma matches: " ++ show matches,
          "  final construction: "
            ++ show (elaboratedOwnerFinalConstruction elaboration)
        ]
  where
    localMatches =
      filter
        ( \certificate ->
            lgccOwner certificate == expectedOwner
              && not
                ( null
                    ( localGammaConstructionBinders
                        (lgccConstruction certificate)
                    )
                )
        )
        (elaboratedLocalGammaConstructionCertificates elaboration)

    selectionFailure details =
      Left
        ( ValidationFailed
            ( [ "nested application result route has no unique source construction certificate",
                "  owner: " ++ show expectedOwner
              ]
                ++ details
            )
        )

elabTerm :: ElabOut -> Env -> Either ElabError XmlfTerm
elabTerm output env = elaboratedTerm <$> elabDetailed output env

-- | The complete xMLF computation owned by one source instantiation edge.
-- This is deliberately private: callers consume the source, computation, and
-- destination together, so none of the three can be repaired independently
-- from a later type-check result.
data EdgeComputation = EdgeComputation
  { edgeComputationSource :: !ElabType,
    edgeComputationInstantiation :: !Instantiation,
    edgeComputationTarget :: !ElabType,
    -- | Source quantifiers retained by a result-polymorphic application.
    -- The computation is checked under these binders, and the owning
    -- application must emit the matching type abstractions around EApp.
    edgeComputationEnclosingBinders :: ![(TypeBinderRef, Maybe BoundType)],
    edgeComputationFrozenEndpoint :: !(Maybe FrozenEndpointCertificate)
  }

frozenEndpointTypes :: Env -> IntMap.IntMap ElabType
frozenEndpointTypes =
  frozenEndpointCertificateTypes . envFrozenEndpointCertificates

-- | Keep invariant failures useful even for deeply nested Church encodings.
-- A complete 'show' of one application endpoint can be tens of kilobytes and
-- hide the actual failing computation behind outer validation context.
diagnosticShown :: Show a => a -> String
diagnosticShown value
  | renderedLength <= 2 * retainedLength = rendered
  | otherwise =
      take retainedLength rendered
        ++ "...<"
        ++ show renderedLength
        ++ " chars>..."
        ++ drop (renderedLength - retainedLength) rendered
  where
    rendered = show value
    renderedLength = length rendered
    retainedLength = 320

diagnosticElabType :: ElabType -> String
diagnosticElabType = diagnosticShown

diagnosticTypeCheckError :: TypeCheckError -> String
diagnosticTypeCheckError checkError =
  case checkError of
    TCResolvedVarTypeMismatch name expectedTy actualTy ->
      unwords
        [ "TCResolvedVarTypeMismatch"
        , show name
        , "expectedRefs="
            ++ show (freeTypeVarRefsType expectedTy)
        , "actualRefs="
            ++ show (freeTypeVarRefsType actualTy)
        ]
    _ -> diagnosticShown checkError

diagnosticOptionalElabType :: Maybe ElabType -> String
diagnosticOptionalElabType =
  maybe "Nothing" (("Just " ++) . diagnosticElabType)

diagnosticExpectedTermEndpoint :: Maybe ExpectedTermEndpoint -> String
diagnosticExpectedTermEndpoint =
  maybe "Nothing" $ \case
    CheckingExpectedTerm ty ->
      "Just CheckingExpectedTerm " ++ diagnosticElabType ty
    ExactConstructionExpectedTerm ty ->
      "Just ExactConstructionExpectedTerm "
        ++ diagnosticElabType ty
    SourceLambdaValueExpectedTerm construction ty ->
      "Just SourceLambdaValueExpectedTerm "
        ++ diagnosticElabType ty
        ++ " owner="
        ++ show (slvcOwner construction)
        ++ " parameter="
        ++ show (fst (slvcParameterBinder construction))
    AdministrativeLambdaBodyExpectedTerm construction ty ->
      "Just AdministrativeLambdaBodyExpectedTerm "
        ++ diagnosticElabType ty
        ++ " construction="
        ++ diagnosticElabType
          ( schemeToType
              (administrativeLambdaBodyConstructionScheme construction)
          )

publishFrozenEndpoint
  :: Env
  -> Maybe FrozenEndpointCertificate
  -> Either ElabError Env
publishFrozenEndpoint env Nothing = pure env
publishFrozenEndpoint env (Just certificate) =
  pure
    env
      { envFrozenEndpointCertificates =
          publishFrozenEndpointCertificate
            certificate
            (envFrozenEndpointCertificates env)
      }

data EdgeEndpointAuthority
  = ReplayComputedEndpoint
  | ApplicationFunctionEndpoint ElabType
  | ApplicationResultEndpoint ElabType
  | ExactApplicationFunctionEndpoint ElabType ElabType
  | ExactTransportEndpoint ElabType
  deriving (Show)

data FunctionResultEndpointPlan
  = RetainResultUndeterminedReplay
  | SpecializeFunctionResult [ElabType]

-- | Decide from the checked source scheme whether a parent result endpoint can
-- construct this function occurrence.  A result may either determine all
-- relevant source binders, or leave a binder that occurs only in the argument
-- domain for the shared application endpoint to determine.  With neither
-- proof, the parent endpoint is not an 'ApplicationResultEndpoint'; ordinary
-- replay and argument-domain construction must handle the occurrence.
functionResultEndpointPlan
  :: (ElabType -> ElabType -> Bool)
  -> ElabType
  -> ElabType
  -> Maybe FunctionResultEndpointPlan
functionResultEndpointPlan endpointTypesAgree sourceTy resultEndpoint = do
  let sourceScheme = schemeFromType sourceTy
      sourceBinders = map fst (schemeBinderRefs sourceScheme)
      mentions binderRef ty =
        any
          (typeBinderRefsSameIdentity binderRef)
          (freeTypeVarRefsType ty)
  (sourceDomain, sourceResult) <-
    case schemeBody sourceScheme of
      TArrow domainTy codomainTy -> Just (domainTy, codomainTy)
      _ -> Nothing
  if
      any
        ( \binderRef ->
            mentions binderRef sourceDomain
              && not (mentions binderRef sourceResult)
        )
        sourceBinders
    then Just RetainResultUndeterminedReplay
    else
      case sourceBinders of
        []
          | endpointTypesAgree sourceResult resultEndpoint ->
              Just (SpecializeFunctionResult [])
          | otherwise ->
              -- With no quantified identity there is no N/application
              -- computation that can transport between two merely
              -- Church-equivalent recursive presentations.
              Nothing
        _ ->
          do
            arguments <-
              inferInstAppArgsFromSchemeRefsExact
                (schemeBinderRefs sourceScheme)
                sourceResult
                resultEndpoint
            -- The inference helper deliberately returns the longest
            -- determined source-spine prefix.  Result-directed construction
            -- is authoritative only when that prefix consumes the complete
            -- forall spine; otherwise applying it leaves a residual forall
            -- where the application requires an arrow.
            guard (length arguments == length sourceBinders)
            pure (SpecializeFunctionResult arguments)

data ApplicationOccurrence
  = ApplicationFunctionOccurrence
  | ApplicationArgumentOccurrence

-- | The computation that consumes a leading forall at an application
-- argument boundary.  Omega records bounded elimination with the primitive
-- @N@, but Figure 15.3.5 applies the Gamma-closed argument at that explicit
-- bound.  Publish that derived application as @[bound]@; an unbounded forall
-- has no bound argument to publish and retains @N@.
applicationArgumentEliminationFor :: ElabType -> Instantiation
applicationArgumentEliminationFor sourceTy =
  case sourceTy of
    TForallRef _ (Just bound) _ -> InstApp (tyToElab bound)
    _ -> InstElim

normalizeScopedType :: ScopeContext p -> ElabType -> ElabType
normalizeScopedType scopeContext =
  inlineBoundVarsTypeWithContext (scInlineBoundVarsContext scopeContext)

scopedTypesAgree :: ScopeContext p -> ElabType -> ElabType -> Bool
scopedTypesAgree scopeContext left right =
  let left' = normalizeScopedType scopeContext left
      right' = normalizeScopedType scopeContext right
   in alphaEqType left' right' || churchAwareEqType left' right'

-- | Equality at an operational xMLF endpoint.  Unlike the broader semantic
-- comparison above, this deliberately preserves the explicit forall and
-- flexible-bound ABI.  A term of type @forall a. tau@ cannot be passed where
-- @tau@ is required, and a term of type @sigma@ cannot be passed where
-- @alpha >= sigma@ is required, until the edge computation constructs the
-- corresponding type application or Hyp.
scopedEndpointTypesAgree :: ScopeContext p -> ElabType -> ElabType -> Bool
scopedEndpointTypesAgree _scopeContext =
  operationalEndpointTypesAgree

data AlgebraContext (p :: Phase) = AlgebraContext
  { algPresolutionView :: PresolutionView p,
    algTraceConfig :: TraceConfig,
    algCanonical :: NodeId -> NodeId,
    algResolvedLambdaParamNode :: NodeId -> Maybe NodeId,
    algAnnotationContext :: AnnotationContext p,
    algNamedSetReify :: IntSet.IntSet,
    -- | Source types for compiler-owned exact lambda parameters, which have no
    -- annotation edge and therefore retain their node-keyed authority.
    algExactLambdaParamSourceTypes :: IntMap.IntMap NormSrcType,
    algSourceTypeHeadIdentities :: Map.Map String SymbolIdentity,
    algSourceTypeBinderIdentities :: Map.Map String TypeBinderIdentity,
    algSubtermGeneralizations :: SubtermGeneralizations,
    algExactProducerTypes :: IntMap.IntMap ElabType,
    algCompilerExactConstructionRefs :: IntMap.IntMap (IntMap.IntMap TypeBinderRef)
  }

-- | Free Hyp references carried by a Phi computation. References introduced
-- by 'InstUnderRef' are lexical and therefore do not name construction Gamma.
freeInstantiationAbstractionRefs :: Instantiation -> [TypeBinderRef]
freeInstantiationAbstractionRefs inst =
  case inst of
    InstId -> []
    InstApp _ -> []
    InstBot _ -> []
    InstIntro -> []
    InstElim -> []
    InstAbstrRef ref -> [ref]
    InstInside inner -> freeInstantiationAbstractionRefs inner
    InstSeq left right ->
      unionRefs
        (freeInstantiationAbstractionRefs left)
        (freeInstantiationAbstractionRefs right)
    InstUnderRef ref inner ->
      filter
        (not . typeBinderRefsSameIdentity ref)
        (freeInstantiationAbstractionRefs inner)
  where
    unionRefs left right = foldr insertRef right left
    insertRef ref refs
      | any (typeBinderRefsSameIdentity ref) refs = refs
      | otherwise = ref : refs

-- | Resolve a construction-Gamma identity route to its final outward
-- declaration.  Packet placement can compose routes such as
-- @Graph child -> Graph parent -> StructuralSelf@; stopping after the first
-- hop leaves a Hyp naming an intermediate graph identity that no constructor
-- emits.  Every hop comes from the prepared construction alias map, and a
-- cycle is rejected before an instantiation is built.
resolveConstructionGammaAlias
  :: String
  -> IntMap.IntMap TypeBinderRef
  -> TypeBinderRef
  -> Either ElabError TypeBinderRef
resolveConstructionGammaAlias role aliases = go []
  where
    go visited ref
      | any (typeBinderRefsSameIdentity ref) visited =
          Left
            ( ValidationFailed
                [ "construction Gamma identity routes contain a cycle"
                , "  role: " ++ role
                , "  cycle at: " ++ show ref
                , "  route: " ++ show (reverse (ref : visited))
                ]
            )
      | otherwise =
          case typeBinderRefNode ref >>= (`IntMap.lookup` aliases) . getNodeId of
            Just nextRef
              | typeBinderRefsSameIdentity ref nextRef ->
                  pure nextRef
              | otherwise ->
                  go (ref : visited) nextRef
            Nothing -> pure ref

constructionGammaAliasLookup
  :: String
  -> IntMap.IntMap TypeBinderRef
  -> TypeBinderRef
  -> Either ElabError (Maybe TypeBinderRef)
constructionGammaAliasLookup role aliases ref = do
  resolved <- resolveConstructionGammaAlias role aliases ref
  pure
    ( if typeBinderRefsSameIdentityAndName ref resolved
        then Nothing
        else Just resolved
    )

-- | Rewrite only free Hyp references through the construction Gamma's
-- identity routes.  A reference introduced by 'InstUnderRef' is lexical to
-- that computation and must not be captured by an outward alias.
canonicalizeFreeInstantiationHypRefs
  :: (TypeBinderRef -> Either ElabError (Maybe TypeBinderRef))
  -> Instantiation
  -> Either ElabError Instantiation
canonicalizeFreeInstantiationHypRefs lookupAlias = go []
  where
    go bound inst =
      case inst of
        InstId -> pure InstId
        InstApp ty -> pure (InstApp ty)
        InstBot ty -> pure (InstBot ty)
        InstIntro -> pure InstIntro
        InstElim -> pure InstElim
        InstAbstrRef ref
          | any (typeBinderRefsSameIdentity ref) bound ->
              pure (InstAbstrRef ref)
          | otherwise ->
              InstAbstrRef . fromMaybe ref <$> lookupAlias ref
        InstUnderRef ref inner ->
          InstUnderRef ref <$> go (ref : bound) inner
        InstInside inner -> InstInside <$> go bound inner
        InstSeq left right ->
          InstSeq <$> go bound left <*> go bound right

-- | Select the prepared construction-Gamma capability for one application
-- occurrence edge.  Owner-selected and direct edge-local planning run
-- independently, so their shared routing metadata is merged only after
-- validating exact identity/bound agreement.  Required binders are retained
-- only when their positive edge certificate names this occurrence.
applicationReplayRequirementsForEdge
  :: EdgeId
  -> GeneralizationRequirements
  -> GeneralizationRequirements
  -> Either ElabError GeneralizationRequirements
applicationReplayRequirementsForEdge edgeId ownerRequirements edgeLocalRequirements = do
  sourceBinderRefs <-
    foldM
      insertSourceBinderRoute
      (grSourceBinderRefs ownerRequirements)
      (IntMap.toList (grSourceBinderRefs edgeLocalRequirements))
  ambientGammaAuthorities <-
    foldM
      insertAmbientGammaAuthority
      (grAmbientGammaAuthorities ownerRequirements)
      (IntMap.toList (grAmbientGammaAuthorities edgeLocalRequirements))
  requiredGammaBinders <-
    foldM
      insertRequiredGammaBinder
      []
      ( filter requirementNamesEdge
          ( grRequiredGammaBinders ownerRequirements
              ++ grRequiredGammaBinders edgeLocalRequirements
          )
      )
  pure
    ownerRequirements
      { grRequiredGammaBinders = requiredGammaBinders,
        grSourceBinderRefs = sourceBinderRefs,
        grAmbientBinderRefs =
          foldr
            insertAmbientBinderRef
            (grAmbientBinderRefs ownerRequirements)
            (grAmbientBinderRefs edgeLocalRequirements),
        grAmbientGammaAuthorities = ambientGammaAuthorities,
        grLocallyClosedGammaNodes =
          IntSet.union
            (grLocallyClosedGammaNodes ownerRequirements)
            (grLocallyClosedGammaNodes edgeLocalRequirements)
      }
  where
    requirementNamesEdge requirement =
      edgeId `elem` rgbEdgeIds requirement

    insertSourceBinderRoute routes (nodeKey, incomingRef) =
      case IntMap.lookup nodeKey routes of
        Nothing -> pure (IntMap.insert nodeKey incomingRef routes)
        Just existingRef
          | typeBinderRefsSameIdentity existingRef incomingRef -> pure routes
          | otherwise ->
              replayRequirementsConflict
                [ "source-binder route disagreement"
                , "  graph node: " ++ show (NodeId nodeKey)
                , "  owner-selected ref: " ++ show existingRef
                , "  edge-local ref: " ++ show incomingRef
                ]

    insertAmbientGammaAuthority authorities (nodeKey, incomingAuthority) =
      case IntMap.lookup nodeKey authorities of
        Nothing -> pure (IntMap.insert nodeKey incomingAuthority authorities)
        Just existingAuthority
          | typeBinderRefsSameIdentity
              (agaExactRef existingAuthority)
              (agaExactRef incomingAuthority)
          , alphaEqType
              (agaBound existingAuthority)
              (agaBound incomingAuthority) ->
              pure authorities
          | otherwise ->
              replayRequirementsConflict
                [ "ambient Gamma authority disagreement"
                , "  graph node: " ++ show (NodeId nodeKey)
                , "  owner-selected authority: " ++ show existingAuthority
                , "  edge-local authority: " ++ show incomingAuthority
                ]

    insertAmbientBinderRef ref refs
      | any (typeBinderRefsSameIdentity ref) refs = refs
      | otherwise = ref : refs

    insertRequiredGammaBinder requirements incoming =
      case find (sameExterior incoming) requirements of
        Nothing -> pure (requirements ++ [incoming])
        Just existing
          | rgbPlacement existing /= rgbPlacement incoming ->
              replayRequirementsConflict
                [ "required Gamma placement disagreement"
                , "  exterior: " ++ show (rgbExteriorNode incoming)
                , "  owner-selected placement: " ++ show (rgbPlacement existing)
                , "  edge-local placement: " ++ show (rgbPlacement incoming)
                ]
          | not
              ( alphaEqType
                  (rgbOperatedType existing)
                  (rgbOperatedType incoming)
              ) ->
              replayRequirementsConflict
                [ "required Gamma bound disagreement"
                , "  exterior: " ++ show (rgbExteriorNode incoming)
                , "  owner-selected bound: " ++ show (rgbOperatedType existing)
                , "  edge-local bound: " ++ show (rgbOperatedType incoming)
                ]
          | otherwise ->
              pure (map (mergeMatchingExterior incoming) requirements)

    sameExterior left right =
      rgbExteriorNode left == rgbExteriorNode right

    mergeMatchingExterior incoming existing
      | sameExterior incoming existing =
          existing
            { rgbEdgeIds =
                foldl
                  appendDistinct
                  (rgbEdgeIds existing)
                  (NonEmpty.toList (rgbEdgeIds incoming)),
              rgbResultRoots =
                foldl
                  appendDistinct
                  (rgbResultRoots existing)
                  (NonEmpty.toList (rgbResultRoots incoming))
            }
      | otherwise = existing

    appendDistinct :: Eq a => NonEmpty a -> a -> NonEmpty a
    appendDistinct values value
      | value `elem` values = values
      | otherwise = values <> NonEmpty.singleton value

    replayRequirementsConflict :: [String] -> Either ElabError a
    replayRequirementsConflict details =
      Left
        ( ValidationFailed
            ( "application replay requirements conflict"
                : ("  edge: " ++ show edgeId)
                : details
            )
        )

-- | Refine an application-owned Gamma declaration at the exact endpoints
-- certified by its direct Figure 15.3.5 edges.  An enclosing
-- application can inherit a descendant declaration such as
-- @alpha > forall beta. beta@ while its own direct argument constructs
-- @Int@ for the same exterior.  Keeping the more-general declaration would
-- make the terminal direct Hyp ill-typed and leave a later term checker to
-- repair the choice.
--
-- Select the most specific endpoint already witnessed by the complete direct
-- edge set.  Refinement is legal only along complete unbounded-forall
-- specialization: every previously accounted source can then construct the
-- refined declaration by an explicit type application.  A direct source that
-- is more general than the current declaration leaves that declaration
-- unchanged for the same reason.  Incomparable endpoints are rejected either
-- during Gamma preparation when the source endpoint is already known, or
-- after the checked direct-edge computation and before the application term
-- is emitted when only that computation determines the exact endpoint.
sourceViewOfGammaBound :: ElabType -> ElabType
sourceViewOfGammaBound boundTy =
  case boundTy of
    TForallRef _ (Just _) _ ->
      case applyInstantiation boundTy InstElim of
        Right next -> sourceViewOfGammaBound next
        Left _ -> boundTy
    _ -> boundTy

sourceEndpointClosesApplicationGammaBound :: ElabType -> ElabType -> Bool
sourceEndpointClosesApplicationGammaBound sourceTy currentTy =
  let sourceScheme = schemeFromType sourceTy
      sourceBinderRefs = map fst (schemeBinderRefs sourceScheme)
      endpointTypesAgree left right =
        alphaEqType left right || churchAwareEqType left right
   in forallClosurePresentsSameIdentityBody currentTy sourceTy
        || ( not (null sourceBinderRefs)
              && endpointTypesAgree (schemeBody sourceScheme) currentTy
              && any
                ( \currentRef ->
                    any
                      (typeBinderRefsSameIdentity currentRef)
                      sourceBinderRefs
                )
                (freeTypeVarRefsType currentTy)
           )

data ApplicationDirectEndpointStage
  = PreparedDirectEndpoint
  | CheckedDirectEndpoint
  deriving (Eq, Show)

refineApplicationGammaBindersAtExactDirectEndpoints
  :: ApplicationDirectEndpointStage
  -> (NodeId -> NodeId)
  -> IntMap.IntMap TypeBinderRef
  -> [(EdgeId, Maybe ElabType)]
  -> GeneralizationRequirements
  -> IntMap.IntMap TypeBinderRef
  -> [(TypeBinderRef, Maybe BoundType)]
  -> Either ElabError [(TypeBinderRef, Maybe BoundType)]
refineApplicationGammaBindersAtExactDirectEndpoints endpointStage canonical sourceBinderRefs directEdges requirements aliases binders =
  foldM refineRequirement binders (grRequiredGammaBinders requirements)
  where
    exactSources =
      IntMap.fromList
        [ (getEdgeId edgeId, routeToSourceConstruction sourceTy)
        | (edgeId, Just sourceTy) <- directEdges
        ]

    -- Exact direct endpoints are recovered from checked source occurrences,
    -- while a provisional Gamma bound can still carry graph identities.  Put
    -- both sides in the source-construction identity domain before deciding
    -- whether to retain or close the declaration.  Otherwise a source forall
    -- can appear to specialize to its own open graph body and the latter is
    -- incorrectly published outside the value's ETyAbs.
    routeToSourceConstruction =
      resolveSourceBinderAliasesInTypeExcept
        Set.empty
        canonical
        sourceBinderRefs

    refineRequirement currentBinders requirement =
      case
          traverse
            ( \edgeId ->
                IntMap.lookup (getEdgeId edgeId) exactSources
            )
            (NonEmpty.toList (rgbEdgeIds requirement))
        of
          Nothing -> pure currentBinders
          Just sourceTypes ->
            case
                IntMap.lookup
                  (getNodeId (rgbExteriorNode requirement))
                  aliases
              of
                Nothing -> pure currentBinders
                Just routedRef ->
                  foldM
                    (refineBinder requirement routedRef)
                    currentBinders
                    sourceTypes

    refineBinder requirement routedRef currentBinders sourceTy =
      case break (typeBinderRefsSameIdentity routedRef . fst) currentBinders of
        (_, []) -> pure currentBinders
        (before, (binderRef, mbCurrentBound) : after)
          | endpointTypesAgree currentTy sourceTy ->
              pure currentBinders
          | isNothing mbCurrentBound
          , sourceTy /= TBottom -> do
              -- Bottom records the absence of a local Gamma bound; it is not
              -- an endpoint competing with the checked direct edge.  Once
              -- that complete edge constructs a non-bottom endpoint, publish
              -- it on the owner declaration before provenance selection.
              refinedBound <- endpointBound binderRef sourceTy
              pure (before ++ (binderRef, refinedBound) : after)
          | sourceEndpointClosesApplicationGammaBound sourceTy currentTy -> do
              -- The graph requirement can retain the body of a checked
              -- source scheme after its source-owned binders have been
              -- placed inside the value.  Publishing that body as an
              -- enclosing Gamma bound would let those lexical identities
              -- escape their ETyAbs scope.  The direct edge has now checked
              -- the complete source endpoint, so close the declaration with
              -- that same source binder spine at construction time.
              refinedBound <- endpointBound binderRef sourceTy
              pure (before ++ (binderRef, refinedBound) : after)
          | exactEndpointSpecializesTo sourceTy currentTy ->
              pure currentBinders
          | exactEndpointSpecializesTo currentTy sourceTy -> do
              refinedBound <- endpointBound binderRef sourceTy
              pure (before ++ (binderRef, refinedBound) : after)
          | endpointStage == CheckedDirectEndpoint -> do
              -- The prepared direct edge is only a pre-body placeholder for
              -- this same local Gamma declaration.  Once every edge in the
              -- requirement has a checked source computation, that complete
              -- edge set is Figure 15.3.5's final local authority.  Replace
              -- its own incomparable provisional view here; any enclosing
              -- endpoint must still be reached later by an independently
              -- checked outgoing computation.
              refinedBound <- endpointBound binderRef sourceTy
              pure (before ++ (binderRef, refinedBound) : after)
          | otherwise ->
              Left
                ( ValidationFailed
                    [ "application Gamma has incomparable exact construction endpoints"
                    , "  requirement: " ++ show requirement
                    , "  binder: " ++ show binderRef
                    , "  inherited endpoint: " ++ show currentTy
                    , "  direct source endpoint: " ++ show sourceTy
                    ]
                )
          where
            currentTy =
              routeToSourceConstruction
                (maybe TBottom tyToElab mbCurrentBound)

    endpointTypesAgree left right =
      alphaEqType left right || churchAwareEqType left right

    exactEndpointSpecializesTo sourceTy targetTy =
      completeUnboundedForallSpecializesTo sourceTy targetTy
        || case
            planExactBinderSpine
              endpointTypesAgree
              sourceTy
              targetTy
          of
            Just plan ->
              exactBinderSpineInstantiation plan /= InstId
            Nothing -> False

    endpointBound binderRef endpoint =
      case endpoint of
        TBottom -> pure Nothing
        TVarRef endpointRef ->
          Left
            ( ValidationFailed
                [ "application Gamma exact endpoint cannot be a binder bound variable"
                , "  binder: " ++ show binderRef
                , "  endpoint: " ++ show endpointRef
                ]
            )
        _ ->
          either
            ( \cause ->
                Left
                  ( ValidationFailed
                      [ "application Gamma exact endpoint is not a legal bound"
                      , "  binder: " ++ show binderRef
                      , "  endpoint: " ++ show endpoint
                      , "  cause: " ++ cause
                      ]
                  )
            )
            (pure . Just)
            (elabToBound endpoint)

-- | Enter an inherited exact application result in the ambient declaration
-- named by the frozen result topology before either child is elaborated.  A
-- surrounding lambda can move a flexible declaration underneath one of its
-- source foralls, changing (for example) @b >= forall a. a -> a@ into
-- @b >= a -> a@.  The downward endpoint and a checked exact instantiation
-- from the old bound are the construction proof for that transition.
refineAmbientApplicationResultAtExactEndpoint
  :: (ElabType -> ElabType -> Bool)
  -> NodeId
  -> [(TypeBinderRef, Maybe BoundType)]
  -> Maybe ElabType
  -> ElabType
  -> Env
  -> Either ElabError Env
refineAmbientApplicationResultAtExactEndpoint typesAgree applicationNode localBinders mbExpectedEndpoint resultTopology env =
  case mbExpectedEndpoint of
    Just expectedEndpoint
      | Just resultRef <- ambientResultDeclarationRef
      , not (locallyOwned resultRef)
      , not
          ( any
              (typeBinderRefsSameIdentity resultRef)
              (freeTypeVarRefsType expectedEndpoint)
          ) ->
          case matchingBindings resultRef (envTypeBindings env) of
            [] -> pure env
            (_, currentBound) : remainingBindings
              | not
                  ( all
                      (typesAgree currentBound . snd)
                      remainingBindings
                  ) ->
                  refinementFailure
                    resultRef
                    expectedEndpoint
                    "the ambient result identity has conflicting current bounds"
              | not (sourceAuthorityAllows resultRef expectedEndpoint) ->
                  pure env
              | typesAgree currentBound expectedEndpoint
                  || isJust
                    ( constructExactInstantiation
                        (typeCheckEnvFrom env)
                        typesAgree
                        currentBound
                        expectedEndpoint
                    ) ->
                  pure
                    env
                      { envTypeBindings =
                          replaceIdentityBound
                            resultRef
                            expectedEndpoint
                            (envTypeBindings env)
                      , envSourceRefinedGammaBounds =
                          replaceIdentityBound
                            resultRef
                            expectedEndpoint
                            (envSourceRefinedGammaBounds env)
                      }
              | otherwise -> pure env
    _ -> pure env
  where
    ambientResultDeclarationRef =
      case distinctResultDeclarationRefs of
        [ref] -> Just ref
        _ -> Nothing

    -- Reification can expose the declaration's bound as the result topology,
    -- so a structured topology does not itself retain the ambient binder ref.
    -- The application result node is the immutable identity key that joins
    -- the graph result to the already-installed declaration.
    distinctResultDeclarationRefs =
      foldr insertDistinctRef []
        [ ref
        | (ref, _) <- Map.toList (envTypeBindings env)
        , typeBinderRefNode ref == Just applicationNode
        ]

    insertDistinctRef ref refs
      | any (typeBinderRefsSameIdentity ref) refs = refs
      | otherwise = ref : refs

    locallyOwned ref =
      any (typeBinderRefsSameIdentity ref . fst) localBinders

    sourceAuthorityAllows ref expectedEndpoint =
      all
        ( \(_, sourceBound) ->
            typesAgree sourceBound expectedEndpoint
              || isJust
                ( constructExactInstantiation
                    (typeCheckEnvFrom env)
                    typesAgree
                    sourceBound
                    expectedEndpoint
                )
        )
        (matchingBindings ref (envSourceRefinedGammaBounds env))

    matchingBindings ref =
      filter (typeBinderRefsSameIdentity ref . fst) . Map.toList

    replaceIdentityBound ref bound =
      Map.mapWithKey
        ( \existingRef existingBound ->
            if typeBinderRefsSameIdentity ref existingRef
              then bound
              else existingBound
        )

    refinementFailure ref expectedEndpoint detail =
      Left
        ( ValidationFailed
            [ "application exact result cannot enter its ambient declaration"
            , "  detail: " ++ detail
            , "  application: " ++ show applicationNode
            , "  result declaration: " ++ show ref
            , "  result topology: " ++ show resultTopology
            , "  expected endpoint: " ++ show expectedEndpoint
            , "  current bindings: "
                ++ show (matchingBindings ref (envTypeBindings env))
            ]
        )

mkEdgeComputation ::
  AlgebraContext p ->
  Maybe SubtermConsumerAuthority ->
  Maybe SubtermConsumerAuthority ->
  TypeCheck.Env ->
  (IdDetails -> Maybe SchemeInfo) ->
  (TypeBinderRef -> Maybe ElabType) ->
  IntMap.IntMap TypeBinderRef ->
  IntMap.IntMap ElabType ->
  GeneralizationRequirements ->
  String ->
  ApplicationOccurrence ->
  EdgeEndpointAuthority ->
  AnnExpr ->
  InstantiationSite ->
  ElabType ->
  ElabType ->
  Either ElabError EdgeComputation
mkEdgeComputation algebraContext currentConsumer enclosingConsumer edgeTypeEnv resolvedLookup typeBindingLookup constructionAliases exactFrozenEndpoints replayRequirements owner occurrence endpointAuthority sourceAnn site sourceTy targetTy = do
  replayAuthority <- edgeAuthority
  let frozenSourceTy =
        reifyNodeTypePreferringBound scopeContext sourceNode
      replayAppliesToCheckedSource =
        case frozenSourceTy of
          Right replaySourceTy ->
            -- A replay witness acts on the frozen graph presentation, not on
            -- every source type that is merely semantically equivalent to
            -- it.  In particular, a nominal/structural recursive source may
            -- be Church-equivalent to a graph-owned recursive encoding while
            -- carrying different binder identities.  Replaying the latter's
            -- Intro/Hyp sequence on the former is not a typed xMLF
            -- computation.  Require the same alpha presentation here; the
            -- enclosing application endpoint constructs any remaining
            -- transport explicitly.
            alphaEqTypePreservingStructuralBinders replaySourceTy sourceTy
          Left _ -> True
      directExactTransport =
        case endpointAuthority of
          ExactTransportEndpoint exactEndpoint
            | exactEndpointTypesAgree sourceTy exactEndpoint ->
                -- The checked occurrence already inhabits the exact
                -- constructor-owned endpoint.  Its frozen graph destination
                -- may still carry a provisional RaiseMerge binder; replaying
                -- that presentation before honoring the exact certificate
                -- would manufacture an unrelated outgoing Hyp.
                Just InstId
            | exactEndpointTypesAgree exactEndpoint targetTy ->
                exactGammaTransport exactEndpoint
          _ -> Nothing
  rawInstUncanonicalized <-
    case directExactTransport of
      Just inst -> pure inst
      Nothing ->
        case replayAuthority of
          ReplayEdgeAuthority
            | replayAppliesToCheckedSource
                || frozenEndpointsCoverEveryGraft
                || strictCheckedRoutesCoverEveryGraft ->
            case
              reifyInstWithFrozenEndpointsFromCheckedSourceInConstructionGamma
                annotationContext
                currentConsumer
                enclosingConsumer
                namedSetReify
                constructionAliases
                replayRequirements
                ( Just
                    PhiEndpointShapeAuthority
                      { pesaOccurrenceRole =
                          case occurrence of
                            ApplicationFunctionOccurrence ->
                              PhiApplicationFunctionOccurrence
                            ApplicationArgumentOccurrence ->
                              PhiApplicationArgumentOccurrence
                      , pesaRequiredEndpointType = targetTy
                      }
                )
                resolvedLookup
                exactFrozenEndpoints
                sourceTy
                sourceAnn
                edgeId
            of
              Left err ->
                Left
                  ( ValidationFailed
                      [ "application occurrence edge replay failed under its prepared construction Gamma"
                      , "  edge: " ++ show edgeId
                      , "  owner: " ++ owner
                      , "  source type: " ++ show sourceTy
                      , "  target type: " ++ show targetTy
                      , "  frozen source type: " ++ show frozenSourceTy
                      , "  endpoint authority: " ++ show endpointAuthority
                      , "  requirements: " ++ show replayRequirements
                      , "  cause: " ++ show err
                      ]
                  )
              Right inst -> pure inst
            | otherwise -> pure InstId
          IdentityEdgeAuthority -> pure InstId
          GraftedEdgeAuthority -> pure InstId
  rawInst0 <-
    canonicalizeFreeInstantiationHypRefs
      gammaAliasLookup
      rawInstUncanonicalized
  rawInstScoped <-
    case filter (isNothing . typeBindingLookup) (freeInstantiationAbstractionRefs rawInst0) of
      [] -> pure rawInst0
      unscopedRefs
        | not replayAppliesToCheckedSource ->
            -- The checked occurrence and frozen graph source are different
            -- presentations, while the replay requires a Hyp not owned by
            -- this occurrence's prepared Gamma.  Preserve the checked
            -- occurrence and let its exact application endpoint construct
            -- the transport.
            pure InstId
        | authoritativeTypesAgree sourceTy targetTy -> pure InstId
        | otherwise ->
            failEdge
              [ "edge computation uses Hyp identities outside its prepared Γ",
                "unscoped refs=" ++ show unscopedRefs,
                "source type=" ++ show sourceTy,
                "target type=" ++ show targetTy,
                "raw instantiation=" ++ show rawInst0,
                "artifact=" ++ show edgeArtifact
              ]
  rawInst <-
    sourceSpecializeOutgoingHyp sourceTy rawInstScoped
  let rawApplied = TypeCheck.checkInstantiation edgeTypeEnv sourceTy rawInst
  (inst0, authoritativeTargetTy, computationEnclosingBinders) <-
    case endpointAuthority of
      ReplayComputedEndpoint ->
        case (replayAuthority, rawApplied) of
          -- A deferred constructor/method can have a more precise checked
          -- source type than the frozen graph placeholder used to build its
          -- witness.  Such a witness is not a computation on the checked
          -- occurrence: retain the occurrence identity here and let the
          -- application construction specialize the other side to this exact
          -- endpoint.  If the frozen and checked sources agree, rejection is
          -- a real witness/Γ invariant failure and must remain visible.
          (ReplayEdgeAuthority, Left _)
            | not replayAppliesToCheckedSource ->
                pure (InstId, sourceTy, [])
          (ReplayEdgeAuthority, Left rawError) ->
            failEdge
              [ "edge replay is not admissible in its prepared Gamma",
                "source type=" ++ show sourceTy,
                "frozen source type=" ++ show frozenSourceTy,
                "raw instantiation=" ++ show rawInst,
                "typecheck error=" ++ show rawError
              ]
          (_, Right replayTarget) ->
            -- Identity/grafted authority certifies that Ω contributes no
            -- computation.  At the ordinary replay endpoint that means the
            -- occurrence retains its source presentation exactly.
            case replayAuthority of
              IdentityEdgeAuthority -> pure (rawInst, sourceTy, [])
              GraftedEdgeAuthority -> pure (rawInst, sourceTy, [])
              ReplayEdgeAuthority -> pure (rawInst, replayTarget, [])
          (_, Left rawError) ->
            failEdge
              [ "identity/grafted computation failed type checking",
                "source type=" ++ show sourceTy,
                "raw instantiation=" ++ show rawInst,
                "typecheck error=" ++ show rawError
              ]
      ApplicationFunctionEndpoint argumentEndpoint ->
        case rawApplied of
          Left rawError ->
            constructFunctionAtEndpoint (show rawError) argumentEndpoint
          Right appliedTy@(TArrow replayDomain _)
            | exactEndpointTypesAgree replayDomain argumentEndpoint ->
                pure (rawInst, appliedTy, [])
          Right (TArrow _ replayCodomain) -> do
            let applicationTarget = TArrow argumentEndpoint replayCodomain
            transported <-
              transportEdgeComputation sourceTy applicationTarget
            pure (transported, applicationTarget, [])
          Right _ -> do
            -- Figure 15.3.5 owns the shared application endpoint
            -- independently of Ω replay.  An identity/grafted graph edge can
            -- therefore still require a source-scheme InstApp to expose its
            -- arrow.  Infer that application from the domain alone; the
            -- specialized source scheme, not a partially reified graph
            -- codomain, owns the resulting codomain.
            constructFunctionAtEndpoint
              "replay did not expose an arrow"
              argumentEndpoint
      ApplicationResultEndpoint resultEndpoint ->
        case rawApplied of
          Right appliedTy@(TArrow _ codomainTy)
            | exactEndpointTypesAgree codomainTy resultEndpoint ->
                -- Ω already translated the occurrence edge through the
                -- source function's result context.  Preserve that exact
                -- paper computation before attempting source-forall
                -- specialization: the latter only sees the checked scheme
                -- spine and cannot reconstruct a deep result operation.  A
                pure (rawInst, appliedTy, [])
          _ ->
            addNoEnclosingBinders
              <$> constructFunctionAtResultEndpoint
                replayAuthority
                frozenSourceTy
                replayAppliesToCheckedSource
                rawInst
                rawApplied
                resultEndpoint
      ExactApplicationFunctionEndpoint argumentEndpoint resultEndpoint -> do
        let applicationTarget = TArrow argumentEndpoint resultEndpoint
        case rawApplied of
          Right appliedTy
            | exactEndpointTypesAgree appliedTy applicationTarget ->
                pure (rawInst, applicationTarget, [])
          _ -> do
            -- The result certificate is the stronger source-spine
            -- discriminator.  Specialize it first and retain the exact
            -- domain produced by that source computation; the caller then
            -- transports the argument occurrence to the same domain.  Trying
            -- to match the whole provisional graph arrow in one step can
            -- choose source binders from its domain that contradict the
            -- checked result (notably @apply g g@), while a bare graph
            -- argument endpoint cannot determine @a@ in @IO a@ at all.
            case
                ( addNoEnclosingBinders
                    <$> constructFunctionAtResultEndpoint
                      replayAuthority
                      frozenSourceTy
                      replayAppliesToCheckedSource
                      rawInst
                      rawApplied
                      resultEndpoint
                )
              of
                Right
                  resultDirected@(
                    _,
                    TArrow resultDirectedDomain resultDirectedCodomain,
                    _
                    )
                    | exactEndpointTypesAgree
                        resultDirectedCodomain
                        resultEndpoint
                    , resultDirectedDomain /= TBottom ->
                        pure resultDirected
                _ ->
                  case
                      constructFunctionAtEndpoint
                        "exact result did not determine the source function"
                        argumentEndpoint
                    of
                      Right
                        domainDirected@(
                          _,
                          TArrow _ domainDirectedCodomain,
                          _
                          )
                          | exactEndpointTypesAgree
                              domainDirectedCodomain
                              resultEndpoint ->
                              pure domainDirected
                      _ -> do
                        transported <-
                          transportEdgeComputation sourceTy applicationTarget
                        pure (transported, applicationTarget, [])
      ExactTransportEndpoint exactEndpoint ->
        case rawApplied of
          Left _ -> do
            transported <-
              transportEdgeComputation sourceTy exactEndpoint
            pure (transported, exactEndpoint, [])
          Right appliedTy
            | exactEndpointTypesAgree appliedTy exactEndpoint ->
                pure (rawInst, exactEndpoint, [])
          Right _ -> do
            transported <-
              transportEdgeComputation sourceTy exactEndpoint
            pure (transported, exactEndpoint, [])
  let inst =
        case occurrence of
          ApplicationArgumentOccurrence ->
            canonicalApplicationArgumentInstantiation sourceTy inst0
          ApplicationFunctionOccurrence -> inst0
  case inst of
    InstId
      | not (authoritativeTypesAgree sourceTy authoritativeTargetTy) ->
          failEdge
            [ "identity computation has unequal endpoints",
              "authority=" ++ show replayAuthority,
              "site source=" ++ show sourceNode,
              "site target=" ++ show targetNode,
              "site=" ++ show site,
              "source node=" ++ show (pvLookupNode presolutionView sourceNode),
              "target node=" ++ show (pvLookupNode presolutionView targetNode),
              "source bound=" ++ show (pvLookupVarBound presolutionView sourceNode),
              "target bound=" ++ show (pvLookupVarBound presolutionView targetNode),
              "source node type=" ++ show (reifyNodeTypePreferringBound scopeContext sourceNode),
              "artifact=" ++ show edgeArtifact,
              "source type=" ++ show sourceTy,
              "target type=" ++ show authoritativeTargetTy
            ]
    _ -> pure ()
  let computationTypeEnv =
        foldl
          ( \typeEnv (ref, mbBound) ->
              TypeCheck.insertTypeBindingRef
                ref
                (maybe TBottom tyToElab mbBound)
                typeEnv
          )
          edgeTypeEnv
          computationEnclosingBinders
  appliedTy <-
    case TypeCheck.checkInstantiation computationTypeEnv sourceTy inst of
      Left err ->
        failEdge
          [ "edge computation does not apply to its source",
            "authority=" ++ show replayAuthority,
            "site=" ++ show site,
            "artifact=" ++ show edgeArtifact,
            "source type=" ++ show sourceTy,
            "instantiation=" ++ show inst,
            "apply error=" ++ show err
          ]
      Right ty -> pure ty
  if authoritativeTypesAgree appliedTy authoritativeTargetTy
    then
      pure
        EdgeComputation
          { edgeComputationSource = sourceTy,
            edgeComputationInstantiation = inst,
            edgeComputationTarget = authoritativeTargetTy,
            edgeComputationEnclosingBinders =
              computationEnclosingBinders,
            edgeComputationFrozenEndpoint =
              (\traceInfo ->
                FrozenEndpointCertificate
                  { fecProducerEdge = edgeId,
                    fecResultRoot = etResultRoot traceInfo,
                    fecEndpointType = authoritativeTargetTy
                  }
              )
                <$> (edgeArtifactTrace <$> edgeArtifact)
          }
    else
      failEdge
        [ "edge computation result does not equal its destination",
          "authority=" ++ show replayAuthority,
          "site source=" ++ show sourceNode,
          "site target=" ++ show targetNode,
          "artifact=" ++ show edgeArtifact,
          "source type=" ++ show sourceTy,
          "instantiation=" ++ show inst,
          "applied type=" ++ show appliedTy,
          "target type=" ++ show authoritativeTargetTy
        ]
  where
    addNoEnclosingBinders (inst, target) = (inst, target, [])

    gammaAliasLookup =
      constructionGammaAliasLookup
        ("application edge " ++ show edgeId)
        constructionAliases

    annotationContext = algAnnotationContext algebraContext
    scopeContext = acScopeContext annotationContext
    presolutionView = algPresolutionView algebraContext
    namedSetReify = algNamedSetReify algebraContext
    canonical = algCanonical algebraContext
    edgeId@(EdgeId edgeKey) = instantiationSiteEdgeId site
    sourceNode = canonical (instantiationSiteSource site)
    targetNode = canonical (instantiationSiteTarget site)
    edgeArtifact =
      lookupEdgeArtifact edgeId (acEdgeArtifacts annotationContext)
    identityEdges = acIdentityEdges annotationContext
    graftedEdges = cGraftedEdges (pvConstraint (algPresolutionView algebraContext))
    frozenEndpointsCoverEveryGraft =
      case edgeArtifact of
        Nothing -> False
        Just artifact ->
          let edgeWitness = edgeArtifactWitness artifact
           in case
                [ operated
                  | OpGraft operated _ <-
                      getInstanceOps (ewWitness edgeWitness)
                ]
              of
                [] -> False
                operatedNodes ->
                  all
                    (\operated -> IntMap.member (getNodeId operated) exactFrozenEndpoints)
                    operatedNodes
    strictCheckedRoutesCoverEveryGraft =
      case edgeArtifact of
        Just artifact ->
          let edgeWitness = edgeArtifactWitness artifact
              traceInfo = edgeArtifactTrace artifact
           in etReplayContract traceInfo == ReplayContractStrict
                && case
                    [ sourceBinder
                      | OpGraft _operated sourceBinder <-
                          getInstanceOps (ewWitness edgeWitness)
                    ]
                  of
                    [] -> False
                    sourceBinders ->
                      all
                        (strictCheckedRouteExists traceInfo)
                        sourceBinders
        Nothing -> False
    strictCheckedRouteExists traceInfo sourceBinder =
      case
          ( [ traceSource
              | (traceSource, _argument) <- etBinderArgs traceInfo
              , traceSource == sourceBinder
            ],
            IntMap.lookup sourceKey (acSourceBinderRefs annotationContext)
          )
        of
          ([_], Just sourceRef) ->
            case
                filter
                  (typeBinderRefsSameIdentity sourceRef)
                  checkedSourceBinders
              of
                [_] ->
                  case IntMap.lookup sourceKey (etBinderReplayMap traceInfo) of
                    Just replayTarget ->
                      not (null (etReplayDomainBinders traceInfo))
                        && replayTarget `elem` etReplayDomainBinders traceInfo
                    Nothing -> False
                _ -> False
          _ -> False
      where
        sourceKey = getNodeId sourceBinder
    checkedSourceBinders =
      map fst (schemeBinderRefs (schemeFromType sourceTy))
    dataAuthority
      | IntSet.member edgeKey graftedEdges = GraftedEdgeAuthority
      | IntSet.member edgeKey identityEdges = IdentityEdgeAuthority
      | otherwise = ReplayEdgeAuthority

    edgeAuthority =
      case edgeArtifact of
        Just artifact ->
          validateReplayWitness (edgeArtifactWitness artifact)
        Nothing ->
          case dataAuthority of
            ReplayEdgeAuthority ->
              failEdge ["ordinary edge is missing its replay artifact packet"]
            authority -> pure authority

    validateReplayWitness witness
      | canonical (ewLeft witness) /= sourceNode =
          failEdge
            [ "witness source does not match the construction site",
              "site source=" ++ show sourceNode,
              "witness source=" ++ show (canonical (ewLeft witness))
            ]
      | canonical (ewRight witness) /= targetNode =
          failEdge
            [ "witness destination does not match the construction site",
              "site target=" ++ show targetNode,
              "witness target=" ++ show (canonical (ewRight witness))
            ]
      | otherwise = pure ReplayEdgeAuthority

    edgeContext =
      owner
        ++ " edge "
        ++ show edgeId
        ++ " authority="
        ++ diagnosticEndpointAuthority endpointAuthority
    failEdge :: [String] -> Either ElabError a
    failEdge details =
      Left
        ( PhiInvariantError
            (unlines (edgeContext : details))
        )

    endpointTypesAgree = scopedTypesAgree scopeContext
    exactEndpointTypesAgree = scopedEndpointTypesAgree scopeContext
    authoritativeTypesAgree =
      case endpointAuthority of
        ReplayComputedEndpoint -> endpointTypesAgree
        ApplicationFunctionEndpoint {} -> exactEndpointTypesAgree
        ApplicationResultEndpoint {} -> exactEndpointTypesAgree
        ExactApplicationFunctionEndpoint {} -> exactEndpointTypesAgree
        ExactTransportEndpoint {} -> exactEndpointTypesAgree

    -- The enclosing application has already installed the exact Figure
    -- 15.3.5 Gamma declaration.  When its bound is the checked occurrence
    -- type, Inst-Hyp is the complete transport; replaying the frozen graph
    -- would merely rediscover the same operation and can traverse unrelated
    -- scheme roots outside this occurrence.
    exactGammaTransport exactEndpoint
      | exactEndpointTypesAgree sourceTy exactEndpoint =
          Just InstId
      | TVarRef targetRef <- exactEndpoint
      , Just targetBound <- typeBindingLookup targetRef
      , exactEndpointTypesAgree sourceTy targetBound =
          Just (InstAbstrRef targetRef)
      | otherwise = Nothing

    diagnosticEndpointAuthority authority =
      case authority of
        ReplayComputedEndpoint -> "ReplayComputedEndpoint"
        ApplicationFunctionEndpoint argumentEndpoint ->
          "ApplicationFunctionEndpoint "
            ++ diagnosticElabType argumentEndpoint
        ApplicationResultEndpoint resultEndpoint ->
          "ApplicationResultEndpoint "
            ++ diagnosticElabType resultEndpoint
        ExactApplicationFunctionEndpoint argumentEndpoint resultEndpoint ->
          "ExactApplicationFunctionEndpoint "
            ++ diagnosticElabType argumentEndpoint
            ++ " => "
            ++ diagnosticElabType resultEndpoint
        ExactTransportEndpoint exactEndpoint ->
          "ExactTransportEndpoint "
            ++ diagnosticElabType exactEndpoint

    -- Figure 15.3.5 applies the argument occurrence computation to the
    -- Gamma-closed argument term.  When that term starts with a bounded
    -- abstraction, spell the bound-matching application as the derived
    -- @[bound]@ computation.  It is definitionally
    -- @InstSeq (InstInside (InstBot bound)) InstElim@, but retaining
    -- 'InstApp' records that the parent application consumes the child's
    -- explicit bound; function-side bounded elimination remains the thesis
    -- primitive N.
    canonicalApplicationArgumentInstantiation source inst =
      case inst of
        InstElim -> applicationArgumentEliminationFor source
        InstSeq InstElim rest ->
          InstSeq (applicationArgumentEliminationFor source) rest
        _ -> inst

    -- A root RaiseMerge translates to @alpha ; Hyp@.  Replay can recover only
    -- the terminal Hyp when the frozen operated root is a graph occurrence
    -- variable, while the checked source occurrence retains its exact
    -- scheme.  The construction Gamma's bound is the positive
    -- authority for alpha: specialize the checked source to that exact bound
    -- before applying the unchanged Hyp.
    --
    -- This is determined from the typed computation itself.  Only a terminal
    -- free Hyp is eligible; nested/lexically-bound abstractions keep their
    -- original computation, and failure to construct the prefix remains an
    -- edge invariant error rather than a path or syntax fallback.
    sourceSpecializeOutgoingHyp source inst =
      case splitOutgoingHyp inst of
        Nothing -> pure inst
        Just (InstId, hypRef)
          | TVarRef sourceRef <- source
          , typeBinderRefsSameIdentity sourceRef hypRef ->
              -- Hyp(alpha) is the introduction from alpha's bound to alpha.
              -- An edge whose checked source is already that exact alpha has
              -- no introduction to perform.  In particular, an unbounded
              -- construction-Gamma declaration is represented by Bottom in
              -- the type-check environment; attempting to specialize alpha
              -- to that sentinel would turn an identity edge into an
              -- impossible alpha -> Bottom transport.
              pure InstId
        Just (prefix, hypRef) -> do
          prefixTarget <-
            case TypeCheck.checkInstantiation edgeTypeEnv source prefix of
              Right ty -> pure ty
              Left err ->
                failEdge
                  [ "outgoing Hyp prefix does not apply to the checked source"
                  , "source type=" ++ show source
                  , "prefix=" ++ show prefix
                  , "Hyp ref=" ++ show hypRef
                  , "typecheck error=" ++ show err
                  ]
          case typeBindingLookup hypRef of
            Nothing -> pure inst
            Just hypBound
              | exactEndpointTypesAgree prefixTarget hypBound ->
                  pure inst
              | otherwise -> do
                  specialization <-
                    case
                        constructOutgoingHypBound
                          prefixTarget
                          hypBound
                      of
                      Right constructed -> pure constructed
                      Left cause ->
                        case endpointAuthority of
                          ExactTransportEndpoint exactEndpoint ->
                            case
                                constructInstantiation
                                  source
                                  exactEndpoint
                              of
                              Right exactTransport ->
                                pure exactTransport
                              Left exactCause ->
                                failEdge
                                  [ "outgoing Hyp and exact endpoint transports both failed"
                                  , "source type=" ++ show source
                                  , "raw instantiation=" ++ show inst
                                  , "prefix=" ++ show prefix
                                  , "prefix target=" ++ show prefixTarget
                                  , "Hyp ref=" ++ show hypRef
                                  , "Hyp bound=" ++ show hypBound
                                  , "exact endpoint="
                                      ++ show exactEndpoint
                                  , "Hyp transport cause=" ++ show cause
                                  , "exact transport cause="
                                      ++ show exactCause
                                  ]
                          _ ->
                            failEdge
                              [ "outgoing Hyp prefix cannot be specialized to its prepared bound"
                              , "source type=" ++ show source
                              , "raw instantiation=" ++ show inst
                              , "prefix=" ++ show prefix
                              , "prefix target=" ++ show prefixTarget
                              , "Hyp ref=" ++ show hypRef
                              , "Hyp bound=" ++ show hypBound
                              , "cause=" ++ show cause
                              ]
                  pure
                    ( composeInst
                        (composeInst prefix specialization)
                        (InstAbstrRef hypRef)
                    )

    constructOutgoingHypBound source target =
      case target of
        TForallRef targetRef targetBound targetBody
          | not
              ( any
                  (typeBinderRefsSameIdentity targetRef)
                  (freeTypeVarRefsType targetBody)
              ) -> do
              -- Inst-Quant-Intro constructs a target-only vacuous binder
              -- before the unchanged terminal Hyp is applied.  This occurs
              -- when an earlier application specializes one source binder
              -- while the prepared Gamma retains another binder that no
              -- longer occurs in the specialized body (for example,
              -- Int -> forall a. Int -> Hyp(Gamma)).
              --
              -- Keep this construction local to outgoing-Hyp completion.
              -- General edge transport has additional exact-endpoint choices;
              -- accepting O there would pre-empt those positive plans.
              bodyInstantiation <-
                constructOutgoingHypBound source targetBody
              let introduced =
                    composeInst bodyInstantiation InstIntro
              pure
                ( case targetBound of
                    Nothing -> introduced
                    Just bound ->
                      composeInst
                        introduced
                        (InstInside (InstBot (tyToElab bound)))
                )
        _ -> constructInstantiation source target

    splitOutgoingHyp inst =
      case inst of
        InstAbstrRef ref -> Just (InstId, ref)
        InstSeq prefix suffix -> do
          (suffixPrefix, ref) <- splitOutgoingHyp suffix
          pure (composeInst prefix suffixPrefix, ref)
        _ -> Nothing

    transportEdgeComputation source target =
      constructInstantiation source target

    constructFunctionAtEndpoint replayError argumentEndpoint = do
      (transported, enclosingBinders) <-
        constructFunctionInstantiation sourceTy argumentEndpoint
      computationTypeEnv <-
        foldM
          insertEnclosingBinder
          edgeTypeEnv
          enclosingBinders
      transportedTy <-
        case
            TypeCheck.checkInstantiation
              computationTypeEnv
              sourceTy
              transported
          of
          Left err ->
            failEdge
              [ "application function transport does not type check",
                "source type=" ++ show sourceTy,
                "raw replay error=" ++ replayError,
                "instantiation=" ++ show transported,
                "typecheck error=" ++ show err
              ]
          Right ty -> pure ty
      pure (transported, transportedTy, enclosingBinders)
      where
        insertEnclosingBinder typeEnv (ref, mbBound) =
          case TypeCheck.lookupTypeBindingRef ref typeEnv of
            Just existingBound ->
              failEdge
                [ "result-polymorphic application binder is already ambient"
                , "binder=" ++ show ref
                , "ambient bound=" ++ show existingBound
                , "source type=" ++ show sourceTy
                , "argument endpoint=" ++ show argumentEndpoint
                ]
            Nothing ->
              pure
                ( TypeCheck.insertTypeBindingRef
                    ref
                    (maybe TBottom tyToElab mbBound)
                    typeEnv
                )

    -- Construct a function occurrence from the result endpoint supplied by
    -- its parent application.  Matching the source arrow codomain first can
    -- determine quantifiers that do not occur in the current argument's
    -- unreduced source presentation.  For example, in @apply g g@ the parent
    -- requires the child @apply g@ at @sigma-id -> sigma-id@; that endpoint
    -- uniquely selects both quantifiers of @apply@ before the first @g@ is
    -- transported to its function domain.
    constructFunctionAtResultEndpoint
      replayAuthority
      frozenSourceTy
      replayAppliesToCheckedSource
      rawInst
      rawApplied
      resultEndpoint = do
      let sourceScheme = schemeFromType sourceTy
      (sourceDomain, sourceResult) <-
        case schemeBody sourceScheme of
          TArrow domainTy codomainTy -> pure (domainTy, codomainTy)
          bodyTy ->
            failEdge
              [ "application function source scheme does not expose an arrow body"
              , "source type=" ++ show sourceTy
              , "scheme body=" ++ show bodyTy
              ]
      case
          functionResultEndpointPlan
            exactEndpointTypesAgree
            sourceTy
            resultEndpoint
        of
        Just RetainResultUndeterminedReplay ->
          -- The result endpoint cannot choose a source binder that occurs
          -- only in the argument domain.  Retain the replayed occurrence so
          -- the caller constructs that binder from the shared argument
          -- endpoint.  Defaulting it to Bottom here would make a result such
          -- as @Foo@ incorrectly specialize @forall a. a -> Foo@ to
          -- @Bottom -> Foo@ before its argument is considered.
          case rawApplied of
            Right appliedTy -> pure (rawInst, appliedTy)
            Left rawError ->
              failEdge
                [ "result-undetermined function replay does not apply"
                , "source type=" ++ show sourceTy
                , "source domain=" ++ show sourceDomain
                , "source result=" ++ show sourceResult
                , "expected result=" ++ show resultEndpoint
                , "raw instantiation=" ++ show rawInst
                , "typecheck error=" ++ show rawError
                ]
        Just (SpecializeFunctionResult arguments) -> do
          (inst, appliedTy) <- applyArguments sourceTy arguments
          case appliedTy of
            TArrow _ codomainTy
              | exactEndpointTypesAgree codomainTy resultEndpoint ->
                  pure (inst, appliedTy)
            _ ->
              failEdge
                [ "result-directed application specialization did not expose the expected arrow"
                , "source type=" ++ show sourceTy
                , "arguments=" ++ show arguments
                , "applied type=" ++ show appliedTy
                , "expected result=" ++ show resultEndpoint
                ]
        Nothing ->
          failEdge
            [ "cannot specialize the source function at the expected application result"
            , "source type=" ++ show sourceTy
            , "source domain=" ++ show sourceDomain
            , "source result=" ++ show sourceResult
            , "expected result=" ++ show resultEndpoint
            , "raw instantiation=" ++ show rawInst
            , "raw application=" ++ show rawApplied
            , "replay authority=" ++ show replayAuthority
            , "frozen source=" ++ show frozenSourceTy
            , "replay applies to checked source="
                ++ show replayAppliesToCheckedSource
            , "artifact=" ++ show edgeArtifact
            ]

    constructInstantiation source target
      | Just inst <-
          constructExactInstantiation
            edgeTypeEnv
            exactEndpointTypesAgree
            source
            target =
          pure inst
      | exactEndpointTypesAgree source target = pure InstId
      | TVarRef targetRef <- target,
        Just targetBound <- typeBindingLookup targetRef,
        exactEndpointTypesAgree source targetBound =
          -- Inst-Hyp is the construction owned by the exact application
          -- Gamma: under @targetRef > source@, the argument occurrence is
          -- transported from the published bound to that binder.  In
          -- particular, a bounded result such as @alpha > Bool@ keeps
          -- @alpha@ as the shared Figure 15.3.5 endpoint instead of forcing
          -- the function occurrence back down to @Bool@.
          pure (InstAbstrRef targetRef)
      | TBottom <- source = pure (InstBot target)
      | otherwise = do
          args <-
            case inferArgumentsFromTarget sourceScheme' target of
                Nothing ->
                  failEdge
                    [ "cannot transport the source scheme to the exact application endpoint",
                      "source type=" ++ show source,
                      "target type=" ++ show target,
                      "artifact=" ++ show edgeArtifact,
                      "solved source node=" ++ show (pvLookupNode presolutionView sourceNode),
                      "solved target node=" ++ show (pvLookupNode presolutionView targetNode),
                      "solved source bound=" ++ show (pvLookupVarBound presolutionView sourceNode),
                      "solved target bound=" ++ show (pvLookupVarBound presolutionView targetNode),
                      "solved target binding="
                        ++ show
                          ( IntMap.lookup
                              (nodeRefKey (typeRef targetNode))
                              (cBindParents (pvConstraint presolutionView))
                          ),
                      "source binding path="
                        ++ show
                          ( bindingPathToRootLocal
                              (gaBindParentsBase (scGaParents scopeContext))
                              (typeRef sourceNode)
                          ),
                      "target binding path="
                        ++ show
                          ( bindingPathToRootLocal
                              (gaBindParentsBase (scGaParents scopeContext))
                              (typeRef targetNode)
                          ),
                      "target binding links="
                        ++ show
                          [ (ref, IntMap.lookup (nodeRefKey ref) bindParents)
                          | ref <-
                              either
                                (const [])
                                id
                                ( bindingPathToRootLocal
                                    bindParents
                                    (typeRef targetNode)
                                )
                          ]
                    ]
                Just inferred -> pure inferred
          (inst0, applied0) <- applyArguments source args
          (inst, applied) <-
            eliminateVacuousForallsToEndpoint
              target
              inst0
              applied0
          if exactEndpointTypesAgree applied target
            then pure inst
            else
              failEdge
                [ "application computation transport does not reach the exact endpoint",
                  "source type=" ++ show source,
                  "arguments=" ++ show args,
                  "applied type=" ++ show applied,
                  "target type=" ++ show target
                ]
      where
        sourceScheme' = schemeFromType source
        bindParents = gaBindParentsBase (scGaParents scopeContext)

        inferArgumentsFromTarget sourceScheme endpointTy =
          inferExactTransportArguments
            exactEndpointTypesAgree
            sourceScheme
            endpointTy

        -- Exact transport first chooses every source binder whose identity is
        -- determined by the destination.  Any leading binders left after that
        -- inference are necessarily positional, and may be vacuous.  Figure
        -- 15.3.5 still requires their explicit N computations before the
        -- occurrence reaches its shared application endpoint.  Construct
        -- those steps from the quantified type itself; do not wait for the
        -- completed application to fail type checking and strip them later.
        eliminateVacuousForallsToEndpoint endpoint = go
          where
            go prefix current
              | exactEndpointTypesAgree current endpoint =
                  pure (prefix, current)
              | TForallRef ref _ body <- current
              , not
                  ( any
                      (typeBinderRefsSameIdentity ref)
                      (freeTypeVarRefsType body)
                  ) = do
                  next <-
                    case TypeCheck.checkInstantiation edgeTypeEnv current InstElim of
                      Right ty -> pure ty
                      Left err ->
                        failEdge
                          [ "vacuous application binder elimination does not type check",
                            "current type=" ++ show current,
                            "target type=" ++ show endpoint,
                            "prefix=" ++ show prefix,
                            "typecheck error=" ++ show err
                          ]
                  go (composeInst prefix InstElim) next
              | otherwise = pure (prefix, current)

    constructFunctionInstantiation source argumentEndpoint =
      case resultPolymorphicClosedDomainConstruction of
        Just construction -> construction
        Nothing -> constructDirectly
      where
        sourceScheme' = schemeFromType source
        sourceBinderRefs = map fst (schemeBinderRefs sourceScheme')
        sourceDomain =
          case schemeBody sourceScheme' of
            TArrow domainTy _ -> Just domainTy
            _ -> Nothing
        sourceDomainDependsOnBinder domainTy =
          any
            ( \freeRef ->
                any
                  (typeBinderRefsSameIdentity freeRef)
                  sourceBinderRefs
            )
            (freeTypeVarRefsType domainTy)

        -- When the argument domain is independent of every source
        -- quantifier, those quantifiers belong to the result construction.
        -- Figure 15.3.5 cannot erase an unbounded result variable to Bottom:
        -- it constructs the application under that variable and emits the
        -- matching Lambda afterwards.  Bounded result variables take the
        -- paper's canonical N step inside that Lambda.
        resultPolymorphicClosedDomainConstruction = do
          domainTy <- sourceDomain
          guard (exactEndpointTypesAgree domainTy argumentEndpoint)
          guard (not (sourceDomainDependsOnBinder domainTy))
          guard
            ( any
                retainsResultBinder
                (schemeBinderRefs sourceScheme')
            )
          pure (constructResultSpine source)

        retainsResultBinder (ref, Nothing) =
          case source of
            TForallRef sourceRef Nothing body
              | typeBinderRefsSameIdentity ref sourceRef ->
                  any
                    (typeBinderRefsSameIdentity ref)
                    (freeTypeVarRefsType body)
            _ ->
              any
                (typeBinderRefsSameIdentity ref)
                (freeTypeVarRefsType (schemeBody sourceScheme'))
        retainsResultBinder (_, Just _) = False

        constructResultSpine =
          go [] InstId edgeTypeEnv
          where
            go retained prefix typeEnv current =
              case current of
                TForallRef ref Nothing body
                  | any
                      (typeBinderRefsSameIdentity ref)
                      (freeTypeVarRefsType body) -> do
                      case TypeCheck.lookupTypeBindingRef ref typeEnv of
                        Just existingBound ->
                          failEdge
                            [ "result-polymorphic source binder is already ambient"
                            , "binder=" ++ show ref
                            , "ambient bound=" ++ show existingBound
                            , "source type=" ++ show source
                            ]
                        Nothing -> pure ()
                      let binder = (ref, Nothing)
                          typeEnv' =
                            TypeCheck.insertTypeBindingRef ref TBottom typeEnv
                          step = InstApp (TVarRef ref)
                      next <-
                        case
                            TypeCheck.checkInstantiation
                              typeEnv'
                              current
                              step
                          of
                            Right ty -> pure ty
                            Left err ->
                              failEdge
                                [ "result-polymorphic source application does not type check"
                                , "current type=" ++ show current
                                , "retained binder=" ++ show ref
                                , "typecheck error=" ++ show err
                                ]
                      go
                        (retained ++ [binder])
                        (composeInst prefix step)
                        typeEnv'
                        next
                TForallRef _ _ _ -> do
                  next <-
                    case
                        TypeCheck.checkInstantiation
                          typeEnv
                          current
                          InstElim
                      of
                        Right ty -> pure ty
                        Left err ->
                          failEdge
                            [ "result-polymorphic source N computation does not type check"
                            , "current type=" ++ show current
                            , "typecheck error=" ++ show err
                            ]
                  go
                    retained
                    (composeInst prefix InstElim)
                    typeEnv
                    next
                TArrow domainTy _
                  | exactEndpointTypesAgree domainTy argumentEndpoint ->
                      pure (prefix, retained)
                _ ->
                  failEdge
                    [ "result-polymorphic source construction did not expose the exact argument domain"
                    , "source type=" ++ show source
                    , "current type=" ++ show current
                    , "argument endpoint=" ++ show argumentEndpoint
                    , "retained binders=" ++ show retained
                    ]

        constructDirectly = do
          case schemeBody sourceScheme' of
            TArrow {} -> pure ()
            bodyTy ->
              failEdge
                [ "application function source scheme does not expose an arrow body",
                  "source type=" ++ show source,
                  "scheme body=" ++ show bodyTy
                ]
          -- This constructor has exact authority only for the shared argument
          -- endpoint.  Specialize binders determined by that domain first, and
          -- consume a remaining bounded prefix with the paper's N computation.
          -- In particular, a result-only flexible binder must not be specialized
          -- from the provisional graph codomain: its bound is the only source
          -- construction available until an exact result certificate exists.
          (initialArgs, initialInst, initiallyApplied) <-
            constructAtArgumentDomain [] InstId source
          (residualArgs, inst, applied) <-
            case initiallyApplied of
              TArrow {} -> pure ([], initialInst, initiallyApplied)
              _ ->
                case
                    inferResidualResultArguments initiallyApplied targetTy
                      <|> inferResidualResultArguments
                        initiallyApplied
                        (normalizeScopedType scopeContext targetTy)
                  of
                    Just inferredResidualArgs -> do
                      (residualInst, residualApplied) <-
                        applyArguments initiallyApplied inferredResidualArgs
                      pure
                        ( inferredResidualArgs,
                          composeInst initialInst residualInst,
                          residualApplied
                        )
                    Nothing -> pure ([], initialInst, initiallyApplied)
          let args = initialArgs ++ residualArgs
          case applied of
            TArrow domainTy _
              | exactEndpointTypesAgree domainTy argumentEndpoint ->
                  pure (inst, [])
            _ ->
              failEdge
                [ "application function specialization did not expose the exact argument domain",
                  "source type=" ++ show source,
                  "arguments=" ++ show args,
                  "applied type=" ++ show applied,
                  "argument endpoint=" ++ show argumentEndpoint,
                  "application target=" ++ show targetTy
                ]
        -- Once domain construction reaches an unbounded result-only binder,
        -- the complete application topology may determine it.  For example,
        -- specializing @forall a b. IO a -> (a -> IO b) -> IO b@ at @IO Unit@
        -- can still choose @b@ from an exact residual result.  Bounded
        -- result-only binders have already taken their canonical N step above.
        inferResidualResultArguments partiallyApplied applicationTarget =
          let residualScheme = schemeFromType partiallyApplied
              residualBinders = schemeBinderRefs residualScheme
           in case residualBinders of
                [] -> Nothing
                _ -> do
                  terminalArgs <-
                    inferInstAppArgsFromSchemeRefsExact
                      residualBinders
                      (terminalArrowResult (schemeBody residualScheme))
                      (terminalArrowResult applicationTarget)
                  case applyArguments partiallyApplied terminalArgs of
                    Right (_, appliedResidual)
                      | residualTopologyAgreesExact
                          (normalizeScopedType scopeContext appliedResidual)
                          ( normalizeScopedType
                              scopeContext
                              (residualApplicationTarget applicationTarget)
                          ) ->
                          Just terminalArgs
                    _ -> Nothing
          where
            residualApplicationTarget target =
              case target of
                TArrow _ codomain ->
                  TArrow argumentEndpointForInference codomain
                _ -> target
        terminalArrowResult =
          \case
            TArrow _ codomain -> terminalArrowResult codomain
            result -> result
        -- The caller selected this occurrence endpoint from the application
        -- site's constructed edge computation.  Its binder identity is the
        -- authority used to infer InstApp; normalizing it through a flexible
        -- bound can select a different graph binder and construct a function
        -- domain that no longer equals the argument occurrence.
        argumentEndpointForInference =
          argumentEndpoint

        constructAtArgumentDomain arguments prefix current =
          case current of
            TArrow {} -> pure (arguments, prefix, current)
            _ ->
              let currentScheme = schemeFromType current
               in case schemeBody currentScheme of
                    TArrow currentDomain _
                      | Just inferred@(_ : _) <-
                          inferInstAppArgsFromSchemeRefsExact
                            (schemeBinderRefs currentScheme)
                            currentDomain
                            argumentEndpointForInference -> do
                          (domainInst, domainApplied) <-
                            applyArguments current inferred
                          constructAtArgumentDomain
                            (arguments ++ inferred)
                            (composeInst prefix domainInst)
                            domainApplied
                    _ ->
                      case current of
                        TForallRef _ (Just _) _ -> do
                          next <-
                            case
                                TypeCheck.checkInstantiation
                                  edgeTypeEnv
                                  current
                                  InstElim
                              of
                                Right ty -> pure ty
                                Left err ->
                                  failEdge
                                    [ "application function bounded-prefix elimination does not type check"
                                    , "current type=" ++ show current
                                    , "prefix=" ++ show prefix
                                    , "typecheck error=" ++ show err
                                    ]
                          constructAtArgumentDomain
                            arguments
                            (composeInst prefix InstElim)
                            next
                        _ -> pure (arguments, prefix, current)

    applyArguments source =
      foldM applyArgument (InstId, source)

    applyArgument (prefix, current) argument = do
      step <- leadingArgumentInstantiation current argument
      current' <-
        case TypeCheck.checkInstantiation edgeTypeEnv current step of
          Left err ->
            failEdge
              [ "application transport argument does not apply",
                "current type=" ++ show current,
                "argument=" ++ show argument,
                "step=" ++ show step,
                "apply error=" ++ show err
              ]
          Right ty -> pure ty
      let prefix' =
            case prefix of
              InstId -> step
              _ -> InstSeq prefix step
      pure (prefix', current')

    leadingArgumentInstantiation current argument =
      case current of
        TForallRef _ Nothing _ -> pure (InstApp argument)
        TForallRef _ (Just bound) _
          | let boundTy = tyToElab bound,
            exactEndpointTypesAgree argument boundTy -> pure InstElim
          | otherwise -> do
              inside <- constructInstantiation (tyToElab bound) argument
              pure (InstSeq (InstInside inside) InstElim)
        _ ->
          failEdge
            [ "application transport has no leading quantifier",
              "current type=" ++ show current,
              "argument=" ++ show argument
            ]

data EdgeAuthority
  = ReplayEdgeAuthority
  | IdentityEdgeAuthority
  | GraftedEdgeAuthority
  deriving (Eq, Show)

-- | Reify destination types from the application topology retained by
-- constraint generation.  Its allocation fields own the original
-- @arrow(domain, codomain)@ construction; the prepared fields project those
-- endpoints through redirects, copying, and canonicalization.  Do not recover
-- either relation from the post-normalization base graph, an elaborated term,
-- or a type-checking failure.
applicationDestinationTypes ::
  AlgebraContext p ->
  IntMap.IntMap TypeBinderRef ->
  InstantiationSite ->
  InstantiationSite ->
  NodeId ->
  Either ElabError (ElabType, ElabType)
applicationDestinationTypes algebraContext constructionAliases funSite argSite appNode = do
  (domainAllocated, domainPrepared, codomainPrepared) <-
    case instantiationSiteTargetTopology funSite of
      ArrowInstantiationTarget
        { instantiationArrowAllocatedDomain = domain0,
          instantiationArrowDomain = domain,
          instantiationArrowCodomain = codomain
        } -> pure (domain0, domain, codomain)
      AtomicInstantiationTarget ->
        failTopology ["function edge site does not retain an arrow target topology"]
  -- The retained allocation topology is the construction-time authority.
  -- Normalization may graft a more precise child into the arrow node before
  -- this acyclic base is captured, so re-reading that transformed node here
  -- would compare two different phases and reject a valid application.
  if domainAllocated == argTargetAllocated
    then pure ()
    else
      failTopology
        [ "function arrow domain is not the argument edge allocation target",
          "arrow domain=" ++ show domainAllocated,
          "argument target=" ++ show argTargetAllocated
        ]
  namedRoutes0 <-
    foldM
      insertNamedRoute
      IntMap.empty
      (IntMap.toList constructionAliases)
  namedRoutes <-
    bridgeAllocatedDomainRoute
      domainPrepared
      (instantiationSiteTarget argSite)
      namedRoutes0
  let namedSet =
        IntSet.fromList (IntMap.keys namedRoutes)
      namedSchemeInfo =
        schemeInfoFromRefSubst
          (schemeFromType TBottom)
          namedRoutes
      reifyPreparedType node =
        let canonicalKey =
              getNodeId (scCanonical scopeContext node)
         in if IntMap.member canonicalKey namedRoutes
              then
                -- A construction alias is an exact named S' declaration;
                -- retaining its identity is the point of this projection.
                reifyTargetNodeType
                  scopeContext
                  namedSet
                  namedSchemeInfo
                  node
              else
                -- Unnamed graph destinations still follow their solved
                -- lower bound.  Treating every topology node as named would
                -- turn a grafted literal endpoint back into a fresh TVar.
                reifyNodeTypePreferringBound scopeContext node
  domainTy <- reifyPreparedType domainPrepared
  argumentTy <- reifyPreparedType (instantiationSiteTarget argSite)
  codomainTy <- reifyPreparedType codomainPrepared
  applicationResultTy <- reifyPreparedType appNode
  if scopedTypesAgree scopeContext domainTy argumentTy
    then pure ()
    else
      failTopology
        [ "projected arrow domain does not equal projected argument destination",
          "allocated shared domain=" ++ show domainAllocated,
          "prepared arrow domain=" ++ show domainPrepared,
          "prepared argument destination="
            ++ show (instantiationSiteTarget argSite),
          "canonical arrow domain="
            ++ show (scCanonical scopeContext domainPrepared),
          "canonical argument destination="
            ++ show
              ( scCanonical
                  scopeContext
                  (instantiationSiteTarget argSite)
              ),
          "arrow domain node="
            ++ show
              ( pvLookupNode
                  (scPresolutionView scopeContext)
                  domainPrepared
              ),
          "argument destination node="
            ++ show
              ( pvLookupNode
                  (scPresolutionView scopeContext)
                  (instantiationSiteTarget argSite)
              ),
          "construction aliases=" ++ show constructionAliases,
          "domain type=" ++ show domainTy,
          "argument type=" ++ show argumentTy
        ]
  if scopedTypesAgree scopeContext codomainTy applicationResultTy
    then pure ()
    else
      failTopology
        [ "projected arrow codomain does not equal projected application result",
          "codomain type=" ++ show codomainTy,
          "application result type=" ++ show applicationResultTy
        ]
  pure (argumentTy, codomainTy)
  where
    scopeContext = acScopeContext (algAnnotationContext algebraContext)
    argTargetAllocated = instantiationSiteAllocatedTarget argSite
    -- Constraint generation allocated one shared S'(n1) destination for the
    -- function domain and argument edge.  Redirect/copy preparation may leave
    -- the two retained endpoint nodes distinct, but a local-Gamma declaration
    -- published for either prepared endpoint therefore names both.  Bridge
    -- that identity before reification; this preserves the allocation
    -- invariant instead of comparing one named endpoint with the other's
    -- inlined bound.
    bridgeAllocatedDomainRoute leftNode rightNode routes =
      let leftKey = getNodeId (scCanonical scopeContext leftNode)
          rightKey = getNodeId (scCanonical scopeContext rightNode)
       in case (IntMap.lookup leftKey routes, IntMap.lookup rightKey routes) of
            (Nothing, Nothing) -> pure routes
            (Just leftRef, Nothing) ->
              pure (IntMap.insert rightKey leftRef routes)
            (Nothing, Just rightRef) ->
              pure (IntMap.insert leftKey rightRef routes)
            (Just leftRef, Just rightRef)
              | typeBinderRefsSameIdentity leftRef rightRef -> pure routes
              | otherwise ->
                  failTopology
                    [ "shared application domain has conflicting construction identities",
                      "prepared arrow domain=" ++ show leftNode,
                      "prepared argument destination=" ++ show rightNode,
                      "arrow-domain identity=" ++ show leftRef,
                      "argument identity=" ++ show rightRef
                    ]
    insertNamedRoute routes (nodeKey, outwardRef) =
      let canonicalKey =
            getNodeId
              (scCanonical scopeContext (NodeId nodeKey))
       in case IntMap.lookup canonicalKey routes of
            Nothing -> pure (IntMap.insert canonicalKey outwardRef routes)
            Just existing
              | typeBinderRefsSameIdentity existing outwardRef -> pure routes
              | otherwise ->
                  failTopology
                    [ "construction aliases collapse to different exact S' identities",
                      "graph node=" ++ show (NodeId nodeKey),
                      "canonical node=" ++ show (NodeId canonicalKey),
                      "first identity=" ++ show existing,
                      "second identity=" ++ show outwardRef
                    ]
    failTopology details =
      Left
        ( PhiInvariantError
            (unlines ("AAppF: invalid construction-time topology" : details))
        )

containsMuType :: ElabType -> Bool
containsMuType ty =
  case ty of
    TMuRef {} -> True
    TArrow dom cod -> containsMuType dom || containsMuType cod
    TConWithIdentity _ _ args -> any containsMuType args
    TVarAppRef _ args -> any containsMuType args
    TForallRef _ mb body -> maybe False containsMuBound mb || containsMuType body
    _ -> False
  where
    containsMuBound bound = case bound of
      TArrow dom cod -> containsMuType dom || containsMuType cod
      TConWithIdentity _ _ args -> any containsMuType args
      TVarAppRef _ args -> any containsMuType args
      TForallRef _ mb body -> maybe False containsMuBound mb || containsMuType body
      TMuRef {} -> True
      _ -> False

hasContractiveRecursiveWitness :: ElabType -> Bool
hasContractiveRecursiveWitness ty =
  containsMuType ty && isNothing (firstNonContractiveRecursiveType ty)

isSingleBinderIdentityScheme :: SchemeInfo -> Bool
isSingleBinderIdentityScheme schemeInfo =
  case (schemeBinderRefs (siScheme schemeInfo), schemeBody (siScheme schemeInfo)) of
    ([(binderRef, Nothing)], TArrow (TVarRef domRef) (TVarRef codRef)) ->
      typeBinderRefsSameIdentity binderRef domRef && typeBinderRefsSameIdentity binderRef codRef
    _ -> False

containsInternalTypeVar :: ElabType -> Bool
containsInternalTypeVar = any isInternalTypeBinderRef . freeTypeVarRefsType

{- Note [Internal graph variables are free variables]
~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
A graph-backed 'TypeBinderRef' is not necessarily unresolved: generalized
schemes deliberately retain graph identities for their bound variables.  The
recovery predicates in this module must therefore inspect only free type
variables.  Traversing every 'TVarRef' misclassifies @forall a. a -> a@ as an
internal scheme and repeatedly rebuilds identity wrappers around it.
-}

{- Note [Recursive identity applications use the argument type]
~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
An unannotated identity lambda is valid at every monomorphic parameter type.
At an application such as @(\y. y) k@, the checked type of @k@ is therefore
the authoritative parameter type.  Presolution can retain two closed,
non-equivalent mu representations across the application edge even though the
edge itself needs no xMLF instantiation.  Choosing the lambda-domain replay in
that case constructs an ill-typed application.

When the head is syntactically an identity lambda and the argument carries a
contractive recursive type, AApp constructs the lambda binder and its matching
occurrences with the argument type.  This is valid by the identity-lambda rule
and avoids treating bound graph identities as unresolved-variable evidence.
-}

isInternalTypeBinderRef :: TypeBinderRef -> Bool
isInternalTypeBinderRef ref =
  isJust (typeBinderRefNode ref)

mkEnvBinding :: VarName -> IdDetails -> SchemeInfo -> Maybe TransparentMediatorKind -> EnvBinding
mkEnvBinding name details schemeInfo transparentMediator =
  EnvBinding
    { ebSchemeInfo = schemeInfo,
      ebSchemeType = schemeToType (siScheme schemeInfo),
      ebIdentityDetails = details,
      ebRuntimeName = name,
      ebTransparentMediator = transparentMediator,
      ebAliasTarget = Nothing,
      ebExplicitRecursiveParam = False
    }

mkEnvValueBinding :: VarName -> EnvRef -> SchemeInfo -> Maybe TransparentMediatorKind -> EnvBinding
mkEnvValueBinding name envRef =
  mkEnvBinding name (EnvId envRef)

resolvedTermBinderDetails :: VarName -> IdDetails -> IdDetails
resolvedTermBinderDetails runtimeAlias =
  idDetailsRenameLocal runtimeAlias

mkLocalEnvBinding :: VarName -> IdDetails -> SchemeInfo -> Maybe TransparentMediatorKind -> EnvBinding
mkLocalEnvBinding = mkEnvBinding

localBinderIsDiscard :: IdDetails -> Bool
localBinderIsDiscard = idDetailsIsDiscard

resolvedLocalBinder :: IdDetails -> ElabType -> ResolvedVar
resolvedLocalBinder details ty =
  ResolvedVar
    { resolvedVarType = ty,
      resolvedVarDetails = details
    }

mkLocalLam :: IdDetails -> ElabType -> XmlfTerm -> XmlfTerm
mkLocalLam details ty =
  ELam (resolvedLocalBinder details ty)

mkLocalLet :: IdDetails -> ElabScheme -> XmlfTerm -> XmlfTerm -> XmlfTerm
mkLocalLet details scheme =
  ELet (resolvedLocalBinder details (schemeToType scheme)) scheme

mkEnv :: Map.Map VarName SchemeInfo -> Env
mkEnv schemeInfos =
  mkEnvFromBindings (map snd bindings)
  where
    (_, bindings) =
      mapAccumL mkBinding initialGenerator (Map.toList schemeInfos)

    initialGenerator =
      identityGeneratorAfter $
        concatMap generatedIdentitiesInSchemeInfo (Map.elems schemeInfos)

    mkBinding generator (name, schemeInfo) =
      let (envRef, generator') = freshEnvRef name generator
       in (generator', (name, mkEnvValueBinding name envRef schemeInfo Nothing))

mkEnvWithResolvedBindings :: Map.Map VarName (SchemeInfo, ResolvedVar) -> Env
mkEnvWithResolvedBindings schemeInfos =
  mkEnvFromBindings (Map.elems bindings)
  where
    bindings =
      Map.map
        ( \(schemeInfo, resolved) ->
            mkEnvBinding (resolvedVarRuntimeName resolved) (resolvedVarDetails resolved) schemeInfo Nothing
        )
        schemeInfos

mkEnvFromBindings :: [EnvBinding] -> Env
mkEnvFromBindings bindings =
  Env
    { envBindingsByIdentity = envBindingIdentityIndex bindings
    , envTypeBindings = Map.empty
    , envConstructionGammaAliases = IntMap.empty
    , envGammaCopiedBinderRoutes = Map.empty
    , envSourceRefinedGammaBounds = Map.empty
    , envConstructedLambdaParamTypes = Map.empty
    , envExactApplicationLambdaParamSchemes = Map.empty
    , envLambdaParamBoundaryCertificates = []
    , envConstructionBinderRenames = []
    , envCompilerExactBinderRenames = []
    , envActiveSubtermConstruction = Nothing
    , envLocalGammaClosures = IntMap.empty
    , envFrozenEndpointCertificates = IntMap.empty
    , envExpectedTermEndpoint = Nothing
    , envApplicationSourceOccurrence = Nothing
    }

envBindingIdentityIndex :: [EnvBinding] -> Map.Map EnvBindingIdentityKey EnvBinding
envBindingIdentityIndex bindings =
  Map.fromList
    [ (envBindingIdentityKey binding, binding)
    | binding <- bindings
    ]

envGeneratedIdentities :: Env -> [UniqueIdentity]
envGeneratedIdentities env =
  concatMap envBindingGeneratedIdentities (authoritativeEnvBindings env)
  where
    envBindingGeneratedIdentities binding =
      idDetailsGeneratedIdentities (ebIdentityDetails binding)
        ++ generatedIdentitiesInSchemeInfo (ebSchemeInfo binding)
        ++ generatedIdentitiesInType (ebSchemeType binding)

typeCheckEnvFrom :: Env -> TypeCheck.Env
typeCheckEnvFrom env =
  TypeCheck.mkTypeCheckEnvWithResolvedTerms
    [ (resolvedEnvBindingVar binding, ebSchemeType binding)
    | binding <- authoritativeEnvBindings env
    ]
    completedTypeBindings
  where
    typeBindings0 = envTypeBindings env
    -- Every declaration in the flattened type-checking environment is already
    -- in lexical scope.  Preserve those declarations while applying a newly
    -- inherited parameter-boundary certificate: an opened dependent bound such
    -- as @b : a -> a@ must not be closed back to @b : forall a. a -> a@ after
    -- the construction Gamma has completed it.
    lexicalRefs = Map.keys typeBindings0
    completedTypeBindings =
      Map.mapWithKey
        ( completeLambdaParamBoundaryDeclarationBoundInScope
            (envLambdaParamBoundaryCertificates env)
            lexicalRefs
        )
        typeBindings0

-- | Project only the resolved-term lookup payloads used by a boundary-local
-- xMLF check.  An occurrence route is not a new construction quotient, so
-- leave Gamma binders, aliases, and accumulated construction routes
-- untouched.  The caller supplies the same ordered composition used for the
-- term: graph occurrence to source, followed by any exact owner construction.
projectResolvedOccurrenceLookupTypes
  :: [(TypeBinderRef, TypeBinderRef)]
  -> Env
  -> Env
projectResolvedOccurrenceLookupTypes requestedRenames env =
  env
    { envBindingsByIdentity =
        Map.map projectBinding (envBindingsByIdentity env)
    }
  where
    projectBinding binding =
      binding
        { ebSchemeType =
            applyTypeVarRefRenames
              requestedRenames
              (ebSchemeType binding)
        }

-- | Compose an edge-local graph-to-source occurrence route with any exact
-- lambda-parameter boundary that has already completed the routed source
-- graph root.  The ordinary source projection deliberately accepts only a
-- generated identity in one step.  At a nested application, however, the
-- positive construction is often two steps:
--
-- @Graph(argument) -> Graph(parameter) -> Source(parameter)@.
--
-- The first edge is carried by the application requirement sidecar and the
-- second by 'LambdaParamBoundaryCertificate'.  Only substitute through a
-- graph-valued sidecar when the boundary certificate actually completes that
-- graph root; unrelated graph-to-graph routes retain their existing meaning.
projectSourceOccurrenceThroughLambdaBoundaries
  :: (NodeId -> NodeId)
  -> IntMap.IntMap TypeBinderRef
  -> [LambdaParamBoundaryCertificate]
  -> ElabType
  -> ElabType
projectSourceOccurrenceThroughLambdaBoundaries
  representative
  sourceBinderRefs
  certificates
  ty0 =
  foldl' completeRoutedGraph sourceProjected sourceProjectedFreeRefs
  where
    sourceProjected =
      resolveSourceBinderAliasesInType
        representative
        sourceBinderRefs
        ty0
    sourceProjectedFreeRefs = freeTypeVarRefsType sourceProjected

    completeRoutedGraph ty graphRef =
      case routedSourceRef graphRef of
        Nothing -> ty
        Just routedRef ->
          let routedTy = TVarRef routedRef
              completedTy =
                completeLambdaParamBoundaryType certificates routedTy
           in if boundaryCompleted routedRef completedTy
                then substTypeCaptureRef graphRef completedTy ty
                else ty

    routedSourceRef graphRef = do
      graphNode <- typeBinderRefNode graphRef
      case IntMap.lookup (getNodeId graphNode) sourceBinderRefs of
        Just directRef -> Just directRef
        Nothing ->
          IntMap.lookup
            (getNodeId (representative graphNode))
            sourceBinderRefs

    boundaryCompleted routedRef completedTy =
      case completedTy of
        TVarRef completedRef ->
          not (typeBinderRefsSameIdentity routedRef completedRef)
        _ -> True

extendEnvTypeScope :: [(TypeBinderRef, Maybe BoundType)] -> Env -> Env
extendEnvTypeScope binders env =
  env
    { envTypeBindings =
        foldl insertBinding (envTypeBindings env) binders
    }
  where
    constructionRenames = envConstructionBinderRenames env

    insertBinding bindings (ref, mbBound) =
      let ref' = applyRefRenames constructionRenames ref
          bound' =
            completeLambdaParamBoundaryDeclarationBoundInScope
              (envLambdaParamBoundaryCertificates env)
              (Map.keys bindings)
              ref'
              ( applyTypeVarRefRenames constructionRenames
                  (maybe TBottom tyToElab mbBound)
              )
       in Map.insert ref' bound' $
            Map.filterWithKey
              (\existing _ -> not (typeBinderRefsSameIdentity existing ref'))
              bindings

-- | Enter the binder spine carried by an already certified exact
-- construction.  Unlike the ordinary scope extension, this boundary refuses
-- to overwrite a completed declaration with an unrelated bound.  The only
-- admissible refinement is the transition from an existing provisional
-- @Bottom@ slot to the bound fixed by the certificate.
extendEnvTypeScopeFromExactConstruction
  :: String
  -> [(TypeBinderRef, Maybe BoundType)]
  -> Env
  -> Either ElabError Env
extendEnvTypeScopeFromExactConstruction context binders env0 =
  foldM enterBinder env0 binders
  where
    enterBinder env binder@(ref, _) = do
      let completedEnv = extendEnvTypeScope [binder] env
          completedRef =
            applyRefRenames
              (envConstructionBinderRenames env)
              ref
          existingBindings =
            [ (existingRef, existingBound)
            | (existingRef, existingBound) <-
                Map.toList (envTypeBindings env)
            , typeBinderRefsSameIdentity existingRef completedRef
            ]
      completedBound <-
        case Map.lookup completedRef (envTypeBindings completedEnv) of
          Just bound -> pure bound
          Nothing ->
            Left
              ( ValidationFailed
                  [ "exact construction failed to enter its Gamma declaration"
                  , "  context: " ++ context
                  , "  declaration: " ++ show completedRef
                  ]
              )
      unless
        ( all
            ( \(_, existingBound) ->
                operationalEndpointTypesAgree existingBound completedBound
                  || case existingBound of
                    TBottom -> True
                    _ -> False
            )
            existingBindings
        )
        ( Left
            ( ValidationFailed
                [ "exact construction conflicts with an existing Gamma declaration"
                , "  context: " ++ context
                , "  declaration: " ++ show completedRef
                , "  certified bound: " ++ show completedBound
                , "  existing declarations: " ++ show existingBindings
                , "  source-refined declarations: "
                    ++ show
                      (Map.toList (envSourceRefinedGammaBounds env))
                ]
            )
        )
      pure completedEnv

-- | Extend the construction environment with both the outward scheme
-- binders and every graph-local identity that the scheme substitution maps
-- to those binders.  Omega computations are constructed before the final
-- term-wide substitution is applied, so their Hyp nodes still mention the
-- graph identity even when the published scheme already prefers a source or
-- generated identity.  Both names denote one prepared Gamma obligation; the
-- alias bridge is construction-local and disappears when the term is
-- substituted and closed.
extendEnvTypeScopeWithAliases
  :: IntMap.IntMap TypeBinderRef
  -> [(TypeBinderRef, Maybe BoundType)]
  -> Env
  -> Env
extendEnvTypeScopeWithAliases subst binders env =
  envWithAliases
  where
    constructionSubst =
      IntMap.map
        (applyRefRenames (envConstructionBinderRenames env))
        subst
    envWithBinders = extendEnvTypeScope binders env
    bindingsWithBinders = envTypeBindings envWithBinders
    graphAliases =
      [ (graphRef, outwardType)
      | (nodeKey, outwardRef) <- IntMap.toList constructionSubst,
        Just outwardType <-
          [find
            (typeBinderRefsSameIdentity outwardRef . fst)
            (Map.toList bindingsWithBinders)
            >>= (pure . snd)],
        let graphRef =
              typeBinderRefFromIdentity
                (typeBinderIdentityFromNode (NodeId nodeKey))
                ("t" ++ show nodeKey),
        not (typeBinderRefsSameIdentity graphRef outwardRef)
      ]
    envWithAliases =
      envWithBinders
        { envTypeBindings =
            foldl'
              insertAlias
              bindingsWithBinders
              graphAliases
        , envConstructionGammaAliases =
            IntMap.union
              constructionSubst
              (envConstructionGammaAliases envWithBinders)
        }

    insertAlias bindings (graphRef, outwardType) =
      Map.insert graphRef outwardType $
        Map.filterWithKey
          (\existing _ -> not (typeBinderRefsSameIdentity existing graphRef))
          bindings

-- | Attach the copy certificate returned by packet placement to the exact
-- Gamma declarations installed from that placed scheme.  The declaration is
-- the provenance owner: a prepared packet may be placed more than once, and
-- each placement allocates a different copied binder spine.
installGammaCopiedBinderRoutes
  :: Map.Map
      TypeBinderIdentity
      [(TypeBinderIdentity, TypeBinderRef)]
  -> Env
  -> Either ElabError Env
installGammaCopiedBinderRoutes routes env = do
  merged <-
    foldM
      insertTargetRoutes
      (envGammaCopiedBinderRoutes env)
      (Map.toList routes)
  pure env {envGammaCopiedBinderRoutes = merged}
  where
    insertTargetRoutes accumulated (targetIdentity, incomingRoutes) = do
      unless
        ( any
            ((== targetIdentity) . typeBinderRefIdentity)
            (Map.keys (envTypeBindings env))
        )
        ( Left
            ( ValidationFailed
                [ "placed copied-binder provenance has no construction Gamma declaration"
                , "  target identity: " ++ show targetIdentity
                , "  routes: " ++ show incomingRoutes
                , "  Gamma binders: " ++ show (Map.keys (envTypeBindings env))
                ]
            )
        )
      case Map.lookup targetIdentity accumulated of
        Nothing ->
          pure (Map.insert targetIdentity incomingRoutes accumulated)
        Just existingRoutes
          | copiedBinderRoutesAgree existingRoutes incomingRoutes ->
              pure accumulated
          | otherwise ->
              Left
                ( ValidationFailed
                    [ "construction Gamma declaration has conflicting copied-binder provenance"
                    , "  target identity: " ++ show targetIdentity
                    , "  first routes: " ++ show existingRoutes
                    , "  second routes: " ++ show incomingRoutes
                    ]
                )

    copiedBinderRoutesAgree left right =
      length left == length right
        && all
          ( \(sourceIdentity, copiedRef) ->
              case lookup sourceIdentity right of
                Just otherCopiedRef ->
                  typeBinderRefsSameIdentity copiedRef otherCopiedRef
                Nothing -> False
          )
          left

renameGammaCopiedBinderRoutes
  :: [(TypeBinderRef, TypeBinderRef)]
  -> Map.Map
      TypeBinderIdentity
      [(TypeBinderIdentity, TypeBinderRef)]
  -> Either
      ElabError
      ( Map.Map
          TypeBinderIdentity
          [(TypeBinderIdentity, TypeBinderRef)]
      )
renameGammaCopiedBinderRoutes renames routes =
  foldM insertRenamedTarget Map.empty (Map.toList routes)
  where
    insertRenamedTarget accumulated (targetIdentity, copiedRoutes) =
      let targetRef =
            typeBinderRefFromIdentity
              targetIdentity
              (typeBinderIdentityStableName targetIdentity)
          targetIdentity' = typeBinderRefIdentity (renameRef targetRef)
          copiedRoutes' =
            [ ( typeBinderRefIdentity (renameRef sourceRef)
              , renameRef copiedRef
              )
            | (sourceIdentity, copiedRef) <- copiedRoutes
            , let sourceRef =
                    typeBinderRefFromIdentity
                      sourceIdentity
                      (typeBinderIdentityStableName sourceIdentity)
            ]
       in case Map.lookup targetIdentity' accumulated of
            Nothing ->
              pure (Map.insert targetIdentity' copiedRoutes' accumulated)
            Just existingRoutes
              | copiedBinderRoutesAgree existingRoutes copiedRoutes' ->
                  pure accumulated
              | otherwise ->
                  Left
                    ( ValidationFailed
                        [ "construction quotient merges conflicting copied-binder provenance"
                        , "  target identity: " ++ show targetIdentity'
                        , "  first routes: " ++ show existingRoutes
                        , "  second routes: " ++ show copiedRoutes'
                        ]
                    )

    renameRef ref =
      case find (typeBinderRefsSameIdentity ref . fst) renames of
        Just (_, renamed) -> renamed
        Nothing -> ref

    copiedBinderRoutesAgree left right =
      length left == length right
        && all
          ( \(sourceIdentity, copiedRef) ->
              case lookup sourceIdentity right of
                Just otherCopiedRef ->
                  typeBinderRefsSameIdentity copiedRef otherCopiedRef
                Nothing -> False
          )
          left

-- | Project only construction-authoritative scheme routes into the term
-- environment.  A scheme substitution can retain graph routes used solely to
-- replay Omega, so its mere presence is not permission to change a captured
-- term binding.  A route becomes construction authority exactly when its
-- outward ref is declared by this scheme or is already an exact ambient Gamma
-- binder.  Entering those routes before recursively constructing the body
-- keeps captured variable types in the same identity domain as the scheme that
-- will close the lambda.
schemeConstructionAuthorityRenames
  :: IntMap.IntMap TypeBinderRef
  -> Env
  -> SchemeInfo
  -> [(TypeBinderRef, TypeBinderRef)]
schemeConstructionAuthorityRenames directSourceBinderRefs env schemeInfo =
  [ (graphRef, outwardRef)
  | (nodeKey, outwardRef) <-
      IntMap.toList (schemeInfoBinderRefSubst schemeInfo)
  , let graphRef =
          typeBinderRefFromIdentity
            (typeBinderIdentityFromNode (NodeId nodeKey))
            ("t" ++ show nodeKey)
  , not (typeBinderRefsSameIdentity graphRef outwardRef)
  , any
      (typeBinderRefsSameIdentity outwardRef)
      declaredRefs
      || envOwnsExactTypeBinderRef env outwardRef
      || isJust
        ( directSourceBinderConstructionRename
            directSourceBinderRefs
            nodeKey
            outwardRef
        )
  , routeBoundCompatible graphRef outwardRef
  ]
  where
    declaredBinders = schemeBinderRefs (siScheme schemeInfo)
    declaredRefs = map fst declaredBinders

    routeBoundCompatible graphRef outwardRef =
      constructionRouteBoundCompatible
        (envConstructionBinderRenames env)
        graphRef
        outwardRef
        (lookupCurrentBound graphRef)
        (lookupOutwardBound outwardRef)

    lookupCurrentBound ref =
      let currentRef =
            applyRefRenames
              (envConstructionBinderRenames env)
              ref
       in snd
            <$> find
              (typeBinderRefsSameIdentity currentRef . fst)
              (Map.toList (envTypeBindings env))

    lookupOutwardBound outwardRef =
      case
          find
            (typeBinderRefsSameIdentity outwardRef . fst)
            declaredBinders
        of
          Just (_, mbBound) ->
            Just (maybe TBottom tyToElab mbBound)
          Nothing ->
            snd
              <$> find
                (typeBinderRefsSameIdentity outwardRef . fst)
                (Map.toList (envTypeBindings env))

-- | Install the exact nested-construction proofs prepared for this root.
-- They are consulted only by the matching edge/owner/consumer closure check;
-- no binder or alias is manufactured from this map.
withEnvLocalGammaClosures
  :: IntMap.IntMap LocalGammaClosure
  -> Env
  -> Env
withEnvLocalGammaClosures closures env =
  env {envLocalGammaClosures = closures}

-- | Install the construction domain owned by one compiler-exact edge.  Most
-- delayed packet results are abstracted by 'completeCompilerExactSubtermResults'.
-- An enclosing-owned marker has no completion action, but that alone does not
-- make its packet-local result an ambient binder: a lambda/application below
-- this exact boundary may still own the corresponding type abstraction.
--
-- Bridge the packet construction identity only when its prepared consumer is
-- already present in the explicit ambient type scope.  The consumer authority
-- and packet substitution select the identities; the prepared complete Gamma
-- bound supplies their type.  Thus an exact edge can refine a real lexical
-- binder without pre-opening a result that its child must construct locally.
-- Absence of a prepared result bound remains an error rather than an
-- invitation to manufacture a bottom-bound scope.
--
-- The resulting environment remains edge-local, so sibling exact occurrences
-- cannot observe either these routes or these type-scope bindings.
installCompilerExactConstructionRefs
  :: EdgeId
  -> SubtermGeneralizations
  -> IntMap.IntMap TypeBinderRef
  -> Env
  -> Either ElabError Env
installCompilerExactConstructionRefs edgeId packets edgeRefs env = do
  aliases <-
    foldM
      insertRoute
      (envConstructionGammaAliases env)
      (IntMap.toList edgeRefs)
  enclosingBinders <-
    fmap catMaybes
      ( traverse
          preparedEnclosingBinder
          [ (owner, packet)
          | (owner, packet) <- Map.toList packets
          , subtermGeneralizationCompilerExactBoundary packet == Just edgeId
          ]
      )
  foldM
    installPreparedBinder
    env {envConstructionGammaAliases = aliases}
    enclosingBinders
  where
    insertRoute aliases (nodeKey, outwardRef) =
      case IntMap.lookup nodeKey aliases of
        Nothing -> pure (IntMap.insert nodeKey outwardRef aliases)
        Just existingRef
          | typeBinderRefsSameIdentity existingRef outwardRef -> pure aliases
          | otherwise ->
              Left
                ( ValidationFailed
                    [ "compiler exact edge conflicts with the enclosing construction route"
                    , "  edge: " ++ show edgeId
                    , "  graph node: " ++ show (NodeId nodeKey)
                    , "  enclosing identity: " ++ show existingRef
                    , "  exact identity: " ++ show outwardRef
                    ]
                )

    preparedEnclosingBinder (owner, packet) =
      case
          ( subtermGeneralizationCompilerExactResultRef packet
          , subtermGeneralizationCompilerExactCompletionRef packet
          )
        of
          (Just packetResultRef, Nothing) -> do
            validatePacketResultBound owner packetResultRef packet
            consumerAuthority <-
              case subtermGeneralizationConsumerAuthority packet of
                Just authority -> pure authority
                Nothing ->
                  Left
                    ( ValidationFailed
                        [ "compiler exact enclosing result has no consumer authority"
                        , "  edge: " ++ show edgeId
                        , "  owner: " ++ show owner
                        , "  result: " ++ show packetResultRef
                        ]
                    )
            consumerRef <-
              case subtermGeneralizationResultAbstractionRef packet of
                Just ref -> pure ref
                Nothing ->
                  missingConsumerRoute owner packetResultRef
                    "has no semantic consumer reference"
            constructionRef <-
              case subtermGeneralizationConstructionResultAbstractionRef packet of
                Just ref -> pure ref
                Nothing ->
                  missingConsumerRoute owner packetResultRef
                    "has no construction consumer reference"
            unless
              ( typeBinderRefIdentity consumerRef
                  == scaConsumerIdentity consumerAuthority
              )
              ( Left
                  ( ValidationFailed
                      [ "compiler exact enclosing result changed consumer identity"
                      , "  edge: " ++ show edgeId
                      , "  owner: " ++ show owner
                      , "  result: " ++ show packetResultRef
                      , "  authority consumer: "
                          ++ show (scaConsumerIdentity consumerAuthority)
                      , "  semantic consumer: " ++ show consumerRef
                      ]
                  )
              )
            let consumerDomainRefs =
                  uniqueRefs
                    ( consumerRef
                        : constructionRef
                        : routedRefsFor consumerRef
                          ++ routedRefsFor constructionRef
                    )
                ambientBindings =
                  [ binding
                  | binding@(existingRef, _) <-
                      Map.toList (envTypeBindings env)
                  , any
                      (typeBinderRefsSameIdentity existingRef)
                      consumerDomainRefs
                  , envOwnsExactTypeBinderRef env existingRef
                  ]
            case ambientBindings of
              [] -> pure Nothing
              _ -> do
                let preparedBound =
                      completeLambdaParamBoundaryType
                        (envLambdaParamBoundaryCertificates env)
                        ( schemeToType
                            (subtermGeneralizationGammaBoundScheme packet)
                        )
                mapM_
                  ( validateExisting
                      owner
                      packetResultRef
                      constructionRef
                      preparedBound
                  )
                  ambientBindings
                pure
                  ( Just
                      ( owner
                      , packetResultRef
                      , consumerRef
                      , constructionRef
                      , preparedBound
                      )
                  )
          (Just _, Just _) -> pure Nothing
          (Nothing, _) ->
            Left
              ( ValidationFailed
                  [ "compiler exact packet has no prepared result binder"
                  , "  edge: " ++ show edgeId
                  , "  owner: " ++ show owner
                  ]
              )

    validatePacketResultBound owner resultRef packet =
      case
          [ mbBound
          | (binderRef, mbBound) <-
              schemeBinderRefs
                (siScheme (subtermGeneralizationSchemeInfo packet))
          , typeBinderRefsSameIdentity binderRef resultRef
          ]
        of
          [Just _] -> pure ()
          [Nothing] ->
            missingPreparedBound owner resultRef
              "has no operated bound"
          [] ->
            missingPreparedBound owner resultRef
              "is absent from its prepared packet"
          _ ->
            missingPreparedBound owner resultRef
              "occurs more than once in its prepared packet"

    missingPreparedBound owner resultRef reason =
      Left
        ( ValidationFailed
            [ "compiler exact enclosing result " ++ reason
            , "  edge: " ++ show edgeId
            , "  owner: " ++ show owner
            , "  result: " ++ show resultRef
            ]
        )

    missingConsumerRoute owner resultRef reason =
      Left
        ( ValidationFailed
            [ "compiler exact enclosing result " ++ reason
            , "  edge: " ++ show edgeId
            , "  owner: " ++ show owner
            , "  result: " ++ show resultRef
            ]
        )

    routedRefsFor ref =
      case typeBinderRefNode ref of
        Nothing -> []
        Just node ->
          maybeToList
            ( IntMap.lookup
                (getNodeId node)
                (envConstructionGammaAliases env)
            )
            ++ maybeToList
              (IntMap.lookup (getNodeId node) edgeRefs)

    uniqueRefs = foldr insertUniqueRef []

    insertUniqueRef ref refs
      | any (typeBinderRefsSameIdentity ref) refs = refs
      | otherwise = ref : refs

    installPreparedBinder
      scopedEnv
      (owner, packetResultRef, consumerRef, constructionRef, preparedBound) =
      foldM
        (installOne owner packetResultRef preparedBound)
        scopedEnv
        installRefs
      where
        packetConstructionRef =
          [ packetResultRef
          | any
              (typeBinderRefsSameIdentity packetResultRef)
              [consumerRef, constructionRef]
          ]
        constructionDomainRefs =
          uniqueRefs
            ( consumerRef
                : constructionRef
                : packetConstructionRef
                  ++ routedRefsFor consumerRef
                  ++ routedRefsFor constructionRef
            )
        installRefs =
          uniqueRefs
            ( constructionDomainRefs
                ++ concatMap graphAliasesFor constructionDomainRefs
            )

    graphAliasesFor resultRef =
      [ graphRef
      | (nodeKey, outwardRef) <- IntMap.toList edgeRefs
      , typeBinderRefsSameIdentity outwardRef resultRef
      , let graphRef =
              typeBinderRefFromIdentity
                (typeBinderIdentityFromNode (NodeId nodeKey))
                ("t" ++ show nodeKey)
      , not (typeBinderRefsSameIdentity graphRef resultRef)
      ]

    installOne owner resultRef preparedBound scopedEnv ref = do
      mapM_ (validateExisting owner resultRef ref preparedBound) sameIdentityBindings
      pure
        scopedEnv
          { envTypeBindings =
              Map.insert ref preparedBound $
                Map.filterWithKey
                  (\existing _ -> not (typeBinderRefsSameIdentity existing ref))
                  (envTypeBindings scopedEnv)
          }
      where
        sameIdentityBindings =
          [ (existingRef, existingBound)
          | (existingRef, existingBound) <- Map.toList (envTypeBindings scopedEnv)
          , typeBinderRefsSameIdentity existingRef ref
          ]

    validateExisting owner resultRef installedRef preparedBound (existingRef, existingBound)
      | existingBound == TBottom = pure ()
      | alphaEqType existingBound preparedBound
          || churchAwareEqType existingBound preparedBound = pure ()
      | otherwise =
          Left
            ( ValidationFailed
                [ "compiler exact enclosing result conflicts with its prepared Gamma bound"
                , "  edge: " ++ show edgeId
                , "  owner: " ++ show owner
                , "  result: " ++ show resultRef
                , "  installed identity: " ++ show installedRef
                , "  existing identity: " ++ show existingRef
                , "  existing bound: " ++ show existingBound
                , "  prepared bound: " ++ show preparedBound
                ]
            )

-- | Exact graph-node routes for binders already present in a construction
-- environment.  Explicit aliases win, while a graph-backed type-scope binder
-- supplies its own identity route when no alias was necessary.
envConstructionIdentityRoutes :: Env -> IntMap.IntMap TypeBinderRef
envConstructionIdentityRoutes env =
  IntMap.union
    (envConstructionGammaAliases env)
    ( IntMap.fromList
        [ (getNodeId node, ref)
        | ref <- Map.keys (envTypeBindings env),
          Just node <- [typeBinderRefNode ref]
        ]
    )

-- | Enter the parameter boundary chosen by construction.  Exact source
-- evidence parameters own their complete type and therefore remove a graph
-- root alias instead of treating that root as one type-variable occurrence.
-- Ordinary constructed parameters retain the historical Gamma refinement.
installConstructedLambdaParamBound
  :: NodeId
  -> LambdaParamBoundaryAuthority
  -> Env
  -> Either
      ElabError
      ( ElabType
      , Set.Set TypeBinderIdentity
      , LambdaParamBoundaryCertificate
      , Env
      )
installConstructedLambdaParamBound paramNode authority env = do
  installation <-
    installLambdaParamBoundary
      paramNode
      authority
      (envConstructionGammaAliases env)
      (envTypeBindings env)
  let certificate = lambdaParamBoundaryCertificate installation
      completeExactBinding binding =
        let schemeInfo =
              completeLambdaParamBoundarySchemeInfo
                [certificate]
                (ebSchemeInfo binding)
         in binding
              { ebSchemeInfo = schemeInfo
              , ebSchemeType = schemeToType (siScheme schemeInfo)
              }
      completedTermBindings =
        case authority of
          ExactSourceLambdaParamBoundary {} ->
            Map.map completeExactBinding (envBindingsByIdentity env)
          ExactApplicationLambdaParamBoundary {} ->
            Map.map completeExactBinding (envBindingsByIdentity env)
          ConstructedLambdaParamBoundary {} ->
            envBindingsByIdentity env
  pure
    ( lambdaParamBoundaryType installation,
      lambdaParamBoundaryLocalBinderIdentities installation,
      certificate,
      env
        { envBindingsByIdentity = completedTermBindings
        , envConstructionGammaAliases =
            lambdaParamBoundaryGammaAliases installation
        , envTypeBindings =
            lambdaParamBoundaryTypeBindings installation
        , envLambdaParamBoundaryCertificates =
            certificate : envLambdaParamBoundaryCertificates env
        }
    )

-- | Publish source-owned construction aliases at both their concrete graph
-- node and solved representative.  Descendant Γ preparation can reify a
-- sibling copy of the same lexical binder, so the representative route must
-- exist before its operated bound is built.  A representative that already
-- belongs to a distinct lexical source binder is deliberately left ambiguous;
-- conflicting concrete routes are still rejected.
constructionSourceBinderRefs
  :: (NodeId -> NodeId)
  -> Env
  -> IntMap.IntMap TypeBinderRef
  -> Either ElabError (IntMap.IntMap TypeBinderRef)
constructionSourceBinderRefs representative env sourceRefs = do
  let constructionSourceRefs =
        IntMap.map
          (applyRefRenames (envConstructionBinderRenames env))
          sourceRefs
  mergeConstructionSourceBinderRefs
    representative
    constructionSourceRefs
    (envConstructionGammaAliases env)

-- | Join immutable source provenance to the identity used by the current
-- checked construction.  A direct graph-occurrence key is the strongest
-- authority for this join because a packet quotient may intentionally make
-- the two identities differ.  An expanded construction route can lack that
-- original key while still retaining the source identity itself; in that
-- case the identity is sufficient authority.  A construction-only alias with
-- neither the source key nor its identity cannot be promoted.
sourceBinderAuthoritiesForConstruction
  :: String
  -> IntMap.IntMap TypeBinderRef
  -> IntMap.IntMap TypeBinderRef
  -> Either ElabError (IntMap.IntMap SourceBinderAuthority)
sourceBinderAuthoritiesForConstruction role sidecarRefs constructionRefs =
  IntMap.traverseWithKey authorityFor constructionRefs
  where
    authorityFor nodeKey constructionRef =
      case IntMap.lookup nodeKey sidecarRefs of
        Just sidecarRef ->
          pure (mkSourceBinderAuthority sidecarRef constructionRef)
        Nothing ->
          case
              find
                (typeBinderRefsSameIdentity constructionRef)
                (IntMap.elems sidecarRefs)
            of
              Just sidecarRef ->
                pure (mkSourceBinderAuthority sidecarRef constructionRef)
              Nothing ->
                Left
                  ( ValidationFailed
                      [ "source-owned construction route has no source-sidecar authority"
                      , "  role: " ++ role
                      , "  graph occurrence: " ++ show (NodeId nodeKey)
                      , "  construction ref: " ++ show constructionRef
                      , "  source sidecar: " ++ show sidecarRefs
                      ]
                  )

-- | Freeze only direct construction aliases whose outward identities have an
-- exact type binding in the current environment.  This is the authority used
-- before source-ABI alignment: graph-local inherited Gamma routes are not
-- source binder aliases and must remain in their own certificate channel.
ambientGammaAuthoritiesForEnv
  :: Env
  -> Either ElabError (IntMap.IntMap AmbientGammaAuthority)
ambientGammaAuthoritiesForEnv env =
  buildAmbientGammaAuthorities
    (envConstructionGammaAliases env)
    (envTypeBindings env)

-- | Select the complete owner-local Γ constructed for one Figure 15.3.5
-- boundary.  Ordinary binders produced by generalizing at that exact owner and
-- explicit root-RaiseMerge binders are one scope: both must be in scope before
-- the child computations are constructed.  The scheme has already been
-- generalized against the outer environment, so every remaining binder is
-- local to this boundary.  Bound dependencies follow it in scheme order.
constructionGammaBinders
  :: ConstructionGammaCoverage
  -> ScopeContext p
  -> IntSet.IntSet
  -> LocalGammaOwner
  -> Maybe PendingLocalResultSourcePacket
  -> Maybe PacketConsumerWithoutLocalBinder
  -> Maybe SchemeInfo
  -> Env
  -> GeneralizationRequirements
  -> SchemeInfo
  -> Either ElabError ConstructionGammaPlan
constructionGammaBinders coverage scopeContext directSourceBinderKeys owner pendingResultSourcePacket packetConsumerResolution ownerEmissionScheme0 env requirements0 schemeInfo0 = do
  constructionIdentityRoutes <- boundaryConstructionIdentityRoutes
  let boundaryOccurrenceRenames =
        boundaryGraphOccurrenceRenames constructionIdentityRoutes
      directRequirementSourceBinderRefs =
        IntMap.restrictKeys
          relevantRequirementSourceBinderRefs
          directSourceBinderKeys
      directSourceConstructionRoutes =
        IntMap.restrictKeys
          constructionIdentityRoutes
          directSourceBinderKeys
  sourceRequirementBoundRenames <-
    either
      (Left . ValidationFailed . pure)
      Right
      ( sourceBinderConstructionRenames
          (scopeTypeBinderIdentityRepresentative scopeContext)
          directRequirementSourceBinderRefs
          directSourceConstructionRoutes
      )
  requirementBoundRenames <-
    foldM
      insertRequirementBoundRename
      []
      ( boundaryOccurrenceRenames
          ++ ambientAuthorityOccurrenceRenames
          ++ sourceRequirementBoundRenames
      )
  requiredRefs <-
    traverse
      (requirementRefForOwner requirementBoundRenames)
      requiredBinders
  let EnvFreeTypeBinderRefs environmentRefList =
        envFreeTypeBinderRefs env
  ambientCandidateAuthorities <-
    traverse
      (uncurry (ambientBoundFor (const True)))
      (zip requiredBinders requiredRefs)
  let ambientSatisfiesRequirement requirement ref =
        maybe
          False
          ( \authority ->
              requiredBoundSatisfiedBy
                requirementBoundRenames
                ref
                (expectedBoundForRef requirementBoundRenames requirement ref)
                (agaBound authority)
          )
      requiredEntries =
        zip
          requiredBinders
          (zip requiredRefs ambientCandidateAuthorities)
  ownerConstructionPlans <-
    traverse
      ( \(requirement, (ref, mbAmbientAuthority)) ->
          localClosureBindersFor
            requirementBoundRenames
            ( ambientSatisfiesRequirement
                requirement
                ref
                mbAmbientAuthority
            )
            requirement
      )
      requiredEntries
  let ownerConstructionBinders = concatMap snd ownerConstructionPlans
      ownerLocalRequirementRefs =
        [ ref
        | ( (ownedByBoundary, _),
            (requirement, (ref, mbAmbientAuthority))
            ) <- zip
              ownerConstructionPlans
              requiredEntries,
          requirementNeedsLocalConstruction
            ownedByBoundary
            (rgbPlacement requirement)
            ( ambientSatisfiesRequirement
                requirement
                ref
                mbAmbientAuthority
            )
        ]
  let schemeConstructionBinders =
        [ ( ref
          , fmap
              (mapBoundType (applyBinderBoundRenames ref requirementBoundRenames))
              mbBound
          )
        | (ref, mbBound) <- schemeBinders
        ]
      ( schemeEndpointConstructionBinders
        , schemeLocalConstructionBinders
        ) =
          partition
            (ownerEmissionOwns . fst)
            schemeConstructionBinders
  -- Every binder explicitly declared by this exact construction boundary
  -- shadows an ambient ref in the same solved graph class.  Representative
  -- equality is valid only after excluding those owner-local declarations;
  -- otherwise their exact S(operated) bounds would be replaced by TBottom.
  -- An ordinary local-Gamma closure has no prebuilt owner scheme, but it is
  -- still the proof that this boundary owns the requirement.  Its ref shadows
  -- a provisional enclosing packet slot only when that slot does not already
  -- satisfy S(operated); an already-constructed ambient bound remains owned by
  -- its enclosing Gamma and must not be abstracted a second time.
  let localConstructionRefs =
        ownerLocalRequirementRefs
          ++ map fst ownerConstructionBinders
          ++ map fst ownerEmissionConstructionBinders
          ++ map fst schemeConstructionBinders
      refAlreadyInGamma ref =
        constructionRefAlreadyInGamma
          (scopeTypeBinderIdentityRepresentative scopeContext)
          localConstructionRefs
          environmentRefList
          ref
          || ( not
                 ( any
                     (typeBinderRefsSameIdentity ref)
                     localConstructionRefs
              )
                 && any
                   ( \(requiredRef, mbAuthority) ->
                       typeBinderRefsSameIdentity ref requiredRef
                         && isJust mbAuthority
                   )
                   (zip requiredRefs ambientCandidateAuthorities)
             )
      alignedOwnerEmissionConstructionBinders0 =
        [ ( ref,
            fmap
              (mapBoundType (applyBinderBoundRenames ref requirementBoundRenames))
              mbBound
          )
        | (ref, mbBound) <- ownerEmissionConstructionBinders
        ]
      -- 'validateOwnerConstructionBinders' has already selected the actual
      -- term-boundary declaration for every proved local closure.  A prepared
      -- owner scheme can retain a same-identity binder solely as replay
      -- metadata after that declaration moved into the current generalized
      -- scheme.  Keep only the residual prepared declarations here; otherwise
      -- the replay view competes with the actual emitter under the same local
      -- provenance (and can re-close a source forall that is already open).
      alignedOwnerEmissionConstructionBinders =
        [ binder
        | binder@(ref, _) <- alignedOwnerEmissionConstructionBinders0
        , not
            ( any
                (typeBinderRefsSameIdentity ref . fst)
                ownerConstructionBinders
            )
        ]
  requirementConstructionBinders <-
    concat
      <$> traverse
        (uncurry (requirementConstructionBinder requirementBoundRenames refAlreadyInGamma))
        (zip requiredBinders requiredRefs)
  let declaredConstructionBinders =
        ownerConstructionBinders
          ++ alignedOwnerEmissionConstructionBinders
          ++ schemeConstructionBinders
          ++ requirementConstructionBinders
      undeclaredDependencyRefs =
        foldr insertDistinctRef []
          [ dependency
          | (_, Just bound) <- declaredConstructionBinders
          , dependency <- freeTypeVarRefsType (tyToElab bound)
          , not (refAlreadyInGamma dependency)
          , not
              ( any
                  (typeBinderRefsSameIdentity dependency . fst)
                  declaredConstructionBinders
              )
          ]
  dependencyBinders <-
    completeDependencyConstructionBinders
      constructionIdentityRoutes
      requirementBoundRenames
      refAlreadyInGamma
      (map fst declaredConstructionBinders)
      undeclaredDependencyRefs
  candidateBinders <-
    case
        mergeConstructionBinderBoundsByProvenance
          ("application construction Gamma " ++ show owner)
          -- The generalized scheme has already placed descendant packets and
          -- allocated copied bound identities.  A requirement binder is the
          -- construction fallback for a quotient with no syntactic binder; it
          -- is exact-endpoint evidence, not authority to replace that prepared
          -- local declaration with the graph's raw operated type.
          --
          -- When this boundary also has an owner-emission scheme, that scheme
          -- was materialized from the recursively checked child and is the
          -- Figure 15.3.5 local-Gamma authority.  The independently
          -- generalized scheme can expose a specialized operated view of the
          -- same identity; keep that view as endpoint evidence so it cannot
          -- replace the complete bound that the emitted Hyp will consume.
          ( map
              (\binder -> (ConstructionLocalGammaBound, binder))
              ( dependencyBinders
                  ++ ownerConstructionBinders
                  ++ alignedOwnerEmissionConstructionBinders
                  ++ schemeLocalConstructionBinders
              )
              ++ map
                (\binder -> (ConstructionExactEndpoint, binder))
                ( schemeEndpointConstructionBinders
                    ++ requirementConstructionBinders
                )
          )
      of
        Right binders -> pure binders
        Left cause ->
          Left
            ( ValidationFailed
                [ "construction Gamma binder sources cannot be merged"
                , "  owner-construction binders: " ++ show ownerConstructionBinders
                , "  owner-emission binders: "
                    ++ show alignedOwnerEmissionConstructionBinders
                , "  scheme-construction binders: " ++ show schemeConstructionBinders
                , "  requirement-construction binders: " ++ show requirementConstructionBinders
                , "  cause: " ++ show cause
                ]
            )
  ambientRequiredAuthorities <-
    traverse
      (uncurry (ambientBoundFor refAlreadyInGamma))
      (zip requiredBinders requiredRefs)
  let ordinaryOwnerRefs =
        case coverage of
          RequiredGammaOnly -> []
          OwnerLocalAndRequiredGamma ->
            [ ref
            | (ref, _) <- schemeBinders,
              binderOwnedByBoundary ref
            ]
          -- An active consumer packet carries the completed type expected of
          -- this exact source boundary.  Once that certificate has selected
          -- the application, every leading binder left in its aligned scheme
          -- is precisely the local Gamma_g prefix from Figure 15.3.5.
          CompleteSchemeAndRequiredGamma ->
            map fst schemeBinders
      localRoots =
        [ ref
        | ref <- requiredRefs ++ ordinaryOwnerRefs,
          not (refAlreadyInGamma ref)
        ]
      localRefs = dependencyClosure refAlreadyInGamma candidateBinders localRoots
      selected =
        [ binder
        | binder@(ref, _) <- candidateBinders,
          refMember ref localRefs
        ]
      selectedRefs = map fst selected
      missingRoots =
        [ ref
        | ref <- localRoots,
          not (refMember ref selectedRefs)
        ]
      missingDependencies =
        [ dependency
        | (_, Just bound) <- selected,
          dependency <- freeTypeVarRefsType (tyToElab bound),
          not (refAlreadyInGamma dependency),
          not (refMember dependency selectedRefs)
        ]
      requiredBounds =
        [ ( requirement,
            ref,
            expectedBoundForRef requirementBoundRenames requirement ref,
            selectedBoundFor ref selected <|> (agaBound <$> ambientAuthority)
          )
        | ((requirement, ref), ambientAuthority) <-
            zip (zip requiredBinders requiredRefs) ambientRequiredAuthorities
        ]
      missingAmbientBounds =
        [ (ref, expectedBound)
        | (_, ref, expectedBound, Nothing) <- requiredBounds,
          refAlreadyInGamma ref
        ]
      mismatchedBounds =
        [ (ref, expectedBound, actualBound)
        | (_, ref, expectedBound, Just actualBound) <- requiredBounds,
          not
            ( requiredBoundSatisfiedBy
                requirementBoundRenames
                ref
                expectedBound
                actualBound
            )
        ]
  if null missingRoots
      && null missingDependencies
      && null missingAmbientBounds
      && null mismatchedBounds
    then do
      ambientAliases <-
        foldM
          insertAmbientAlias
          IntMap.empty
          [ (getNodeId node, agaExactRef authority)
          | (requirement, Just authority) <-
              zip requiredBinders ambientRequiredAuthorities,
            node <-
              rgbOperatedRoot requirement
                : rgbExteriorNode requirement
                : NonEmpty.toList (rgbResultRoots requirement)
          ]
      pure
        ConstructionGammaPlan
          { cgpBinders = selected,
            cgpAmbientAliases = ambientAliases,
            -- Preserve the exact quotient used to validate S(operated), not
            -- merely the first graph-routing subset.  Later declaration
            -- authorization must compare the emitted bound in this same
            -- construction domain.
            cgpRequirementBoundRenames = requirementBoundRenames,
            cgpValidatedLocalRequirementRefs =
              foldr insertDistinctRef []
                [ ref
                | (_, ref, _, Just _) <- requiredBounds,
                  not (refAlreadyInGamma ref),
                  refMember ref selectedRefs
                ]
          }
    else
      Left
        ( ValidationFailed
            [ "construction Γ requirements are not closed by the prepared scheme",
              "  required refs: " ++ show requiredRefs,
              "  exact owner: " ++ show owner,
              "  selected refs: " ++ show selectedRefs,
              "  missing roots: " ++ show missingRoots,
              "  missing dependencies: " ++ show missingDependencies,
              "  missing ambient bound authorities: " ++ show missingAmbientBounds,
              "  mismatched bounds: " ++ show mismatchedBounds,
              "  requirement bound renames: " ++ show requirementBoundRenames,
              "  construction identity routes: " ++ show constructionIdentityRoutes,
              "  relevant source refs: " ++ show relevantRequirementSourceBinderRefs,
              "  all source refs: " ++ show (grSourceBinderRefs requirements),
              "  direct source keys: " ++ show directSourceBinderKeys,
              "  construction binder renames: " ++ show constructionBinderRenames,
              "  requirements: " ++ show requiredBinders,
              "  requirement free-node state: "
                ++ show
                  [ ( ref
                    , scCanonical scopeContext <$> typeBinderRefNode ref
                    , typeBinderRefNode ref >>= pvLookupNode presolutionView
                    , typeBinderRefNode ref >>= pvLookupVarBound presolutionView
                    , typeBinderRefNode ref
                        >>= pvLookupVarBound presolutionView
                        >>= Just . scCanonical scopeContext
                    , typeBinderRefNode ref
                        >>= pvLookupVarBound presolutionView
                        >>= pvLookupNode presolutionView
                    , typeBinderRefNode ref
                        >>= either (const Nothing) Just
                          . reifyNodeTypePreferringBound scopeContext
                    )
                  | ref <- foldr insertDistinctRef [] (concatMap (freeTypeVarRefsType . rgbOperatedType) requiredBinders)
                  ],
              "  scheme substitution: " ++ show (siSubstRefs schemeInfo),
              "  scheme: " ++ show (siScheme schemeInfo)
            ]
        )
  where
    constructionBinderRenames =
      envConstructionBinderRenames env

    presolutionView = scPresolutionView scopeContext

    -- A boundary SchemeInfo substitution is an occurrence-level construction
    -- certificate: graph node @n@ and its routed ref denote the same already
    -- selected binder.  Its bound can still contain the graph-local identity
    -- even after the substitution publishes the source identity.  Project
    -- those free occurrences before merging Gamma bounds; waiting for final
    -- term substitution would compare two construction domains and reject a
    -- bound that was already equal by construction.
    boundaryGraphOccurrenceRenames routes =
      [ (graphRef, occurrenceRef)
      | (nodeKey, routedRef) <- IntMap.toList routes
      , let graphRef =
              typeBinderRefFromIdentity
                (typeBinderIdentityFromNode (NodeId nodeKey))
                ("t" ++ show nodeKey)
            occurrenceRef =
              sourceOwnedOccurrenceRef routes nodeKey routedRef
      , not (typeBinderRefsSameIdentity graphRef occurrenceRef)
      ]

    -- Generalization can publish a lexical/source identity as the exact
    -- ambient declaration for a graph node before this local Gamma is
    -- planned.  The authority carries both that declaration and its checked
    -- bound; use the same identity route inside requirement bounds.  Looking
    -- only at the construction alias map would retain the graph placeholder
    -- in S(operated) and compare it with the already-published source
    -- declaration as though they were two unrelated bounds.
    ambientAuthorityOccurrenceRenames =
      [ ( graphRef
        , agaExactRef authority
        )
      | (nodeKey, authority) <-
          IntMap.toList (grAmbientGammaAuthorities requirements)
      , let graphRef =
              typeBinderRefFromIdentity
                (typeBinderIdentityFromNode (NodeId nodeKey))
                ("t" ++ show nodeKey)
      , not
          ( typeBinderRefsSameIdentity
              graphRef
              (agaExactRef authority)
          )
      ]

    -- A graph occurrence can retain an administrative Gamma identity after a
    -- sibling occurrence in the same solved class has already published the
    -- exact lexical source identity.  In that case the source route is the
    -- positive construction witness for the occurrence; keeping the graph
    -- ref would make a prepared bound disagree with its source-projected
    -- S(operated).  A sidecar occurrence alone is not enough: when no exact
    -- source identity is present in this boundary's routes, as for an outer
    -- identity wrapper around the paper's @g g@, the graph binder remains a
    -- distinct declaration.
    sourceOwnedOccurrenceRef routes nodeKey fallbackRef =
      case IntMap.lookup nodeKey (grSourceBinderRefs requirements) of
        Nothing -> fallbackRef
        Just sourceRef
          | any
              ( \(candidateKey, candidateRef) ->
                  scopeTypeBinderIdentityRepresentative
                    scopeContext
                    (NodeId candidateKey)
                    == scopeTypeBinderIdentityRepresentative
                      scopeContext
                      (NodeId nodeKey)
                    && typeBinderRefsSameIdentity sourceRef candidateRef
              )
              (IntMap.toList routes) ->
              sourceRef
          | otherwise -> fallbackRef

    insertRequirementBoundRename renames rename@(sourceRef, targetRef) =
      case
          [ existingTarget
          | (existingSource, existingTarget) <- renames
          , typeBinderRefsSameIdentity existingSource sourceRef
          ]
        of
          [] -> pure (renames ++ [rename])
          existingTargets
            | all (typeBinderRefsSameIdentity targetRef) existingTargets ->
                pure renames
            | Just ambientRef <- exactAmbientOccurrenceRef sourceRef
            , any
                (typeBinderRefsSameIdentity ambientRef)
                (targetRef : existingTargets) ->
                pure
                  ( filter
                      ( not
                          . typeBinderRefsSameIdentity sourceRef
                          . fst
                      )
                      renames
                      ++ [(sourceRef, ambientRef)]
                  )
            | otherwise ->
                Left
                  ( ValidationFailed
                      [ "construction boundary routes one bound occurrence to multiple identities"
                      , "  owner: " ++ show owner
                      , "  occurrence: " ++ show sourceRef
                      , "  targets: " ++ show (targetRef : existingTargets)
                      , "  ambient declaration routes: "
                          ++ show ambientAuthorityOccurrenceRenames
                      ]
                  )

    -- A bound occurrence is interpreted in the Gamma that precedes the local
    -- declaration.  When a preparatory SchemeInfo route and the already
    -- checked ambient declaration name different members of one solved graph
    -- class, only the latter is in scope in that position.  The typed ambient
    -- authority is therefore the construction witness that resolves this
    -- otherwise genuine ambiguity; without it the disagreement remains an
    -- error rather than being settled by representative equality.
    exactAmbientOccurrenceRef ref = do
      node <- typeBinderRefNode ref
      agaExactRef
        <$> IntMap.lookup
          (getNodeId node)
          (grAmbientGammaAuthorities requirements)

    dependencyConstructionBinders constructionRoutes boundRenames ref =
      if
          sourceConstructionOwnsUnboundedDependency
            constructionRoutes
            ref
        then pure [(ref, Nothing)]
        else
          case dependencyBinderAuthorityNodes constructionRoutes ref of
            [] -> pure []
            authorityNodes -> do
              candidates <-
                traverse
                  (dependencyConstructionBinder boundRenames ref)
                  authorityNodes
              mergeConstructionBinderBoundsByProvenance
                ("application construction Gamma dependency " ++ show ref)
                ( map
                    (\binder -> (ConstructionLocalGammaBound, binder))
                    candidates
                )

    -- Bounds of generated dependency binders can themselves name earlier
    -- declarations.  Build that transitive declaration closure here, while
    -- graph/source authority is still available, instead of discovering a
    -- free variable after the construction Gamma has been selected.  The
    -- visited identity set makes the traversal finite; lexical dependency
    -- ordering and cycle rejection remain the responsibility of
    -- 'orderConstructionGammaBinders' at the emission boundary.
    completeDependencyConstructionBinders constructionRoutes boundRenames refAlreadyInGamma declaredRefs =
      go [] []
      where
        go _ accumulated [] = pure accumulated
        go visited accumulated (ref : pending)
          | refAlreadyInGamma ref
              || refMember ref declaredRefs
              || refMember ref visited =
              go visited accumulated pending
          | otherwise = do
              binders <-
                dependencyConstructionBinders
                  constructionRoutes
                  boundRenames
                  ref
              let dependencies =
                    foldr insertDistinctRef []
                      [ dependency
                      | (_, Just bound) <- binders
                      , dependency <- freeTypeVarRefsType (tyToElab bound)
                      , not (refAlreadyInGamma dependency)
                      , not (refMember dependency declaredRefs)
                      ]
                  pending' =
                    foldr insertDistinctRef pending dependencies
              go
                (insertDistinctRef ref visited)
                (accumulated ++ binders)
                pending'

    dependencyConstructionBinder boundRenames ref node = do
      mbBound <-
        case pvLookupVarBound presolutionView node of
          Nothing -> pure Nothing
          Just _ -> do
            bound <- reifyNodeTypePreferringBound scopeContext node
            requirementConstructionBound
              ref
              (applyBinderBoundRenames ref boundRenames bound)
      pure (ref, mbBound)

    dependencyBinderAuthorityNodes constructionRoutes ref =
      foldr
        insertDistinctNode
        []
        ( graphBinderAuthorityNodes ref
            ++ sourceSidecarLiveBinderNodes ref
            ++ sourceConstructionLiveBinderNodes constructionRoutes ref
        )

    graphBinderAuthorityNodes ref =
      [ pvCanonical presolutionView node
      | node <- maybeToList (typeBinderRefNode ref)
      , case pvLookupNode presolutionView node of
          Just TyVar {} -> True
          _ -> False
      ]

    sourceSidecarLiveBinderNodes ref =
      foldr insertDistinctNode []
        [ pvCanonical presolutionView (NodeId nodeKey)
        | (nodeKey, sourceRef) <-
            IntMap.toList (grSourceBinderRefs requirements)
        , IntSet.member nodeKey directSourceBinderKeys
        , typeBinderRefsSameIdentity ref sourceRef
        , case pvLookupNode presolutionView (NodeId nodeKey) of
            Just TyVar {} -> True
            -- Constraint generation deliberately records both the lexical
            -- variable node and the forall/mu node that owns it.  Only the
            -- variable entry is a construction dependency binder.
            Just _ -> False
            Nothing -> False
        ]

    -- A source annotation sidecar and the construction packet need not use
    -- the same graph occurrence key.  The sidecar fixes the semantic binder
    -- identity, while the current boundary's already-merged SchemeInfo route
    -- fixes the live occurrence at which its declaration is constructed.
    -- Their conjunction is sufficient binder authority even when the source
    -- declaration key itself has solved to a structural node.  This admits
    -- the declaration before Gamma selection; it does not synthesize a
    -- forall from a residual free result type.
    sourceConstructionLiveBinderNodes constructionRoutes ref
      | not
          ( any
              (typeBinderRefsSameIdentity ref)
              (IntMap.elems relevantRequirementSourceBinderRefs)
          ) = []
      | otherwise =
          foldr insertDistinctNode []
            [ pvCanonical presolutionView (NodeId nodeKey)
            | (nodeKey, routedRef) <-
                IntMap.toList constructionRoutes
            , typeBinderRefsSameIdentity ref routedRef
            , case pvLookupNode presolutionView (NodeId nodeKey) of
                Just TyVar {} -> True
                _ -> False
            ]

    -- Free variables of a source annotation are introduced as the unbounded
    -- existential prefix by 'sourceAnnotationSchemeAgainstEnv'.  Their
    -- generated identity and direct source-sidecar key therefore fix both
    -- declaration identity and empty bound before graph reification.  If the
    -- current construction scheme also routes a concrete occurrence to that
    -- identity, it may retain the declaration even after the source key has
    -- solved to a structural node.  The exact owner-emission scheme is an
    -- equally strong occurrence witness: closing its selected Gamma binder
    -- requires every free source declaration in that binder's bound, and the
    -- direct source sidecar fixes the declaration identity before the graph
    -- key becomes structural.  Explicit/bounded source declarations do not
    -- enter this lane: they retain graph or scheme-binder authority for their
    -- bound.
    sourceConstructionOwnsUnboundedDependency constructionRoutes ref =
      isJust
        ( typeBinderIdentityGeneratedUnique
            (typeBinderRefIdentity ref)
        )
        && any
          (typeBinderRefsSameIdentity ref)
          (IntMap.elems relevantRequirementSourceBinderRefs)
        && ( any
               (typeBinderRefsSameIdentity ref)
               (IntMap.elems constructionRoutes)
               || ( any
                      ( \(nodeKey, sourceRef) ->
                          IntSet.member nodeKey directSourceBinderKeys
                            && typeBinderRefsSameIdentity ref sourceRef
                      )
                      (IntMap.toList relevantRequirementSourceBinderRefs)
                      && any
                        (typeBinderRefsSameIdentity ref)
                        ownerEmissionFreeRefs
                  )
           )

    insertDistinctNode node nodes
      | node `elem` nodes = nodes
      | otherwise = node : nodes

    insertDistinctRef ref refs
      | any (typeBinderRefsSameIdentity ref) refs = refs
      | otherwise = ref : refs

    ownerEmissionScheme =
      applySchemeInfoRefRenames constructionBinderRenames
        <$> ownerEmissionScheme0
    ownerEmissionConstructionBinders =
      maybe
        []
        (schemeBinderRefs . siScheme)
        ownerEmissionScheme
    ownerEmissionFreeRefs =
      maybe
        []
        (freeTypeVarRefsType . schemeToType . siScheme)
        ownerEmissionScheme
    ownerEmissionOwns ref =
      any
        (typeBinderRefsSameIdentity ref . fst)
        ownerEmissionConstructionBinders
    alignedSourceBinderRefs =
      IntMap.map
        (applyRefRenames constructionBinderRenames)
        (grSourceBinderRefs requirements0)
    alignedAmbientGammaAuthorities =
      IntMap.map
        ( \authority ->
            authority
              { agaExactRef =
                  applyRefRenames
                    constructionBinderRenames
                    (agaExactRef authority)
              , agaBound =
                  applyTypeVarRefRenames
                    constructionBinderRenames
                    (agaBound authority)
              }
        )
        (grAmbientGammaAuthorities requirements0)
    requirements =
      requirements0
        { grRequiredGammaBinders =
            map alignRequirement (grRequiredGammaBinders requirements0)
        , grSourceBinderRefs = alignedSourceBinderRefs
        , grAmbientGammaAuthorities = alignedAmbientGammaAuthorities
        }
    alignRequirement requirement =
      requirement
        { rgbOperatedType =
            applyTypeVarRefRenames
              constructionBinderRenames
              (rgbOperatedType requirement)
        }
    schemeInfo =
      applySchemeInfoRefRenames constructionBinderRenames schemeInfo0
    requiredBinders = grRequiredGammaBinders requirements
    -- The operated requirement is not the only source-identity consumer.  A
    -- pending packet can carry a free lexical result ref that its local Gamma
    -- consumer will bind under the graph construction identity.  Include both
    -- owner views when building the one source-to-construction quotient.
    requiredSourceRefs =
      concatMap
        (freeTypeVarRefsType . rgbOperatedType)
        requiredBinders
        ++ concatMap
          (freeTypeVarRefsType . schemeToType . siScheme)
          pendingOwnerSchemeInfos
        ++ maybe
          []
          (freeTypeVarRefsType . schemeToType . siScheme)
          ownerEmissionScheme
    pendingOwnerSchemeInfos =
      [ ownerSchemeInfo
      | requirement <- requiredBinders
      , edgeId <- NonEmpty.toList (rgbEdgeIds requirement)
      , Just closure <-
          [IntMap.lookup (getEdgeId edgeId) (envLocalGammaClosures env)]
      , lgcOwner closure == owner
      , Just ownerSchemeInfo <- [lgcOwnerPendingScheme closure]
      ]
    relevantRequirementSourceBinderRefs =
      IntMap.filter
        (\sourceRef -> any (typeBinderRefsSameIdentity sourceRef) requiredSourceRefs)
        (grSourceBinderRefs requirements)
    ownerScope = localGammaOwnerScope owner
    -- A generalized binder may be placed in the leading body spine when it
    -- constructs the result of this exact source boundary.  It is still part
    -- of the boundary's Lambda(Gamma) prefix: child computations need it in
    -- scope and the completed term must emit the matching ETyAbsRef.  Looking
    -- only at the outer 'ElabScheme' list leaves such a result forall in the
    -- expected type while asking the children to construct that closed
    -- scheme directly.
    schemeBinders =
      fst (splitForallsRefs (schemeToType (siScheme schemeInfo)))
    subst = schemeInfoBinderRefSubst schemeInfo
    liveBindParents = cBindParents (pvConstraint (scPresolutionView scopeContext))
    boundaryConstructionIdentityRoutes =
      foldM
        insertBoundaryConstructionRoute
        (envConstructionIdentityRoutes env)
        (schemeIdentityRoutes ++ ownerEmissionIdentityRoutes)
    schemeIdentityRoutes =
      binderIdentityRoutes schemeBinders
        ++ IntMap.toList subst
    ownerEmissionIdentityRoutes =
      maybe
        []
        ( \ownerSchemeInfo ->
            binderIdentityRoutes
              (schemeBinderRefs (siScheme ownerSchemeInfo))
              ++ IntMap.toList
                (schemeInfoBinderRefSubst ownerSchemeInfo)
        )
        ownerEmissionScheme

    -- An explicit graph-backed forall is itself an identity route even when
    -- generalization did not need a separate substitution entry for it.  Make
    -- that construction fact available to source-binder projection before
    -- comparing S(operated); otherwise an ordinary source annotation can stay
    -- in the generated source domain while its owner binder is already in the
    -- graph construction domain.
    binderIdentityRoutes binders =
      [ (getNodeId node, ref)
      | (ref, _) <- binders
      , Just node <- [typeBinderRefNode ref]
      ]

    insertBoundaryConstructionRoute routes (nodeKey, routedRef) =
      case IntMap.lookup nodeKey routes of
        Nothing -> pure (IntMap.insert nodeKey routedRef routes)
        Just existing ->
          case
              selectBoundaryConstructionRoute
                ( IntMap.lookup
                    nodeKey
                    (envConstructionIdentityRoutes env)
                )
                (boundaryLocalRefsFor nodeKey)
                existing
                routedRef
            of
            Just selected
              | typeBinderRefsSameIdentity selected existing ->
                  pure routes
              | otherwise ->
                  pure (IntMap.insert nodeKey selected routes)
            Nothing ->
              Left
                ( ValidationFailed
                    [ "construction boundary has conflicting identity routes"
                    , "  graph node: " ++ show (NodeId nodeKey)
                    , "  established authority: "
                        ++ show
                          ( IntMap.lookup
                              nodeKey
                              (envConstructionIdentityRoutes env)
                          )
                    , "  enclosing route: " ++ show existing
                    , "  local route: " ++ show routedRef
                    , "  owner: " ++ show owner
                    , "  scheme binders: " ++ show schemeBinders
                    , "  scheme: " ++ show (siScheme schemeInfo)
                    , "  scheme substitution: " ++ show subst
                    , "  owner emission scheme: " ++ show (siScheme <$> ownerEmissionScheme)
                    , "  enclosing construction aliases: " ++ show (envConstructionGammaAliases env)
                    ]
                )

    -- The actual owner emission is the construction authority for every
    -- graph key it publishes.  The independently generalized scheme is still
    -- boundary-local for keys that the owner does not publish, but it cannot
    -- compete with the term that will actually emit an ETyAbs at the same
    -- key.  Selecting this per key prevents a source-sidecar identity in the
    -- preparatory scheme from defeating the required-Gamma exterior chosen by
    -- the owner.
    boundaryLocalRefsFor nodeKey =
      case
          [ ref
          | (key, ref) <- ownerEmissionIdentityRoutes
          , key == nodeKey
          ]
        of
          [] -> leadingConstructionRefs schemeInfo
          ownerRefs -> ownerRefs

    -- Root closure can place an owner-local forall in the leading body spine
    -- instead of the outer 'ElabScheme' binder list.  Both representations
    -- are declarations owned by this exact boundary and therefore shadow an
    -- enclosing route for the same graph node.  Non-leading nested foralls
    -- remain lexical to their own subterm and are deliberately excluded.
    leadingConstructionRefs =
      map fst
        . fst
        . splitForallsRefs
        . schemeToType
        . siScheme
    localClosureBindersFor boundRenames ambientSatisfied requirement = do
      mbClosure <-
        selectLocalGammaClosureOwnerLane
          owner
          (envLocalGammaClosures env)
          requirement
      case mbClosure of
        Nothing -> pure (False, [])
        Just closure
          | not
              ( edgeKeySet (rgbEdgeIds requirement)
                  `IntSet.isSubsetOf` edgeKeySet (lgcEdgeIds closure)
              ) ->
              localClosureFailure
                requirement
                "local Gamma closure does not cover the complete required edge set"
                [closure]
          | lgcExteriorNode closure /= rgbExteriorNode requirement ->
              localClosureFailure
                requirement
                "local Gamma closure exterior disagrees with the requirement"
                [closure]
          | lgcConsumerIdentity closure
              /= typeBinderIdentityFromNode (rgbExteriorNode requirement) ->
              localClosureFailure
                requirement
                "local Gamma closure consumer disagrees with the exterior identity"
                [closure]
          | lgcOwner closure /= owner ->
              localClosureFailure
                requirement
                "local Gamma closure belongs to a different source constructor"
                [closure]
          | not
              ( directEdgeLocalClosureOwnsRequirement closure requirement
                  || rootRaiseMergeExteriorOwnedByScope
                    (scGaParents scopeContext)
                    (localGammaOwnerScope owner)
                    (lgcExteriorNode closure)
              ) ->
              localClosureFailure
                requirement
                "local Gamma closure has neither direct edge-local nor flexible-scope ownership"
                [closure]
          | otherwise ->
              if
                  requirementNeedsLocalConstruction
                    True
                    (rgbPlacement requirement)
                    ambientSatisfied
                then
                  fmap
                    ((,) True)
                    ( validateOwnerConstructionBinders
                        boundRenames
                        requirement
                        closure
                    )
                else
                  -- The closure still proves that this boundary owns the
                  -- requirement, but the exact ambient declaration already
                  -- satisfies S(operated).  There is consequently no local
                  -- binder for the owner to emit or validate.
                  pure (True, [])

    directEdgeLocalClosureOwnsRequirement closure requirement =
      preparedApplicationClosureOwnsForwardedRequirement
        closure
        requirement
        || case coverage of
          RequiredGammaOnly ->
            directApplicationClosureOwnsEdges
              closure
              (rgbEdgeIds requirement)
          OwnerLocalAndRequiredGamma -> False
          CompleteSchemeAndRequiredGamma -> False

    -- A prepared application closure can own an ordinary Gamma_g
    -- requirement contributed by enclosing result-transparent constructors.
    -- The requirement contains only the forwarded subset; the closure's
    -- non-empty direct edge is the source-occurrence certificate that makes
    -- the complete direct-plus-forwarded frame authoritative.
    preparedApplicationClosureOwnsForwardedRequirement closure requirement =
      rgbPlacement requirement
        == RequiredGammaAtConstructionScope
          (localGammaOwnerScope (lgcOwner closure))
        && not (IntSet.null requirementEdgeKeys)
        && requirementEdgeKeys
          `IntSet.isSubsetOf` forwardedEdgeKeys
        && directApplicationClosureOwnsEdges
          closure
          (lgcEdgeIds closure)
      where
        requirementEdgeKeys =
          edgeKeySet (rgbEdgeIds requirement)
        forwardedEdgeKeys =
          IntSet.fromList
            (map getEdgeId (lgcForwardedResultEdgeIds closure))

    validateOwnerConstructionBinders boundRenames requirement closure =
      case lgcOwnerPendingScheme closure of
        -- An ordinary syntactic owner has no prebuilt packet binder.  It must
        -- still select and emit the requirement through this local planner.
        Nothing -> pure []
        Just recordedOwnerSchemeInfo -> do
          originalRecordedConsumerRef <-
            routedOwnerConsumer
              "unrenamed recorded graph packet"
              closure
              recordedOwnerSchemeInfo
          _ <-
            validatePendingOwnerConsumer
              False
              closure
              recordedOwnerSchemeInfo
              originalRecordedConsumerRef
          actualOwnerSchemeInfo <-
            case ownerEmissionScheme of
              Just actual
                | ownerSchemeCarriesConsumer closure actual ->
                    pure actual
              _
                | ownerSchemeCarriesConsumer closure schemeInfo ->
                    -- The prepared owner view can retain an exterior route
                    -- solely for packet replay after its pending declaration
                    -- has moved into the ordinary Gen(Gamma,tau) result.  The
                    -- current generalized scheme is then the term boundary
                    -- that will actually carry that declaration.  Select it
                    -- by the exact exterior route and either its explicit
                    -- leading binder or its exact ambient use, while both
                    -- construction views are present.
                    pure schemeInfo
              _ ->
                Left
                  ( ValidationFailed
                      [ "local Gamma packet proof has no actual owner emission"
                      , "  edges: " ++ show (lgcEdgeIds closure)
                      , "  owner: " ++ show (lgcOwner closure)
                      , "  recorded scheme: " ++ show recordedOwnerSchemeInfo
                      , "  prepared owner scheme: "
                          ++ show (siScheme <$> ownerEmissionScheme)
                      , "  current construction scheme: "
                          ++ show (siScheme schemeInfo)
                      ]
                  )
          let alignedRecordedGraphSchemeInfo =
                applySchemeInfoRefRenames
                  boundRenames
                  ( applySchemeInfoRefRenames
                      constructionBinderRenames
                      recordedOwnerSchemeInfo
                  )
              alignedActualSchemeInfo =
                applySchemeInfoRefRenames
                  boundRenames
                  actualOwnerSchemeInfo
          recordedGraphConsumerRef <-
            routedOwnerConsumer
              "recorded graph packet"
              closure
              alignedRecordedGraphSchemeInfo
          actualConsumerRef <-
            routedOwnerConsumer
              "actual owner emission"
              closure
              alignedActualSchemeInfo
          let recordedSchemeAlignedToOwner =
                if
                    typeBinderRefsSameIdentity
                      recordedGraphConsumerRef
                      actualConsumerRef
                  then alignedRecordedGraphSchemeInfo
                  else
                    -- Both schemes route the closure's exact exterior key.
                    -- The pending packet records the earlier construction
                    -- identity; the actual owner emission fixes its final
                    -- binder identity.  Join those typed routes here before
                    -- source projection instead of comparing their graph
                    -- representatives or display names.
                    applySchemeInfoRefRenames
                      [(recordedGraphConsumerRef, actualConsumerRef)]
                      alignedRecordedGraphSchemeInfo
          alignedRecordedSchemeInfo <-
            either
              ( \cause ->
                  Left
                    ( ValidationFailed
                        [ "local Gamma pending scheme has inconsistent source-binder provenance"
                        , "  edges: " ++ show (lgcEdgeIds closure)
                        , "  owner: " ++ show (lgcOwner closure)
                        , "  cause: " ++ cause
                        ]
                    )
              )
              Right
              ( resolveConstructionSourceBindersInSchemeInfoExcept
                  ( Set.singleton
                      (typeBinderRefIdentity actualConsumerRef)
                  )
                  (scopeTypeBinderIdentityRepresentative scopeContext)
                  (grSourceBinderRefs requirements)
                  recordedSchemeAlignedToOwner
              )
          recordedConsumerRef <-
            routedOwnerConsumer
              "recorded packet"
              closure
              alignedRecordedSchemeInfo
          if not
              ( typeBinderRefsSameIdentity
                  recordedConsumerRef
                  actualConsumerRef
              )
            then
              Left
                ( ValidationFailed
                    [ "local Gamma packet proof and actual owner route disagree"
                    , "  edges: " ++ show (lgcEdgeIds closure)
                    , "  owner: " ++ show (lgcOwner closure)
                    , "  recorded consumer: " ++ show recordedConsumerRef
                    , "  actual consumer: " ++ show actualConsumerRef
                    , "  recorded representative: " ++ show (consumerRepresentative recordedConsumerRef)
                    , "  actual representative: " ++ show (consumerRepresentative actualConsumerRef)
                    , "  recorded scheme: " ++ show (siScheme alignedRecordedSchemeInfo)
                    , "  recorded substitution: " ++ show (siSubstRefs alignedRecordedSchemeInfo)
                    , "  actual scheme: " ++ show (siScheme alignedActualSchemeInfo)
                    , "  actual substitution: " ++ show (siSubstRefs alignedActualSchemeInfo)
                    , "  source binder routes: " ++ show (grSourceBinderRefs requirements)
                    , "  source-to-construction renames: " ++ show boundRenames
                    ]
                )
            else do
              pendingOwnerBinders <-
                validatePendingOwnerConsumer
                  ( not
                      ( typeBinderRefsSameIdentity
                          originalRecordedConsumerRef
                          actualConsumerRef
                      )
                  )
                  closure
                  alignedRecordedSchemeInfo
                  recordedConsumerRef
              actualOwnerBinders <-
                validateOwnerConsumerBinder
                  "actual owner emission"
                  boundRenames
                  requirement
                  closure
                  alignedActualSchemeInfo
                  actualConsumerRef
              let actualOwnerDeclarationRefs =
                    map fst
                      ( fst
                          ( splitForallsRefs
                              (schemeToType (siScheme alignedActualSchemeInfo))
                          )
                      )
                  -- The recorded pending scheme proves the closure's route,
                  -- but the actual term construction is the unique bound
                  -- authority for every declaration it now emits.  Retain
                  -- only pending dependencies that the emission does not
                  -- declare; otherwise a stale pre-body bound competes with
                  -- the completed S'(operated) bound for one identity.
                  pendingDependencies =
                    [ binder
                    | binder@(ref, _) <- pendingOwnerBinders
                    , not
                        ( any
                            (typeBinderRefsSameIdentity ref)
                            actualOwnerDeclarationRefs
                        )
                    ]
              pure (pendingDependencies ++ actualOwnerBinders)

    ownerSchemeCarriesConsumer closure ownerSchemeInfo =
      case
          IntMap.lookup
            (getNodeId (lgcExteriorNode closure))
            (siSubstRefs ownerSchemeInfo)
        of
          Nothing -> False
          Just routedRef ->
            any
              (typeBinderRefsSameIdentity routedRef . fst)
              declaredBinders
              || any
                (typeBinderRefsSameIdentity routedRef)
                (freeTypeVarRefsType ownerType)
      where
        ownerType = schemeToType (siScheme ownerSchemeInfo)
        declaredBinders = fst (splitForallsRefs ownerType)

    consumerRepresentative ref =
      scopeTypeBinderIdentityRepresentative scopeContext
        <$> typeBinderRefNode ref

    eqFreeEliminatesOwnerConsumer boundRenames routedConsumerRef =
      case packetConsumerResolution of
        Just (PacketConsumerEliminatedByEqFree eliminatedRef) ->
          any
            (typeBinderRefsSameIdentity routedConsumerRef)
            [ eliminatedRef
            , applyRefRenames
                boundRenames
                (applyRefRenames constructionBinderRenames eliminatedRef)
            ]
        _ -> False

    -- The prepared closure records only the constructor's pending consumer
    -- route.  Its empty bound is deliberate: the recursively checked child is
    -- the sole authority that materializes S'(operated) in the actual owner
    -- emission.  Comparing an earlier completed packet presentation with the
    -- current exact requirement would reintroduce two competing bound owners.
    validatePendingOwnerConsumer allowMaterializedQuotient closure ownerSchemeInfo routedConsumerRef =
      case matchingBinders of
        [(_, Nothing)] ->
          pure nonConsumerBinders
        [(_, Just _)]
          | allowMaterializedQuotient ->
              -- The original packet above proved an unmaterialized consumer.
              -- A typed construction rename can quotient that slot with an
              -- already bounded declaration of the same semantic identity.
              -- The quotient owns one declaration, so retain the existing
              -- bound and do not emit a second consumer here.
              pure nonConsumerBinders
        [(_, Just staleBound)] ->
          Left
            ( ValidationFailed
                [ "local Gamma pending consumer is already materialized"
                , "  edges: " ++ show (lgcEdgeIds closure)
                , "  owner: " ++ show (lgcOwner closure)
                , "  consumer: " ++ show routedConsumerRef
                , "  stale bound: " ++ show (tyToElab staleBound)
                , "  pending scheme: " ++ show (siScheme ownerSchemeInfo)
                ]
            )
        [] ->
          Left
            ( ValidationFailed
                [ "local Gamma pending scheme does not emit its proved consumer slot"
                , "  edges: " ++ show (lgcEdgeIds closure)
                , "  owner: " ++ show (lgcOwner closure)
                , "  consumer: " ++ show routedConsumerRef
                , "  pending scheme: " ++ show (siScheme ownerSchemeInfo)
                ]
            )
        matches ->
          Left
            ( ValidationFailed
                [ "local Gamma pending scheme emits its consumer slot more than once"
                , "  edges: " ++ show (lgcEdgeIds closure)
                , "  owner: " ++ show (lgcOwner closure)
                , "  matching binders: " ++ show matches
                ]
            )
      where
        ownerBinders =
          fst (splitForallsRefs (schemeToType (siScheme ownerSchemeInfo)))
        (matchingBinders, nonConsumerBinders) =
          partition
            (typeBinderRefsSameIdentity routedConsumerRef . fst)
            ownerBinders

    routedOwnerConsumer role closure ownerSchemeInfo =
      case
          IntMap.lookup
            (getNodeId (lgcExteriorNode closure))
            (siSubstRefs ownerSchemeInfo)
      of
        Just ref -> pure ref
        Nothing ->
          Left
            ( ValidationFailed
                [ "local Gamma packet has no substitution route for its proved exterior"
                , "  role: " ++ role
                , "  edges: " ++ show (lgcEdgeIds closure)
                , "  owner: " ++ show (lgcOwner closure)
                , "  exterior: " ++ show (lgcExteriorNode closure)
                , "  owner substitution: " ++ show (siSubstRefs ownerSchemeInfo)
                ]
            )

    validateOwnerConsumerBinder role boundRenames requirement closure ownerSchemeInfo routedConsumerRef =
      case matchingBinders of
        [binder@(_, mbBound)] ->
          let expectedBound =
                expectedBoundForRef
                  boundRenames
                  requirement
                  routedConsumerRef
              actualBound = maybe TBottom tyToElab mbBound
           in if
                requiredBoundSatisfiedBy
                  boundRenames
                  routedConsumerRef
                  expectedBound
                  actualBound
                then pure [binder]
                else
                  Left
                    ( ValidationFailed
                        [ "local Gamma owner binder disagrees with S(operated)"
                        , "  role: " ++ role
                        , "  edges: " ++ show (lgcEdgeIds closure)
                        , "  owner: " ++ show (lgcOwner closure)
                        , "  consumer: " ++ show routedConsumerRef
                        , "  expected bound: " ++ show expectedBound
                        , "  actual bound: " ++ show actualBound
                        , "  source binder routes: " ++ show relevantRequirementSourceBinderRefs
                        , "  source-to-construction renames: " ++ show boundRenames
                        , "  owner scheme: " ++ show (siScheme ownerSchemeInfo)
                        ]
                    )
        []
          -- The recursively checked child can prove through Eq-Free that this
          -- exact packet quantifier is absent from the owner emission.  That
          -- proof is stronger than an ambient-placement fallback: no ETyAbs
          -- for this consumer may be emitted at this boundary.
          | eqFreeEliminatesOwnerConsumer boundRenames routedConsumerRef ->
              pure []
          -- Root closure can own this forall while the local packet scheme
          -- refers to it freely.  Accept that placement only when the exact
          -- routed identity is already in the construction Γ and is present
          -- in the owner payload.  The enclosing required-bound check below
          -- still proves that the ambient binding satisfies S(operated).
          | envContainsFreeTypeBinderRef
              (scopeTypeBinderIdentityRepresentative scopeContext)
              (envFreeTypeBinderRefs env)
              routedConsumerRef
          , any
              (typeBinderRefsSameIdentity routedConsumerRef)
              (freeTypeVarRefsType (schemeToType (siScheme ownerSchemeInfo))) ->
              pure []
          | otherwise ->
              Left
                ( ValidationFailed
                    [ "local Gamma packet does not emit its proved consumer binder"
                    , "  role: " ++ role
                    , "  edges: " ++ show (lgcEdgeIds closure)
                    , "  owner: " ++ show (lgcOwner closure)
                    , "  consumer identity: " ++ show (lgcConsumerIdentity closure)
                    , "  routed consumer: " ++ show routedConsumerRef
                    , "  owner binders: " ++ show ownerBinders
                    , "  owner scheme: " ++ show (siScheme ownerSchemeInfo)
                    ]
                )
        matches ->
          Left
            ( ValidationFailed
                [ "local Gamma packet emits its consumer binder more than once"
                , "  role: " ++ role
                , "  edges: " ++ show (lgcEdgeIds closure)
                , "  owner: " ++ show (lgcOwner closure)
                , "  matching binders: " ++ show matches
                ]
            )
      where
        -- Root closure may move an owner-local forall from the scheme binder
        -- list into the leading body spine.  Both forms are explicit emitted
        -- binders, so validate the complete leading construction type rather
        -- than only the outer 'ElabScheme' field.
        ownerBinders =
          fst (splitForallsRefs (schemeToType (siScheme ownerSchemeInfo)))
        matchingBinders =
          [ binder
          | binder@(ref, _) <- ownerBinders
          , typeBinderRefsSameIdentity ref routedConsumerRef
          ]

    localClosureFailure requirement reason closures =
      Left
        ( ValidationFailed
            [ reason,
              "  exact owner: " ++ show owner,
              "  requirement: " ++ show requirement,
              "  closures: " ++ show closures
            ]
        )

    edgeKeySet =
      IntSet.fromList . map getEdgeId . NonEmpty.toList

    -- A construction quotient may route a source binder to the exterior that
    -- this very Gamma entry declares.  That route is valid in the entry's
    -- body, after the declaration has entered scope, but never in its bound:
    -- xMLF requires @alpha@ not to occur free in @sigma@ for
    -- @Gamma, alpha > sigma@.  Keep the source dependency in the bound so the
    -- dependency closure emits (or inherits) its declaration before alpha.
    -- This is the identity-bearing analogue of capture avoidance; turning the
    -- dependency into alpha would manufacture the invalid F-bound
    -- @alpha > sigma[alpha/beta]@.
    applyBinderBoundRenames targetRef =
      applyTypeVarRefRenames
        . filter
          ( \(_, outwardRef) ->
              not (typeBinderRefsSameIdentity targetRef outwardRef)
          )

    expectedBoundForRef boundRenames requirement targetRef =
      case applyBinderBoundRenames targetRef boundRenames (rgbOperatedType requirement) of
        TVarRef _ -> TVarRef targetRef
        expectedBound -> expectedBound

    -- A 'RequiredGammaBinder' is the typed construction fact for its local
    -- abstraction.  Generalization can quotient its exterior and result to
    -- the target itself, in which case the resulting scheme substitution has
    -- the authoritative binder identity but no syntactic forall yet.  Build
    -- that binder here from the requirement, instead of rejecting the lawful
    -- quotient and asking a later term/type comparison to recover it.
    requirementConstructionBinder boundRenames refAlreadyInGamma requirement ref
      | refAlreadyInGamma ref = pure []
      | otherwise = do
          mbBound <- requirementConstructionBound ref expectedBound
          pure [(ref, mbBound)]
      where
        expectedBound = expectedBoundForRef boundRenames requirement ref

    requirementConstructionBound ref expectedBound =
      case expectedBound of
        TBottom -> pure Nothing
        TVarRef operatedRef
          | typeBinderRefsSameIdentity ref operatedRef -> pure Nothing
        _ ->
          either
            ( \cause ->
                Left
                  ( ValidationFailed
                      [ "construction Gamma requirement has no structural bound"
                      , "  binder: " ++ show ref
                      , "  expected bound: " ++ show expectedBound
                      , "  cause: " ++ cause
                      ]
                  )
            )
            (pure . Just)
            (elabToBound expectedBound)

    -- Generalization may quotient a required exterior directly to the
    -- lexical variable that is S(operated).  In that case the requirement is
    -- already closed by identity: the ambient variable is the RaiseMerge
    -- result, not a new Gamma binder whose lexical bound must become @a@.
    -- All other routes still require the prepared or ambient bound to agree.
    requiredBoundSatisfiedBy boundRenames ref expectedBound actualBound =
      case expectedBound of
        TVarRef operatedRef
          | typeBinderRefsSameIdentity ref operatedRef -> True
        _ ->
          alphaEqType expectedBound actualBound
            || churchAwareEqType expectedBound actualBound
            || completeUnboundedForallSpecializesTo
              actualBound
              expectedBound
            || packetEliminationDischargesAtAmbientBound
              boundRenames
              ref
              expectedBound
              actualBound

    -- Consumer resolution is produced only after the recursively checked
    -- child has proved that this exact packet declaration is omitted at an
    -- exact ambient bound.  Preserve that directional construction here:
    -- the requirement endpoint may be more general than the installed bound
    -- (for example a child-owned vacuous forall), but it must have a checked
    -- leading-binder computation to the certified ambient endpoint.
    packetEliminationDischargesAtAmbientBound boundRenames ref expectedBound actualBound =
      case packetConsumerResolution of
        Just
          ( PacketConsumerEliminatedAtAmbientBound
              eliminatedRef
              certifiedAmbientBound
            ) ->
              let alignedEliminatedRef =
                    applyRefRenames boundRenames eliminatedRef
                  alignedCertifiedAmbientBound =
                    applyBinderBoundRenames
                      ref
                      boundRenames
                      certifiedAmbientBound
               in ( typeBinderRefsSameIdentity ref eliminatedRef
                      || typeBinderRefsSameIdentity ref alignedEliminatedRef
                  )
                && operationalEndpointTypesAgree
                  actualBound
                  alignedCertifiedAmbientBound
                && ( operationalEndpointTypesAgree
                      expectedBound
                      alignedCertifiedAmbientBound
                      || isJust
                        ( planExactBinderSpine
                            operationalEndpointTypesAgree
                            expectedBound
                            alignedCertifiedAmbientBound
                        )
                   )
        _ -> False

    findBinder ref = find (typeBinderRefsSameIdentity ref . fst)

    selectedBoundFor ref binders =
      maybe TBottom tyToElab . snd <$> findBinder ref binders

    insertAmbientAlias aliases (nodeKey, exactRef) =
      case IntMap.lookup nodeKey aliases of
        Nothing -> pure (IntMap.insert nodeKey exactRef aliases)
        Just existing
          | typeBinderRefsSameIdentity existing exactRef -> pure aliases
          | otherwise ->
              Left
                ( ValidationFailed
                    [ "construction Gamma requirements select different exact ambient declarations"
                    , "  graph node: " ++ show (NodeId nodeKey)
                    , "  first ambient declaration: " ++ show existing
                    , "  second ambient declaration: " ++ show exactRef
                    ]
                )

    ambientBoundFor refAlreadyInGamma requirement ref
      | not (refAlreadyInGamma ref) = pure Nothing
      | otherwise = do
          preparedAuthority <- directPreparedAmbientAuthority ref requirement
          case preparedAuthority of
            Just authority -> pure (Just authority)
            Nothing -> selectFirstAmbientGroup candidateGroups
      where
        bindings = Map.toList (envTypeBindings env)
        directOperatedRefs =
          case rgbOperatedType requirement of
            TVarRef operatedRef -> [operatedRef]
            _ -> []
        requiredRefsForLookup = [ref]
        routedExteriorRefs =
          routedRefsForNodes [rgbExteriorNode requirement]
        routedResultRefs =
          routedRefsForNodes (NonEmpty.toList (rgbResultRoots requirement))
        routedOperatedRootRefs =
          routedRefsForNodes [rgbOperatedRoot requirement]
        routedRefsForNodes nodes =
          [ routedRef
          | node <- nodes
          , Just routedRef <-
              [ IntMap.lookup
                  (getNodeId node)
                  (envConstructionGammaAliases env)
              ]
          ]

        exactBindingCandidates lookupRefs =
          [ (candidateRef, bound)
          | (candidateRef, bound) <- bindings,
            any
              (`typeBinderRefsSameIdentity` candidateRef)
              lookupRefs
          ]
        representativeBindingCandidates lookupRefs =
          [ (candidateRef, bound)
          | (candidateRef, bound) <- bindings,
            any
              (`sameGraphRepresentative` candidateRef)
              lookupRefs
          ]
        exactFreeCandidates lookupRefs =
          [ (candidateRef, TBottom)
          | candidateRef <- ambientFreeRefs,
            any
              (`typeBinderRefsSameIdentity` candidateRef)
              lookupRefs
          ]
        representativeFreeCandidates lookupRefs =
          [ (candidateRef, TBottom)
          | candidateRef <- ambientFreeRefs,
            any
              (`sameGraphRepresentative` candidateRef)
              lookupRefs
          ]
        candidateGroups =
          [ ( "exact required type binding",
              exactBindingCandidates requiredRefsForLookup
            ),
            ( "exact required free binder",
              exactFreeCandidates requiredRefsForLookup
            ),
            -- The exterior is the declaration consumed by this Gamma
            -- requirement. Operated and result roots are producer routes;
            -- they may legitimately retain different exact ambient
            -- identities until this construction publishes their common
            -- outward alias. Select each role independently instead of
            -- treating all three endpoint routes as declarations of one
            -- pre-existing identity.
            ( "exact exterior construction route type binding",
              exactBindingCandidates routedExteriorRefs
            ),
            ( "exact exterior construction route free binder",
              exactFreeCandidates routedExteriorRefs
            ),
            ( "exact result construction route type binding",
              exactBindingCandidates routedResultRefs
            ),
            ( "exact result construction route free binder",
              exactFreeCandidates routedResultRefs
            ),
            ( "exact operated-root construction route type binding",
              exactBindingCandidates routedOperatedRootRefs
            ),
            ( "exact operated-root construction route free binder",
              exactFreeCandidates routedOperatedRootRefs
            ),
            ( "exact operated type binding",
              exactBindingCandidates directOperatedRefs
            ),
            ( "exact operated free binder",
              exactFreeCandidates directOperatedRefs
            ),
            ( "representative required type binding",
              representativeBindingCandidates requiredRefsForLookup
            ),
            ( "representative required free binder",
              representativeFreeCandidates requiredRefsForLookup
            ),
            ( "representative exterior construction route type binding",
              representativeBindingCandidates routedExteriorRefs
            ),
            ( "representative exterior construction route free binder",
              representativeFreeCandidates routedExteriorRefs
            ),
            ( "representative result construction route type binding",
              representativeBindingCandidates routedResultRefs
            ),
            ( "representative result construction route free binder",
              representativeFreeCandidates routedResultRefs
            ),
            ( "representative operated-root construction route type binding",
              representativeBindingCandidates routedOperatedRootRefs
            ),
            ( "representative operated-root construction route free binder",
              representativeFreeCandidates routedOperatedRootRefs
            ),
            ( "representative operated type binding",
              representativeBindingCandidates directOperatedRefs
            ),
            ( "representative operated free binder",
              representativeFreeCandidates directOperatedRefs
            )
          ]

        -- A term binding such as @y : alpha@ puts @alpha@ in the ambient
        -- paper Gamma even when this owner has no explicit local type-binding
        -- entry for it.  In that case the only bound authority available at
        -- this boundary is the unbounded one.  Treating the missing map entry
        -- as absence from Gamma makes a local RaiseMerge requirement shadow
        -- @alpha@ and later emits a second @Lambda alpha@ around a term that
        -- still refers to @y@.  That construction is ill-scoped by design.
        EnvFreeTypeBinderRefs ambientFreeRefs = envFreeTypeBinderRefs env

        selectFirstAmbientGroup [] = pure Nothing
        selectFirstAmbientGroup ((_, []) : rest) =
          selectFirstAmbientGroup rest
        selectFirstAmbientGroup ((role, candidates) : _) =
          uniqueAmbientAuthority role candidates

        uniqueAmbientAuthority _ [] = pure Nothing
        uniqueAmbientAuthority role ((exactRef, exactBound) : rest)
          | any
              (not . typeBinderRefsSameIdentity exactRef . fst)
              rest =
              Left
                ( ValidationFailed
                    [ "construction Gamma has multiple exact ambient declarations for one representative"
                    , "  lookup role: " ++ role
                    , "  required ref: " ++ show ref
                    , "  requirement: " ++ show requirement
                    , "  routed requirement refs: "
                        ++ show routedRequirementRefPairs
                    , "  construction aliases: "
                        ++ show (envConstructionGammaAliases env)
                    , "  first exact declaration: " ++ show exactRef
                    , "  other candidates: " ++ show rest
                    ]
                )
          | all
              ( \(_, candidateBound) ->
                  alphaEqType exactBound candidateBound
                    || churchAwareEqType exactBound candidateBound
              )
              rest =
              pure
                ( Just
                    AmbientGammaAuthority
                      { agaExactRef = exactRef,
                        agaBound = exactBound
                      }
                )
          | otherwise =
              Left
                ( ValidationFailed
                    [ "construction Gamma has conflicting ambient bounds for one identity"
                    , "  required ref: " ++ show ref
                    , "  exact ambient declaration: " ++ show exactRef
                    , "  exact ambient bound: " ++ show exactBound
                    , "  conflicting candidates: " ++ show rest
                    ]
                )

        sameGraphRepresentative left right =
          case (typeBinderRefNode left, typeBinderRefNode right) of
            (Just leftNode, Just rightNode) ->
              scopeTypeBinderIdentityRepresentative scopeContext leftNode
                == scopeTypeBinderIdentityRepresentative scopeContext rightNode
            _ -> False

        routedRequirementRefPairs =
          [ (node, routedRef)
          | node <-
              rgbOperatedRoot requirement
                : rgbExteriorNode requirement
                : NonEmpty.toList (rgbResultRoots requirement)
          , Just routedRef <-
              [ IntMap.lookup
                  (getNodeId node)
                  (envConstructionGammaAliases env)
              ]
          ]

    directPreparedAmbientAuthority requiredRef requirement =
      case
          selectDirectAmbientGammaAuthority
            requiredRef
            directAuthorities
        of
        Right authority -> pure authority
        Left (ValidationFailed messages) ->
          Left
            ( ValidationFailed
                ( "one construction requirement has conflicting direct ambient Gamma authorities"
                    : ("  requirement: " ++ show requirement)
                    : messages
                )
            )
        Left err -> Left err
      where
        directAuthorities =
          foldr insertDistinctAuthority []
            [ (authorityProvenance node authority, authority)
            | node <-
                rgbOperatedRoot requirement
                  : rgbExteriorNode requirement
                  : NonEmpty.toList (rgbResultRoots requirement)
            , Just authority <-
                [ IntMap.lookup
                    (getNodeId node)
                    (grAmbientGammaAuthorities requirements)
                ]
            ]

        authorityProvenance =
          directAmbientGammaAuthorityProvenance
            constructionBinderRenames
            owner
            pendingResultSourcePacket
            (envLocalGammaClosures env)
            requirement

        insertDistinctAuthority candidate authorities
          | any (sameDirectAuthority candidate) authorities = authorities
          | otherwise = candidate : authorities

        sameDirectAuthority (leftProvenance, left) (rightProvenance, right) =
          leftProvenance == rightProvenance
            && sameAmbientAuthority left right

        sameAmbientAuthority left right =
          typeBinderRefsSameIdentity
            (agaExactRef left)
            (agaExactRef right)
            && ( alphaEqType (agaBound left) (agaBound right)
                   || churchAwareEqType (agaBound left) (agaBound right)
               )

    requirementRefForOwner boundRenames requirement =
      case ownerConstructionRequirementRef boundRenames requirement of
        -- The owner packet can retain a structural source occurrence in its
        -- substitution map.  That route is valid inside the operated type,
        -- but the requirement being emitted here is the flexible exterior
        -- itself.  Apply the same typed exterior selection used by the
        -- non-owner path so a mu self/result identity can never become a
        -- Lambda(Gamma) declaration.
        Just ref -> pure (gammaConsumerRefForRoute requirement ref)
        Nothing -> requirementRef requirement

    ownerConstructionRequirementRef boundRenames requirement =
      case
          [ closure
          | edgeId <- NonEmpty.toList (rgbEdgeIds requirement),
            Just closure <-
              [IntMap.lookup (getEdgeId edgeId) (envLocalGammaClosures env)]
          ]
      of
        closure : rest
          | length rest + 1 == NonEmpty.length (rgbEdgeIds requirement),
            all (== closure) rest,
            lgcOwner closure == owner,
            edgeKeySet (lgcEdgeIds closure)
              == edgeKeySet (rgbEdgeIds requirement),
            Just ownerSchemeInfo <- lgcOwnerPendingScheme closure ->
              IntMap.lookup
                (getNodeId (lgcExteriorNode closure))
                ( siSubstRefs
                    (applySchemeInfoRefRenames boundRenames ownerSchemeInfo)
                )
        _ -> Nothing

    binderOwnedByBoundary ref =
      any nodeOwnedByBoundary (binderRouteNodes ref)

    binderRouteNodes ref =
      case typeBinderRefNode ref of
        -- A graph identity carries its declaration node.  Other substitution
        -- routes can be descendant/result aliases and must not transfer
        -- ownership to this boundary merely because they share the ref.
        Just ownerNode -> [ownerNode]
        Nothing ->
          [ NodeId nodeKey
          | (nodeKey, routedRef) <- IntMap.toList subst,
            typeBinderRefsSameIdentity ref routedRef
          ]

    -- Binder ownership is a declaration fact from the live binding tree, not
    -- a quotient-class fact.  Canonicalizing the declaration before following
    -- its bind-parent path can jump past the exact gen node that owns
    -- @Lambda(Gamma_g)@.  In particular, an application's result binder may
    -- already have been merged with its enclosing consumer while its original
    -- node is still flexibly bound to the application's gen.  Keep that exact
    -- node for both ordinary and root-RaiseMerge ownership checks.
    nodeOwnedByBoundary node =
      flexiblyOwnedBy liveBindParents ownerScope node
        || rootRaiseMergeExteriorOwnedByScope
          (scGaParents scopeContext)
          ownerScope
          node

    flexiblyOwnedBy bindParents expectedOwnerScope node =
      go IntSet.empty (typeRef node)
      where
        go seen child
          | IntSet.member childKey seen = False
          | otherwise =
              case IntMap.lookup childKey bindParents of
                Just (parent, BindFlex)
                  | parent == expectedOwnerScope -> True
                  | TypeRef {} <- parent ->
                      go (IntSet.insert childKey seen) parent
                _ -> False
          where
            childKey = nodeRefKey child

    requirementRef requirement =
      case resultRootRef <|> IntMap.lookup (getNodeId (rgbExteriorNode requirement)) subst
        of
          Just ref -> pure (gammaConsumerRefForRoute requirement ref)
          Nothing ->
            Left
              ( ValidationFailed
                  [ "construction Γ requirement has no prepared binder substitution",
                    "  requirement: " ++ show requirement,
                    "  substitution: " ++ show subst
                  ]
              )
      where
        resultRootRef =
          foldr
            (\resultRoot fallback ->
                IntMap.lookup (getNodeId resultRoot) subst <|> fallback
            )
            Nothing
            (rgbResultRoots requirement)

    dependencyClosure refAlreadyInGamma binders = go
      where
        go refs =
          let dependencies =
                [ dependency
                | (ref, Just bound) <- binders,
                  refMember ref refs,
                  dependency <- freeTypeVarRefsType (tyToElab bound),
                  not (refAlreadyInGamma dependency),
                  any (typeBinderRefsSameIdentity dependency . fst) binders
                ]
              refs' = foldr insertRef refs dependencies
           in if length refs' == length refs then refs else go refs'

    insertRef ref refs
      | refMember ref refs = refs
      | otherwise = ref : refs

    refMember ref = any (typeBinderRefsSameIdentity ref)

-- | Close only the part of a prepared construction Gamma that survives in
-- the constructed term or its result type.  Edge replay is allowed to use a
-- wider Gamma while constructing children, but an obligation that cancels
-- inside the boundary is not a free dependency of the completed xMLF term.
-- Selecting the bound-dependency closure here prevents a vacuous outer
-- forall such as @forall (a >= Int). Int@ without rewriting the completed
-- type after construction.
constructionGammaCompletionBinders
  :: [(TypeBinderRef, Maybe BoundType)]
  -> XmlfTerm
  -> ElabType
  -> Either ElabError [(TypeBinderRef, Maybe BoundType)]
constructionGammaCompletionBinders binders term resultTy =
  orderConstructionGammaBinders
    "construction Gamma completion"
    [ binder
    | binder@(ref, _) <- binders,
      refMember ref selectedRefs
    ]
    resultTy
  where
    liveRoots =
      foldr insertRef (freeTypeVarRefsType resultTy) (Reduce.freeTypeVarRefsTerm term)
    selectedRefs = dependencyClosure liveRoots

    dependencyClosure refs =
      let dependencies =
            [ dependency
            | (ref, Just bound) <- binders,
              refMember ref refs,
              dependency <- freeTypeVarRefsType (tyToElab bound),
              any (typeBinderRefsSameIdentity dependency . fst) binders
            ]
          refs' = foldr insertRef refs dependencies
       in if length refs' == length refs
            then refs
            else dependencyClosure refs'

    insertRef ref refs
      | refMember ref refs = refs
      | otherwise = ref : refs

    refMember ref = any (typeBinderRefsSameIdentity ref)

-- | Put a completed Gamma spine in lexical dependency order before emitting
-- its type abstractions.  Construction sources preserve their own stable
-- order, but merging independently prepared sources can place a dependent
-- binder before a binder named by its bound.  Reject cycles at this typed
-- construction boundary rather than discovering an out-of-scope variable
-- after the term has been built.
orderConstructionGammaBinders
  :: String
  -> [(TypeBinderRef, Maybe BoundType)]
  -> ElabType
  -> Either ElabError [(TypeBinderRef, Maybe BoundType)]
orderConstructionGammaBinders role binders resultTy =
  either
    (Left . ValidationFailed . pure)
    (Right . schemeBinderRefs)
    ( orderSourceProjectedSchemeBinders
        role
        (mkElabSchemeWithRefs binders resultTy)
    )

-- | Combine independently prepared construction-binder sources before they
-- are emitted.  A local Gamma closure and its pending owner scheme can both
-- carry the same declaration; that is one construction authority, not two
-- nested type abstractions.  Conversely, disagreeing bounds for one identity
-- are an invalid owner packet and must fail before term construction.
mergeConstructionBinderSources
  :: String
  -> [(TypeBinderRef, Maybe BoundType)]
  -> [(TypeBinderRef, Maybe BoundType)]
  -> Either ElabError [(TypeBinderRef, Maybe BoundType)]
mergeConstructionBinderSources context first second = do
  first' <- validateSource "ordinary Gamma" first
  second' <- validateSource "prepared owner scheme" second
  foldM mergeBinder first' second'
  where
    validateSource source = foldM (insertSourceBinder source) []

    insertSourceBinder source accumulated binder@(ref, mbBound) =
      case find (typeBinderRefsSameIdentity ref . fst) accumulated of
        Nothing -> pure (accumulated ++ [binder])
        Just (_, existingBound) ->
          Left
            ( ValidationFailed
                [ "one construction source repeats a binder identity"
                , "  context: " ++ context
                , "  source: " ++ source
                , "  binder: " ++ show ref
                , "  first bound: " ++ show existingBound
                , "  second bound: " ++ show mbBound
                ]
            )

    mergeBinder accumulated binder@(ref, mbBound) =
      case find (typeBinderRefsSameIdentity ref . fst) accumulated of
        Nothing -> pure (accumulated ++ [binder])
        Just (_, existingBound)
          | constructionBoundsAgree existingBound mbBound -> pure accumulated
          | otherwise ->
              Left
                ( ValidationFailed
                    [ "construction sources disagree on one binder bound"
                    , "  context: " ++ context
                    , "  binder: " ++ show ref
                    , "  first bound: " ++ show existingBound
                    , "  second bound: " ++ show mbBound
                    ]
                )

    constructionBoundsAgree left right =
      let leftTy = maybe TBottom tyToElab left
          rightTy = maybe TBottom tyToElab right
       in alphaEqType leftTy rightTy || churchAwareEqType leftTy rightTy

-- | Resolve a packet consumer through the construction scheme that owns it.
-- A quotient may publish the graph exterior only in 'siSubstRefs' while the
-- emitted forall already carries the outward source identity.  Both are one
-- typed route; consumers must not compare only the pre-quotient graph identity
-- against the final binder list.
schemeConsumerBinderCandidates
  :: TypeBinderIdentity
  -> SchemeInfo
  -> [(TypeBinderRef, Maybe BoundType)]
schemeConsumerBinderCandidates consumerIdentity schemeInfo =
  [ binder
  | binder@(ref, _) <- schemeBinderRefs (siScheme schemeInfo)
  , any (typeBinderRefsSameIdentity ref) consumerRefs
  ]
  where
    consumerRefs = schemeConsumerConstructionRefs consumerIdentity schemeInfo

-- | Resolve a prepared Gamma consumer in the construction domain of the
-- scheme currently being emitted.  Packet preparation and an enclosing
-- constructor can legitimately choose different graph representatives for
-- the same consumer.  The current scheme substitution is the typed quotient
-- that joins those domains; consulting the packet's earlier completed view
-- would retain a stale representative after that quotient.
schemeConsumerConstructionRefs
  :: TypeBinderIdentity
  -> SchemeInfo
  -> [TypeBinderRef]
schemeConsumerConstructionRefs consumerIdentity schemeInfo =
  directConsumerRef : maybe [] pure routedConsumerRef
  where
    directConsumerRef = directSchemeConsumerRef consumerIdentity
    routedConsumerRef = do
      consumerNode <- typeBinderRefNode directConsumerRef
      IntMap.lookup
        (getNodeId consumerNode)
        (schemeInfoBinderRefSubst schemeInfo)

schemeConsumerConstructionRef
  :: TypeBinderIdentity
  -> SchemeInfo
  -> TypeBinderRef
schemeConsumerConstructionRef consumerIdentity schemeInfo =
  fromMaybe directConsumerRef $ do
    consumerNode <- typeBinderRefNode directConsumerRef
    IntMap.lookup
      (getNodeId consumerNode)
      (schemeInfoBinderRefSubst schemeInfo)
  where
    directConsumerRef = directSchemeConsumerRef consumerIdentity

directSchemeConsumerRef :: TypeBinderIdentity -> TypeBinderRef
directSchemeConsumerRef consumerIdentity =
  typeBinderRefFromIdentity consumerIdentity "$consumer"

-- | Materialize the bound of a prepared consumer at the constructor that owns
-- its outgoing edge.  Packet preparation fixes the consumer identity and its
-- lexical placement before term elaboration; the recursively constructed child
-- fixes the exact @Typ(a)@ source.  Joining those two authorities here makes
-- the local Gamma correct before either Hyp or the enclosing type abstraction
-- is emitted.
materializeConsumerBound
  :: ScopeContext p
  -> ConsumerBoundOwnership
  -> TypeBinderIdentity
  -> ElabType
  -> SchemeInfo
  -> Either ElabError (SchemeInfo, ElabType)
materializeConsumerBound scopeContext ownership consumerIdentity sourceTy schemeInfo =
  case ownership of
    ConsumerBoundOwnedByEnclosingGamma _ _ ->
      -- The exact enclosing owner is already proved here.  Its bound is
      -- checked only after the body computation and local binder spine have
      -- been constructed, when the complete lambda type exists.
      pure (schemeInfo, sourceTy)
    ConsumerBoundEliminatedAtAmbientBound _ _ ->
      -- A topology certificate and the recursively checked source have
      -- already proved that this packet consumer is discharged at an exact
      -- ambient declaration.  There is no local binder to materialize.
      pure (schemeInfo, sourceTy)
    ConsumerBoundOwnedByRootGamma _ ->
      -- The definition/root construction owns this exterior.  The completed
      -- child supplies its bound here; root packet placement emits the binder
      -- once at the outer scheme boundary.
      pure (schemeInfo, sourceTy)
    ConsumerBoundOwnedByRequiredGamma _ ->
      -- The packet's typed edge ownership authorizes the ordinary lambda
      -- construction below to emit this binder from the same source type.
      pure (schemeInfo, sourceTy)
    ConsumerBoundOwnedLocally ownedRef ->
      case matchingBindersFor ownedRef of
        [(consumerRef, Nothing)]
          | TVarRef sourceRef <- sourceTy
          , typeBinderRefsSameIdentity sourceRef consumerRef ->
              -- The source already is the flexible consumer.  Turning that
              -- fact into @a >= a@ would manufacture an invalid self-bound;
              -- the unbounded abstraction is the construction itself.
              pure (schemeInfo, sourceTy)
          | TVarRef sourceRef <- sourceTy ->
              -- Section 15.6.2 represents a peer-variable bound as an alias,
              -- not as an xMLF binder @consumer >= source@ (bare variables
              -- are deliberately outside 'BoundType').  Quotient the pending
              -- consumer through the checked child identity now; the same
              -- substitution later rewrites the outgoing Hyp to the ambient
              -- source, where it becomes the identity computation.
              pure
                ( applySchemeInfoRefRenames
                    [(consumerRef, sourceRef)]
                    schemeInfo
                , sourceTy
                )
          | otherwise -> do
              sourceBound <- checkedSourceBound
              pure
                ( schemeInfoFromRefSubst
                    ( mkElabSchemeWithRefs
                        [ if typeBinderRefsSameIdentity ref consumerRef
                            then (ref, Just sourceBound)
                            else binder
                        | binder@(ref, _) <- binders
                        ]
                        (schemeBody scheme)
                    )
                    (schemeInfoBinderRefSubst schemeInfo)
                , sourceTy
                )
        [(consumerRef, Just existingBound)]
          | boundAgrees (tyToElab existingBound) ->
              pure (schemeInfo, tyToElab existingBound)
          | otherwise ->
              incompatibleBound
                "prepared local Gamma"
                consumerRef
                (tyToElab existingBound)
        [] ->
          Left
            ( ValidationFailed
                [ "prepared lambda packet has no local consumer binder"
                , "  consumer: " ++ show consumerIdentity
                ]
            )
        _ ->
          Left
            ( ValidationFailed
                [ "prepared lambda packet binds its consumer identity more than once"
                , "  consumer: " ++ show consumerIdentity
                , "  matches: " ++ show (matchingBindersFor ownedRef)
                ]
            )
  where
    scheme = siScheme schemeInfo
    binders = schemeBinderRefs scheme
    matchingBindersFor ownedRef =
      [ binder
      | binder@(ref, _) <- binders
      , typeBinderRefsSameIdentity ref ownedRef
      ]

    boundAgrees existingBound =
      case sourceTy of
        TVarRef sourceRef
          | typeBinderRefIdentity sourceRef == consumerIdentity -> True
        _ -> scopedTypesAgree scopeContext existingBound sourceTy

    checkedSourceBound = do
      sourceBound <-
        either
          ( \cause ->
              Left
                ( ValidationFailed
                    [ "lambda-body consumer source is not a valid Gamma bound"
                    , "  consumer: " ++ show consumerIdentity
                    , "  source: " ++ show sourceTy
                    , "  cause: " ++ cause
                    ]
                )
          )
          Right
          (elabToBound sourceTy)
      pure sourceBound

    incompatibleBound ownerLabel ref existingBound =
      Left
        ( ValidationFailed
            [ "lambda consumer source contradicts its prepared Gamma bound"
            , "  owner: " ++ ownerLabel
            , "  consumer: " ++ show consumerIdentity
            , "  binder: " ++ show ref
            , "  prepared bound: " ++ show existingBound
            , "  constructed source: " ++ show sourceTy
            ]
        )

prepareLambdaConsumerConstruction
  :: ScopeContext p
  -> Env
  -> LocalGammaOwner
  -> Maybe PreparedSubtermGeneralization
  -> Maybe SchemeInfo
  -> Maybe OwnerFinalConstruction
  -> EdgeId
  -> [LambdaParamBoundaryCertificate]
  -> ElabType
  -> ElabType
  -> Either ElabError LambdaConsumerConstructionPlan
prepareLambdaConsumerConstruction scopeContext enclosingEnv owner mbPacket mbSchemeInfo mbBodyOwnerConstruction bodyEdge paramBoundaryCertificates paramTy sourceTy = do
  ( schemeInfo
    , constructionSourceTy
    , localBodyConsumerBoundRefinement
    , ambientTopologyResultConstruction
    , enclosingConsumerConstruction
    , consumerWithoutLocalBinder
    ) <-
    case (mbPacket, mbSchemeInfo) of
      (Just packet, Just preparedSchemeInfo) ->
        case subtermGeneralizationConsumerIdentity packet of
          Nothing -> do
            ( localResultSchemeInfo
              , localTopologyResultRefinement
              , localTopologyResultConstruction
              ) <-
              materializeLambdaLocalTopologyResultBound
                enclosingEnv
                owner
                bodyEdge
                packet
                sourceTy
                preparedSchemeInfo
            pure
              ( Just localResultSchemeInfo
              , sourceTy
              , localTopologyResultRefinement
              , localTopologyResultConstruction
              , Nothing
              , Nothing
              )
          Just consumerIdentity -> do
            (localSchemeInfo, packetConsumerWithoutLocalBinder) <-
              materializeOwnedPacketGamma
                packet
                preparedSchemeInfo
            ( localResultSchemeInfo
              , localTopologyResultRefinement
              , localTopologyResultConstruction
              ) <-
              materializeLambdaLocalTopologyResultBound
                enclosingEnv
                owner
                bodyEdge
                packet
                sourceTy
                localSchemeInfo
            ownership <-
              consumerBoundOwnership
                enclosingEnv
                owner
                packet
                bodyEdge
                consumerIdentity
                sourceTy
                localResultSchemeInfo
            (materializedSchemeInfo, materializedSourceTy) <-
              materializeConsumerBound
                scopeContext
                ownership
                consumerIdentity
                sourceTy
                localResultSchemeInfo
            let effectiveConsumerWithoutLocalBinder =
                  packetConsumerWithoutLocalBinder
                    <|> case ownership of
                      ConsumerBoundEliminatedAtAmbientBound ref bound ->
                        Just
                          ( PacketConsumerEliminatedAtAmbientBound
                              ref
                              bound
                          )
                      _ -> Nothing
            primaryConsumerRefinement <-
              case
                  ( ownership
                  , sourceTy
                  , subtermGeneralizationConsumerAuthority packet
                  )
                of
                (ConsumerBoundOwnedLocally _, TVarRef _, _) ->
                  pure Nothing
                (ConsumerBoundOwnedLocally _, _, Just authority)
                  | scaEdgeId authority == bodyEdge
                  , subtermConsumerAuthorityEnclosingOwner authority
                      == Just owner
                  , isNothing
                      (subtermGeneralizationGammaAuthority packet) ->
                      Just
                        <$> certifyLocalPacketBodyConsumerBoundRefinement
                          owner
                          bodyEdge
                          packet
                          []
                          materializedSchemeInfo
                          materializedSourceTy
                _ -> pure Nothing
            let ambientPacketGammaRefinement =
                  case effectiveConsumerWithoutLocalBinder of
                    Just (PacketConsumerRefinedAmbient _ certificate) ->
                      Just certificate
                    _ -> Nothing
            localRefinement <-
              case
                  catMaybes
                    [ localTopologyResultRefinement
                    , primaryConsumerRefinement
                    , ambientPacketGammaRefinement
                    ]
                of
                  [] -> pure Nothing
                  [refinement] -> pure (Just refinement)
                  refinements ->
                    Left
                      ( ValidationFailed
                          [ "one lambda packet completed multiple body-consumer declarations"
                          , "  owner: " ++ show owner
                          , "  body edge: " ++ show bodyEdge
                          , "  refinements: " ++ show refinements
                          ]
                      )
            inheritedSchemeInfo <-
              inheritAmbientConsumerBinder
                ownership
                consumerIdentity
                materializedSourceTy
                materializedSchemeInfo
            enclosingConstruction <-
              case ownership of
                ConsumerBoundOwnedByEnclosingGamma consumerRef _bound ->
                  case subtermGeneralizationConsumerAuthority packet of
                    Just authority
                      | Just enclosingOwner <-
                          subtermConsumerAuthorityEnclosingOwner authority
                      , lgoConstructor enclosingOwner == LocalLambdaGamma ->
                          if scaEdgeId authority == bodyEdge
                            then
                              Just
                                <$> certifyEnclosingBodyConsumer
                                  packet
                                  authority
                                  consumerRef
                                  materializedSourceTy
                            else do
                              let expectedLambdaTy =
                                    subtractOpenedLambdaLeadingBinders
                                      ( fromMaybe
                                          ( schemeToType
                                              ( subtermGeneralizationGammaBoundScheme
                                                  packet
                                              )
                                          )
                                          ( exactCompletedLambdaEndpoint
                                              packet
                                              authority
                                          )
                                      )
                              pure
                                ( Just
                                    ( EnclosingCompletedLambdaConstruction
                                        enclosingOwner
                                        (scaEdgeId authority)
                                        expectedLambdaTy
                                    )
                                )
                    _ -> pure Nothing
                _ -> pure Nothing
            let completedConstructionSourceTy =
                  case effectiveConsumerWithoutLocalBinder of
                    Just
                      ( PacketConsumerRefinedAmbient
                          completedGammaBound
                          _
                        ) ->
                        completedGammaBound
                    Just (PacketConsumerEliminatedAtAmbientBound _ _) ->
                      -- The completed packet has already proved that its
                      -- vacuous consumer disappears.  Preserve the packet's
                      -- operated binder spine as the lambda-body
                      -- construction source so Lambda(Gamma) closes those
                      -- binders inside the body instead of lifting them
                      -- around the enclosing value lambda.  When this is the
                      -- exact source-lambda packet, the constructor itself
                      -- emits its Var-Abs/arrow; only the certified codomain
                      -- is a recursively constructed body target.
                      let operatedTy =
                            subtractAmbientLeadingBinders
                              ( schemeToType
                                  ( siScheme
                                      ( subtermGeneralizationOperatedSchemeInfo
                                          packet
                                      )
                                  )
                              )
                       in fromMaybe
                            operatedTy
                            ( certifiedSourceLambdaOperatedBody
                                subtractAmbientLeadingBinders
                                packet
                                operatedTy
                                <|> certifiedCheckedBodyOperatedBody
                                  subtractAmbientLeadingBinders
                                  packet
                                  operatedTy
                            )
                    Just (PacketConsumerEliminatedByEqFree _) ->
                      -- Eq-Free owns the same erased packet endpoint without
                      -- requiring a matching declaration in ambient Gamma.
                      -- Preserve its complete operated spine: binders made
                      -- visible while recursively checking the child are not
                      -- thereby reclassified as enclosing paper Gamma.  An
                      -- exact source-lambda packet again contributes only its
                      -- certified body codomain at this boundary.
                      let operatedTy =
                            schemeToType
                              ( siScheme
                                  ( subtermGeneralizationOperatedSchemeInfo
                                      packet
                                  )
                              )
                       in fromMaybe
                            operatedTy
                            ( certifiedSourceLambdaOperatedBody
                                id
                                packet
                                operatedTy
                                <|> certifiedCheckedBodyOperatedBody
                                  id
                                  packet
                                  operatedTy
                            )
                    _ -> materializedSourceTy
            pure
              ( Just inheritedSchemeInfo
              , completedConstructionSourceTy
              , localRefinement
              , localTopologyResultConstruction
              , enclosingConstruction
              , effectiveConsumerWithoutLocalBinder
              )
      (Nothing, Nothing) ->
        pure (Nothing, sourceTy, Nothing, Nothing, Nothing, Nothing)
      _ ->
        Left
          ( ValidationFailed
              [ "prepared lambda packet and construction scheme disagree"
              , "  packet: " ++ show mbPacket
              , "  scheme: " ++ show mbSchemeInfo
              ]
          )
  pure
    LambdaConsumerConstructionPlan
      { lccOwner = owner
      , lccSourceType = constructionSourceTy
      , lccSchemeInfo = schemeInfo
      , lccLocalBodyConsumerBoundRefinement =
          localBodyConsumerBoundRefinement
      , lccAmbientTopologyResultConstruction =
          ambientTopologyResultConstruction
      , lccEnclosingConsumerConstruction =
          enclosingConsumerConstruction
      , lccEnclosingOwnedBinderRefs =
          maybeToList
            (atrcResultRef <$> ambientTopologyResultConstruction)
            ++ maybe
              []
              enclosingConsumerOwnedBinderRefs
              enclosingConsumerConstruction
      , lccConsumerWithoutLocalBinder = consumerWithoutLocalBinder
      }
  where
    enclosingConsumerOwnedBinderRefs construction =
      case construction of
        EnclosingBodyConsumerConstruction certificate ->
          ebccConsumerRef certificate
            : map fst (ebccAmbientDependencies certificate)
        EnclosingCompletedLambdaConstruction _ _ expectedTy ->
          [ expectedRef
          | expectedRef <- freeTypeVarRefsType expectedTy
          , any
              (typeBinderRefsSameIdentity expectedRef)
              (Map.keys (envTypeBindings enclosingEnv))
          ]

    -- A source-owned exact specialization consumes the complete packet while
    -- omitting its intermediate enclosing-Gamma declaration.  Its certified
    -- endpoint is therefore the completed lambda that this boundary must
    -- construct; the packet Gamma bound is only the omitted declaration's
    -- bound and can be merely the lambda body type.
    exactCompletedLambdaEndpoint packet authority = do
      (certificateAuthority, endpoint, _, _) <-
        subtermGeneralizationExactConsumerSpecialization packet
      guard (certificateAuthority == authority)
      pure endpoint

    -- A prepared source-lambda packet constructs the whole value lambda,
    -- while its outgoing Gamma is materialized after recursively constructing
    -- the body.  Select the immediate codomain only from the packet's exact
    -- owner, edge, parameter, and completed-construction certificates; a
    -- merely arrow-shaped operated type is not construction authority.
    certifiedSourceLambdaOperatedBody
      projectAtBoundary
      packet
      operatedAtBoundary = do
        (lambdaNode, _, certifiedParamTy) <-
          subtermGeneralizationApplicationSourceLambdaParameter
            packetBinderCanBeEliminated
            packet
        guard (lambdaNode == lgoTermNode owner)
        guard (lgoBoundaryEdge owner == bodyEdge)
        (resultLambdaNode, completedLambdaTy) <-
          subtermGeneralizationApplicationSourceLambdaResultConstruction
            packetBinderCanBeEliminated
            packet
        guard (resultLambdaNode == lambdaNode)
        let completedAtBoundary = projectAtBoundary completedLambdaTy
        guard
          ( scopedTypesAgree
              scopeContext
              completedAtBoundary
              operatedAtBoundary
          )
        (domainTy, codomainTy) <- sourceLambdaBoundary completedAtBoundary
        guard
          ( scopedTypesAgree scopeContext certifiedParamTy paramTy
              && scopedTypesAgree scopeContext domainTy paramTy
              && ( scopedTypesAgree scopeContext codomainTy sourceTy
                    || isJust
                      ( planExactBinderSpine
                          (scopedTypesAgree scopeContext)
                          sourceTy
                          codomainTy
                      )
                 )
          )
        pure codomainTy
      where
        packetBinderCanBeEliminated ref =
          not (envOwnsExactTypeBinderRef enclosingEnv ref)

    -- Figure 15.3.5 constructs a value lambda from its exact parameter and
    -- the recursively constructed body.  Some nested packets do not retain
    -- the optional source-lambda summary above, but the recursive body's
    -- owner-final certificate is still the positive construction authority
    -- for the codomain.  The packet owns the surrounding declaration/arrow
    -- prefix; its frozen codomain is not authority to make the child recreate
    -- that whole provisional tail.  Return the checked child endpoint here
    -- and let the enclosing lambda constructor validate the completed arrow.
    certifiedCheckedBodyOperatedBody
      projectAtBoundary
      packet
      operatedAtBoundary = do
        childConstruction <- mbBodyOwnerConstruction
        guard (ofcOwner childConstruction /= owner)
        guard (lgoBoundaryEdge owner == bodyEdge)
        let childConstructedTy =
              completeLambdaParamBoundaryType
                paramBoundaryCertificates
                (ofcConstructedType childConstruction)
            completedAtBoundary = projectAtBoundary operatedAtBoundary
            completedScheme = schemeFromType completedAtBoundary
            leadingBinders = schemeBinderRefs completedScheme
            constructionRefs =
              IntMap.elems
                ( siConstructionBinderOrderRefs
                    (subtermGeneralizationSchemeInfo packet)
                )
            sourceRefs =
              IntMap.elems
                ( siSourceBinderOrderRefs
                    (subtermGeneralizationSchemeInfo packet)
                )
            constructionOwns (ref, _) =
              any (typeBinderRefsSameIdentity ref) constructionRefs
                && not (any (typeBinderRefsSameIdentity ref) sourceRefs)
        guard
          ( ( scopedTypesAgree scopeContext childConstructedTy sourceTy
                || isJust
                  ( planExactBinderSpine
                      (scopedTypesAgree scopeContext)
                      childConstructedTy
                      sourceTy
                  )
            )
              && all constructionOwns leadingBinders
          )
        domainTy <-
          case schemeBody completedScheme of
            TArrow domain _ -> Just domain
            _ -> Nothing
        guard
          (scopedTypesAgree scopeContext domainTy paramTy)
        pure sourceTy

    sourceLambdaBoundary ty =
      case ty of
        TForallRef _ _ body -> sourceLambdaBoundary body
        TArrow domainTy codomainTy -> Just (domainTy, codomainTy)
        _ -> Nothing

    certifyEnclosingBodyConsumer
      packet
      authority
      consumerRef
      constructedSourceTy = do
        let pendingEndpoint = TVarRef consumerRef
        ( ambientRef
          , completedBound
          , ambientDependencies
          , sourceSpecialization
          , certificate
          ) <-
          certifyEnclosingPacketBodyConsumerBoundRefinement
            owner
            bodyEdge
            packet
            paramBoundaryCertificates
            constructedSourceTy
            certifiedBodyConstructionForConsumer
            (envLocalGammaClosures enclosingEnv)
            (envTypeBindings enclosingEnv)
        specializedSourceTy <-
          either
            ( \cause ->
                enclosingBodyConsumerFailure
                  authority
                  consumerRef
                  pendingEndpoint
                  constructedSourceTy
                  [ "certified source specialization does not typecheck"
                  , "  specialization: " ++ show sourceSpecialization
                  , "  cause: " ++ show cause
                  ]
            )
            pure
            ( TypeCheck.checkInstantiation
                (typeCheckEnvFrom enclosingEnv)
                constructedSourceTy
                sourceSpecialization
            )
        unless
          ( typeBinderRefsSameIdentity ambientRef consumerRef
              && scopedEndpointTypesAgree
                scopeContext
                specializedSourceTy
                completedBound
          )
          ( enclosingBodyConsumerFailure
              authority
              consumerRef
              pendingEndpoint
              constructedSourceTy
              [ "certified consumer completion changed identity or source type"
              , "  certified consumer: " ++ show ambientRef
              , "  certified specialization: " ++ show sourceSpecialization
              , "  specialized source: " ++ show specializedSourceTy
              , "  certified bound: " ++ show completedBound
              ]
          )
        pure
          ( EnclosingBodyConsumerConstruction
              EnclosingBodyConsumerCertificate
                { ebccEdgeId = scaEdgeId authority
                , ebccConsumerRef = ambientRef
                , ebccCompletedBound = completedBound
                , ebccAmbientDependencies = ambientDependencies
                , ebccSourceSpecialization = sourceSpecialization
                , ebccBoundRefinement = certificate
                }
            )

    certifiedBodyConstructionForConsumer = do
      ownerConstruction <- mbBodyOwnerConstruction
      certifyLambdaBodyConstruction
        (ofcOwner ownerConstruction)
        (ofcConstructedType ownerConstruction)
        (ofcConstructedBinderSpine ownerConstruction)
        (ofcConsumedLocalBinders ownerConstruction)
        (ownerFinalOpenSourceBinderRefs ownerConstruction)
        (ownerFinalOpenValueLambdaParameterRefs ownerConstruction)
        (ownerFinalReturnedResultEndpoints ownerConstruction)

    enclosingBodyConsumerFailure
      :: SubtermConsumerAuthority
      -> TypeBinderRef
      -> ElabType
      -> ElabType
      -> [String]
      -> Either ElabError a
    enclosingBodyConsumerFailure
      authority
      consumerRef
      expectedEndpoint
      constructedSourceTy
      details =
        Left
          ( ValidationFailed
              ( [ "enclosing lambda-body consumer lacks a complete construction certificate"
                , "  body edge: " ++ show bodyEdge
                , "  consumer edge: " ++ show (scaEdgeId authority)
                , "  consumer: " ++ show consumerRef
                , "  packet endpoint: " ++ show expectedEndpoint
                , "  checked body source: " ++ show constructedSourceTy
                ]
                  ++ details
              )
          )

    -- The enclosing packet publishes its complete scheme, while this child
    -- lambda is constructed after that Gamma has already opened any shared
    -- leading binders.  Apply Gen(Gamma, tau)'s environment subtraction to
    -- the expected endpoint as well as to the child's construction scheme;
    -- otherwise an ordinary rank-1 @\x -> f x@ is incorrectly required to
    -- recreate the enclosing @forall a b@ prefix.
    subtractAmbientLeadingBinders ty =
      schemeToType
        ( mkElabSchemeWithRefs
            [ binder
            | binder@(ref, _) <- schemeBinderRefs leadingScheme
            , not (envOwnsExactTypeBinderRef enclosingEnv ref)
            ]
            (schemeBody leadingScheme)
        )
      where
        leadingScheme = schemeFromType ty

    -- A source annotation on the value parameter owns its forall declarations
    -- inside the arrow domain.  Packet preparation can retain the same source
    -- identities as a vacuous leading prefix of the completed lambda endpoint.
    -- They are not members of this lambda's Lambda(Gamma): emitting them again
    -- would bind one identity both outside and inside the parameter type.
    --
    -- Project only a matching, source-owned parameter prefix, and only when
    -- the complete prefix is absent from the remainder after projection.
    -- This handles dependent parameter binders as one declaration group while
    -- preserving any source binder that is genuinely free in the result or a
    -- retained Gamma bound.
    subtractOpenedLambdaLeadingBinders =
      projectParameterLocalSourcePrefix . subtractAmbientLeadingBinders

    projectParameterLocalSourcePrefix ty =
      case
          [ projected
          | prefixLength <- reverse [1 .. length matchingPrefix]
          , let droppedRefs =
                  map fst (take prefixLength expectedBinders)
                projected =
                  schemeToType
                    ( mkElabSchemeWithRefs
                        (drop prefixLength expectedBinders)
                        expectedBody
                    )
          , all
              ( \droppedRef ->
                  not
                    ( any
                        (typeBinderRefsSameIdentity droppedRef)
                        (freeTypeVarRefsType projected)
                    )
              )
              droppedRefs
          ]
        of
          projected : _ -> projected
          [] -> ty
      where
        expectedScheme = schemeFromType ty
        expectedBinders = schemeBinderRefs expectedScheme
        expectedBody = schemeBody expectedScheme
        parameterBinders =
          schemeBinderRefs (schemeFromType paramTy)
        matchingPrefix =
          takeWhile
            matchingParameterDeclaration
            (zip expectedBinders parameterBinders)

        matchingParameterDeclaration
          ( (expectedRef, expectedBound)
            , (parameterRef, parameterBound)
            ) =
            typeBinderRefsSameIdentity expectedRef parameterRef
              && sourceOwnsExpectedRef expectedRef
              && declaredBoundsAgree expectedBound parameterBound

        sourceOwnsExpectedRef ref =
          any
            (typeBinderRefsSameIdentity ref)
            packetSourceBinderRefs

        packetSourceBinderRefs =
          maybe
            []
            ( IntMap.elems
                . siSourceBinderOrderRefs
                . subtermGeneralizationConsumerConstructionSchemeInfo
            )
            mbPacket

        declaredBoundsAgree Nothing Nothing = True
        declaredBoundsAgree (Just left) (Just right) =
          operationalEndpointTypesAgree
            (tyToElab left)
            (tyToElab right)
        declaredBoundsAgree _ _ = False

    -- Gen(Gamma, tau) never re-emits the packet consumer when its declaration
    -- is already owned by the enclosing Gamma.  The consumer can be a vacuous
    -- marker for the completed lambda itself, so this subtraction must follow
    -- the certified ownership rather than wait for the checked child to have a
    -- peer-variable shape.
    --
    -- A locally classified peer-variable consumer has the same outcome after
    -- materialization quotients it to an exact ambient identity.  Keep that
    -- route as a second, independently certified way to subtract the binder.
    inheritAmbientConsumerBinder
      ownership
      consumerIdentity
      constructionSourceTy
      schemeInfo
        | ConsumerBoundOwnedByEnclosingGamma {} <- ownership =
            subtractConsumerBinder
        | ConsumerBoundEliminatedAtAmbientBound {} <- ownership =
            subtractConsumerBinder
        | TVarRef sourceRef <- constructionSourceTy
        , envOwnsExactTypeBinderRef enclosingEnv sourceRef
        , let consumerRef =
                schemeConsumerConstructionRef consumerIdentity schemeInfo
        , typeBinderRefsSameIdentity consumerRef sourceRef =
            subtractConsumerBinder
        | otherwise = pure schemeInfo
      where
        consumerCandidates =
          schemeConsumerBinderCandidates consumerIdentity schemeInfo

        subtractConsumerBinder =
          case consumerCandidates of
            [] -> pure schemeInfo
            [(consumerRef, _)] ->
              pure
                ( schemeInfoFromRefSubst
                    ( mkElabSchemeWithRefs
                        [ binder
                        | binder@(ref, _) <-
                            schemeBinderRefs (siScheme schemeInfo)
                        , not
                            (typeBinderRefsSameIdentity ref consumerRef)
                        ]
                        (schemeBody (siScheme schemeInfo))
                    )
                    (schemeInfoBinderRefSubst schemeInfo)
                )
            matches ->
              Left
                ( ValidationFailed
                    [ "ambient packet consumer is not one construction binder"
                    , "  consumer: " ++ show consumerIdentity
                    , "  source: " ++ show constructionSourceTy
                    , "  matches: " ++ show matches
                    ]
                )

    -- A packet can both be consumed by an enclosing Gamma and own a distinct
    -- root-RaiseMerge consumer at this lambda-body edge.  The latter is the
    -- result abstraction used by T(e), so its bound must be installed from the
    -- recursively checked child before that instantiation is validated.  The
    -- enclosing consumer is handled afterwards and remains a proof about the
    -- completed lambda, not about the lambda body.
    materializeOwnedPacketGamma packet schemeInfo =
      case subtermGeneralizationGammaAuthority packet of
        Just gammaAuthority
          | gpaEdgeId gammaAuthority == bodyEdge -> do
              case map fst
                  ( schemeConsumerBinderCandidates
                      (gpaConsumerIdentity gammaAuthority)
                      schemeInfo
                  ) of
                [gammaRef] ->
                  do
                    materializedSchemeInfo <-
                      fst
                        <$> materializeConsumerBound
                          scopeContext
                          (ConsumerBoundOwnedLocally gammaRef)
                          (gpaConsumerIdentity gammaAuthority)
                          sourceTy
                          schemeInfo
                    pure (materializedSchemeInfo, Nothing)
                [] -> do
                  resolution <-
                    resolvePacketConsumerWithoutLocalBinder
                      gammaAuthority
                      packet
                      schemeInfo
                  case resolution of
                    PacketConsumerInheritedFree _ ->
                      pure (schemeInfo, Just resolution)
                    PacketConsumerEliminatedAtAmbientBound _ _ ->
                      pure (schemeInfo, Just resolution)
                    PacketConsumerEliminatedByEqFree _ ->
                      pure (schemeInfo, Just resolution)
                    PacketConsumerRefinedAmbient _ _ ->
                      pure (schemeInfo, Just resolution)
                refs ->
                  Left
                    ( ValidationFailed
                        [ "packet-owned local Gamma has multiple construction binders"
                        , "  edge: " ++ show bodyEdge
                        , "  consumer: " ++ show (gpaConsumerIdentity gammaAuthority)
                        , "  binders: " ++ show refs
                        ]
                    )
        _ -> pure (schemeInfo, Nothing)

    resolvePacketConsumerWithoutLocalBinder gammaAuthority packet schemeInfo =
      case inheritedFreeRefs of
        [inheritedRef]
          | packetEndpointIsExactInheritedConsumer inheritedRef ->
              -- The packet asks the checked body to construct the exact
              -- ambient consumer, not a new bound for it.  Its unbounded
              -- declaration therefore remains complete as
              -- @alpha > Bottom@; refining it to the operated endpoint would
              -- manufacture the illegal recursive bound @alpha > alpha@.
              pure (PacketConsumerInheritedFree inheritedRef)
          | packetCompletedBoundIsExactInheritedConsumer inheritedRef ->
              -- The current scheme can retain a graph occurrence that the
              -- enclosing construction has already quotiented to the exact
              -- completed packet declaration.  The two construction routes
              -- (packet exterior -> current occurrence, current occurrence ->
              -- ambient declaration) and the checked completed bound prove
              -- that this is an inherited consumer, even though the
              -- intermediate graph ref is not itself ambient authority.
              pure (PacketConsumerInheritedFree inheritedRef)
          | ambientPacketConsumerIsPending ->
              refineAmbientPacketConsumer
          | otherwise ->
              pure (PacketConsumerInheritedFree inheritedRef)
        []
          | ambientPacketConsumerIsPending ->
              refineAmbientPacketConsumer
          | not (null currentConsumerOccurrences) ->
              missingConsumer
                [ "the current scheme retains the consumer without exact ambient ownership"
                , "  current consumer occurrences: " ++ show currentConsumerOccurrences
                ]
          | otherwise ->
              eliminateVacuousPacketConsumer
        refs ->
          missingConsumer
            [ "the current scheme has multiple exact ambient consumer routes"
            , "  inherited routes: " ++ show refs
            ]
      where
        consumerIdentity = gpaConsumerIdentity gammaAuthority
        constructionConsumerRefs =
          uniqueIdentityRefs
            ( schemeConsumerConstructionRefs consumerIdentity schemeInfo
                ++ maybeToList
                  ( typeBinderIdentityNode consumerIdentity
                      >>= \consumerNode ->
                        IntMap.lookup
                          (getNodeId consumerNode)
                          packetConsumerConstructionRoutes
                  )
            )
        currentSchemeRefs =
          freeTypeVarRefsType (schemeToType (siScheme schemeInfo))
        currentConsumerOccurrences =
          [ occurrence
          | occurrence <- currentSchemeRefs
          , any (typeBinderRefsSameIdentity occurrence) constructionConsumerRefs
          ]
        inheritedFreeRefs =
          uniqueIdentityRefs
            [ inheritedRef
            | occurrence <- currentConsumerOccurrences
            , inheritedRef <- exactAmbientRoutesFor occurrence
            ]
        exactAmbientRoutesFor occurrence =
          uniqueIdentityRefs
            ( [ occurrence
              | envOwnsExactTypeBinderRef enclosingEnv occurrence
              ]
                ++ do
                  occurrenceNode <- maybeToList (typeBinderRefNode occurrence)
                  routedRef <-
                    maybeToList
                      ( IntMap.lookup
                          (getNodeId occurrenceNode)
                          (envConstructionGammaAliases enclosingEnv)
                      )
                  guard
                    ( any
                        (typeBinderRefsSameIdentity routedRef)
                        constructionConsumerRefs
                    )
                  guard (envOwnsExactTypeBinderRef enclosingEnv routedRef)
                  pure routedRef
            )
        ambientConsumerBindings =
          [ (ref, bound)
          | (ref, bound) <- Map.toList (envTypeBindings enclosingEnv)
          , typeBinderRefsSameIdentity ref constructionConsumerRef
          ]
        constructionConsumerRef =
          schemeConsumerConstructionRef consumerIdentity schemeInfo
        packetConsumerConstructionRoutes =
          schemeInfoBinderRefSubst
            (subtermGeneralizationConsumerConstructionSchemeInfo packet)
        -- The exact consumer SchemeInfo is the occurrence-level quotient
        -- certificate. Eq-Free can omit the pending declaration after its
        -- graph identity has been projected to the lexical source identity,
        -- so identity equality alone is too early at this boundary.
        consumerRefMatchesConstruction candidateRef =
          typeBinderRefsSameIdentity candidateRef constructionConsumerRef
            || case typeBinderRefNode constructionConsumerRef of
              Just constructionNode ->
                maybe
                  False
                  (typeBinderRefsSameIdentity candidateRef)
                  ( IntMap.lookup
                      (getNodeId constructionNode)
                      packetConsumerConstructionRoutes
                  )
              Nothing -> False
        pendingPacketConsumerDeclarations =
          schemeConsumerBinderCandidates
            consumerIdentity
            (subtermGeneralizationConsumerConstructionSchemeInfo packet)
        ambientPacketConsumerIsPending =
          case
              ( ambientConsumerBindings
              , pendingPacketConsumerDeclarations
              )
            of
              ([(ambientRef, TBottom)], [(pendingRef, Nothing)]) ->
                typeBinderRefsSameIdentity
                  ambientRef
                  constructionConsumerRef
                  && typeBinderRefIdentity pendingRef
                    == consumerIdentity
              _ -> False
        packetEndpointIsExactInheritedConsumer inheritedRef =
          case
              subtractAmbientLeadingBinders
                ( schemeToType
                    (siScheme (subtermGeneralizationOperatedSchemeInfo packet))
                )
            of
            TVarRef endpointRef ->
              typeBinderRefsSameIdentity endpointRef inheritedRef
                && any
                  (typeBinderRefsSameIdentity endpointRef)
                  constructionConsumerRefs
                && envOwnsExactTypeBinderRef enclosingEnv endpointRef
            _ -> False
        packetCompletedBoundIsExactInheritedConsumer inheritedRef =
          case
              ( completedConsumerDeclarations
              , exactAmbientBindings
              )
            of
              ([(completedRef, Just completedBound)], [(ambientRef, ambientBound)]) ->
                typeBinderRefsSameIdentity completedRef inheritedRef
                  && typeBinderRefsSameIdentity ambientRef inheritedRef
                  && operationalEndpointTypesAgree
                    (tyToElab completedBound)
                    ambientBound
                  && operationalEndpointTypesAgree sourceTy ambientBound
              _ -> False
          where
            completedConsumerDeclarations =
              schemeConsumerBinderCandidates
                consumerIdentity
                (subtermGeneralizationSchemeInfo packet)
            exactAmbientBindings =
              [ binding
              | binding@(ref, _) <- Map.toList (envTypeBindings enclosingEnv)
              , typeBinderRefsSameIdentity ref inheritedRef
              , envOwnsExactTypeBinderRef enclosingEnv ref
              ]

        refineAmbientPacketConsumer = do
          (_, completedGammaBound, certificate) <-
            certifyAmbientPacketGammaConsumerBoundRefinement
              owner
              bodyEdge
              packet
              paramBoundaryCertificates
              sourceTy
              schemeInfo
              (envTypeBindings enclosingEnv)
          pure
            ( PacketConsumerRefinedAmbient
                completedGammaBound
                certificate
            )

        eliminateVacuousPacketConsumer = do
          let completedPacketInfo = subtermGeneralizationSchemeInfo packet
              completedPacketScheme = siScheme completedPacketInfo
              completedConsumerCandidates =
                schemeConsumerBinderCandidates
                  consumerIdentity
                  completedPacketInfo
          (completedConsumerRef, mbCompletedBound) <-
            case completedConsumerCandidates of
              [(consumerRef, Just bound)] ->
                pure (consumerRef, Just (tyToElab bound))
              [(_, Nothing)] ->
                missingConsumer
                  [ "the eliminated packet consumer has no completed bound" ]
              [] -> do
                pendingRef <-
                  case pendingPacketConsumerDeclarations of
                    [(consumerRef, Nothing)] -> pure consumerRef
                    declarations ->
                      missingConsumer
                        [ "an omitted completed consumer has no unique pending declaration"
                        , "  pending declarations: " ++ show declarations
                        ]
                unless
                  (consumerRefMatchesConstruction pendingRef)
                  ( missingConsumer
                      [ "the omitted consumer changed identity before completion"
                      , "  pending consumer: " ++ show pendingRef
                      , "  current consumer: " ++ show constructionConsumerRef
                      ]
                  )
                case
                    uniqueIdentityRefs
                      ( schemeConsumerConstructionRefs
                          consumerIdentity
                          completedPacketInfo
                      )
                  of
                    refs@(_ : _)
                      | all consumerRefMatchesConstruction refs ->
                          pure (constructionConsumerRef, Nothing)
                    refs ->
                      missingConsumer
                        [ "the omitted completed consumer has no unique construction route"
                        , "  completed routes: " ++ show refs
                        ]
              candidates ->
                missingConsumer
                  [ "the completed packet has multiple consumer declarations"
                  , "  declarations: " ++ show candidates
                  ]
          let completedConsumerRefs =
                uniqueIdentityRefs
                  ( completedConsumerRef
                      : schemeConsumerConstructionRefs
                          consumerIdentity
                          completedPacketInfo
                  )
              completedPayloadRefs =
                freeTypeVarRefsType (schemeBody completedPacketScheme)
                  ++ concatMap
                    (maybe [] (freeTypeVarRefsType . tyToElab) . snd)
                    (schemeBinderRefs completedPacketScheme)
              completedConsumerUses =
                [ occurrence
                | occurrence <- completedPayloadRefs
                , any
                    (typeBinderRefsSameIdentity occurrence)
                    completedConsumerRefs
                ]
              completedSchemeWithoutConsumer =
                mkElabSchemeWithRefs
                  ( projectConstructionBindersForConsumerComparison
                      completedConsumerRef
                      completedPacketInfo
                      currentComparisonScheme
                  )
                  (schemeBody completedPacketScheme)
              completedTypeWithoutConsumer =
                schemeToType completedSchemeWithoutConsumer
              currentConstructionScheme = siScheme schemeInfo
              currentPendingConsumerCandidates =
                case
                    ( subtermGeneralizationConsumerIdentity packet
                    , subtermGeneralizationConsumerAuthority packet
                    )
                  of
                  (Just pendingIdentity, Just pendingAuthority)
                    | pendingIdentity /= consumerIdentity
                    , isJust
                        ( subtermConsumerAuthorityEnclosingOwner
                            pendingAuthority
                        ) ->
                        schemeConsumerBinderCandidates
                          pendingIdentity
                          schemeInfo
                  _ -> []
              currentConstructionPayloadRefs =
                freeTypeVarRefsType (schemeBody currentConstructionScheme)
                  ++ concatMap
                    (maybe [] (freeTypeVarRefsType . tyToElab) . snd)
                    (schemeBinderRefs currentConstructionScheme)
              currentComparisonSchemeBeforeEqFree =
                case currentPendingConsumerCandidates of
                  [(pendingRef, Nothing)]
                    | not
                        ( any
                            (typeBinderRefsSameIdentity pendingRef)
                            currentConstructionPayloadRefs
                        ) ->
                        mkElabSchemeWithRefs
                          [ binder
                          | binder@(ref, _) <-
                              schemeBinderRefs currentConstructionScheme
                          , not
                              (typeBinderRefsSameIdentity ref pendingRef)
                          ]
                          (schemeBody currentConstructionScheme)
                  _ -> currentConstructionScheme
              currentComparisonInfoBeforeEqFree =
                rebuildSchemeInfoFromRefSubst
                  schemeInfo
                  currentComparisonSchemeBeforeEqFree
                  (schemeInfoBinderRefSubst schemeInfo)
              -- The same Eq-Free quotient applies to construction-only
              -- binders already present in the current view.  Nested lambda
              -- packets can carry such a completed but vacuous declaration
              -- forward after their consumer has disappeared; retaining it
              -- here would compare a pre-Eq-Free scheme with the completed
              -- packet's post-Eq-Free scheme.
              currentComparisonScheme =
                mkElabSchemeWithRefs
                  ( projectConstructionBindersForConsumerComparison
                      constructionConsumerRef
                      currentComparisonInfoBeforeEqFree
                      currentComparisonSchemeBeforeEqFree
                  )
                  (schemeBody currentComparisonSchemeBeforeEqFree)
              currentConstructionType =
                schemeToType currentConstructionScheme
              currentComparisonType =
                schemeToType currentComparisonScheme
              completedConsumerRouteKeys =
                IntSet.toList
                  ( IntSet.fromList
                      [ nodeKey
                      | consumerRef <- completedConsumerRefs
                      , Just consumerRefNode <- [typeBinderRefNode consumerRef]
                      , let nodeKey = getNodeId consumerRefNode
                      , Just routedRef <-
                          [ IntMap.lookup
                              nodeKey
                              ( schemeInfoBinderRefSubst
                                  completedPacketInfo
                              )
                          ]
                      , any
                          (typeBinderRefsSameIdentity routedRef)
                          completedConsumerRefs
                      ]
                  )
              currentRouteMismatches =
                [ (nodeKey, IntMap.lookup nodeKey (schemeInfoBinderRefSubst schemeInfo))
                | nodeKey <- completedConsumerRouteKeys
                , maybe
                    True
                    (not . typeBinderRefsSameIdentity constructionConsumerRef)
                    (IntMap.lookup nodeKey (schemeInfoBinderRefSubst schemeInfo))
                ]
          unless (null completedConsumerUses) $
            missingConsumer
              [ "the completed packet consumer is not vacuous"
              , "  packet consumer uses: " ++ show completedConsumerUses
              ]
          unless
            (alphaEqType completedTypeWithoutConsumer currentComparisonType)
            ( missingConsumer
                [ "erasing the vacuous completed consumer does not produce the current construction scheme"
                , "  erased completed type: " ++ show completedTypeWithoutConsumer
                , "  current construction type: " ++ show currentConstructionType
                , "  independently owned pending consumers: "
                    ++ show currentPendingConsumerCandidates
                , "  comparison type: " ++ show currentComparisonType
                ]
            )
          consumerNode <-
            case typeBinderRefNode (directSchemeConsumerRef consumerIdentity) of
              Just node -> pure node
              Nothing ->
                missingConsumer
                  [ "the packet Gamma consumer has no graph exterior route" ]
          unless
            ( getNodeId consumerNode `elem` completedConsumerRouteKeys
                && null currentRouteMismatches
            )
            ( missingConsumer
                [ "the completed-to-current consumer quotient is incomplete"
                , "  completed consumer: " ++ show completedConsumerRef
                , "  current consumer: " ++ show constructionConsumerRef
                , "  completed route keys: " ++ show completedConsumerRouteKeys
                , "  current route mismatches: " ++ show currentRouteMismatches
                ]
            )
          let exactAmbientConsumerRefs =
                uniqueIdentityRefs
                  [ ref
                  | ref <- constructionConsumerRefs
                  , envOwnsExactTypeBinderRef enclosingEnv ref
                  ]
          case exactAmbientConsumerRefs of
            [] -> do
              -- Eq-Free removes a vacuous quantifier without first turning
              -- its graph exterior into an ambient declaration.  The
              -- completed/current scheme equality and quotient checks above
              -- are the construction certificate for that removal.
              verifyConsumerErasedOperatedPacket False
              pure
                (PacketConsumerEliminatedByEqFree constructionConsumerRef)
            [ambientConstructionConsumerRef] -> do
              ambientBound <-
                case
                    [ bound
                    | (ambientRef, bound) <-
                        Map.toList (envTypeBindings enclosingEnv)
                    , typeBinderRefsSameIdentity
                        ambientConstructionConsumerRef
                        ambientRef
                    ]
                of
                  [bound] -> pure bound
                  [] ->
                    missingConsumer
                      [ "the eliminated consumer has no exact ambient bound"
                      , "  ambient consumer: "
                          ++ show ambientConstructionConsumerRef
                      ]
                  bounds ->
                    missingConsumer
                      [ "the eliminated consumer has multiple exact ambient bounds"
                      , "  ambient consumer: "
                          ++ show ambientConstructionConsumerRef
                      , "  ambient bounds: " ++ show bounds
                      ]
              case mbCompletedBound of
                Just completedBound -> do
                  unless
                    (scopedTypesAgree scopeContext completedBound ambientBound)
                    ( missingConsumer
                        [ "the completed packet bound disagrees with ambient Gamma"
                        , "  completed packet bound: " ++ show completedBound
                        , "  ambient bound: " ++ show ambientBound
                        ]
                    )
                  unless
                    (sourceTy == ambientBound || alphaEqType sourceTy ambientBound)
                    ( missingConsumer
                        [ "the recursively checked source cannot construct the eliminated consumer"
                        , "  source type: " ++ show sourceTy
                        , "  ambient bound: " ++ show ambientBound
                        ]
                    )
                Nothing -> do
                  -- An omitted completed consumer has two construction
                  -- lanes. Eq-Free leaves the exact ambient declaration at
                  -- Bottom. A source/packet specialization can instead have
                  -- completed that same declaration to the packet's operated
                  -- endpoint before this nested lambda is built. In the
                  -- latter case require the exact ambient identity plus the
                  -- checked operated endpoint; the non-Bottom bound is never
                  -- inferred merely from the current result type.
                  verifyConsumerErasedOperatedPacket True
                  unless
                    ( operationalEndpointTypesAgree ambientBound TBottom
                        || completedOperatedPacketOwnsAmbientBound ambientBound
                    )
                    ( missingConsumer
                        [ "the omitted packet consumer has no exact completed ambient construction"
                        , "  ambient bound: " ++ show ambientBound
                        , "  operated packet at boundary: "
                            ++ show consumerErasedOperatedTypeAtBoundary
                        ]
                    )
              pure
                ( PacketConsumerEliminatedAtAmbientBound
                    constructionConsumerRef
                    ambientBound
                )
            refs ->
              missingConsumer
                [ "the eliminated consumer has multiple exact owners in ambient Gamma"
                , "  construction consumer: " ++ show constructionConsumerRef
                , "  ambient owners: " ++ show refs
                ]

        verifyConsumerErasedOperatedPacket projectAmbientBinders = do
          let projectAtBoundary =
                if projectAmbientBinders
                  then subtractAmbientLeadingBinders
                  else id
              operatedAtBoundary =
                projectAtBoundary
                  ( schemeToType
                      ( siScheme
                          ( subtermGeneralizationOperatedSchemeInfo
                              packet
                          )
                      )
                  )
          unless
            ( scopedTypesAgree scopeContext sourceTy operatedAtBoundary
                || isJust
                  ( certifiedSourceLambdaOperatedBody
                      projectAtBoundary
                      packet
                      operatedAtBoundary
                  )
                || isJust
                  ( certifiedCheckedBodyOperatedBody
                      projectAtBoundary
                      packet
                      operatedAtBoundary
                  )
            )
            ( missingConsumer
                [ "the recursively checked source is not the consumer-erased operated packet"
                , "  source type: " ++ show sourceTy
                , "  operated type at boundary: "
                    ++ show operatedAtBoundary
                ]
            )

        consumerErasedOperatedTypeAtBoundary =
          subtractAmbientLeadingBinders
            ( schemeToType
                ( siScheme
                    (subtermGeneralizationOperatedSchemeInfo packet)
                )
            )

        -- The operated packet can retain arrow/declaration prefixes owned by
        -- enclosing lambdas.  Once the recursively checked child publishes an
        -- owner-final construction, that exact endpoint is the completed tail
        -- against which an omitted ambient consumer is discharged.
        consumerErasedOperatedConstructionEndpoint =
          fromMaybe
            consumerErasedOperatedTypeAtBoundary
            ( certifiedSourceLambdaOperatedBody
                subtractAmbientLeadingBinders
                packet
                consumerErasedOperatedTypeAtBoundary
                <|> certifiedCheckedBodyOperatedBody
                  subtractAmbientLeadingBinders
                  packet
                  consumerErasedOperatedTypeAtBoundary
            )

        completedOperatedPacketOwnsAmbientBound ambientBound =
          constructsAmbientBound
            consumerErasedOperatedConstructionEndpoint
            ambientBound
            && constructsAmbientBound sourceTy ambientBound

        constructsAmbientBound sourceEndpoint ambientBound =
          scopedTypesAgree scopeContext sourceEndpoint ambientBound
            || isJust
              ( planExactBinderSpine
                  operationalEndpointTypesAgree
                  sourceEndpoint
                  ambientBound
              )

        -- Compare completed and current packets after projecting binders that
        -- construction no longer owns locally: either Eq-Free removes a
        -- vacuous quantifier, or the exact same declaration and bound already
        -- live in ambient Gamma.  Source-owned binders are never projected.
        -- Process from right to left because removing an inner vacuous binder
        -- can make an enclosing construction binder vacuous as well.
        projectConstructionBindersForConsumerComparison
          consumerRef
          completedInfo
          currentScheme =
          project (schemeBinderRefs completedScheme)
          where
            completedScheme = siScheme completedInfo
            sourceRefs =
              IntMap.elems (siSourceBinderOrderRefs completedInfo)
            constructionRefs =
              IntMap.elems
                (siConstructionBinderOrderRefs completedInfo)

            project [] = []
            project (binder@(ref, mbBound) : binders) =
              let retainedBinders = project binders
                  retainedType =
                    schemeToType
                      ( mkElabSchemeWithRefs
                          retainedBinders
                          (schemeBody completedScheme)
                      )
                  constructionOwned =
                    any
                      (typeBinderRefsSameIdentity ref)
                      constructionRefs
                  sourceOwned =
                    any (typeBinderRefsSameIdentity ref) sourceRefs
                  vacuous =
                    not
                      ( any
                          (typeBinderRefsSameIdentity ref)
                          (freeTypeVarRefsType retainedType)
                      )
                  ambientOwnsDeclaration =
                    constructionOwned
                      && not sourceOwned
                      && not
                        ( any
                            (typeBinderRefsSameIdentity ref . fst)
                            (schemeBinderRefs currentScheme)
                        )
                      && envOwnsExactTypeBinderRef enclosingEnv ref
                      && any
                        ( \(ambientRef, ambientBound) ->
                            typeBinderRefsSameIdentity ref ambientRef
                              && scopedTypesAgree
                                scopeContext
                                (maybe TBottom tyToElab mbBound)
                                ambientBound
                        )
                        (Map.toList (envTypeBindings enclosingEnv))
               in if
                    typeBinderRefsSameIdentity ref consumerRef
                      || ( constructionOwned
                            && not sourceOwned
                            && vacuous
                         )
                      || ambientOwnsDeclaration
                    then retainedBinders
                    else binder : retainedBinders

        missingConsumer :: [String] -> Either ElabError a
        missingConsumer details =
          Left
            ( ValidationFailed
                ( [ "packet-owned local Gamma has no construction binder or valid elimination proof"
                  , "  edge: " ++ show bodyEdge
                  , "  consumer: " ++ show consumerIdentity
                  , "  scheme: " ++ show (siScheme schemeInfo)
                  , "  scheme substitution: " ++ show (schemeInfoBinderRefSubst schemeInfo)
                  , "  packet scheme: " ++ show (siScheme (subtermGeneralizationSchemeInfo packet))
                  , "  packet consumer construction scheme: "
                      ++ show
                        ( siScheme
                            ( subtermGeneralizationConsumerConstructionSchemeInfo
                                packet
                            )
                        )
                  , "  packet operated scheme: "
                      ++ show
                        ( siScheme
                            (subtermGeneralizationOperatedSchemeInfo packet)
                        )
                  , "  packet Gamma bound scheme: "
                      ++ show (subtermGeneralizationGammaBoundScheme packet)
                  , "  packet substitution: "
                      ++ show
                        ( schemeInfoBinderRefSubst
                            (subtermGeneralizationSchemeInfo packet)
                        )
                  , "  packet source binder order: "
                      ++ show
                        ( siSourceBinderOrderRefs
                            (subtermGeneralizationSchemeInfo packet)
                        )
                  , "  packet construction binder order: "
                      ++ show
                        ( siConstructionBinderOrderRefs
                            (subtermGeneralizationSchemeInfo packet)
                        )
                  , "  construction consumer refs: " ++ show constructionConsumerRefs
                  , "  enclosing free binders: " ++ show enclosingFreeBinderRefs
                  , "  enclosing consumer bindings: "
                      ++ show
                        [ (ref, bound)
                        | (ref, bound) <- Map.toList (envTypeBindings enclosingEnv)
                        , any
                            (typeBinderRefsSameIdentity ref)
                            constructionConsumerRefs
                        ]
                  , "  source-refined Gamma bounds: "
                      ++ show
                        [ (ref, bound)
                        | (ref, bound) <-
                            Map.toList
                              (envSourceRefinedGammaBounds enclosingEnv)
                        , any
                            (typeBinderRefsSameIdentity ref)
                            constructionConsumerRefs
                        ]
                  , "  enclosing construction aliases: "
                      ++ show (envConstructionGammaAliases enclosingEnv)
                  , "  constructed source: " ++ show sourceTy
                  , "  packet Gamma authority: "
                      ++ show (subtermGeneralizationGammaAuthority packet)
                  , "  packet consumer authority: "
                      ++ show (subtermGeneralizationConsumerAuthority packet)
                  ]
                    ++ details
                )
            )

    uniqueIdentityRefs = foldr insertUnique []
      where
        insertUnique ref refs
          | any (typeBinderRefsSameIdentity ref) refs = refs
          | otherwise = ref : refs

    EnvFreeTypeBinderRefs enclosingFreeBinderRefs =
      envFreeTypeBinderRefs enclosingEnv

-- | Complete a packet-local topology result, or validate that an enclosing
-- Gamma already owns the exact declaration after construction-environment
-- subtraction.  The packet authority alone is not enough to choose the
-- second case: the aligned scheme must retain the same identity free, and the
-- enclosing environment must contain one exact bound that the checked body
-- constructs, either directly or by consuming its complete unbounded forall
-- spine.
materializeLambdaLocalTopologyResultBound
  :: Env
  -> LocalGammaOwner
  -> EdgeId
  -> PreparedSubtermGeneralization
  -> ElabType
  -> SchemeInfo
  -> Either
      ElabError
      ( SchemeInfo
      , Maybe BodyConsumerBoundRefinementCertificate
      , Maybe AmbientTopologyResultConstructionCertificate
      )
materializeLambdaLocalTopologyResultBound enclosingEnv owner bodyEdge packet completedBound schemeInfo =
  case subtermGeneralizationLocalResultAuthority packet of
    Nothing -> pure (schemeInfo, Nothing, Nothing)
    Just authority
      | not (null localDeclarations) ->
          materializeLocalDeclaration
      | any
          (\freeRef -> any (typeBinderRefsSameIdentity freeRef) resultRefs)
          (freeTypeVarRefsType (schemeToType (siScheme schemeInfo))) ->
          case ambientDeclarations of
            [(ambientRef, ambientBound)]
              | operationalEndpointTypesAgree ambientBound completedBound ->
                  pure (schemeInfo, Nothing, Nothing)
              | TVarRef completedRef <- completedBound
              , typeBinderRefsSameIdentity completedRef ambientRef ->
                  pure (schemeInfo, Nothing, Nothing)
              | isJust
                  ( constructExactInstantiation
                      (typeCheckEnvFrom enclosingEnv)
                      operationalEndpointTypesAgree
                      ambientBound
                      completedBound
                  ) -> do
                  refinement <-
                    certifyAmbientTopologyResultBoundRefinement
                      (typeCheckEnvFrom enclosingEnv)
                      owner
                      bodyEdge
                      packet
                      ambientRef
                      ambientBound
                      completedBound
                  pure (schemeInfo, Just refinement, Nothing)
              | completeUnboundedForallSpecializesTo
                  completedBound
                  ambientBound
              , Just specialization <-
                  constructExactInstantiation
                    (typeCheckEnvFrom enclosingEnv)
                    operationalEndpointTypesAgree
                    completedBound
                    ambientBound ->
                  pure
                    ( schemeInfo
                    , Nothing
                    , Just
                        AmbientTopologyResultConstructionCertificate
                          { atrcOwner = owner
                          , atrcBodyEdge = bodyEdge
                          , atrcResultRef = ambientRef
                          , atrcSourceType = completedBound
                          , atrcResultBound = ambientBound
                          , atrcInstantiation = specialization
                          }
                    )
            declarations ->
              Left
                ( ValidationFailed
                    [ "local topology result was generalized without one exact enclosing declaration"
                    , "  owner: " ++ show owner
                    , "  body edge: " ++ show bodyEdge
                    , "  result refs: " ++ show resultRefs
                    , "  checked body: " ++ show completedBound
                    , "  enclosing declarations: " ++ show declarations
                    , "  construction scheme: "
                        ++ show (siScheme schemeInfo)
                    ]
                )
      | otherwise ->
          materializeLocalDeclaration
      where
        materializeLocalDeclaration = do
          (materializedSchemeInfo, refinement) <-
            materializeLocalTopologyResultBound
              owner
              bodyEdge
              packet
              completedBound
              schemeInfo
          pure (materializedSchemeInfo, refinement, Nothing)

        consumerIdentity = scaConsumerIdentity authority
        directRef =
          typeBinderRefFromIdentity
            consumerIdentity
            (typeBinderIdentityStableName consumerIdentity)
        routedRef = do
          node <- typeBinderRefNode directRef
          IntMap.lookup
            (getNodeId node)
            (schemeInfoBinderRefSubst schemeInfo)
        resultRefs =
          distinctBinderRefs (directRef : maybeToList routedRef)
        localDeclarations =
          [ binder
          | binder@(ref, _) <- schemeBinderRefs (siScheme schemeInfo)
          , any (typeBinderRefsSameIdentity ref) resultRefs
          ]
        ambientDeclarations =
          [ (ref, bound)
          | (ref, bound) <- Map.toList (envTypeBindings enclosingEnv)
          , any (typeBinderRefsSameIdentity ref) resultRefs
          ]

-- | Select the one packet whose recorded consumer is owned by this exact
-- lambda-body construction.  Edge equality alone is insufficient: a nested
-- recursive helper can expose a descendant packet at its parent's body while
-- retaining the descendant lambda as its lexical owner.  Conversely, owner
-- equality alone can select a different edge of the same lambda.  Require both
-- pieces of identity-bearing authority before expected-endpoint selection or
-- a terminal Hyp may use the packet.
selectExactLambdaBodyPacket
  :: LocalGammaOwner
  -> EdgeId
  -> [Maybe PreparedSubtermGeneralization]
  -> Either ElabError (Maybe PreparedSubtermGeneralization)
selectExactLambdaBodyPacket owner edgeId candidatePackets =
  case
      selectUniqueCandidateBy
        (==)
        (filter ownsExactBodyConstruction (catMaybes candidatePackets))
    of
      NoCandidateSelection -> pure Nothing
      UniqueCandidateSelection packet -> pure (Just packet)
      AmbiguousCandidateSelection ->
        Left
          ( ValidationFailed
              [ "lambda body has multiple exact construction packets"
              , "  owner: " ++ show owner
              , "  edge: " ++ show edgeId
              ]
          )
  where
    ownsExactBodyConstruction packet =
      case subtermGeneralizationConsumerAuthority packet of
        Just authority ->
          scaEdgeId authority == edgeId
            && subtermConsumerAuthorityEnclosingOwner authority == Just owner
        Nothing -> False

-- | Identity-bearing evidence that an application constructs the declared
-- bound of an active packet consumer.  Keep the ref and bound together: the
-- ref routes the enclosing Hyp, while the bound is the application's exact
-- result endpoint before that Hyp is emitted.
data ActiveApplicationConsumerAuthority = ActiveApplicationConsumerAuthority
  { activeApplicationConsumerRef :: TypeBinderRef,
    activeApplicationConsumerBound :: ElabType
  }
  deriving (Show)

-- | Prove that an application is the exact source boundary for the completed
-- bound of an active packet-owned Gamma consumer.  Figure 15.3.5 constructs
-- that bound as @Lambda(Gamma_g)(a1 a2)@ before the enclosing edge discharges
-- the consumer with Hyp.  The returned certificate is deliberately not a
-- graph target: its ref routes the later Hyp and its declared bound determines
-- the application result by construction.
--
-- The exact lexical owner and either the completed packet scheme or its
-- already-open ambient bound are the authority for this choice.  The complete
-- scheme case is the boundary that will emit the binder itself; the bound case
-- requires that binder to be ambient already.  In particular, nested
-- application children merely inherit the active packet; their different
-- expected endpoint cannot select this target.
activeApplicationConsumerSchemeAuthority
  :: ScopeContext p
  -> Env
  -> NodeRef
  -> Either ElabError (Maybe ActiveApplicationConsumerAuthority)
activeApplicationConsumerSchemeAuthority scopeContext env applicationScope =
  case
      ( envActiveSubtermConstruction env
      , envExpectedTermEndpoint env >>= exactConstructionExpectedType
      )
    of
    (Just packet, Just expectedTy)
      | activeConsumerOwnsConstruction packet applicationScope
      , Just graphRef <- subtermGeneralizationResultAbstractionRef packet ->
          let constructionRenames = envConstructionBinderRenames env
              constructionRefs =
                uniqueIdentityRefs
                  ( map
                      (applyRefRenames constructionRenames)
                      ( graphRef
                          : maybeToList
                            (subtermGeneralizationConstructionResultAbstractionRef packet)
                      )
                  )
              completedPacketInfo =
                completeLambdaParamBoundarySchemeInfo
                  (envLambdaParamBoundaryCertificates env)
                  ( applySchemeInfoRefRenames
                      constructionRenames
                      (subtermGeneralizationSchemeInfo packet)
                  )
              completedPacketTy =
                schemeToType (siScheme completedPacketInfo)
              expectedIsCompletedPacket =
                scopedEndpointTypesAgree
                  scopeContext
                  expectedTy
                  completedPacketTy
              ambientRefs = envGeneralizationAmbientTypeBinderRefs env
              matchingConsumerBinders =
                [ (constructionRef, constructionBound)
                | (constructionRef, Just packetBound) <-
                    schemeBinderRefs (siScheme completedPacketInfo)
                , any
                    (typeBinderRefsSameIdentity constructionRef)
                    constructionRefs
                , let packetBoundTy = tyToElab packetBound
                      constructionBound =
                        case
                            find
                              ( typeBinderRefsSameIdentity constructionRef
                                  . fst
                              )
                              (Map.toList (envSourceRefinedGammaBounds env))
                          of
                            Just (_, refinedBound)
                              | isExactSchemeProjection
                                  refinedBound
                                  packetBoundTy ->
                                  refinedBound
                            _ ->
                              case
                                  find
                                    ( typeBinderRefsSameIdentity
                                        constructionRef
                                        . fst
                                    )
                                    (Map.toList (envTypeBindings env))
                                of
                                  Just (_, completedBound)
                                    | completedBound /= TBottom ->
                                      -- The exact parameter boundary has
                                      -- already completed this packet-owned
                                      -- declaration in the construction
                                      -- environment.  Retain that complete
                                      -- bound before selecting the
                                      -- application's endpoint; replaying the
                                      -- packet's opened instance would emit
                                      -- an extra InstApp before Hyp.
                                      completedBound
                                  _ -> packetBoundTy
                , envOwnsExactEndpointType env constructionBound
                , expectedIsCompletedPacket
                    || scopedEndpointTypesAgree
                      scopeContext
                      expectedTy
                      constructionBound
                , expectedIsCompletedPacket
                    || any
                      (typeBinderRefsSameIdentity constructionRef)
                      ambientRefs
                ]
           in case matchingConsumerBinders of
                (constructionRef, constructionBound) : rest
                  | all
                      ( \(otherRef, otherBound) ->
                          typeBinderRefsSameIdentity constructionRef otherRef
                            && scopedEndpointTypesAgree
                              scopeContext
                              constructionBound
                              otherBound
                      )
                      rest ->
                      -- This exact packet binder is only an ownership
                      -- certificate.  Its quotient representative is routing
                      -- data for the enclosing Hyp, not the application node
                      -- to generalize.  Returning the identity-bearing ref
                      -- prevents the application boundary from selecting or
                      -- emitting a canonical representative by accident.
                      pure
                        ( Just
                            ActiveApplicationConsumerAuthority
                              { activeApplicationConsumerRef = constructionRef,
                                activeApplicationConsumerBound = constructionBound
                              }
                        )
                _ -> pure Nothing
    _ -> pure Nothing
  where
    -- Packet-owned Gamma has the strongest lexical owner.  In its absence,
    -- only the two consumer authorities that construct their own result
    -- endpoint may select S': topology carries an exact local owner, while a
    -- root consumer is scoped by the active construction environment itself.
    activeConsumerOwnsConstruction packet scope =
      case subtermGeneralizationGammaAuthority packet of
        -- The active environment carries this packet only along the recursive
        -- source-construction path.  The Gamma certificate itself is the
        -- authority; its owner gen names where the pending slot was created,
        -- not necessarily the descendant application gen that fills it.
        Just _ -> True
        Nothing ->
          case subtermGeneralizationConsumerAuthority packet of
            Just authority
              | subtermConsumerAuthorityIsTopology authority ->
                  maybe
                    False
                    ((== scope) . localGammaOwnerScope)
                    (subtermConsumerAuthorityEnclosingOwner authority)
              | subtermConsumerAuthorityIsRootGamma authority -> True
            _ -> False

    uniqueIdentityRefs = foldr insertUnique []
      where
        insertUnique ref refs
          | any (typeBinderRefsSameIdentity ref) refs = refs
          | otherwise = ref : refs

consumerBoundOwnership
  :: Env
  -> LocalGammaOwner
  -> PreparedSubtermGeneralization
  -> EdgeId
  -> TypeBinderIdentity
  -> ElabType
  -> SchemeInfo
  -> Either ElabError ConsumerBoundOwnership
consumerBoundOwnership enclosingEnv owner packet bodyEdge consumerIdentity sourceTy schemeInfo =
  case subtermGeneralizationConsumerAuthority packet of
    Nothing -> missingOwner
    Just authority
      | scaConsumerIdentity authority /= consumerIdentity ->
          Left
            ( ValidationFailed
                [ "prepared lambda packet consumer authority changed identity"
                , "  packet consumer: " ++ show consumerIdentity
                , "  authority consumer: " ++ show (scaConsumerIdentity authority)
                ]
            )
      | Just enclosingOwner <-
          subtermConsumerAuthorityEnclosingOwner authority ->
          if subtermConsumerAuthorityIsTopology authority
            then topologyOwnership
            else
              case
                  subtermGeneralizationLocalConsumerClosure
                    (envLocalGammaClosures enclosingEnv)
                    packet
                of
                  Just closure
                    | enclosingOwner == lgcOwner closure ->
                        case lgcOwnerPendingScheme closure of
                          Nothing
                            | owner == enclosingOwner ->
                                -- A closure without a pending owner scheme is
                                -- the ordinary syntactic-owner lane.  The
                                -- current lambda must construct that Gamma
                                -- through its local/required planner;
                                -- classifying it as ambient would demand a
                                -- declaration that no enclosing construction
                                -- has opened.
                                packetOwnership
                            | otherwise -> enclosingClosureOwnership
                          Just _ -> enclosingClosureOwnership
                  _ -> missingOwner
      | subtermConsumerAuthorityIsRootGamma authority ->
          rootGammaOwnership
      | scaEdgeId authority == bodyEdge
      , subtermGeneralizationOwnsGammaForEdge bodyEdge packet ->
          packetOwnership
      | otherwise -> missingOwner
  where
    localCandidates =
      schemeConsumerBinderCandidates consumerIdentity schemeInfo
    directConsumerRef =
      typeBinderRefFromIdentity consumerIdentity "$consumer"
    packetOwnership =
      case localCandidates of
        [(localRef, _)] -> pure (ConsumerBoundOwnedLocally localRef)
        [] -> pure (ConsumerBoundOwnedByRequiredGamma bodyEdge)
        _ ->
          Left
            ( ValidationFailed
                [ "prepared lambda packet binds its consumer identity more than once"
                , "  consumer: " ++ show consumerIdentity
                , "  matches: " ++ show localCandidates
                ]
            )

    topologyOwnership =
      case localCandidates of
        [(localRef, _)] ->
          pure (ConsumerBoundOwnedLocally localRef)
        [] ->
          case exactAmbientTopologyConsumer of
            Just (ambientRef, ambientBound)
              | sourceConstructsAmbientBound ambientBound ->
                  pure
                    ( ConsumerBoundEliminatedAtAmbientBound
                        ambientRef
                        ambientBound
                    )
            _ ->
              Left
                ( ValidationFailed
                    [ "topology consumer has neither a local binder nor an exact ambient discharge"
                    , "  consumer: " ++ show consumerIdentity
                    , "  edge: " ++ show bodyEdge
                    , "  checked source: " ++ show sourceTy
                    , "  scheme: " ++ show (siScheme schemeInfo)
                    , "  scheme substitution: "
                        ++ show (schemeInfoBinderRefSubst schemeInfo)
                    , "  ambient candidates: "
                        ++ show ambientTopologyConsumerCandidates
                    ]
                )
        _ ->
          Left
            ( ValidationFailed
                [ "topology consumer occurs more than once in its prepared construction scheme"
                , "  consumer: " ++ show consumerIdentity
                , "  matches: " ++ show localCandidates
                ]
            )

    constructionConsumerRefs =
      schemeConsumerConstructionRefs consumerIdentity schemeInfo

    ambientTopologyConsumerCandidates =
      [ (ref, bound)
      | (ref, bound) <- Map.toList (envTypeBindings enclosingEnv)
      , any
          (typeBinderRefsSameIdentity ref)
          constructionConsumerRefs
      ]

    exactAmbientTopologyConsumer =
      case ambientTopologyConsumerCandidates of
        [] -> Nothing
        first@(firstRef, firstBound) : rest
          | all
              ( \(otherRef, otherBound) ->
                  typeBinderRefsSameIdentity firstRef otherRef
                    && operationalEndpointTypesAgree firstBound otherBound
              )
              rest ->
              Just first
        _ -> Nothing

    sourceConstructsAmbientBound ambientBound =
      operationalEndpointTypesAgree sourceTy ambientBound
        || isJust
          ( planExactBinderSpine
              operationalEndpointTypesAgree
              sourceTy
              ambientBound
          )
        || isJust
          ( constructExactInstantiation
              (typeCheckEnvFrom enclosingEnv)
              operationalEndpointTypesAgree
              sourceTy
              ambientBound
          )

    rootGammaOwnership =
      case localCandidates of
        [] ->
          pure (ConsumerBoundOwnedByRootGamma directConsumerRef)
        _ ->
          Left
            ( ValidationFailed
                [ "root-owned consumer unexpectedly occurs in its local construction scheme"
                , "  consumer: " ++ show consumerIdentity
                , "  matches: " ++ show localCandidates
                ]
            )

    enclosingClosureOwnership =
      let expectedBound =
            schemeToType
              (subtermGeneralizationGammaBoundScheme packet)
          enclosingRef =
            typeBinderRefFromIdentity
              consumerIdentity
              "$consumer"
       in pure
            ( ConsumerBoundOwnedByEnclosingGamma
                enclosingRef
                expectedBound
            )

    missingOwner =
      Left
        ( ValidationFailed
            [ "lambda consumer has neither a local, enclosing, nor required Gamma owner"
            , "  consumer: " ++ show consumerIdentity
            , "  body edge: " ++ show bodyEdge
            , "  owner: " ++ show owner
            , "  consumer authority: "
                ++ show (subtermGeneralizationConsumerAuthority packet)
            , "  body-edge closure: "
                ++ show
                  ( IntMap.lookup
                      (getEdgeId bodyEdge)
                      (envLocalGammaClosures enclosingEnv)
                  )
            ]
        )

-- | Select the outward identity owned by one Gamma construction.  Structural
-- self/result identities belong to their enclosing mu/forall reconstruction;
-- they can occur in a generalized substitution, but they are never the
-- flexible exterior introduced by Figure 15.3.5.  Likewise, a source identity
-- already free in a structured @S'(operated)@ is a dependency of the
-- exterior, not the exterior itself: choosing it would manufacture the
-- recursive declaration @alpha >= S'(operated)[alpha]@.  Preserve the frozen
-- graph exterior in both cases.  A bare operated variable remains the exact
-- identity-alias case described by RaiseMerge.
gammaConsumerRefForRoute
  :: RequiredGammaBinder
  -> TypeBinderRef
  -> TypeBinderRef
gammaConsumerRefForRoute requirement routedRef =
  if structuralIdentity || structuredBoundDependsOnRoutedRef
    then graphExteriorRef
    else routedRef
  where
    structuralIdentity =
      isJust
        (typeBinderIdentityStructural (typeBinderRefIdentity routedRef))

    structuredBoundDependsOnRoutedRef =
      case rgbOperatedType requirement of
        TVarRef _ -> False
        operatedType ->
          any
            (typeBinderRefsSameIdentity routedRef)
            (freeTypeVarRefsType operatedType)

    graphExteriorIdentity =
      typeBinderIdentityFromNode (rgbExteriorNode requirement)

    graphExteriorRef =
      typeBinderRefFromIdentity
        graphExteriorIdentity
        (typeBinderIdentityStableName graphExteriorIdentity)

-- | Retain every graph-local route named by an explicit Γ requirement.  The
-- generalized scheme can publish the result root under a different outward
-- binder, but Ω replay can still name either side of the terminal RaiseMerge.
-- The operated, exterior, and result routes are therefore one prepared Gamma
-- obligation and must enter scope together before either application child is
-- elaborated.
constructionGammaAliases
  :: (NodeId -> [NodeId])
  -> IntMap.IntMap TypeBinderRef
  -> GeneralizationRequirements
  -> ConstructionGammaPlan
  -> SchemeInfo
  -> Either ElabError ConstructionGammaAliases
constructionGammaAliases constructionRouteNodes constructionSourceRoutes requirements constructionPlan schemeInfo = do
  routedPairs <- concat <$> traverse aliasesFor requiredBinders
  routingAliases <- foldM insertAlias IntMap.empty routedPairs
  authorityPairs <- concat <$> traverse authorityAliasesFor requiredBinders
  authorityAliases <- foldM insertAlias IntMap.empty authorityPairs
  pure
    ConstructionGammaAliases
      { cgaRoutingAliases = routingAliases
      , cgaAuthorityAliases = authorityAliases
      }
  where
    requiredBinders = grRequiredGammaBinders requirements
    subst = schemeInfoBinderRefSubst schemeInfo
    constructionBinders = cgpBinders constructionPlan
    ambientAliases = cgpAmbientAliases constructionPlan

    aliasesFor requirement = do
      outwardRef <-
        case emittedExteriorRefs requirement of
          [] ->
            case ambientRequirementRefs requirement of
              [] -> preparedOutwardRef requirement
              [ambientRef] -> pure ambientRef
              ambientRefs ->
                Left
                  ( ValidationFailed
                      [ "construction Gamma requirement routes to multiple exact ambient declarations"
                      , "  requirement: " ++ show requirement
                      , "  ambient declarations: " ++ show ambientRefs
                      ]
                  )
          [emittedRef] -> pure emittedRef
          emittedRefs ->
            Left
              ( ValidationFailed
                  [ "construction Gamma emits one exterior under multiple binder identities"
                  , "  requirement: " ++ show requirement
                  , "  emitted binders: " ++ show emittedRefs
                  ]
              )
      pure
        (requirementRoutingAliasPairs requirement outwardRef)

    authorityAliasesFor requirement =
      case emittedExteriorRefs requirement of
        [emittedRef] ->
          pure (requirementAuthorityAliasPairs requirement emittedRef)
        [] ->
          case ambientRequirementRefs requirement of
            [ambientRef] ->
              pure (requirementAuthorityAliasPairs requirement ambientRef)
            [] -> pure []
            ambientRefs ->
              Left
                ( ValidationFailed
                    [ "construction Gamma authority has multiple exact ambient declarations"
                    , "  requirement: " ++ show requirement
                    , "  ambient declarations: " ++ show ambientRefs
                    ]
                )
        emittedRefs ->
          Left
            ( ValidationFailed
                [ "construction Gamma authority has multiple emitted exterior binders"
                , "  requirement: " ++ show requirement
                , "  emitted binders: " ++ show emittedRefs
                ]
            )

    requirementRoutingAliasPairs requirement outwardRef =
      filter
        ( \pair ->
            IntSet.notMember
              (fst pair)
              (structuredOperatedDependencyKeys requirement)
        )
        ( requirementAuthorityAliasPairs requirement outwardRef
            ++ [ (getNodeId operatedNode, outwardRef)
               | operatedRef <-
                  maybeToList (rgbExactOperatedOccurrenceRef requirement)
               , Just operatedNode <- [typeBinderRefNode operatedRef]
               ]
            ++ [ (getNodeId sourceNode, outwardRef)
               | routeNode <- requirementRouteNodes requirement
               , Just sourceRef <-
                  [ IntMap.lookup
                      (getNodeId routeNode)
                      constructionSourceRoutes
                  ]
               , Just sourceNode <- [typeBinderRefNode sourceRef]
               ]
            ++ [ (getNodeId operatedNode, outwardRef)
               | operatedRef <-
                  freeTypeVarRefsType (rgbOperatedType requirement)
               , any
                  (typeBinderRefsSameIdentity operatedRef)
                  (IntMap.elems constructionSourceRoutes)
               , Just operatedNode <- [typeBinderRefNode operatedRef]
               ]
        )

    -- A structured S'(operated) may mention graph variables that are
    -- dependencies of the flexible exterior.  Routing one of those nodes to
    -- the exterior would construct an illegal self-bound and collapse two
    -- declarations (for example @forall f. forall c > f Int. ...@ into two
    -- declarations of @c@).  The separate authority map still retains the
    -- requirement topology; only the occurrence-routing map excludes these
    -- dependency nodes.  A bare variable endpoint remains the exact consumer
    -- capability and is routed normally.
    structuredOperatedDependencyKeys requirement =
      case rgbOperatedType requirement of
        TVarRef _ -> IntSet.empty
        operatedType ->
          IntSet.fromList
            [ getNodeId node
            | ref <- freeTypeVarRefsType operatedType
            , Just node <- [typeBinderRefNode ref]
            ]

    requirementAuthorityAliasPairs requirement outwardRef =
      [ (getNodeId node, outwardRef)
      | directNode <- directRequirementNodes requirement
      , node <- directNode : constructionRouteNodes directNode
      ]

    requirementRouteNodes requirement =
      concatMap
        (\directNode -> directNode : constructionRouteNodes directNode)
        (directRequirementNodes requirement)

    directRequirementNodes requirement =
      rgbOperatedRoot requirement
        : rgbExteriorNode requirement
        : NonEmpty.toList (rgbResultRoots requirement)

    preparedOutwardRef requirement =
      case
          foldr
            (\resultRoot fallback ->
              IntMap.lookup (getNodeId resultRoot) subst <|> fallback
            )
            (IntMap.lookup (getNodeId (rgbExteriorNode requirement)) subst)
            (rgbResultRoots requirement)
        of
          Just ref -> pure (gammaConsumerRefForRoute requirement ref)
          Nothing ->
            Left
              ( ValidationFailed
                  [ "construction Γ aliases have no prepared outward binder"
                  , "  requirement: " ++ show requirement
                  , "  substitution: " ++ show subst
                  , "  ambient routes: " ++ show ambientAliases
                  ]
              )

    ambientRequirementRefs requirement =
      foldr insertDistinctRef []
        [ ambientRef
        | node <-
            rgbOperatedRoot requirement
              : rgbExteriorNode requirement
              : NonEmpty.toList (rgbResultRoots requirement)
        , Just ambientRef <-
            [IntMap.lookup (getNodeId node) ambientAliases]
        ]

    emittedExteriorRefs requirement =
      foldr insertDistinctRef []
        [ ref
        | (ref, _) <- constructionBinders
        , typeBinderRefNode ref == Just (rgbExteriorNode requirement)
        ]

    insertDistinctRef ref refs
      | any (typeBinderRefsSameIdentity ref) refs = refs
      | otherwise = ref : refs

    insertAlias aliases (nodeKey, outwardRef) =
      case IntMap.lookup nodeKey aliases of
        Nothing -> pure (IntMap.insert nodeKey outwardRef aliases)
        Just existing
          | typeBinderRefsSameIdentity existing outwardRef -> pure aliases
          | otherwise ->
              Left
                ( ValidationFailed
                    [ "construction Γ routes disagree on their outward binder"
                    , "  graph node: " ++ show (NodeId nodeKey)
                    , "  first binder: " ++ show existing
                    , "  second binder: " ++ show outwardRef
                    ]
                )

-- | Carry only the aliases whose outward identity is published by this
-- scheme, replacing their presentation with the scheme's authoritative ref.
-- A surrounding let construction can contain aliases for sibling packets;
-- those are intentionally left with their owners.
alignConstructionAliasesToScheme
  :: IntMap.IntMap TypeBinderRef
  -> SchemeInfo
  -> Either ElabError (IntMap.IntMap TypeBinderRef)
alignConstructionAliasesToScheme aliases schemeInfo =
  foldM alignOne (schemeInfoBinderRefSubst schemeInfo) (IntMap.toList aliases)
  where
    schemeRefs = map fst (schemeBinderRefs (siScheme schemeInfo))
    substitutionRefs = IntMap.elems (schemeInfoBinderRefSubst schemeInfo)
    authoritativeRefs = schemeRefs ++ substitutionRefs

    alignOne subst (nodeKey, aliasRef) =
      case filter (typeBinderRefsSameIdentity aliasRef) authoritativeRefs of
        [] -> pure subst
        schemeRef : _ ->
          case IntMap.lookup nodeKey subst of
            Nothing -> pure (IntMap.insert nodeKey schemeRef subst)
            Just existing
              | typeBinderRefsSameIdentity existing schemeRef -> pure subst
              | otherwise ->
                  Left
                    ( ValidationFailed
                        [ "construction Gamma alias conflicts with the exact owner substitution"
                        , "  graph node: " ++ show (NodeId nodeKey)
                        , "  existing ref: " ++ show existing
                        , "  exact owner ref: " ++ show schemeRef
                        ]
                    )

-- | Select the edge-local RaiseMerge authorities that actually belong to the
-- current application's Γ.  The frozen binding tree owns placement: ordinary
-- named nodes are direct flexible children of the gen, while the structural-
-- recursive extension can retain the exterior below an entirely flexible
-- mu/alias shell.  In both cases the nearest gen owns the Hyp binder.
applicationRequirementEdges
  :: ScopeContext p
  -> EdgeArtifacts
  -> IntMap.IntMap ElabType
  -> SubtermGeneralizations
  -> (AnnExpr -> Either ElabError (Maybe SchemeInfo))
  -> EdgeId
  -> NodeId
  -> AnnExpr
  -> Either ElabError [(EdgeId, Maybe RootEdgeExactEndpoint)]
applicationRequirementEdges scopeContext edgeArtifacts exactProducerTypes subtermPackets sourceSchemeFor boundaryEdge applicationNode applicationAnn = do
  applicationScope <-
    scopeRootForBoundary scopeContext boundaryEdge applicationNode
  ownedRequirementEdgesForOwnerWithSources
    scopeContext
    edgeArtifacts
    exactProducerTypes
    subtermPackets
    sourceSchemeFor
    ( LocalGammaOwner
        { lgoConstructor = LocalApplicationGamma,
          lgoBoundaryEdge = boundaryEdge,
          lgoTermNode = applicationNode,
          lgoScope = applicationScope
        }
    )
    applicationAnn

-- | Select application obligations together with the source expression that
-- produced each edge.  A source scheme recovered from resolved identities is
-- authoritative when the frozen expansion root is an occurrence variable,
-- including one whose graph-local lower bound has already been installed: it
-- is the bottom-up @S'(operated)@ used to construct the
-- root-RaiseMerge Gamma binder, not a later transport repair.
ownedRequirementEdgesForOwnerWithSources
  :: ScopeContext p
  -> EdgeArtifacts
  -> IntMap.IntMap ElabType
  -> SubtermGeneralizations
  -> (AnnExpr -> Either ElabError (Maybe SchemeInfo))
  -> LocalGammaOwner
  -> AnnExpr
  -> Either ElabError [(EdgeId, Maybe RootEdgeExactEndpoint)]
ownedRequirementEdgesForOwnerWithSources scopeContext edgeArtifacts exactProducerTypes subtermPackets sourceSchemeFor owner ann = do
  ownedSources <-
    localOwnerInstantiationEdgeSources
      scopeContext
      edgeArtifacts
      subtermPackets
      owner
      ann
  owned <-
    requirementEdgesForSources
      scopeContext
      edgeArtifacts
      exactProducerTypes
      sourceSchemeFor
      ownedSources
  pure
    ( IntMap.elems
        ( IntMap.fromList
            [ (getEdgeId edgeId, requirement)
            | requirement@(edgeId, _) <- owned
            ]
        )
    )

-- | Attach the exact operated endpoint, when source construction is the only
-- authority that can provide it, without making any ownership decision for
-- the edge.  Local-owner selection and edge-local Figure 15.3.5 preparation
-- deliberately share this projection so they cannot disagree about
-- @S'(operated)@ while retaining distinct placement proofs.
requirementEdgesForSources
  :: ScopeContext p
  -> EdgeArtifacts
  -> IntMap.IntMap ElabType
  -> (AnnExpr -> Either ElabError (Maybe SchemeInfo))
  -> [(EdgeId, AnnExpr)]
  -> Either ElabError [(EdgeId, Maybe RootEdgeExactEndpoint)]
requirementEdgesForSources scopeContext edgeArtifacts exactProducerTypes sourceSchemeFor =
  traverse edgeRequirement
  where
    edgeRequirement (edgeId, sourceAnn) = do
      sourceType <- sourceTypeForOperatedOccurrence edgeId sourceAnn
      pure
        ( edgeId
        , case sourceType of
            Just exactOperatedType ->
              Just (RootEdgeExactOperated exactOperatedType)
            Nothing ->
              RootEdgeExactProducer
                <$> IntMap.lookup (getEdgeId edgeId) exactProducerTypes
        )

    sourceTypeForOperatedOccurrence edgeId sourceAnn = do
      authority <- rootRaiseMergeAuthorityFor edgeArtifacts edgeId
      case authority of
        Just rootAuthority
          | frozenOperatedRootIsOccurrence rootAuthority ->
              fmap (schemeToType . siScheme) <$> sourceSchemeFor sourceAnn
        _ -> pure Nothing

    -- A resolved producer scheme is the exact type constructed by an
    -- occurrence variable, even when constraint generation has already put a
    -- graph-local lower bound on that occurrence.  The lower bound can retain
    -- flexible/structural graph aliases that are semantically equivalent but
    -- are not the xMLF endpoint accepted by Inst-Hyp.  Carry the checked
    -- source scheme into Gamma construction so the Hyp is well-typed by
    -- construction.  A structural root (arrow, forall, mu, ...) remains its
    -- own S'(operated) authority and must not be replaced by an enclosing
    -- source scheme.
    frozenOperatedRootIsOccurrence rootAuthority =
      case
          lookupNodeIn
            (cNodes (gaBaseConstraint (scGaParents scopeContext)))
            (rrmaOperatedRoot rootAuthority)
        of
          Just TyVar {} -> True
          _ -> False

-- | Select the ordinary Gamma_g edge set owned by one exact source
-- constructor.  The shared typed selector reserves sources named directly by
-- an AApp frame for its edge-local lane; every remaining edge uses the nearest
-- constructor whose frozen scope flexibly owns the exterior.  Scope equality
-- alone is insufficient because nested lambda/application/let nodes may share
-- one gen while constructing distinct local Gammas.
localOwnerInstantiationEdgeSources
  :: ScopeContext p
  -> EdgeArtifacts
  -> SubtermGeneralizations
  -> LocalGammaOwner
  -> AnnExpr
  -> Either ElabError [(EdgeId, AnnExpr)]
localOwnerInstantiationEdgeSources scopeContext edgeArtifacts subtermPackets expectedOwner ann = do
  directApplicationOwners <-
    localGammaDirectApplicationEdgeOwners
      (scopeRootForBoundary scopeContext)
      ann
  preparedEnclosingOwners <-
    localGammaPreparedEnclosingEdgeOwners
      (Map.elems subtermPackets)
  go directApplicationOwners preparedEnclosingOwners [] ann
  where
    go directApplicationOwners preparedEnclosingOwners localOwners expr = do
      frame <-
        localGammaFrame
          (scopeRootForBoundary scopeContext)
          expr
      let localOwners' =
            maybe localOwners (: localOwners) (lgfOwner frame)
      direct <-
        fmap concat
          ( traverse
              ( claimedBy
                  directApplicationOwners
                  preparedEnclosingOwners
                  localOwners'
              )
              (lgfDirectEdgeSources frame)
          )
      descendants <-
        fmap concat
          ( traverse
              (go directApplicationOwners preparedEnclosingOwners localOwners')
              (lgfChildren frame)
          )
      pure (direct ++ descendants)

    claimedBy directApplicationOwners preparedEnclosingOwners localOwners edgeSource@(edgeId, _) = do
      authority <- rootRaiseMergeAuthorityFor edgeArtifacts edgeId
      case authority of
        Nothing -> pure []
        Just rootAuthority -> do
          ownership <-
            selectLocalGammaEdgeOwnership
              directApplicationOwners
              preparedEnclosingOwners
              edgeId
              localOwners
              (ownsExterior rootAuthority)
          pure
            [ edgeSource
            | owner <-
                case ownership of
                  Just (PreparedEnclosingEdgeOwnership owner) -> [owner]
                  Just (FlexibleExteriorEdgeOwnership owner) -> [owner]
                  _ -> []
            , owner == expectedOwner
            ]

    ownsExterior rootAuthority owner =
      rootRaiseMergeExteriorOwnedByScope
        (scGaParents scopeContext)
        (localGammaOwnerScope owner)
        (rrmaExterior rootAuthority)

ownedRequirementEdgesForOwner
  :: ScopeContext p
  -> EdgeArtifacts
  -> IntMap.IntMap ElabType
  -> SubtermGeneralizations
  -> LocalGammaOwner
  -> AnnExpr
  -> Either ElabError [(EdgeId, Maybe ElabType)]
ownedRequirementEdgesForOwner scopeContext edgeArtifacts exactProducerTypes subtermPackets owner ann = do
  ownedSources <-
    localOwnerInstantiationEdgeSources
      scopeContext
      edgeArtifacts
      subtermPackets
      owner
      ann
  pure
    ( IntMap.elems
        ( IntMap.fromList
            [ ( getEdgeId edgeId,
                ( edgeId,
                  IntMap.lookup (getEdgeId edgeId) exactProducerTypes
                )
              )
            | (edgeId, _) <- ownedSources
            ]
        )
    )

-- | The declaration state published by one zero-local application
-- requirement.  A descendant refinement temporarily advances an enclosing
-- declaration while its checked child is constructed.  The application must
-- therefore choose, as one value, both the declaration bound it relies on and
-- the operated endpoint it publishes:
--
-- * a completed declaration that exactly constructs the graph endpoint, or
-- * the pending enclosing declaration whose exact instantiation is the
--   completed child endpoint.
--
-- Keeping the pair private prevents a caller from combining the completed
-- child bound with the pending owner's polymorphic operated endpoint.
data DirectAmbientRequirementState =
  DirectAmbientRequirementState
    { darsDeclarationBound :: !ElabType
    , darsOperatedType :: !ElabType
    }

-- | Publish direct-edge ownership only after the application has constructed
-- and typechecked its complete Gamma.  The annotated application frame is the
-- occurrence authority for the edge set; the typed requirement supplies the
-- exact exterior/operated/result routes; and the final construction supplies
-- either the one local binder identity reached by every route or the one
-- pre-existing ambient identity/bound selected by its authority aliases.
--
-- Keeping this as a checked constructor prevents a later root planner from
-- turning "this application has some local binder" into ownership of an
-- unrelated or only partially overlapping requirement.
buildDirectApplicationGammaClaims
  :: ScopeContext p
  -> LocalGammaOwner
  -> AnnExpr
  -> [RequiredGammaBinder]
  -> [RequiredGammaBinder]
  -> [(EdgeId, Maybe ElabType)]
  -> [(TypeBinderRef, Maybe BoundType)]
  -> IntMap.IntMap TypeBinderRef
  -> IntMap.IntMap TypeBinderRef
  -> IntMap.IntMap TypeBinderRef
  -> [BodyConsumerBoundRefinementCertificate]
  -> [LambdaParamBoundaryCertificate]
  -> [AmbientGammaAuthority]
  -> Map.Map TypeBinderRef ElabType
  -> EnvFreeTypeBinderRefs
  -> Either
      ElabError
      ( NonEmpty EdgeId,
        [DirectApplicationGammaClaim],
        [DirectApplicationAmbientGammaClaim]
      )
buildDirectApplicationGammaClaims scopeContext owner ann ownerRequirements requirements directConstructionEndpoints constructionBinders routes sourceBinderRefs ambientRoutes bodyConsumerBoundRefinements paramBoundaryCertificates childAmbientDeclarations ambientBindings (EnvFreeTypeBinderRefs ambientFreeRefs) = do
  frame <-
    localGammaFrame
      (scopeRootForBoundary scopeContext)
      ann
  unless
    (lgfOwner frame == Just owner)
    ( claimFailure
        [ "annotated application frame disagrees with the certificate owner"
        , "  frame owner: " ++ show (lgfOwner frame)
        ]
    )
  unless
    (lgoConstructor owner == LocalApplicationGamma)
    (claimFailure ["certificate owner is not an application"])
  directSourceEdges <-
    case NonEmpty.nonEmpty (map fst (lgfDirectEdgeSources frame)) of
      Just edgeIds -> pure edgeIds
      Nothing ->
        claimFailure
          ["application frame has no direct source edge"]
  let directEdgeKeys =
        IntSet.fromList
          (map getEdgeId (NonEmpty.toList directSourceEdges))
  unless
    (IntSet.size directEdgeKeys == NonEmpty.length directSourceEdges)
    ( claimFailure
        [ "application frame repeats one direct source edge"
        , "  direct edges: " ++ show directSourceEdges
        ]
    )
  claimResults <-
    traverse (buildClaim directEdgeKeys) requirements
  let claims = mapMaybe fst claimResults
      ambientClaims = mapMaybe snd claimResults
      allClaimEdgeSets =
        map dagcEdgeIds claims
          ++ map daagcEdgeIds ambientClaims
  unless
    (null (overlappingClaimEdgeSets allClaimEdgeSets))
    ( claimFailure
        [ "direct requirements overlap one source edge"
        , "  overlapping claim edges: "
            ++ show (overlappingClaimEdgeSets allClaimEdgeSets)
        ]
    )
  pure (directSourceEdges, claims, ambientClaims)
  where
    buildClaim directEdgeKeys requirement = do
      let claimEdgeIds = rgbEdgeIds requirement
          claimEdgeKeys =
            IntSet.fromList
              (map getEdgeId (NonEmpty.toList claimEdgeIds))
          routeNodes =
            rgbExteriorNode requirement
              : rgbOperatedRoot requirement
              : NonEmpty.toList (rgbResultRoots requirement)
          routedRefs =
            [ routedRef
            | node <- routeNodes
            , Just routedRef <-
                [IntMap.lookup (getNodeId node) routes]
            ]
      unless
        ( IntSet.size claimEdgeKeys == NonEmpty.length claimEdgeIds
            && claimEdgeKeys `IntSet.isSubsetOf` directEdgeKeys
        )
        ( claimFailure
            [ "requirement is not a complete subset of the application's direct source edges"
            , "  requirement: " ++ show requirement
            , "  direct edges: "
                ++ show (map EdgeId (IntSet.toList directEdgeKeys))
            ]
        )
      mbRoutedRef <-
        case routedRefs of
          [] -> pure Nothing
          firstRef : remainingRefs
            | length routedRefs == length routeNodes
            , all (typeBinderRefsSameIdentity firstRef) remainingRefs ->
                pure (Just firstRef)
          _ ->
            claimFailure
              [ "requirement endpoints do not all route to one constructed binder"
              , "  requirement: " ++ show requirement
              , "  routes: " ++ show routes
              ]
      case mbRoutedRef of
        Nothing -> do
          (ambientRef, ambientBound, operatedType) <-
            exactAmbientAuthority requirement routeNodes
          -- Publish positive zero-local evidence.  Later root preparation
          -- must not infer ambient ownership merely from a missing route.
          pure
            ( Nothing
            , Just
                DirectApplicationAmbientGammaClaim
                  { daagcEdgeIds = claimEdgeIds
                  , daagcExteriorNode = rgbExteriorNode requirement
                  , daagcOperatedRoot = rgbOperatedRoot requirement
                  , daagcConstructionResultRoots =
                      rgbResultRoots requirement
                  , daagcOperatedType = operatedType
                  , daagcAmbientRef = ambientRef
                  , daagcAmbientBound = ambientBound
                  }
            )
        Just routedRef -> do
          constructedBound <-
            case
                [ mbBound
                | (constructionRef, mbBound) <- constructionBinders
                , typeBinderRefsSameIdentity constructionRef routedRef
                ]
              of
                [mbBound] -> pure mbBound
                matches ->
                  claimFailure
                    [ "routed requirement does not name exactly one construction binder"
                    , "  requirement: " ++ show requirement
                    , "  routed ref: " ++ show routedRef
                    , "  matching bounds: " ++ show matches
                    ]
          operatedType <-
            completedLocalOperatedType
              requirement
              routedRef
              constructedBound
          pure
            ( Just
                DirectApplicationGammaClaim
                  { dagcEdgeIds = claimEdgeIds
                  , dagcExteriorNode = rgbExteriorNode requirement
                  , dagcOperatedRoot = rgbOperatedRoot requirement
                  , dagcConstructionResultRoots = rgbResultRoots requirement
                  , dagcOperatedType = operatedType
                  , dagcBinderRef = routedRef
                  , dagcConstructedBound = constructedBound
                  }
            , Nothing
            )

    -- One application Gamma can own an enclosing edge and one of its direct
    -- Figure 15.3.5 edges for the same exterior.  The direct graph view may
    -- still carry the provisional bottom endpoint after the owner-selected
    -- view has completed that declaration.  Advance the direct claim only
    -- from the exact owner requirement: exterior, placement, complete result
    -- occurrence, construction route, and checked binder bound must all agree.
    completedLocalOperatedType requirement routedRef constructedBound
      | boundsAgree constructedBound (rgbOperatedType requirement) =
          pure (rgbOperatedType requirement)
      | constructedBoundProvides constructedBound (rgbOperatedType requirement) =
          -- A checked source value can close the binders that occur free in
          -- the graph's operated body.  Keep S(operated) in the claim, but
          -- retain the complete closed source scheme as the constructed
          -- Gamma declaration; its explicit binder-spine instantiation is
          -- the proof that the declaration provides this occurrence.
          pure (rgbOperatedType requirement)
      | Just completedEndpoint <-
          exactDirectClosureEndpoint requirement constructedBound =
          -- The direct edge computation has already checked the complete
          -- source value, including a bounded forall which closes an identity
          -- still free in the graph's S(operated) view.  Publish that exact
          -- endpoint as the claim state.  This is a construction transition,
          -- not an attempt to instantiate the bounded binder with itself.
          pure completedEndpoint
      | rgbOperatedType requirement == TBottom =
          case matchingOwnerCompletions of
            [completed] -> pure (rgbOperatedType completed)
            matches ->
              claimFailure
                [ "provisional direct requirement has no unique owner completion"
                , "  requirement: " ++ show requirement
                , "  constructed bound: " ++ show constructedBound
                , "  matching owner requirements: " ++ show matches
                ]
      | otherwise =
          claimFailure
            [ "constructed binder bound disagrees with S(operated)"
            , "  requirement: " ++ show requirement
            , "  constructed bound: " ++ show constructedBound
            , "  routed constructed bound: "
                ++ show
                  ( routeExactConstructionOccurrences
                      (maybe TBottom tyToElab constructedBound)
                  )
            , "  source occurrence routes: " ++ show sourceBinderRefs
            , "  ambient authority routes: " ++ show ambientRoutes
            ]
      where
        matchingOwnerCompletions =
          [ completed
          | completed <- ownerRequirements
          , rgbExteriorNode completed == rgbExteriorNode requirement
          , rgbPlacement completed == rgbPlacement requirement
          , sameNodeSet
              (rgbResultRoots completed)
              (rgbResultRoots requirement)
          , boundsAgree constructedBound (rgbOperatedType completed)
          , all
              (routesTo routedRef)
              ( rgbOperatedRoot completed
                  : rgbExteriorNode completed
                  : NonEmpty.toList (rgbResultRoots completed)
              )
          ]

        routesTo expectedRef node =
          maybe
            False
            (typeBinderRefsSameIdentity expectedRef)
            (IntMap.lookup (getNodeId node) routes)

    exactDirectClosureEndpoint requirement constructedBound = do
      completedEndpoints <-
        traverse
          ( \edgeId ->
              IntMap.lookup
                (getEdgeId edgeId)
                exactDirectConstructionEndpoints
          )
          (NonEmpty.toList (rgbEdgeIds requirement))
      completedEndpoint <-
        case completedEndpoints of
          [] -> Nothing
          firstEndpoint : remainingEndpoints
            | all (directEndpointTypesAgree firstEndpoint) remainingEndpoints ->
                Just firstEndpoint
          _ -> Nothing
      let routedConstructedType =
            routeExactConstructionOccurrences
              (maybe TBottom tyToElab constructedBound)
          routedCompletedEndpoint =
            routeExactConstructionOccurrences completedEndpoint
          routedOperatedType =
            routeExactConstructionOccurrences
              (rgbOperatedType requirement)
      guard
        ( directEndpointTypesAgree
            routedConstructedType
            routedCompletedEndpoint
        )
      guard
        ( exactIdentityForallClosureOf
            routedCompletedEndpoint
            routedOperatedType
        )
      pure completedEndpoint

    exactDirectConstructionEndpoints =
      IntMap.fromList
        [ (getEdgeId edgeId, endpoint)
        | (edgeId, Just endpoint) <- directConstructionEndpoints
        ]

    directEndpointTypesAgree left right =
      alphaEqType left right || churchAwareEqType left right

    sameNodeSet left right =
      IntSet.fromList (map getNodeId (NonEmpty.toList left))
        == IntSet.fromList (map getNodeId (NonEmpty.toList right))

    exactAmbientAuthority requirement routeNodes = do
      routedAmbientRefs <-
        traverse
          ( \node ->
              case IntMap.lookup (getNodeId node) ambientRoutes of
                Just ref -> pure ref
                Nothing ->
                  claimFailure
                    [ "zero-local requirement has no exact ambient route"
                    , "  requirement: " ++ show requirement
                    , "  missing route node: " ++ show node
                    , "  ambient routes: " ++ show ambientRoutes
                    ]
          )
          routeNodes
      ambientRef <-
        case routedAmbientRefs of
          firstRef : remainingRefs
            | all
                (typeBinderRefsSameIdentity firstRef)
                remainingRefs ->
                pure firstRef
          _ ->
            claimFailure
              [ "zero-local requirement routes to multiple ambient declarations"
              , "  requirement: " ++ show requirement
              , "  routed ambient refs: " ++ show routedAmbientRefs
              ]
      let matchingChildDeclarations =
            [ authority
            | authority <- childAmbientDeclarations
            , typeBinderRefsSameIdentity
                ambientRef
                (agaExactRef authority)
            ]
      when
        ( any
            (typeBinderRefsSameIdentity ambientRef . fst)
            constructionBinders
        )
        ( claimFailure
            [ "zero-local requirement names an application-local binder"
            , "  requirement: " ++ show requirement
            , "  ambient ref: " ++ show ambientRef
            ]
        )
      let matchingExplicitBounds =
            [ bound
            | (boundRef, bound) <- Map.toList ambientBindings
            , typeBinderRefsSameIdentity boundRef ambientRef
            ]
          matchingFreeRefs =
            foldr insertUniqueRef []
              [ freeRef
              | freeRef <- ambientFreeRefs
              , typeBinderRefsSameIdentity freeRef ambientRef
              ]
      ambientBound <-
        case (matchingExplicitBounds, matchingFreeRefs) of
            ([bound], _) -> pure bound
            ([], [_]) -> pure TBottom
            _ ->
              claimFailure
                [ "zero-local requirement has no unique exact ambient declaration"
                , "  requirement: " ++ show requirement
                , "  ambient ref: " ++ show ambientRef
                , "  matching explicit bounds: "
                    ++ show matchingExplicitBounds
                , "  matching free refs: " ++ show matchingFreeRefs
                ]
      requirementState <-
        if ambientBoundSatisfies ambientRef ambientBound requirementOperatedType
          then
            pure
              DirectAmbientRequirementState
                { darsDeclarationBound = ambientBound
                , darsOperatedType = requirementOperatedType
                }
          else
            if
                completeUnboundedForallSpecializesTo
                  requirementOperatedType
                  ambientBound
              then
                -- Every requirement occurrence routes to this exact ambient
                -- identity, and the checked environment has already
                -- published its completed specialization.  Advance the
                -- zero-local claim to that constructed bound directly.  The
                -- reverse binder-spine proof supplies the N computation; no
                -- descendant refinement is needed merely to rediscover an
                -- already published declaration.
                pure
                  DirectAmbientRequirementState
                    { darsDeclarationBound = ambientBound
                    , darsOperatedType = ambientBound
                    }
          else
            case
                directConstructionCompletedAmbientRequirement
                  requirement
                  ambientBound
              of
              Just completedAmbientBound ->
                -- The complete direct edge set has already constructed the
                -- exact ambient declaration.  The graph requirement may
                -- retain a provisional dependency-ordered forall closure,
                -- while the checked endpoint retains source lexical order.
                -- Consume both pieces of positive construction evidence here
                -- instead of treating the stale S(operated) presentation as
                -- the declaration authority.
                pure
                  DirectAmbientRequirementState
                    { darsDeclarationBound = completedAmbientBound
                    , darsOperatedType = completedAmbientBound
                    }
              Nothing ->
                case
                    filter
                      ( bodyConsumerBoundRefinementCertifiesTransition
                          ambientRef
                          requirementOperatedType
                          ambientBound
                      )
                  bodyConsumerBoundRefinements
                  of
                    [_] ->
                      -- The unique checked child certificate proves this exact
                      -- identity's complete previous-to-ambient transition.
                      -- Publish the state the application actually used without
                      -- rediscovering that transition from a privileged type
                      -- shape such as Bottom or a leading forall.
                      pure
                        DirectAmbientRequirementState
                          { darsDeclarationBound = ambientBound
                          , darsOperatedType = ambientBound
                          }
                    [] ->
                      case matchingChildDeclarations of
                        firstDeclaration : remainingDeclarations
                          | all
                              ( operationalEndpointTypesAgree
                                  (agaBound firstDeclaration)
                                  . agaBound
                              )
                              remainingDeclarations
                          , operationalEndpointTypesAgree
                              (agaBound firstDeclaration)
                              ambientBound ->
                              -- A recursively checked child can publish the exact
                              -- ambient declaration used to construct its value
                              -- without a body-consumer transition (the zero-local
                              -- mixed-annotation path).  The child owner-final
                              -- certificate and this requirement's exact ambient
                              -- route jointly identify the declaration; advance
                              -- the claim to that already constructed bound rather
                              -- than comparing it with the stale graph-operated
                              -- presentation.
                              pure
                                DirectAmbientRequirementState
                                  { darsDeclarationBound = ambientBound
                                  , darsOperatedType = ambientBound
                                  }
                        _ ->
                          claimFailure
                            [ "zero-local ambient declaration disagrees with S(operated)"
                            , "  requirement: " ++ show requirement
                            , "  ambient ref: " ++ show ambientRef
                            , "  ambient bound: " ++ show ambientBound
                            , "  boundary-completed ambient bound: "
                                ++ show
                                  ( completeLambdaParamBoundarySourceRootBound
                                      paramBoundaryCertificates
                                      sourceBinderRefs
                                      ambientBound
                                  )
                            , "  exact direct endpoints: "
                                ++ show
                                  [ ( edgeId
                                    , IntMap.lookup
                                        (getEdgeId edgeId)
                                        exactDirectConstructionEndpoints
                                    )
                                  | edgeId <-
                                      NonEmpty.toList
                                        (rgbEdgeIds requirement)
                                  ]
                            , "  matching body-consumer refinements: []"
                            , "  matching checked child declarations: "
                                ++ show matchingChildDeclarations
                            ]
                    matchingRefinements ->
                      claimFailure
                        [ "zero-local ambient declaration has ambiguous body-consumer refinements"
                        , "  requirement: " ++ show requirement
                        , "  ambient ref: " ++ show ambientRef
                        , "  ambient bound: " ++ show ambientBound
                        , "  matching body-consumer refinements: "
                            ++ show matchingRefinements
                        ]
      pure
        ( ambientRef
        , darsDeclarationBound requirementState
        , darsOperatedType requirementState
        )
      where
        requirementOperatedType = rgbOperatedType requirement

        insertUniqueRef ref refs
          | any (typeBinderRefsSameIdentity ref) refs = refs
          | otherwise = ref : refs

    -- An ambient Gamma declaration may be used at one exact operated
    -- endpoint without changing the declaration itself.  Accept that use
    -- only when the ordinary xMLF binder-spine constructor can build the
    -- endpoint from a real forall declaration.  In particular, do not let
    -- the planner's TBottom/InstBot case turn a free ambient type variable
    -- into an arbitrary operated type.
    ambientBoundSatisfies ambientRef ambientBound operatedType =
      case operatedType of
        TVarRef operatedRef
          | typeBinderRefsSameIdentity ambientRef operatedRef -> True
        _ ->
          alphaEqType ambientBound operatedType
            || churchAwareEqType ambientBound operatedType
            || case ambientBound of
              TForallRef {} ->
                isJust
                  ( planExactBinderSpine
                      endpointTypesAgree
                      ambientBound
                      operatedType
                  )
              _ -> False
      where
        endpointTypesAgree left right =
          alphaEqType left right || churchAwareEqType left right

    directConstructionCompletedAmbientRequirement requirement ambientBound =
      case
          traverse
            ( \edgeId ->
                IntMap.lookup
                  (getEdgeId edgeId)
                  exactDirectConstructionEndpoints
            )
            (NonEmpty.toList (rgbEdgeIds requirement))
        of
          Just (firstEndpoint : remainingEndpoints)
            | all
                (directEndpointTypesAgree firstEndpoint)
                remainingEndpoints ->
                let completedAmbientBound =
                      completeLambdaParamBoundarySourceRootBound
                        paramBoundaryCertificates
                        sourceBinderRefs
                        ambientBound
                    routedAmbientBound =
                      routeExactConstructionOccurrences completedAmbientBound
                    routedEndpoint =
                      routeExactConstructionOccurrences firstEndpoint
                    routedOperatedType =
                      routeExactConstructionOccurrences
                        (rgbOperatedType requirement)
                 in if
                        directAmbientBoundConstructsEndpoint
                          routedAmbientBound
                          routedEndpoint
                          && ( directEndpointTypesAgree
                                routedOperatedType
                                routedEndpoint
                                || forallClosurePresentsSameIdentityBody
                                  routedOperatedType
                                  routedEndpoint
                             )
                      then Just firstEndpoint
                      else Nothing
          _ -> Nothing
    -- A returned source lambda can require the complete xMLF construction:
    -- M introduces its target forall before N/Hyp specializes an ambient
    -- bounded declaration beneath it.  The exact edge endpoint and ambient
    -- identity route select both sides; the shared constructor then checks
    -- the whole computation.  A leading-spine-only plan is insufficient here
    -- because it cannot introduce a fresh target declaration.
    directAmbientBoundConstructsEndpoint candidateBound endpoint =
      isJust
        ( constructExactInstantiation
            directConstructionTypeEnv
            directEndpointTypesAgree
            candidateBound
            endpoint
        )

    directConstructionTypeEnv =
      TypeCheck.mkTypeCheckEnvWithResolvedTerms [] ambientBindings

    boundsAgree mbBound operatedType =
      let constructedType =
            routeExactConstructionOccurrences
              (maybe TBottom tyToElab mbBound)
          routedOperatedType =
            routeExactConstructionOccurrences operatedType
       in alphaEqType constructedType routedOperatedType
            || churchAwareEqType constructedType routedOperatedType

    constructedBoundProvides mbBound operatedType =
      let constructedType =
            routeExactConstructionOccurrences
              (maybe TBottom tyToElab mbBound)
          routedOperatedType =
            routeExactConstructionOccurrences operatedType
       in completeUnboundedForallSpecializesTo
            constructedType
            routedOperatedType

    -- Bounds are constructed before the direct application claim is
    -- published, so their free occurrences can still carry graph-local
    -- identities.  The authority aliases are the exact Gamma declarations
    -- selected for those occurrences.  Consume that construction proof here
    -- so the claim compares one identity domain rather than repairing it
    -- after elaboration.
    routeExactConstructionOccurrences =
      routeExactAmbientOccurrences
        . resolveSourceBinderAliasesInTypeExcept
          protectedAmbientIdentities
          (scCanonical scopeContext)
          sourceBinderRefs

    -- An explicit ambient Gamma identity is already the construction
    -- authority for that occurrence.  A source-annotation sidecar may retain
    -- the same graph node as provenance for a generated binder, but it cannot
    -- rewrite the ambient declaration after construction has selected it.
    protectedAmbientIdentities =
      Set.fromList
        [ typeBinderRefIdentity ambientRef
        | ambientRef <- ambientFreeRefs
        , Just graphNode <- [typeBinderRefNode ambientRef]
        , IntMap.member (getNodeId graphNode) ambientRoutes
        ]

    routeExactAmbientOccurrences ty =
      applyTypeVarRefRenames
        [ (graphRef, exactRef)
        | graphRef <- freeTypeVarRefsType ty
        , Just graphNode <- [typeBinderRefNode graphRef]
        , Just exactRef <-
            [IntMap.lookup (getNodeId graphNode) ambientRoutes]
        , not (typeBinderRefsSameIdentity graphRef exactRef)
        ]
        ty

    overlappingClaimEdgeSets claimEdgeSets =
      [ claimEdges
      | (index, claimEdges) <- zip [0 :: Int ..] claimEdgeSets
      , any (claimEdgesOverlap claimEdges) (drop (index + 1) claimEdgeSets)
      ]

    claimEdgesOverlap left right =
      not
        ( IntSet.null
            ( IntSet.intersection
                (edgeKeySet left)
                (edgeKeySet right)
            )
        )

    edgeKeySet =
      IntSet.fromList . map getEdgeId . NonEmpty.toList

    claimFailure :: [String] -> Either ElabError a
    claimFailure details =
      Left
        ( ValidationFailed
            ( [ "invalid direct application Gamma requirement claim"
              , "  owner: " ++ show owner
              , "  annotation: " ++ show ann
              ]
                ++ details
            )
        )

annotationInstantiationEdges :: AnnExpr -> [EdgeId]
annotationInstantiationEdges = map fst . annotationInstantiationEdgeSources

annotationInstantiationEdgeSources :: AnnExpr -> [(EdgeId, AnnExpr)]
annotationInstantiationEdgeSources ann =
  case ann of
    AResolvedVar {} -> []
    ALit {} -> []
    ALam _ _ _ _ body bodyEdge _ ->
      (bodyEdge, body) : annotationInstantiationEdgeSources body
    AApp fun arg funSite argSite _ ->
      (instantiationSiteEdgeId funSite, fun)
        : (instantiationSiteEdgeId argSite, arg)
        : (annotationInstantiationEdgeSources fun ++ annotationInstantiationEdgeSources arg)
    ALet _ _ _ _ _ _ rhs body _ ->
      annotationInstantiationEdgeSources rhs ++ annotationInstantiationEdgeSources body
    AExactAnn inner _ _ edgeId ->
      (edgeId, inner) : annotationInstantiationEdgeSources inner
    AAnn inner _ edgeId ->
      (edgeId, inner) : annotationInstantiationEdgeSources inner
    ALetScope inner _ edgeId ->
      (edgeId, inner) : annotationInstantiationEdgeSources inner
    AUnfold inner _ edgeId ->
      (edgeId, inner) : annotationInstantiationEdgeSources inner

authoritativeEnvBindings :: Env -> [EnvBinding]
authoritativeEnvBindings env =
  Map.elems $
    Map.fromList
      [ (envBindingIdentityKey binding, binding)
      | binding <- Map.elems (envBindingsByIdentity env)
      ]

lookupEnvBindingForDetails :: IdDetails -> Env -> Maybe EnvBinding
lookupEnvBindingForDetails details env =
  Map.lookup (envBindingDetailsKey details) (envBindingsByIdentity env)

insertEnvBinding :: EnvBinding -> Env -> Env
insertEnvBinding binding env =
  env
    { envBindingsByIdentity =
        Map.insert
          (envBindingIdentityKey completedBinding)
          completedBinding
          (envBindingsByIdentity env)
    }
  where
    completedBinding =
      completeEnvBindingAtLambdaParamBoundaries env binding

insertEnvBindingIdentityAlias :: IdDetails -> EnvBinding -> Env -> Env
insertEnvBindingIdentityAlias aliasDetails binding env =
  env
    { envBindingsByIdentity =
        Map.insert
          (envBindingDetailsKey aliasDetails)
          (completeEnvBindingAtLambdaParamBoundaries env binding)
          (envBindingsByIdentity env)
    }

-- | A binding introduced under an exact lambda-parameter boundary is born in
-- that boundary's completed identity domain.  This is needed for binders
-- introduced after the certificate itself (for example the second source
-- parameter of a constrained helper); only rewriting bindings that happened
-- to exist when the first boundary was installed would make construction
-- order observable.
completeEnvBindingAtLambdaParamBoundaries :: Env -> EnvBinding -> EnvBinding
completeEnvBindingAtLambdaParamBoundaries env binding =
  let schemeInfo =
        completeLambdaParamBoundarySchemeInfo
          (envLambdaParamBoundaryCertificates env)
          (ebSchemeInfo binding)
   in binding
        { ebSchemeInfo = schemeInfo
        , ebSchemeType = schemeToType (siScheme schemeInfo)
        }

-- | Enter the graph-identity domain that constructs the current packet.
-- Source-expected and compiler-exact packets both contribute routes here;
-- only the latter also carry authority to publish a source ABI.
alignEnvToConstructionBinderRenames
  :: [(TypeBinderRef, TypeBinderRef)]
  -> Env
  -> Either ElabError Env
alignEnvToConstructionBinderRenames renames env
  | null renames = pure env
  | otherwise = do
      accumulatedRenames <-
        foldM
          insertConstructionBinderRename
          (envConstructionBinderRenames env)
          renames
      typeBindings <-
        foldM
          insertTypeBinding
          Map.empty
          (Map.toList (envTypeBindings env))
      sourceRefinedGammaBounds <-
        foldM
          insertTypeBinding
          Map.empty
          (Map.toList (envSourceRefinedGammaBounds env))
      gammaCopiedBinderRoutes <-
        renameGammaCopiedBinderRoutes
          renames
          (envGammaCopiedBinderRoutes env)
      pure
        env
          { envBindingsByIdentity =
              Map.map alignBinding (envBindingsByIdentity env)
          , envTypeBindings = typeBindings
          , envConstructionGammaAliases =
              IntMap.map
                (applyRefRenames renames)
                (envConstructionGammaAliases env)
          , envGammaCopiedBinderRoutes = gammaCopiedBinderRoutes
          , envSourceRefinedGammaBounds = sourceRefinedGammaBounds
          , envConstructedLambdaParamTypes =
              Map.map
                (applyTypeVarRefRenames renames)
                (envConstructedLambdaParamTypes env)
          , envExactApplicationLambdaParamSchemes =
              Map.map
                (applySchemeInfoRefRenames renames)
                (envExactApplicationLambdaParamSchemes env)
          , envLambdaParamBoundaryCertificates =
              map
                (renameLambdaParamBoundaryCertificate renames)
                (envLambdaParamBoundaryCertificates env)
          , envConstructionBinderRenames = accumulatedRenames
          }
  where
    insertConstructionBinderRename accumulated rename@(oldRef, newRef) =
      case find (typeBinderRefsSameIdentity oldRef . fst) accumulated of
        Nothing -> pure (accumulated ++ [rename])
        Just (_, existingRef)
          | typeBinderRefsSameIdentity existingRef newRef -> pure accumulated
          | otherwise ->
              Left
                ( ValidationFailed
                    [ "construction binder quotient routes one source binder to multiple graph identities"
                    , "  source binder: " ++ show oldRef
                    , "  first target: " ++ show existingRef
                    , "  second target: " ++ show newRef
                    ]
                )

    alignBinding binding =
      let schemeInfo =
            applySchemeInfoRefRenames renames (ebSchemeInfo binding)
       in binding
            { ebSchemeInfo = schemeInfo
            , ebSchemeType = schemeToType (siScheme schemeInfo)
            }

    insertTypeBinding bindings (ref, bound) =
      let ref' = applyRefRenames renames ref
          bound' = applyTypeVarRefRenames renames bound
       in case Map.lookup ref' bindings of
            Nothing -> pure (Map.insert ref' bound' bindings)
            Just existingBound
              | alphaEqType existingBound bound'
                  || churchAwareEqType existingBound bound' ->
                  pure bindings
              | otherwise ->
                  Left
                    ( ValidationFailed
                        [ "construction binder quotient merges incompatible Gamma bounds"
                        , "  binder: " ++ show ref'
                        , "  existing bound: " ++ show existingBound
                        , "  incoming bound: " ++ show bound'
                        , "  requested renames: " ++ show renames
                        ]
                    )

-- | Enter a strictly nested construction domain.  A parent packet may have
-- already routed @source -> parent@ when its direct child proves
-- @source -> child@.  Those are ordered lexical transitions, not two sibling
-- answers for one quotient.  Rebase the child route to @parent -> child@,
-- apply it to the already-aligned environment, and compose every accumulated
-- target to the final identity.  Conflicting routes presented by one layer are
-- still rejected by 'alignEnvToConstructionBinderRenames'.
alignEnvToNestedConstructionBinderRenames
  :: [(TypeBinderRef, TypeBinderRef)]
  -> Env
  -> Either ElabError Env
alignEnvToNestedConstructionBinderRenames requestedRenames env = do
  rebasedRenames <-
    traverse
      (\(oldRef, newRef) ->
        (,) <$> resolveCurrent oldRef <*> resolveCurrent newRef
      )
      requestedRenames
  let effectiveRenames =
        [ rename
        | rename@(oldRef, newRef) <- rebasedRenames
        , not (typeBinderRefsSameIdentity oldRef newRef)
        ]
  aligned <- alignEnvToConstructionBinderRenames effectiveRenames env
  normalizedAccumulated <-
    traverse
      (\(oldRef, targetRef) ->
        do
          finalTargetRef <- resolveRef effectiveRenames [] targetRef
          pure (oldRef, finalTargetRef)
      )
      (envConstructionBinderRenames aligned)
  pure
    aligned
      { envConstructionBinderRenames = normalizedAccumulated
      }
  where
    resolveCurrent =
      resolveRef (envConstructionBinderRenames env) []

    resolveRef renames seen ref
      | any (typeBinderRefsSameIdentity ref) seen =
          Left
            ( ValidationFailed
                [ "construction binder quotient contains a rename cycle"
                , "  cycle at: " ++ show ref
                , "  renames: " ++ show renames
                ]
            )
      | otherwise =
          case
              snd
                <$> find
                  (typeBinderRefsSameIdentity ref . fst)
                  renames
            of
              Just nextRef
                | not (typeBinderRefsSameIdentity ref nextRef) ->
                    resolveRef renames (ref : seen) nextRef
              _ -> pure ref

-- | Enter a compiler-exact construction domain without allowing a nested
-- exact packet to replace a source binder already owned by the ambient
-- Gamma.  The accepted routes are construction routes too, but retaining the
-- exact subset separately preserves the stronger publication authority.
alignEnvToCompilerExactBinderRenames
  :: [(TypeBinderRef, TypeBinderRef)]
  -> Env
  -> Either ElabError Env
alignEnvToCompilerExactBinderRenames requestedRenames env = do
  env' <- alignEnvToConstructionBinderRenames renames env
  exactRenames <-
    foldM
      insertCompilerExactBinderRename
      (envCompilerExactBinderRenames env)
      renames
  pure env' {envCompilerExactBinderRenames = exactRenames}
  where
    renames =
      [ rename
      | rename@(sourceRef, _) <- requestedRenames
      , not
          ( any
              (typeBinderRefsSameIdentity sourceRef)
              (Map.keys (envTypeBindings env))
          )
      ]

    insertCompilerExactBinderRename accumulated rename@(oldRef, newRef) =
      case find (typeBinderRefsSameIdentity oldRef . fst) accumulated of
        Nothing -> pure (accumulated ++ [rename])
        Just (_, existingRef)
          | typeBinderRefsSameIdentity existingRef newRef -> pure accumulated
          | otherwise ->
              Left
                ( ValidationFailed
                    [ "compiler-exact binder quotient routes one source binder to multiple graph identities"
                    , "  source binder: " ++ show oldRef
                    , "  first target: " ++ show existingRef
                    , "  second target: " ++ show newRef
                    ]
                )

lookupEnvBindingForKey :: BindingKey -> Env -> Maybe EnvBinding
lookupEnvBindingForKey (ResolvedBindingKey identityKey) env =
  Map.lookup identityKey (envBindingsByIdentity env)

lookupSchemeInfoForKey :: BindingKey -> Env -> Maybe SchemeInfo
lookupSchemeInfoForKey key env =
  ebSchemeInfo <$> lookupEnvBindingForKey key env

lookupSchemeInfoForResolved :: ResolvedVar -> Env -> Maybe SchemeInfo
lookupSchemeInfoForResolved resolved env =
  ebSchemeInfo <$> Map.lookup (envBindingDetailsKey (resolvedVarDetails resolved)) (envBindingsByIdentity env)

envBindingIdentityKey :: EnvBinding -> EnvBindingIdentityKey
envBindingIdentityKey =
  envBindingDetailsKey . ebIdentityDetails

envBindingDetailsKey :: IdDetails -> EnvBindingIdentityKey
envBindingDetailsKey =
  idDetailsIdentityKey

resolvedEnvBindingVar :: EnvBinding -> ResolvedVar
resolvedEnvBindingVar binding =
  ResolvedVar
    { resolvedVarType = ebSchemeType binding,
      resolvedVarDetails = ebIdentityDetails binding
    }

type LocalVarKey = ResolvedVar

localVarKeyMatchesReference :: LocalVarKey -> ResolvedVar -> Bool
localVarKeyMatchesReference = resolvedVarSameIdentity

-- | Close the existential part of a source annotation against the enclosing
-- paper Gamma, before its explicit universal spine.  This is the pseudo-type
-- order from §12.3.2: @exists beta. forall alpha. ...@.  A solved existential
-- already owned by the ambient Gamma remains free instead of being
-- re-generalized at the annotation boundary.
sourceAnnotationSchemeAgainstEnv :: Env -> ElabType -> ElabScheme
sourceAnnotationSchemeAgainstEnv env ty =
  let sourceScheme = schemeFromType ty
      existentialBinders =
        [ (ref, Nothing)
        | ref <- freeTypeVarRefsInOccurrenceOrder ty
        , not (envOwnsExactTypeBinderRef env ref)
        ]
   in mkElabSchemeWithRefs
        (existentialBinders ++ schemeBinderRefs sourceScheme)
        (schemeBody sourceScheme)

-- | Complete @Gen(Gamma, Typ(rhs))@ at the let publication boundary.  The
-- graph generalizer can return an open scheme when an RHS lambda parameter is
-- owned by a nested constructor that shares the let's solved result class.
-- Any identity still free in the inferred scheme and absent from the ambient
-- paper Gamma is therefore a let binder by definition; introduce it before
-- the existing spine so bounds can depend on it.
completeInferredLetSchemeAgainstEnv
  :: (NodeId -> NodeId)
  -> Env
  -> ElabScheme
  -> ElabScheme
completeInferredLetSchemeAgainstEnv representative env scheme =
  mkElabSchemeWithRefs
    (missingBinders ++ schemeBinderRefs scheme)
    (schemeBody scheme)
  where
    missingBinders =
      [ (ref, Nothing)
      | ref <- freeTypeVarRefsInOccurrenceOrder (schemeToType scheme)
      , not
          ( any
              (typeBinderRefsSameIdentity ref . fst)
              (schemeBinderRefs scheme)
          )
      , not
          ( envContainsFreeTypeBinderRef
              representative
              (envFreeTypeBinderRefs env)
              ref
          )
      ]

-- | Close a checked owner result with the exact local-Gamma declarations
-- captured by its construction certificate.  Such a declaration is ambient
-- while the owner is checked but may not be ambient at the enclosing let
-- publication boundary.  In that case the certificate authorizes the exact
-- @N@ specialization of the result at that declaration's bound; it must not
-- become an unbounded binder rediscovered from the free result type.
completeOwnerFinalConstructionSchemeAgainstEnv
  :: (NodeId -> NodeId)
  -> Env
  -> OwnerFinalConstruction
  -> ElabScheme
  -> Either
      ElabError
      (ElabScheme, [(TypeBinderRef, BoundType)])
completeOwnerFinalConstructionSchemeAgainstEnv representative env certificate scheme = do
  ambientAuthorities <-
    mergeOwnerFinalAmbientDeclarationAuthorities
      "owner-final scheme completion"
      missingRefs
      (ofcAuthoritativeAmbientDeclarations certificate)
      [ofcAmbientDeclarationAuthorities certificate]
  structuralAuthorities <-
    traverse validateStructuralAuthority
      [ authority
      | authority <- ambientAuthorities
      , agaBound authority /= TBottom
      ]
  let specializedType =
        foldl'
          ( \ty (authority, _) ->
              substTypeCaptureRef
                (agaExactRef authority)
                (agaBound authority)
                ty
          )
          (schemeToType scheme)
          structuralAuthorities
      specializedScheme = schemeFromType specializedType
      locallyClosedRefs =
        [ ref
        | ref <-
            freeTypeVarRefsInOccurrenceOrder specializedType
        , any (typeBinderRefsSameIdentity ref) missingRefs
        , not
            ( any
                (typeBinderRefsSameIdentity ref . fst)
                (schemeBinderRefs specializedScheme)
            )
        ]
      ownerCompletedScheme =
        mkElabSchemeWithRefs
          ( map (\ref -> (ref, Nothing)) locallyClosedRefs
              ++ schemeBinderRefs specializedScheme
          )
          (schemeBody specializedScheme)
  pure
    ( completeInferredLetSchemeAgainstEnv
        representative
        env
        ownerCompletedScheme
    , [ (agaExactRef authority, bound)
      | (authority, bound) <- structuralAuthorities
      ]
    )
  where
    missingRefs =
      [ ref
      | ref <- freeTypeVarRefsInOccurrenceOrder (schemeToType scheme)
      , not
          ( any
              (typeBinderRefsSameIdentity ref . fst)
              (schemeBinderRefs scheme)
          )
      , not
          ( ownerCertifiesAmbientUse ref
              && envOwnsExactTypeBinderRef env ref
          )
      ]

    -- A representative peer or construction alias can make an owner-local
    -- identity appear reachable in the publication environment after the
    -- owner has been checked.  Reachability is not ambient authority: the
    -- exact identity must still be owned by the enclosing Gamma.  A declaration
    -- certificate supplies that authority directly; an unbounded ambient use
    -- must also occur freely in an enclosing term scheme.  This distinguishes
    -- a lambda parameter @u : a@ from a packet-local graph alias that happens
    -- to remain in the type environment.  A certified declaration that has
    -- left the exact environment is handled by the bound specialization above.
    ownerCertifiesAmbientUse ref =
      any
        (typeBinderRefsSameIdentity ref . agaExactRef)
        ( ofcAuthoritativeAmbientDeclarations certificate
            ++ ofcAmbientDeclarationAuthorities certificate
        )
        || ( any
              (typeBinderRefsSameIdentity ref)
              (ofcUsedAmbientBinderRefs certificate)
              && any
                (typeBinderRefsSameIdentity ref)
                enclosingTermSchemeFreeRefs
           )

    enclosingTermSchemeFreeRefs =
      concatMap
        (freeTypeVarRefsType . ebSchemeType)
        (authoritativeEnvBindings env)

    validateStructuralAuthority authority =
      case elabToBound (agaBound authority) of
        Right bound -> pure (authority, bound)
        Left cause ->
          Left
            ( ValidationFailed
                [ "owner-final construction has an illegal local Gamma bound"
                , "  owner: " ++ show (ofcOwner certificate)
                , "  declaration: " ++ show authority
                , "  cause: " ++ cause
                ]
            )

-- | Close construction-only ambient declarations around an owner-final term
-- and immediately eliminate them at their certified bounds.  The companion
-- scheme construction substitutes the same identities with the same bounds;
-- building the explicit @forall@/@N@ computation here keeps the term typable
-- without leaking those declarations into the enclosing let environment.
specializeOwnerFinalConstructionForPublication
  :: [(TypeBinderRef, BoundType)]
  -> XmlfTerm
  -> XmlfTerm
specializeOwnerFinalConstructionForPublication binders term =
  foldl'
    (\specialized _ -> ETyInst specialized InstElim)
    closed
    binders
  where
    closed =
      foldr
        ( \(ref, bound) body ->
            ETyAbsRef ref (Just bound) body
        )
        term
        binders

sourceSchemePairForAnnotation :: Env -> AlgebraContext p -> ScopeContext p -> NodeId -> EdgeId -> Either ElabError (Maybe (ElabScheme, IntMap.IntMap TypeBinderRef))
sourceSchemePairForAnnotation env algebraContext scopeContext nodeId edgeId =
  case
      annotationExpectedTypeForEdge
        (algAnnotationContext algebraContext)
        edgeId
    of
    Just expectedTy -> do
      let annotationScheme ty =
            normalizeSchemeSubstPair
              (sourceAnnotationSchemeAgainstEnv env ty, IntMap.empty)
          fallback = annotationScheme expectedTy
      pure $
        case reifyNodeTypePreferringBound scopeContext nodeId of
          Right ty@TMuRef {} -> Just (annotationScheme ty)
          _ -> Just fallback
    Nothing -> pure Nothing

sourceSchemePairForExactLambdaParamNode :: AlgebraContext p -> NodeId -> Either ElabError (Maybe (ElabScheme, IntMap.IntMap TypeBinderRef))
sourceSchemePairForExactLambdaParamNode algebraContext nodeId =
  case
      IntMap.lookup
        (getNodeId nodeId)
        (algExactLambdaParamSourceTypes algebraContext)
    of
    Just srcTy -> do
      ty <- srcTypeToElabType algebraContext srcTy
      pure (Just (schemeFromType ty, IntMap.empty))
    Nothing -> pure Nothing

sourceSchemePairForOuterAnnotation :: Env -> AlgebraContext p -> ScopeContext p -> AnnExpr -> Either ElabError (Maybe (ElabScheme, IntMap.IntMap TypeBinderRef))
sourceSchemePairForOuterAnnotation env algebraContext scopeContext annExpr =
  case annExpr of
    AAnn _ annNodeId edgeId -> sourceSchemePairForAnnotation env algebraContext scopeContext annNodeId edgeId
    AExactAnn _ _ annNodeId edgeId -> sourceSchemePairForAnnotation env algebraContext scopeContext annNodeId edgeId
    ALetScope inner _ _ -> sourceSchemePairForOuterAnnotation env algebraContext scopeContext inner
    AUnfold (AAnn _ annNodeId edgeId) _ _ -> sourceSchemePairForAnnotation env algebraContext scopeContext annNodeId edgeId
    AUnfold (AExactAnn _ _ annNodeId edgeId) _ _ -> sourceSchemePairForAnnotation env algebraContext scopeContext annNodeId edgeId
    _ -> pure Nothing

-- | Find the exact boundary that owns one delayed subterm result.  Only the
-- result-producing path is relevant to a surrounding let scheme: lambda bodies
-- and let bodies retain the enclosing expression's result, while application
-- children and let RHSs do not.
compilerExactBoundarySubject
  :: EdgeId
  -> AnnExpr
  -> Maybe (AnnExpr, ResolvedSrcType)
compilerExactBoundarySubject exactEdge annExpr =
  case annExpr of
    AExactAnn inner exactTy _ edge
      | edge == exactEdge -> Just (inner, exactTy)
      | otherwise -> compilerExactBoundarySubject exactEdge inner
    AAnn inner _ _ -> compilerExactBoundarySubject exactEdge inner
    ALam _ _ _ _ body _ _ -> compilerExactBoundarySubject exactEdge body
    ALet _ _ _ _ _ _ _ body _ -> compilerExactBoundarySubject exactEdge body
    ALetScope inner _ _ -> compilerExactBoundarySubject exactEdge inner
    AUnfold inner _ _ -> compilerExactBoundarySubject exactEdge inner
    _ -> Nothing

-- | Compose a transparent RHS lambda's completed local Gamma into the scheme
-- published by its enclosing let.  The source tree proves that the lambda is
-- on the RHS result path; the prepared packet proves the exact result binder
-- and graph routes.  Performing the quotient here makes the ELet scheme and
-- the RHS type abstractions share one identity by construction.
composeTransparentRhsCompletedGamma
  :: String
  -> (NodeId -> NodeId)
  -> AnnExpr
  -> SubtermGeneralizations
  -> SchemeInfo
  -> Either ElabError (Set.Set TypeBinderIdentity, SchemeInfo)
composeTransparentRhsCompletedGamma binding representative rhsAnn packets baseSchemeInfo =
  case subtermResultOwnershipFor rhsAnn packets of
    Nothing -> pure (Set.empty, baseSchemeInfo)
    Just ownership
      | not (subtermResultOwnershipHasTransparentPath ownership) ->
          pure (Set.empty, baseSchemeInfo)
      | otherwise ->
          let packet = subtermResultOwnershipPacket ownership
           in case subtermGeneralizationGammaAuthority packet of
                Nothing -> pure (Set.empty, baseSchemeInfo)
                Just _ -> composePacket packet
  where
    composePacket packet = do
      resultRef <-
        case subtermGeneralizationConstructionResultAbstractionRef packet of
          Nothing ->
            Left
              ( ValidationFailed
                  [ "transparent RHS Gamma packet has no result abstraction"
                  , "  binding: " ++ binding
                  ]
              )
          Just ref -> pure ref
      let packetSchemeInfo = subtermGeneralizationSchemeInfo packet
          packetBinders = schemeBinderRefs (siScheme packetSchemeInfo)
          baseBinders = schemeBinderRefs (siScheme baseSchemeInfo)
      constructionBinders <-
        mergeCompletedBinders baseBinders packetBinders
      mbResultBinder <-
        case
            [ binder
            | binder@(ref, _) <- constructionBinders
            , typeBinderRefsSameIdentity ref resultRef
            ]
          of
            [binder] -> pure (Just binder)
            []
              | transparentResultResolvedByEnclosingScheme
                  representative
                  packetSchemeInfo
                  resultRef
                  baseSchemeInfo ->
                  pure Nothing
            [] ->
              Left
                ( ValidationFailed
                    [ "transparent RHS Gamma result is absent from its completed construction scheme"
                    , "  binding: " ++ binding
                    , "  result: " ++ show resultRef
                    , "  packet scheme: " ++ show (siScheme packetSchemeInfo)
                    , "  packet operated scheme: "
                        ++ show (siScheme (subtermGeneralizationOperatedSchemeInfo packet))
                    , "  packet Gamma bound: "
                        ++ show (subtermGeneralizationGammaBoundScheme packet)
                    , "  enclosing scheme: " ++ show (siScheme baseSchemeInfo)
                    ]
                )
            binders ->
              Left
                ( ValidationFailed
                    [ "transparent RHS Gamma result is declared more than once"
                    , "  binding: " ++ binding
                    , "  result: " ++ show resultRef
                    , "  declarations: " ++ show binders
                    ]
                )
      case mbResultBinder of
        Nothing ->
          -- The enclosing closed/routed scheme, not this packet, owns the
          -- result completion.  Retain that exact identity as construction
          -- evidence so the RHS constructor consumes its provisional Gamma
          -- abstraction instead of publishing it outside the let.
          pure
            ( Set.singleton (typeBinderRefIdentity resultRef)
            , baseSchemeInfo
            )
        Just resultBinder -> do
          let requiredConstructionBinders =
                packetBinderDependencyClosure constructionBinders resultBinder
              requiredConstructionRefs = map fst requiredConstructionBinders
              retainedPacketBinders =
                [ binder
                | binder@(ref, _) <- packetBinders
                , refMember ref requiredConstructionRefs
                ]
              packetOwnedRoutes =
                IntMap.filter
                  (\ref -> refMember ref requiredConstructionRefs)
                  (schemeInfoBinderRefSubst packetSchemeInfo)
              baseRoutes = schemeInfoBinderRefSubst baseSchemeInfo
          baseRenames <-
            sharedConstructionRouteRenames
              ("transparent RHS Gamma for let " ++ binding)
              packetOwnedRoutes
              baseRoutes
          let renamedBase = applySchemeInfoRefRenames baseRenames baseSchemeInfo
          mergedBinders <-
            mergeCompletedBinders
              (schemeBinderRefs (siScheme renamedBase))
              retainedPacketBinders
          let mergedRoutes =
                IntMap.union
                  packetOwnedRoutes
                  (schemeInfoBinderRefSubst renamedBase)
              mergedSchemeInfo =
                schemeInfoFromRefSubst
                  ( mkElabSchemeWithRefs
                      mergedBinders
                      (schemeBody (siScheme renamedBase))
                  )
                  mergedRoutes
          ordered <-
            orderConstructionSchemeInfoBinders
              ("transparent RHS Gamma for let " ++ binding)
              mergedSchemeInfo
          pure
            ( Set.fromList (map (typeBinderRefIdentity . fst) requiredConstructionBinders)
            , ordered
            )

    packetBinderDependencyClosure packetBinders resultBinder =
      [ binder
      | binder@(ref, _) <- packetBinders
      , refMember ref requiredRefs
      ]
      where
        requiredRefs = close [fst resultBinder]
        close refs =
          let dependencies =
                [ dependency
                | (ref, Just bound) <- packetBinders
                , refMember ref refs
                , dependency <- freeTypeVarRefsType (tyToElab bound)
                , any (typeBinderRefsSameIdentity dependency . fst) packetBinders
                ]
              refs' = foldr insertRef refs dependencies
           in if length refs' == length refs then refs else close refs'

    mergeCompletedBinders baseBinders packetBinders =
      foldM mergeBinder [] (baseBinders ++ packetBinders)
      where
        mergeBinder merged binder@(ref, incomingBound) =
          case break (typeBinderRefsSameIdentity ref . fst) merged of
            (_, []) -> pure (merged ++ [binder])
            (before, (existingRef, existingBound) : after) -> do
              mergedBinder <-
                mergeSameIdentityBinder
                  existingRef
                  existingBound
                  ref
                  incomingBound
              pure (before ++ (mergedBinder : after))

        mergeSameIdentityBinder existingRef existingBound incomingRef incomingBound =
          case (existingBound, incomingBound) of
            (Nothing, Nothing) -> pure (existingRef, Nothing)
            (Just _, Nothing) -> pure (existingRef, existingBound)
            (Nothing, Just _) -> pure (incomingRef, incomingBound)
            (Just existing, Just incoming)
              | boundsAgree existing incoming ->
                  pure (incomingRef, incomingBound)
              | otherwise ->
                  Left
                    ( ValidationFailed
                        [ "transparent RHS Gamma supplies conflicting completed bounds"
                        , "  binding: " ++ binding
                        , "  binder: " ++ show incomingRef
                        , "  let bound: " ++ show existingBound
                        , "  packet bound: " ++ show incomingBound
                        ]
                    )

        boundsAgree left right =
          let leftTy = tyToElab left
              rightTy = tyToElab right
           in alphaEqType leftTy rightTy || churchAwareEqType leftTy rightTy

    insertRef ref refs
      | refMember ref refs = refs
      | otherwise = ref : refs

    refMember ref = any (typeBinderRefsSameIdentity ref)

-- | Join two prepared identity views through their shared graph-node routes.
-- The preferred view owns the outward construction identity; the existing
-- view is renamed into it.  This is used both while composing a transparent
-- RHS packet and while aligning the source-declared let ABI to that completed
-- packet.  Deriving both from one function prevents those two consumers from
-- publishing different identities for the same graph occurrence.
sharedConstructionRouteRenames
  :: String
  -> IntMap.IntMap TypeBinderRef
  -> IntMap.IntMap TypeBinderRef
  -> Either ElabError [(TypeBinderRef, TypeBinderRef)]
sharedConstructionRouteRenames context preferredRoutes existingRoutes =
  foldM insertRename [] rawRenames
  where
    rawRenames =
      [ (existingRef, preferredRef)
      | (nodeKey, preferredRef) <- IntMap.toList preferredRoutes
      , Just existingRef <- [IntMap.lookup nodeKey existingRoutes]
      , not (typeBinderRefsSameIdentity existingRef preferredRef)
      ]

    insertRename renames rename@(existingRef, preferredRef) =
      case
          [ existingTarget
          | (priorExisting, existingTarget) <- renames
          , typeBinderRefsSameIdentity priorExisting existingRef
          ]
        of
          [] -> pure (renames ++ [rename])
          targets
            | all (typeBinderRefsSameIdentity preferredRef) targets ->
                pure renames
            | otherwise ->
                Left
                  ( ValidationFailed
                      [ "one construction binder routes to multiple outward identities"
                      , "  context: " ++ context
                      , "  existing binder: " ++ show existingRef
                      , "  outward binders: " ++ show (preferredRef : targets)
                      ]
                  )

-- | Lift a body-level compiler-exact packet through its resolved lambda owner.
-- The exact source type owns every enclosing arrow.  The packet owns the one
-- codomain transition from the operated type to its pending Gamma result.  By
-- composing those authorities before term elaboration, ALet never has to infer
-- a replacement scheme from a completed term or a type-checking failure.
compilerExactOwnerSchemeInfo
  :: ScopeContext p
  -> ResolvedTermIdentityKey
  -> PreparedSubtermGeneralization
  -> AnnExpr
  -> ElabType
  -> Either ElabError SchemeInfo
compilerExactOwnerSchemeInfo scopeContext owner packet exactSubject exactType = do
  resultRef <-
    case subtermGeneralizationCompilerExactResultRef packet of
      Just ref -> pure ref
      Nothing ->
        Left
          ( ValidationFailed
              [ "compiler exact packet has no delayed Gamma result"
              , "  owner: " ++ show owner
              ]
          )
  resultOperatedType <-
    case
        [ mbBound
        | (binderRef, mbBound) <-
            schemeBinderRefs
              (siScheme (subtermGeneralizationSchemeInfo packet))
        , typeBinderRefsSameIdentity binderRef resultRef
        ]
      of
        [Just bound] -> pure (tyToElab bound)
        [Nothing] ->
          Left
            ( ValidationFailed
                [ "compiler exact delayed Gamma result has no operated bound"
                , "  owner: " ++ show owner
                , "  result: " ++ show resultRef
                ]
            )
        [] ->
          Left
            ( ValidationFailed
                [ "compiler exact delayed Gamma result is absent from its packet"
                , "  owner: " ++ show owner
                , "  result: " ++ show resultRef
                ]
            )
        _ ->
          Left
            ( ValidationFailed
                [ "compiler exact delayed Gamma result occurs more than once in its packet"
                , "  owner: " ++ show owner
                , "  result: " ++ show resultRef
                ]
            )
  liftedType <- liftAtOwner resultRef resultOperatedType exactSubject exactType
  let (exactBinders, liftedBody) = splitForallsRefs liftedType
      packetSchemeInfo = subtermGeneralizationSchemeInfo packet
      packetBinders = schemeBinderRefs (siScheme packetSchemeInfo)
  (mergedBinders, packetRefRenames) <-
    mergeBinderSpines packetSchemeInfo liftedBody exactBinders packetBinders
  let constructionSubst =
        IntMap.map
          (applyRefRenames packetRefRenames)
          (schemeInfoBinderRefSubst packetSchemeInfo)
      operatedSubstRaw =
        IntMap.map
          (applyRefRenames packetRefRenames)
          ( schemeInfoBinderRefSubst
              (subtermGeneralizationOperatedSchemeInfo packet)
          )
  operatedSubst <-
    IntMap.traverseWithKey
      (projectOperatedRoute mergedBinders constructionSubst)
      operatedSubstRaw
  exactSubst <-
    foldM
      (\subst (nodeKey, operatedRef) ->
        case IntMap.lookup nodeKey subst of
          Nothing -> pure (IntMap.insert nodeKey operatedRef subst)
          Just constructionRef
            | typeBinderRefsSameIdentity constructionRef operatedRef -> pure subst
            | otherwise ->
                Left
                  ( ValidationFailed
                      [ "compiler exact construction and operated packet disagree on a binder route"
                      , "  owner: " ++ show owner
                      , "  graph node: " ++ show (NodeId nodeKey)
                      , "  construction ref: " ++ show constructionRef
                      , "  operated ref: " ++ show operatedRef
                      ]
                  )
      )
      constructionSubst
      (IntMap.toList operatedSubst)
  pure
    ( schemeInfoFromRefSubst
        (mkElabSchemeWithRefs mergedBinders liftedBody)
        exactSubst
    )
  where
    typesAgree left right =
      scopedTypesAgree scopeContext left right
        || alphaEqType left right
        || churchAwareEqType left right

    -- The construction packet has already published the outward binder for
    -- each graph class.  Quotient every operated route through that same
    -- authority before the substitutions are merged.  A graph-backed ref is
    -- authoritative only when it is an actual binder of the merged scheme;
    -- arbitrary aliases in the same solved class are not enough.
    projectOperatedRoute mergedBinders constructionSubst nodeKey operatedRef = do
      case typeBinderRefNode operatedRef of
        Just operatedNode
          | routeRepresentative operatedNode /= routeRepresentative (NodeId nodeKey) ->
              Left
                ( ValidationFailed
                    [ "compiler exact operated route crosses graph classes"
                    , "  owner: " ++ show owner
                    , "  graph node: " ++ show (NodeId nodeKey)
                    , "  operated ref: " ++ show operatedRef
                    ]
                )
        _ -> pure ()
      constructionCandidates <-
        concat
          <$> traverse
            publishedCandidate
            [ (NodeId constructionKey, constructionRef)
            | (constructionKey, constructionRef) <- IntMap.toList constructionSubst
            , routeRepresentative (NodeId constructionKey) == routeRepresentative (NodeId nodeKey)
            ]
      case constructionCandidates of
        [] -> pure operatedRef
        candidate : rest
          | all (typeBinderRefsSameIdentity candidate) rest -> pure candidate
          | otherwise ->
              Left
                ( ValidationFailed
                    [ "compiler exact graph class routes to multiple construction binder identities"
                    , "  owner: " ++ show owner
                    , "  operated graph node: " ++ show (NodeId nodeKey)
                    , "  operated ref: " ++ show operatedRef
                    , "  candidates: " ++ show constructionCandidates
                    ]
                )
      where
        routeRepresentative =
          scopeTypeBinderIdentityRepresentative scopeContext

        publishedCandidate (constructionNode, constructionRef) =
          case typeBinderRefNode constructionRef of
            Nothing -> pure [constructionRef]
            Just refNode
              | routeRepresentative refNode /= routeRepresentative constructionNode ->
                  Left
                    ( ValidationFailed
                        [ "compiler exact construction route crosses graph classes"
                        , "  owner: " ++ show owner
                        , "  graph node: " ++ show constructionNode
                        , "  construction ref: " ++ show constructionRef
                        ]
                    )
              | otherwise ->
                  case
                      [ publishedRef
                      | (publishedRef, _) <- mergedBinders
                      , typeBinderRefsSameIdentity constructionRef publishedRef
                      ]
                    of
                      [] -> pure []
                      [publishedRef] -> pure [publishedRef]
                      publishedRefs ->
                        Left
                          ( ValidationFailed
                              [ "compiler exact construction repeats one published binder identity"
                              , "  owner: " ++ show owner
                              , "  construction ref: " ++ show constructionRef
                              , "  published refs: " ++ show publishedRefs
                              ]
                          )

    liftAtOwner resultRef resultOperatedType expr ty =
      case ty of
        TForallRef ref mbBound body ->
          TForallRef ref mbBound
            <$> liftAtOwner resultRef resultOperatedType expr body
        _ ->
          case expr of
            AAnn inner _ _ -> liftAtOwner resultRef resultOperatedType inner ty
            AExactAnn inner _ _ _ -> liftAtOwner resultRef resultOperatedType inner ty
            ALet _ _ _ _ _ _ _ body _ -> liftAtOwner resultRef resultOperatedType body ty
            ALetScope inner _ _ -> liftAtOwner resultRef resultOperatedType inner ty
            AUnfold inner _ _ -> liftAtOwner resultRef resultOperatedType inner ty
            ALam _ details _ _ body _ _ ->
              case ty of
                TArrow domain codomain
                  | idDetailsIdentityKey details == owner ->
                      if typesAgree codomain resultOperatedType
                        then pure (TArrow domain (TVarRef resultRef))
                        else
                          Left
                            ( ValidationFailed
                                [ "compiler exact owner codomain does not equal its operated packet"
                                , "  owner: " ++ show owner
                                , "  exact codomain: " ++ show codomain
                                , "  operated result type: " ++ show resultOperatedType
                                , "  packet scheme: "
                                    ++ show (siScheme (subtermGeneralizationSchemeInfo packet))
                                , "  exact type: " ++ show exactType
                                ]
                            )
                  | otherwise ->
                      TArrow domain
                        <$> liftAtOwner resultRef resultOperatedType body codomain
                _ ->
                  Left
                    ( ValidationFailed
                        [ "compiler exact owner path does not match the exact source type"
                        , "  owner: " ++ show owner
                        , "  expression: " ++ show expr
                        , "  type: " ++ show ty
                        ]
                    )
            _ ->
              Left
                ( ValidationFailed
                    [ "compiler exact result owner is absent from the exact subject path"
                    , "  owner: " ++ show owner
                    , "  expression: " ++ show expr
                    ]
                )

    mergeBinderSpines packetSchemeInfo liftedBody exactBinders packetBinders = do
      exactBinders' <- traverse preferPacketBinder exactBinders
      let exactRefs = map fst exactBinders'
          packetOnlyRaw =
            [ binder
            | binder@(ref, _) <- packetBinders
            , not (any (typeBinderRefsSameIdentity ref) exactRefs)
            ]
          packetOnly =
            retainLivePacketBinders
              ( freeTypeVarRefsType liftedBody
                  ++ concatMap (maybe [] (freeTypeVarRefsType . tyToElab) . snd) exactBinders'
              )
              packetOnlyRaw
          droppedPacketBinders =
            [ binder
            | binder@(ref, _) <- packetOnlyRaw
            , not (any (typeBinderRefsSameIdentity ref . fst) packetOnly)
            , any
                (typeBinderRefsSameIdentity ref)
                (IntMap.elems (schemeInfoBinderRefSubst packetSchemeInfo))
            ]
          exactOnlyBinders =
            [ binder
            | binder@(ref, _) <- exactBinders'
            , not (any (typeBinderRefsSameIdentity ref . fst) packetBinders)
            ]
          packetPayloadRefs =
            freeTypeVarRefsType (schemeBody (siScheme packetSchemeInfo))
              ++ concatMap
                (maybe [] (freeTypeVarRefsType . tyToElab) . snd)
                packetBinders
          carriedExactBinders =
            [ binder
            | binder@(ref, _) <- exactOnlyBinders
            , any (typeBinderRefsSameIdentity ref) packetPayloadRefs
            ]
          exactCandidates
            | length carriedExactBinders == length droppedPacketBinders =
                carriedExactBinders
            | length exactOnlyBinders == length droppedPacketBinders =
                exactOnlyBinders
            | otherwise = []
      packetRefRenames <-
        if null droppedPacketBinders
          then pure []
          else
            if length exactCandidates /= length droppedPacketBinders
              then
                Left
                  ( ValidationFailed
                      [ "compiler exact source cannot account for dropped packet binders"
                      , "  owner: " ++ show owner
                      , "  exact-only binders: " ++ show exactOnlyBinders
                      , "  dropped packet binders: " ++ show droppedPacketBinders
                      ]
                  )
              else traverse alignDroppedBinder (zip droppedPacketBinders exactCandidates)
      pure (exactBinders' ++ packetOnly, packetRefRenames)
      where
        alignDroppedBinder ((packetRef, packetBound), (exactRef, exactBound))
          | boundsAgree packetBound exactBound = pure (packetRef, exactRef)
          | otherwise =
              Left
                ( ValidationFailed
                    [ "compiler exact source and dropped packet binder disagree on their bound"
                    , "  owner: " ++ show owner
                    , "  packet binder: " ++ show packetRef
                    , "  packet bound: " ++ show packetBound
                    , "  exact binder: " ++ show exactRef
                    , "  exact bound: " ++ show exactBound
                    ]
                )

        retainLivePacketBinders initialLive binders =
          fst (foldr retain ([], initialLive) binders)

        retain binder@(ref, mbBound) (kept, liveRefs)
          | any (typeBinderRefsSameIdentity ref) liveRefs =
              ( binder : kept
              , maybe liveRefs
                  ((++ liveRefs) . freeTypeVarRefsType . tyToElab)
                  mbBound
              )
          | otherwise = (kept, liveRefs)

        preferPacketBinder exactBinder@(exactRef, exactBound) =
          case
              [ packetBinder
              | packetBinder@(packetRef, _) <- packetBinders
              , typeBinderRefsSameIdentity exactRef packetRef
              ]
            of
              [] -> pure exactBinder
              [packetBinder@(_, packetBound)]
                | boundsAgree exactBound packetBound -> pure packetBinder
                | otherwise ->
                    Left
                      ( ValidationFailed
                          [ "compiler exact source and packet disagree on a shared binder bound"
                          , "  binder: " ++ show exactRef
                          , "  exact bound: " ++ show exactBound
                          , "  packet bound: " ++ show packetBound
                          ]
                      )
              _ ->
                Left
                  ( ValidationFailed
                      [ "compiler exact packet repeats a source binder identity"
                      , "  binder: " ++ show exactRef
                      ]
                  )

        boundsAgree Nothing Nothing = True
        boundsAgree (Just left) (Just right) =
          typesAgree (tyToElab left) (tyToElab right)
        boundsAgree _ _ = False

lookupAliasTarget :: BindingKey -> Env -> Maybe BindingKey
lookupAliasTarget key env = lookupEnvBindingForKey key env >>= ebAliasTarget

resolveAliasKey :: Env -> BindingKey -> BindingKey
resolveAliasKey env key =
  case lookupAliasTarget key env of
    Just target -> resolveAliasKey env target
    Nothing -> key

isTransparentMediatorKey :: BindingKey -> Env -> Bool
isTransparentMediatorKey key env =
  maybe False (isJust . ebTransparentMediator) (lookupEnvBindingForKey key env)

transparentMediatorArity :: Env -> AnnExpr -> Maybe Int
transparentMediatorArity env ann = do
  key <- directAnnReferenceKey (stripAnnExpr ann)
  binding <- lookupEnvBindingForKey key env
  case ebTransparentMediator binding of
    Just DirectIdentityMediator -> Just 0
    Just (EtaTransparentMediator arity) -> Just arity
    Nothing -> Nothing

-- | Display names already owned by lexical Gamma, excluding any construction
-- identities that the current boundary has proved it owns itself.
freeTypeVarsEnvSchemesExceptIdentities
  :: Set.Set TypeBinderIdentity
  -> Env
  -> Set.Set String
freeTypeVarsEnvSchemesExceptIdentities excludedIdentities env =
  Set.unions
    [ typeBinderRefAliasNames ref
    | ref <- envFreeRefs
    , Set.notMember (typeBinderRefIdentity ref) excludedIdentities
    ]
  where
    envFreeRefs =
      Map.keys (envTypeBindings env)
        ++ concatMap
          (freeTypeVarRefsType . ebSchemeType)
          (authoritativeEnvBindings env)

canonicalBinderRefPayloadRenames
  :: Env
  -> Set.Set String
  -> [TypeBinderRef]
  -> [(TypeBinderRef, TypeBinderRef)]
canonicalBinderRefPayloadRenames env additionallyReserved localRefs =
  [ (oldRef, newRef)
  | (oldRef, newRef) <- renames0
  , not (typeBinderRefsSameIdentityAndName oldRef newRef)
  ]
  where
    localIdentities = Set.fromList (map typeBinderRefIdentity localRefs)
    reservedNames =
      Set.union
        additionallyReserved
        (freeTypeVarsEnvSchemesExceptIdentities localIdentities env)
    (_, renames0) =
      mapAccumL allocateCanonicalName (reservedNames, 0 :: Int) localRefs

    allocateCanonicalName (used, nextIndex) ref =
      let (chosenName, followingIndex) = nextAlphaName used nextIndex
          renamedRef = renameTypeBinderRef chosenName ref
          used' = Set.union used (typeBinderRefAliasNames renamedRef)
       in ((used', followingIndex), (ref, renamedRef))

    nextAlphaName used index
      | Set.member candidate used = nextAlphaName used (index + 1)
      | otherwise = (candidate, index + 1)
      where
        candidate = alphaName index 0

renamePublishedRef
  :: [(TypeBinderRef, TypeBinderRef)]
  -> TypeBinderRef
  -> TypeBinderRef
renamePublishedRef renames ref =
  fromMaybe ref
    ( snd
        <$> find
          (typeBinderRefsSameIdentity ref . fst)
          renames
    )

-- A construction quotient can map several graph occurrences to one exact
-- source declaration. Certificate dependency fields are sets represented as
-- lists, so normalize them immediately after renaming.
distinctBinderRefs :: [TypeBinderRef] -> [TypeBinderRef]
distinctBinderRefs =
  foldl'
    ( \refs ref ->
        if any (typeBinderRefsSameIdentity ref) refs
          then refs
          else refs ++ [ref]
    )
    []

duplicateBinderDeclarations
  :: [(TypeBinderRef, Maybe BoundType)]
  -> [ ( (TypeBinderRef, Maybe BoundType)
       , (TypeBinderRef, Maybe BoundType)
       )
     ]
duplicateBinderDeclarations binders =
  [ (leftBinder, rightBinder)
  | (index, leftBinder@(leftRef, _)) <- zip [0 :: Int ..] binders
  , rightBinder@(rightRef, _) <- drop (index + 1) binders
  , typeBinderRefsSameIdentity leftRef rightRef
  ]

renameExactResultConstructionBinderRefPayloads
  :: [(TypeBinderRef, TypeBinderRef)]
  -> ExactResultConstruction
  -> ExactResultConstruction
renameExactResultConstructionBinderRefPayloads renames construction =
  construction
    { ercConstructedType =
        renameTypeBinderRefPayloads
          renames
          (ercConstructedType construction)
    , ercConstructedBinders =
        [ ( renamePublishedRef renames ref
          , fmap
              (renameBoundTypeBinderRefPayloads renames)
              mbBound
          )
        | (ref, mbBound) <- ercConstructedBinders construction
        ]
    , ercBinderRoutes =
        IntMap.map
          (renamePublishedRef renames)
          (ercBinderRoutes construction)
    , ercTypeAbstractionRefs =
        distinctBinderRefs
          (map (renamePublishedRef renames) (ercTypeAbstractionRefs construction))
    , ercOpenValueLambdaParameterRefs =
        distinctBinderRefs
          ( map
              (renamePublishedRef renames)
              (ercOpenValueLambdaParameterRefs construction)
          )
    , ercReturnedResultConstruction =
        renameExactResultConstructionBinderRefPayloads renames
          <$> ercReturnedResultConstruction construction
    }

renameOwnerFinalConstructionBinderRefPayloads
  :: [(TypeBinderRef, TypeBinderRef)]
  -> OwnerFinalConstruction
  -> OwnerFinalConstruction
renameOwnerFinalConstructionBinderRefPayloads renames ownerCertificate =
  ownerCertificate
    { ofcConstructedType =
        renameTypeBinderRefPayloads
          renames
          (ofcConstructedType ownerCertificate)
    , ofcExactEndpointCompletion =
        renameExactEndpointCompletionBinderRefPayloads renames
          <$> ofcExactEndpointCompletion ownerCertificate
    , ofcLocallyEmittedBinders =
        [ ( renamePublishedRef renames ref
          , fmap
              (renameBoundTypeBinderRefPayloads renames)
              mbBound
          )
        | (ref, mbBound) <- ofcLocallyEmittedBinders ownerCertificate
        ]
    , ofcConsumedLocalBinders =
        [ ( renamePublishedRef renames ref
          , fmap
              (renameBoundTypeBinderRefPayloads renames)
              mbBound
          )
        | (ref, mbBound) <- ofcConsumedLocalBinders ownerCertificate
        ]
    , ofcLocalBinderRoutes =
        IntMap.map (renamePublishedRef renames) (ofcLocalBinderRoutes ownerCertificate)
    , ofcCarriedResultBinders =
        [ ( renamePublishedRef renames ref
          , fmap
              (renameBoundTypeBinderRefPayloads renames)
              mbBound
          )
        | (ref, mbBound) <- ofcCarriedResultBinders ownerCertificate
        ]
    , ofcCarriedResultBinderRoutes =
        IntMap.map
          (renamePublishedRef renames)
          (ofcCarriedResultBinderRoutes ownerCertificate)
    , ofcCarriedResultTypeAbstractionRefs =
        distinctBinderRefs
          ( map
              (renamePublishedRef renames)
              (ofcCarriedResultTypeAbstractionRefs ownerCertificate)
          )
    , ofcReturnedResultConstruction =
        renameExactResultConstructionBinderRefPayloads renames
          <$> ofcReturnedResultConstruction ownerCertificate
    , ofcUsedAmbientBinderRefs =
        distinctBinderRefs
          ( map
              (renamePublishedRef renames)
              (ofcUsedAmbientBinderRefs ownerCertificate)
          )
    , ofcUsedSourceBinderAuthorities =
        IntMap.map
          ( mapSourceBinderAuthorityConstructionRef
              (renamePublishedRef renames)
          )
          (ofcUsedSourceBinderAuthorities ownerCertificate)
    , ofcAmbientDeclarationAuthorities =
        map
          ( \authority ->
              authority
                { agaExactRef =
                    renamePublishedRef
                      renames
                      (agaExactRef authority)
                , agaBound =
                    renameTypeBinderRefPayloads
                      renames
                      (agaBound authority)
                }
          )
          (ofcAmbientDeclarationAuthorities ownerCertificate)
    , ofcAuthoritativeAmbientDeclarations =
        map
          ( \authority ->
              authority
                { agaExactRef =
                    renamePublishedRef
                      renames
                      (agaExactRef authority)
                , agaBound =
                    renameTypeBinderRefPayloads
                      renames
                      (agaBound authority)
                }
          )
          (ofcAuthoritativeAmbientDeclarations ownerCertificate)
    , ofcLambdaParamBoundaryCertificates =
        map
          (renameLambdaParamBoundaryCertificate renames)
          (ofcLambdaParamBoundaryCertificates ownerCertificate)
    , ofcOwnLambdaParamBoundaryCertificate =
        renameLambdaParamBoundaryCertificate renames
          <$> ofcOwnLambdaParamBoundaryCertificate ownerCertificate
    , ofcOpenValueLambdaParameterRefs =
        distinctBinderRefs
          ( map
              (renamePublishedRef renames)
              (ofcOpenValueLambdaParameterRefs ownerCertificate)
          )
    , ofcBodyConsumerBoundRefinements =
        map
          (renameBodyConsumerBoundRefinementCertificate renames)
          (ofcBodyConsumerBoundRefinements ownerCertificate)
    }

renameExactEndpointCompletionBinderRefPayloads
  :: [(TypeBinderRef, TypeBinderRef)]
  -> ExactEndpointCompletion
  -> ExactEndpointCompletion
renameExactEndpointCompletionBinderRefPayloads renames completion =
  completion
    { eecSourceEndpoint =
        renameTypeBinderRefPayloads
          renames
          (eecSourceEndpoint completion)
    , eecCompletedEndpoint =
        renameTypeBinderRefPayloads
          renames
          (eecCompletedEndpoint completion)
    }

renameLocalGammaConstructionCertificateBinderRefPayloads
  :: [(TypeBinderRef, TypeBinderRef)]
  -> LocalGammaConstructionCertificate
  -> LocalGammaConstructionCertificate
renameLocalGammaConstructionCertificateBinderRefPayloads renames localCertificate =
  localCertificate
    { lgccConstructedType =
        renameTypeBinderRefPayloads
          renames
          (lgccConstructedType localCertificate)
    , lgccConstruction =
        renameConstruction (lgccConstruction localCertificate)
    , lgccDirectApplicationGammaClaims =
        map
          renameDirectApplicationGammaClaim
          (lgccDirectApplicationGammaClaims localCertificate)
    , lgccDirectApplicationAmbientGammaClaims =
        map
          renameDirectApplicationAmbientGammaClaim
          (lgccDirectApplicationAmbientGammaClaims localCertificate)
    , lgccAmbientDeclarationAuthorities =
        map
          ( \authority ->
              authority
                { agaExactRef =
                    renamePublishedRef
                      renames
                      (agaExactRef authority)
                , agaBound =
                    renameTypeBinderRefPayloads
                      renames
                      (agaBound authority)
                }
          )
          (lgccAmbientDeclarationAuthorities localCertificate)
    , lgccLocalBinderRoutes =
        IntMap.map (renamePublishedRef renames) (lgccLocalBinderRoutes localCertificate)
    , lgccSourceBinderAuthorities =
        IntMap.map
          ( mapSourceBinderAuthorityConstructionRef
              (renamePublishedRef renames)
          )
          (lgccSourceBinderAuthorities localCertificate)
    , lgccUsedAmbientBinderRefs =
        distinctBinderRefs
          ( map
              (renamePublishedRef renames)
              (lgccUsedAmbientBinderRefs localCertificate)
          )
    , lgccEnclosingTypeAbsBinders =
        [ ( renamePublishedRef renames ref
          , fmap
              (renameBoundTypeBinderRefPayloads renames)
              mbBound
          )
        | (ref, mbBound) <-
            lgccEnclosingTypeAbsBinders localCertificate
        ]
    , lgccUsedSourceBinderAuthorities =
        IntMap.map
          ( mapSourceBinderAuthorityConstructionRef
              (renamePublishedRef renames)
          )
          (lgccUsedSourceBinderAuthorities localCertificate)
    }
  where
    renameConstruction construction =
      case construction of
        LocalGammaEmitted emitted consumed ->
          LocalGammaEmitted
            (fmap renameBinder emitted)
            (map renameBinder consumed)
        LocalGammaConsumed consumed ->
          LocalGammaConsumed (fmap renameBinder consumed)
        LocalGammaAmbient ->
          LocalGammaAmbient

    renameBinder (ref, mbBound) =
      ( renamePublishedRef renames ref
      , fmap
          (renameBoundTypeBinderRefPayloads renames)
          mbBound
      )

    renameDirectApplicationGammaClaim claim =
      claim
        { dagcOperatedType =
            renameTypeBinderRefPayloads
              renames
              (dagcOperatedType claim)
        , dagcBinderRef =
            renamePublishedRef renames (dagcBinderRef claim)
        , dagcConstructedBound =
            fmap
              (renameBoundTypeBinderRefPayloads renames)
              (dagcConstructedBound claim)
        }

    renameDirectApplicationAmbientGammaClaim claim =
      claim
        { daagcOperatedType =
            renameTypeBinderRefPayloads
              renames
              (daagcOperatedType claim)
        , daagcAmbientRef =
            renamePublishedRef renames (daagcAmbientRef claim)
        , daagcAmbientBound =
            renameTypeBinderRefPayloads
              renames
              (daagcAmbientBound claim)
        }

-- | Close application dependencies at the exact let-RHS type abstractions
-- that now enclose them. Applications are elaborated before the let scheme
-- is published, so a scheme binder is ambient while the open RHS is checked.
-- Once the finalized RHS starts with the matching 'ETyAbsRef' and has checked
-- at the published scheme, that declaration is local to the RHS rather than
-- ambient at the enclosing root.
--
-- Keep the declaration in the certificate instead of merely deleting the
-- ambient use. Root preparation can then validate the nested application
-- against the exact lexical binder while excluding it from root
-- generalization candidates.
closeApplicationCertificateDependenciesAtLetRhs
  :: ElabScheme
  -> XmlfTerm
  -> [LocalGammaConstructionCertificate]
  -> Either ElabError [LocalGammaConstructionCertificate]
closeApplicationCertificateDependenciesAtLetRhs publishedScheme rhsTerm =
  traverse closeCertificate
  where
    publishedBinders = schemeBinderRefs publishedScheme
    enclosingBinders =
      takePublishedPrefix (leadingTypeAbsBinders rhsTerm)

    takePublishedPrefix [] = []
    takePublishedPrefix (binder : rest)
      | any (bindersAgree binder) publishedBinders =
          binder : takePublishedPrefix rest
      | otherwise = []

    leadingTypeAbsBinders term =
      case term of
        ETyAbsRef ref mbBound body ->
          (ref, mbBound) : leadingTypeAbsBinders body
        _ -> []

    closeCertificate certificate = do
      closedBinders <-
        foldM
          (insertClosedBinder certificate)
          (lgccEnclosingTypeAbsBinders certificate)
          [ binder
          | binder@(ref, _) <- enclosingBinders
          , any
              (typeBinderRefsSameIdentity ref)
              (lgccUsedAmbientBinderRefs certificate)
          ]
      let closedRefs = map fst closedBinders
      pure
        certificate
          { lgccUsedAmbientBinderRefs =
              [ ref
              | ref <- lgccUsedAmbientBinderRefs certificate
              , not
                  ( any
                      (typeBinderRefsSameIdentity ref)
                      closedRefs
                  )
              ]
          , lgccEnclosingTypeAbsBinders = closedBinders
          }

    insertClosedBinder certificate closed incoming@(incomingRef, incomingBound) =
      case find
        (typeBinderRefsSameIdentity incomingRef . fst)
        closed
      of
        Nothing -> pure (closed ++ [incoming])
        Just (_, existingBound)
          | boundsAgree existingBound incomingBound -> pure closed
          | otherwise ->
              Left
                ( ValidationFailed
                    [ "one nested application dependency is closed by conflicting let-RHS declarations"
                    , "  owner: " ++ show (lgccOwner certificate)
                    , "  binder: " ++ show incomingRef
                    , "  first bound: " ++ show existingBound
                    , "  second bound: " ++ show incomingBound
                    , "  published scheme: " ++ show publishedScheme
                    ]
                )

    bindersAgree
      (leftRef, leftBound)
      (rightRef, rightBound) =
        typeBinderRefsSameIdentity leftRef rightRef
          && boundsAgree leftBound rightBound

    boundsAgree left right =
      let leftTy = maybe TBottom tyToElab left
          rightTy = maybe TBottom tyToElab right
       in alphaEqType leftTy rightTy
            || churchAwareEqType leftTy rightTy

renameElaboratedTermBinderRefPayloads
  :: [(TypeBinderRef, TypeBinderRef)]
  -> ElaboratedTerm
  -> ElaboratedTerm
renameElaboratedTermBinderRefPayloads renames detailed =
  (renameElaboratedConstructionEvidence renames detailed)
    { elaboratedTerm =
        renameTermTypeBinderRefPayloads
          renames
          (elaboratedTerm detailed)
    }

-- | Replay an identity route selected by a checked term construction on every
-- proof object carried beside that term.  Publication has already emitted the
-- corresponding type computation, so this operation deliberately leaves the
-- term untouched; applying the route to the term a second time would replace
-- the explicit computation by an unproved identity substitution.
renameElaboratedConstructionEvidence
  :: [(TypeBinderRef, TypeBinderRef)]
  -> ElaboratedTerm
  -> ElaboratedTerm
renameElaboratedConstructionEvidence renames detailed =
  detailed
    { elaboratedOwnerFinalConstruction =
        renameOwnerFinalConstructionBinderRefPayloads renames
          <$> elaboratedOwnerFinalConstruction detailed
    , elaboratedLocalGammaConstructionCertificates =
        map
          (renameLocalGammaConstructionCertificateBinderRefPayloads renames)
          (elaboratedLocalGammaConstructionCertificates detailed)
    , elaboratedCompilerExactResultBoundCertificates =
        map renameCompilerExactResultBoundCertificate
          (elaboratedCompilerExactResultBoundCertificates detailed)
    , elaboratedBodyConsumerBoundRefinements =
        map
          (renameBodyConsumerBoundRefinementCertificate renames)
          (elaboratedBodyConsumerBoundRefinements detailed)
    }
  where
    renameCompilerExactResultBoundCertificate certificate =
      certificate
        { cerbcResultRef =
            renamePublishedRef renames (cerbcResultRef certificate)
        , cerbcBound =
            renameTypeBinderRefPayloads renames (cerbcBound certificate)
        }

canonicalizePublishedSchemePair
  :: Env
  -> (ElabScheme, IntMap.IntMap TypeBinderRef)
  -> ( (ElabScheme, IntMap.IntMap TypeBinderRef)
     , [(TypeBinderRef, TypeBinderRef)]
     )
canonicalizePublishedSchemePair env (scheme, subst) =
  ( ( mkElabSchemeWithRefs
        [ ( renamePublishedRef renames ref
          , fmap
              (renameBoundTypeBinderRefPayloads renames)
              mbBound
          )
        | (ref, mbBound) <- schemeBinderRefs scheme
        ]
        (renameTypeBinderRefPayloads renames (schemeBody scheme))
    , IntMap.map (renamePublishedRef renames) subst
    )
  , renames
  )
  where
    renames =
      canonicalBinderRefPayloadRenames
        env
        Set.empty
        (map fst (schemeBinderRefs scheme))

-- | Publish a checked local constructor with canonical paper-order binder
-- names.  This is one atomic presentation change over the term and every
-- certificate that describes it; identities and ownership are unchanged.
canonicalizePublishedOwnerConstruction
  :: Env
  -> OwnerFinalConstruction
  -> ElaboratedTerm
  -> Either ElabError (ElaboratedTerm, OwnerFinalConstruction)
canonicalizePublishedOwnerConstruction env certificate elaboration =
  if Set.size localIdentities /= length localRefs
    then
      Left
        ( ValidationFailed
            [ "owner construction publishes one binder identity more than once"
            , "  owner: " ++ show (ofcOwner certificate)
            , "  binders: " ++ show localRefs
            ]
        )
    else
      pure
        ( renameElaboratedTermBinderRefPayloads renames elaboration
        , renameOwnerFinalConstructionBinderRefPayloads renames certificate
        )
  where
    localRefs = ofcLocallyEmittedBinderRefs certificate
    localIdentities = Set.fromList (map typeBinderRefIdentity localRefs)
    ambientAliases =
      Set.unions
        [ typeBinderRefAliasNames ref
        | ref <- ofcUsedAmbientBinderRefs certificate
        , Set.notMember (typeBinderRefIdentity ref) localIdentities
        ]
    renames =
      canonicalBinderRefPayloadRenames env ambientAliases localRefs

freeTypeVarRefsInOccurrenceOrder :: ElabType -> [TypeBinderRef]
freeTypeVarRefsInOccurrenceOrder ty0 = reverse (snd (goType [] [] [] ty0))
  where
    refMember ref =
      any (typeBinderRefsSameIdentity ref)

    addRef bound seen acc ref
      | refMember ref bound = (seen, acc)
      | refMember ref seen = (seen, acc)
      | otherwise = (ref : seen, ref : acc)

    goType bound seen acc ty =
      case ty of
        TVarRef ref -> addRef bound seen acc ref
        TArrow dom cod ->
          let (seen', acc') = goType bound seen acc dom
           in goType bound seen' acc' cod
        TConWithIdentity _ _ args ->
          foldl' (\(seen', acc') arg -> goType bound seen' acc' arg) (seen, acc) args
        TVarAppRef ref args ->
          let (seen', acc') = addRef bound seen acc ref
           in foldl' (\(seen'', acc'') arg -> goType bound seen'' acc'' arg) (seen', acc') args
        TForallRef ref mb body ->
          let (seen', acc') =
                maybe (seen, acc) (\boundTy -> goType bound seen acc (tyToElab boundTy)) mb
           in goType (ref : bound) seen' acc' body
        TMuRef ref body -> goType (ref : bound) seen acc body
        TBaseWithIdentity _ _ -> (seen, acc)
        TBottom -> (seen, acc)

{- Note [Let generalization is identity-relative]
~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
The scheme reconstructed for an inferred let can contain a binder whose
identity is already free in the lexical environment.  That binder represents
an outer type variable, even when its current display name is stale.  Keeping
it quantified changes @Gen(Gamma, tau)@ from

    forall (ftv(tau) \ ftv(Gamma)). tau

into an accidental re-generalization of the outer variable.

Apply the environment subtraction by 'TypeBinderIdentity' before doing the
separate display-name freshening below.  Graph identities are compared through
the solved-to-base identity representative, then the candidate type is aligned
to Gamma's authoritative, complete 'TypeBinderRef' before its quantifier is
removed.  Global redirect/UF canonicalization is insufficient here because
distinct solved copies of one lexical binder can remain in separate UF sets.
The base projection retains that source-identity provenance.  A same-named
binder with a distinct identity is still local and must remain quantified.  The
aligned ref remains in the scheme body and graph-ref substitution: only
ownership of its quantifier changes.
-}
-- | The type-binder identities already owned by the ambient paper Gamma.
-- Explicit type bindings carry their bounds directly.  A free identity in an
-- authoritative term binding is equally part of Gamma: for example, the
-- parameter @x : alpha@ proves that @alpha@ is in scope while elaborating the
-- lambda body.  Keeping both sources in one view lets Gen(Gamma, tau) and
-- boundaries that inherit the full Gamma use the same scope authority.
newtype EnvFreeTypeBinderRefs = EnvFreeTypeBinderRefs [TypeBinderRef]

envFreeTypeBinderRefs :: Env -> EnvFreeTypeBinderRefs
envFreeTypeBinderRefs env =
  EnvFreeTypeBinderRefs
    ( Map.keys (envTypeBindings env)
        ++ concatMap
          freeTypeVarRefsType
          (Map.elems (envTypeBindings env))
        ++ concatMap
          (freeTypeVarRefsType . ebSchemeType)
          (authoritativeEnvBindings env)
    )

-- | Exact explicit type-binder authority opened by the construction currently
-- being elaborated.  Lambda construction deliberately uses this narrower view:
-- packet aliases installed in 'envTypeBindings' describe the type scope opened
-- at that boundary, while its source/parameter packet rules own the separate
-- decision about which enclosing term-binding identities may be retained.
envAmbientTypeBinderRefs :: Env -> [TypeBinderRef]
envAmbientTypeBinderRefs = Map.keys . envTypeBindings

-- | The full paper Gamma inherited by a term boundary which introduces no type
-- binder of its own.  Applications (Figure 15.3.5) and let generalization both
-- inherit every type identity free in an authoritative enclosing term binding;
-- those identities must be supplied to construction generalization up front.
-- Lambdas intentionally keep their narrower explicit-type-binding view because
-- their parameter packet owns the separate decision about which term-binding
-- identities may escape.
envGeneralizationAmbientTypeBinderRefs :: Env -> [TypeBinderRef]
envGeneralizationAmbientTypeBinderRefs env =
  case envFreeTypeBinderRefs env of
    EnvFreeTypeBinderRefs refs -> refs

lookupEnvFreeTypeBinderRef
  :: (NodeId -> NodeId)
  -> EnvFreeTypeBinderRefs
  -> TypeBinderRef
  -> Maybe TypeBinderRef
lookupEnvFreeTypeBinderRef representative (EnvFreeTypeBinderRefs refs) ref =
  lookupRefByIdentityOrRepresentative representative refs ref

envContainsFreeTypeBinderRef
  :: (NodeId -> NodeId)
  -> EnvFreeTypeBinderRefs
  -> TypeBinderRef
  -> Bool
envContainsFreeTypeBinderRef representative refs =
  isJust . lookupEnvFreeTypeBinderRef representative refs

-- | Whether the ambient construction owns this exact outward identity, rather
-- than merely retaining its graph ref as an alias key for another binder.
-- 'extendEnvTypeScopeWithAliases' deliberately installs both forms in
-- 'envTypeBindings'; consulting that map alone would make a packet-local graph
-- exterior look ambient after it has been routed to a structural/source ref.
envOwnsExactTypeBinderRef :: Env -> TypeBinderRef -> Bool
envOwnsExactTypeBinderRef env ref =
  case envFreeTypeBinderRefs env of
    EnvFreeTypeBinderRefs ambientRefs ->
      any (typeBinderRefsSameIdentity ref) ambientRefs
        && case typeBinderRefNode ref of
          Just node ->
            maybe
              True
              (typeBinderRefsSameIdentity ref)
              (IntMap.lookup (getNodeId node) (envConstructionGammaAliases env))
          Nothing -> True

-- | An exact downward endpoint must be closed by the construction environment
-- that receives it.  A packet bound may still contain a provisional graph
-- reference whose declaration will only be completed from the checked child.
-- Such a type is useful checking topology, but it cannot direct an
-- application computation before that declaration exists.
envOwnsExactEndpointType :: Env -> ElabType -> Bool
envOwnsExactEndpointType env =
  all (envOwnsExactTypeBinderRef env) . freeTypeVarRefsType

endpointOwnedByConstructionEnv :: Env -> ElabType -> ExpectedTermEndpoint
endpointOwnedByConstructionEnv env ty
  | envOwnsExactEndpointType env ty =
      ExactConstructionExpectedTerm ty
  | otherwise = CheckingExpectedTerm ty

endpointRetainedByConstructionEnvExcept
  :: Set.Set TypeBinderIdentity
  -> Env
  -> ExpectedTermEndpoint
  -> ExpectedTermEndpoint
endpointRetainedByConstructionEnvExcept protectedIdentities env endpoint =
  case endpoint of
    CheckingExpectedTerm ty -> CheckingExpectedTerm ty
    ExactConstructionExpectedTerm ty ->
      retainExactEndpoint ExactConstructionExpectedTerm ty
    SourceLambdaValueExpectedTerm construction ty ->
      retainExactEndpoint
        (SourceLambdaValueExpectedTerm construction)
        ty
    AdministrativeLambdaBodyExpectedTerm construction ty ->
      -- The administrative constructor is itself the positive certificate
      -- for the exact child endpoint and the Gamma in which it is built.
      -- A source identity declared by a deeper annotation need not already
      -- be ambient at this enclosing lambda boundary.  Requiring ordinary
      -- Gamma ownership here would discard the certificate before the child
      -- can enter that declaration and would force a post-hoc forall move.
      -- Keep applying every admissible identity route, but retain exactness
      -- by construction rather than re-deriving it from the current Env.
      let (routedTy, _) = routeExactEndpoint ty
       in AdministrativeLambdaBodyExpectedTerm construction routedTy
  where
    retainExactEndpoint exactEndpoint ty =
      let (routedTy, retainedExactGraphRefs) = routeExactEndpoint ty
       in if
            all
              (\ref ->
                envOwnsExactTypeBinderRef env ref
                  || any
                    (typeBinderRefsSameIdentity ref)
                    retainedExactGraphRefs
              )
              (freeTypeVarRefsType routedTy)
            then exactEndpoint routedTy
            else CheckingExpectedTerm routedTy

    -- An incoming exact endpoint can still name the graph occurrence whose
    -- declaration has already been routed to an outward construction
    -- identity.  The route plus that exact outward declaration is positive
    -- Gamma authority for the occurrence: consume it before deciding whether
    -- the endpoint remains exact.  Otherwise a nested lambda first
    -- synthesizes a polymorphic codomain and only later tries to specialize
    -- beneath its arrow (the failing nested-let form of the paper's @g g@).
    -- A route is not admissible when its outward identity is already declared
    -- by a lexical forall/mu inside the same endpoint.  That situation occurs
    -- when several graph occurrences retain one source-binder provenance but
    -- live at different lexical scopes.  Reusing the outward ref would turn a
    -- free result occurrence into the private source binder.  The incoming
    -- exact endpoint plus its still-present graph declaration is the positive
    -- authority to keep that occurrence in the graph domain.
    routeExactEndpoint ty =
      ( applyTypeVarRefRenames admissibleRoutes ty
      , [ graphRef
        | (graphRef, outwardRef) <- candidateRoutes
        , routeIsProtected outwardRef
        , Map.member graphRef (envTypeBindings env)
        ]
      )
      where
        candidateRoutes =
          [ (graphRef, outwardRef)
          | graphRef <- freeTypeVarRefsType ty
          , Just outwardRef <- [constructionRoute graphRef]
          , not (typeBinderRefsSameIdentity graphRef outwardRef)
          ]
        admissibleRoutes =
          [ route
          | route@(_, outwardRef) <- candidateRoutes
          , envOwnsExactTypeBinderRef env outwardRef
          , not (routeIsProtected outwardRef)
          ]
        routeIsProtected outwardRef =
          Set.member
            (typeBinderRefIdentity outwardRef)
            protectedIdentities
            || routeConflictsWithLexicalDeclaration outwardRef
        routeConflictsWithLexicalDeclaration outwardRef =
          any
            (typeBinderRefsSameIdentity outwardRef)
            lexicalConstructionRefs
        lexicalConstructionRefs =
          [ fromMaybe declarationRef (constructionRoute declarationRef)
          | declarationRef <- typeBinderDeclarationRefs ty
          ]

    constructionRoute ref = do
      node <- typeBinderRefNode ref
      IntMap.lookup
        (getNodeId node)
        (envConstructionIdentityRoutes env)

generalizeSchemeInfoAgainstEnvExcept
  :: Set.Set TypeBinderIdentity
  -> (NodeId -> NodeId)
  -> Env
  -> SchemeInfo
  -> SchemeInfo
generalizeSchemeInfoAgainstEnvExcept protectedIdentities identityRepresentative env schemeInfo =
  let environmentRefs = envFreeTypeBinderRefs env
      scheme0 = siScheme schemeInfo
      binds0 = schemeBinderRefs scheme0
      -- Construction routes are an alias sidecar, not declarations in Gamma.
      -- In particular, compiler-exact edges install routes without publishing
      -- binders.  A route may therefore choose the ref used after subtraction
      -- only when the ambient environment owns that exact outward identity.
      authoritativeEnvRef ref =
        case typeBinderRefNode ref of
          Just node
            | Just constructionRef <-
                IntMap.lookup
                  (getNodeId node)
                  (envConstructionIdentityRoutes env),
              envOwnsExactTypeBinderRef env constructionRef ->
                Just constructionRef
          _ ->
            lookupEnvFreeTypeBinderRef
              identityRepresentative
              environmentRefs
              ref
      alignments =
        [ (ref, envRef)
          | (ref, _) <- binds0,
            Set.notMember (typeBinderRefIdentity ref) protectedIdentities,
            Just envRef <- [authoritativeEnvRef ref]
        ]
      binds =
        [ (ref, fmap (mapBoundType (applyTypeVarRefRenames alignments)) mbBound)
          | (ref, mbBound) <- binds0,
            not (any (typeBinderRefsSameIdentity ref . fst) alignments)
        ]
      body = applyTypeVarRefRenames alignments (schemeBody scheme0)
      -- A generalized binder can represent several solved graph occurrences
      -- that belong to distinct ambient construction identities.  Once Gen
      -- removes that binder, rewrite each substitution entry from its exact
      -- graph-node route; applying the binder-wide body rename to every entry
      -- would collapse those distinct aliases again.
      subst =
        IntMap.mapWithKey
          alignSubstitutionEntry
          (schemeInfoBinderRefSubst schemeInfo)
      alignSubstitutionEntry nodeKey ref =
        case find (typeBinderRefsSameIdentity ref . fst) alignments of
          Just (_, envRef) ->
            fromMaybe
              envRef
              (IntMap.lookup nodeKey (envConstructionIdentityRoutes env))
          Nothing -> applyRefRenames alignments ref
   in if null alignments
        then schemeInfo
        else
          rebuildSchemeInfoFromRefSubst
            schemeInfo
              { siSourceBinderOrderRefs =
                  IntMap.mapWithKey
                    alignSubstitutionEntry
                    (siSourceBinderOrderRefs schemeInfo)
              , siConstructionBinderOrderRefs =
                  IntMap.mapWithKey
                    alignSubstitutionEntry
                    (siConstructionBinderOrderRefs schemeInfo)
              }
            (mkElabSchemeWithRefs binds body)
            subst

-- | Align source-owned generated binders with the outward binders already
-- selected by the enclosing construction Gamma before computing Gen(Gamma,
-- tau).  Both maps retain the graph-node owner, so their composition is the
-- construction-time proof that the two generated identities denote one
-- lexical binder.
alignSchemeInfoToConstructionGamma
  :: (NodeId -> NodeId)
  -> IntMap.IntMap TypeBinderRef
  -> Env
  -> SchemeInfo
  -> Either ElabError SchemeInfo
alignSchemeInfoToConstructionGamma =
  alignSchemeInfoToConstructionGammaExcept Set.empty

alignSchemeInfoToConstructionGammaExcept
  :: Set.Set TypeBinderIdentity
  -> (NodeId -> NodeId)
  -> IntMap.IntMap TypeBinderRef
  -> Env
  -> SchemeInfo
  -> Either ElabError SchemeInfo
alignSchemeInfoToConstructionGammaExcept protectedIdentities identityRepresentative sourceBinderRefs env schemeInfo0 =
  fst
    <$> alignSchemeInfoToConstructionGammaExceptWithRenames
      protectedIdentities
      identityRepresentative
      sourceBinderRefs
      env
      schemeInfo0

alignSchemeInfoToConstructionGammaExceptWithRenames
  :: Set.Set TypeBinderIdentity
  -> (NodeId -> NodeId)
  -> IntMap.IntMap TypeBinderRef
  -> Env
  -> SchemeInfo
  -> Either
      ElabError
      (SchemeInfo, [(TypeBinderRef, TypeBinderRef)])
alignSchemeInfoToConstructionGammaExceptWithRenames =
  alignSchemeInfoToConstructionGammaPreservingWithRenames Set.empty

alignSchemeInfoToConstructionGammaPreservingWithRenames
  :: Set.Set TypeBinderIdentity
  -> Set.Set TypeBinderIdentity
  -> (NodeId -> NodeId)
  -> IntMap.IntMap TypeBinderRef
  -> Env
  -> SchemeInfo
  -> Either
      ElabError
      (SchemeInfo, [(TypeBinderRef, TypeBinderRef)])
alignSchemeInfoToConstructionGammaPreservingWithRenames lexicalIdentities protectedIdentities identityRepresentative sourceBinderRefs env schemeInfo0 = do
  sourceRenames0 <-
    either
      (Left . ValidationFailed . pure)
      Right
      ( sourceBinderConstructionRenamesRetainingAmbiguousSources
          identityRepresentative
          relevantSourceBinderRefs
          constructionIdentityRoutes
      )
  let -- A source forall declared by this scheme is lexical to the scheme,
      -- even if one of its instantiated graph occurrences later feeds an
      -- enclosing Gamma consumer.  Only free source refs can be captured by
      -- the enclosing construction environment.
      sourceRenames =
        [ rename
        | rename@(sourceRef, outwardRef) <- sourceRenames0
        , not (refIsLexical sourceRef)
        , Set.notMember
            (typeBinderRefIdentity sourceRef)
            protectedIdentities
        , Set.notMember
            (typeBinderRefIdentity outwardRef)
            protectedIdentities
        ]
  constructionAliasRenames <-
    foldM addConstructionAliasRename [] schemeRefs
  sourceIdentityRenames <-
    foldM addSourceIdentityRename [] schemeRefs
  let renames =
        constructionAliasRenames
          ++ sourceIdentityRenames
          ++ sourceRenames
  pure
    ( applySchemeInfoRefRenames renames schemeInfo
    , renames
    )
  where
    -- Scheme substitutions describe graph occurrences, not quantifier
    -- ownership.  A free scheme reference can therefore survive from an
    -- earlier generalization even though its individual occurrence nodes now
    -- have distinct, exact routes in the enclosing construction Gamma.  Keep
    -- genuinely local quantifiers intact, but normalize every free occurrence
    -- by its node-key authority before deriving reference-wide renames.
    schemeInfo =
      rebuildSchemeInfoFromRefSubst
        schemeInfo0
        (siScheme schemeInfo0)
        ( IntMap.mapWithKey
            normalizeAmbientOccurrence
            (schemeInfoBinderRefSubst schemeInfo0)
        )

    normalizeAmbientOccurrence nodeKey ref
      | Set.member (typeBinderRefIdentity ref) protectedIdentities = ref
      | refIsLexical ref = ref
      | otherwise =
          fromMaybe
            ref
            (IntMap.lookup nodeKey constructionIdentityRoutes)

    lexicalBinderRefs = map fst (schemeBinderRefs (siScheme schemeInfo0))

    schemeRefs =
      map fst (schemeBinderRefs (siScheme schemeInfo))
        ++ freeTypeVarRefsType (schemeToType (siScheme schemeInfo))
        ++ IntMap.elems (schemeInfoBinderRefSubst schemeInfo)

    -- This alignment owns occurrence routes for one scheme, not every graph
    -- occurrence that happens to share a generated source identity.  A
    -- generated ref already present in the scheme is its own exact lexical
    -- endpoint; only a source-sidecar key owned by this SchemeInfo can route
    -- a graph occurrence to or from that endpoint.  Pulling in all same-source
    -- sibling keys would ask one lexical binder to choose between distinct
    -- graph placeholders used by separate occurrences.
    relevantSourceBinderRefs =
      IntMap.filterWithKey
        (\nodeKey _ -> IntSet.member nodeKey schemeRouteNodeKeys)
        sourceBinderRefs

    -- A SchemeInfo substitution key is the proof that its graph-local value
    -- and the source sidecar value at that key describe one occurrence. Keep
    -- that route even though the two identities have not yet been joined.
    schemeRouteNodeKeys =
      IntSet.fromList
        [ getNodeId node
        | schemeRef <- schemeRefs
        , node <- schemeRouteNodes schemeRef
        ]

    constructionIdentityRoutes = envConstructionIdentityRoutes env

    addConstructionAliasRename renames ref =
      if Set.member (typeBinderRefIdentity ref) protectedIdentities
          || refIsLexical ref
        then pure renames
        else
          addConstructionAliasRenameUnprotected renames ref

    addConstructionAliasRenameUnprotected renames ref =
      do
        mbOutwardRef <-
          uniqueSchemeRefIdentityRoute
            True
            "construction Gamma"
            constructionIdentityRoutes
            ref
        pure
          ( case mbOutwardRef of
              Just outwardRef
                | not (typeBinderRefsSameIdentityAndName ref outwardRef),
                  not (hasRenameFor ref renames) ->
                    renames ++ [(ref, outwardRef)]
              _ -> renames
          )

    addSourceIdentityRename renames ref =
      if ( Set.member (typeBinderRefIdentity ref) protectedIdentities
            && not (hasDirectSourceDeclarationRoute ref)
         )
          || refIsLexical ref
        then pure renames
        else
          addSourceIdentityRenameUnprotected renames ref

    -- A protected graph identity normally belongs to a construction-local
    -- Gamma consumer and must not be captured through a solved sibling.  A
    -- source sidecar entry at that binder's own graph node is different: it
    -- is the occurrence-level declaration proof for the binder itself.
    hasDirectSourceDeclarationRoute ref =
      case typeBinderRefNode ref of
        Nothing -> False
        Just node ->
          case IntMap.lookup (getNodeId node) sourceBinderRefs of
            Just sourceRef ->
              isJust
                ( typeBinderIdentityGeneratedUnique
                    (typeBinderRefIdentity sourceRef)
                )
                && not (typeBinderRefsSameIdentity ref sourceRef)
            Nothing -> False

    addSourceIdentityRenameUnprotected renames ref =
      do
        mbOutwardRef <-
          uniqueSchemeRefIdentityRoute
            True
            "construction Gamma"
            constructionIdentityRoutes
            ref
        mbSourceRef <-
          uniqueSchemeRefIdentityRoute
            False
            "source binder"
            sourceBinderRefs
            ref
        pure
          ( case (mbOutwardRef, mbSourceRef) of
              (Nothing, Just sourceRef)
                | isJust
                    ( typeBinderIdentityGeneratedUnique
                        (typeBinderRefIdentity sourceRef)
                    ),
                  not (typeBinderRefsSameIdentityAndName ref sourceRef),
                  not (hasRenameFor ref renames) ->
                    renames ++ [(ref, sourceRef)]
              _ -> renames
          )

    -- A generalized reference can be fresh even though its substitution
    -- still records the graph nodes from which it was constructed.  Route
    -- through both facts: consulting only the fresh ref's own node loses an
    -- already-selected enclosing Gamma alias after quotienting.
    uniqueSchemeRefIdentityRoute useSchemeOccurrenceRoute role routes ref = do
      candidates <-
        catMaybes
          <$> traverse
            schemeIdentityRoute
            (schemeRouteNodes ref)
      case foldr insertDistinctRef [] candidates of
        [] -> pure Nothing
        [candidate] -> pure (Just candidate)
        distinct ->
          Left
            ( ValidationFailed
                [ role ++ " scheme reference has multiple identity routes"
                , "  scheme reference: " ++ show ref
                , "  scheme route nodes: " ++ show (schemeRouteNodes ref)
                , "  routes: " ++ show distinct
                , "  scheme: " ++ show (siScheme schemeInfo)
                , "  scheme substitution: " ++ show (schemeInfoBinderRefSubst schemeInfo)
                , "  source binder refs: " ++ show sourceBinderRefs
                , "  construction aliases: " ++ show (envConstructionGammaAliases env)
                ]
            )
      where
        schemeIdentityRoute node =
          case IntMap.lookup (getNodeId node) routes of
            Just direct -> pure (Just direct)
            Nothing
              | useSchemeOccurrenceRoute
              , Just routedRef <-
                  IntMap.lookup
                    (getNodeId node)
                    (schemeInfoBinderRefSubst schemeInfo)
              , typeBinderRefsSameIdentity routedRef ref ->
                  -- This SchemeInfo owns the exact occurrence at this key.
                  -- Preserve that certificate instead of widening the query
                  -- to every route in the solved representative class.
                  pure (Just routedRef)
            _ -> uniqueIdentityRoute role routes node

    schemeRouteNodes ref =
      foldr insertDistinctNode []
        ( retainedIntrinsicNode
            ++ [ NodeId nodeKey
               | (nodeKey, routedRef) <-
                   IntMap.toList (schemeInfoBinderRefSubst schemeInfo)
               , typeBinderRefsSameIdentity ref routedRef
               ]
        )
      where
        -- Once this SchemeInfo explicitly quotients a graph ref's own node to
        -- another identity, that intrinsic node is no longer an occurrence
        -- of the old ref.  Reintroducing it here combines the stale route with
        -- the ref's surviving occurrence keys and creates a false ambiguity.
        -- A generated ref has no intrinsic graph node and is routed entirely
        -- by its occurrence substitution as before.  Likewise, a graph ref
        -- appearing only as a substitution value is an occurrence route, not
        -- a structural declaration at its identity's original graph node.
        retainedIntrinsicNode =
          case (refOccursStructurally, typeBinderRefNode ref) of
            (False, _) -> []
            (True, Just node) ->
              case
                  IntMap.lookup
                    (getNodeId node)
                    (schemeInfoBinderRefSubst schemeInfo)
                of
                  Just routedRef
                    | not (typeBinderRefsSameIdentity routedRef ref) -> []
                  _ -> [node]
            (True, Nothing) -> []

        refOccursStructurally =
          any
            (typeBinderRefsSameIdentity ref)
            structuralSchemeRefs

    structuralSchemeRefs =
      map fst (schemeBinderRefs (siScheme schemeInfo))
        ++ freeTypeVarRefsType (schemeToType (siScheme schemeInfo))

    insertDistinctNode node nodes
      | node `elem` nodes = nodes
      | otherwise = node : nodes

    uniqueIdentityRoute role routes node =
      case IntMap.lookup (getNodeId node) routes of
        Just direct -> pure (Just direct)
        Nothing ->
          case foldr insertDistinctRef [] representativeCandidates of
            [] -> pure Nothing
            [ref] -> pure (Just ref)
            refs ->
              Left
                ( ValidationFailed
                    [ role ++ " representative has multiple identity routes",
                      "  graph node: " ++ show node,
                      "  representative: "
                        ++ show (identityRepresentative node),
                      "  routes: " ++ show refs
                    ]
                )
      where
        representativeCandidates =
          [ routedRef
          | (nodeKey, routedRef) <- IntMap.toList routes,
            identityRepresentative (NodeId nodeKey)
              == identityRepresentative node
          ]

    insertDistinctRef ref refs
      | any (typeBinderRefsSameIdentity ref) refs = refs
      | otherwise = ref : refs

    hasRenameFor ref =
      any (typeBinderRefsSameIdentity ref . fst)

    refIsLexical ref =
      Set.member
        (typeBinderRefIdentity ref)
        lexicalIdentities
        || ( isNothing (typeBinderRefNode ref)
              && any
                (typeBinderRefsSameIdentity ref)
                lexicalBinderRefs
           )

generalizeSchemeInfoAgainstConstructionEnv
  :: (NodeId -> NodeId)
  -> IntMap.IntMap TypeBinderRef
  -> Env
  -> SchemeInfo
  -> Either ElabError SchemeInfo
generalizeSchemeInfoAgainstConstructionEnv =
  generalizeSchemeInfoAgainstConstructionEnvExcept Set.empty

generalizeSchemeInfoAgainstConstructionEnvExcept
  :: Set.Set TypeBinderIdentity
  -> (NodeId -> NodeId)
  -> IntMap.IntMap TypeBinderRef
  -> Env
  -> SchemeInfo
  -> Either ElabError SchemeInfo
generalizeSchemeInfoAgainstConstructionEnvExcept excludedIdentities identityRepresentative sourceBinderRefs env schemeInfo = do
  generalizeSchemeInfoAgainstConstructionEnvPreserving
    Set.empty
    excludedIdentities
    identityRepresentative
    sourceBinderRefs
    env
    schemeInfo

generalizeSchemeInfoAgainstConstructionEnvPreserving
  :: Set.Set TypeBinderIdentity
  -> Set.Set TypeBinderIdentity
  -> (NodeId -> NodeId)
  -> IntMap.IntMap TypeBinderRef
  -> Env
  -> SchemeInfo
  -> Either ElabError SchemeInfo
generalizeSchemeInfoAgainstConstructionEnvPreserving lexicalIdentities excludedIdentities identityRepresentative sourceBinderRefs env schemeInfo = do
  aligned <-
    alignSchemeInfoToConstructionGammaExcept
      protectedIdentities
      identityRepresentative
      sourceBinderRefs
      env
      schemeInfo
  orderConstructionSchemeInfoBinders
    "generalize against construction Gamma"
    ( generalizeSchemeInfoAgainstEnvExcept
        protectedIdentities
        identityRepresentative
        env
        aligned
    )
  where
    protectedIdentities =
      lambdaParamProtectedIdentities
        lexicalIdentities
        (envOwnsExactTypeBinderRef env)
        (envConstructionIdentityRoutes env)
        schemeInfo
        excludedIdentities

freshenSchemeInfoAgainstConstructionEnvExcept
  :: Set.Set TypeBinderIdentity
  -> (NodeId -> NodeId)
  -> IntMap.IntMap TypeBinderRef
  -> Env
  -> SchemeInfo
  -> Either ElabError SchemeInfo
freshenSchemeInfoAgainstConstructionEnvExcept excludedIdentities identityRepresentative sourceBinderRefs env schemeInfo =
  fst
    <$> freshenSchemeInfoAgainstConstructionEnvExceptWithRenames
      excludedIdentities
      identityRepresentative
      sourceBinderRefs
      env
      schemeInfo

freshenSchemeInfoAgainstConstructionEnvExceptWithRenames
  :: Set.Set TypeBinderIdentity
  -> (NodeId -> NodeId)
  -> IntMap.IntMap TypeBinderRef
  -> Env
  -> SchemeInfo
  -> Either
      ElabError
      (SchemeInfo, [(TypeBinderRef, TypeBinderRef)])
freshenSchemeInfoAgainstConstructionEnvExceptWithRenames =
  freshenSchemeInfoAgainstConstructionEnvPreservingWithRenames Set.empty

-- | Freshen a construction scheme while preserving identities already fixed
-- by this exact lexical boundary.  Those identities include both a binder
-- spine emitted by the current owner and free occurrences fixed by an
-- enclosing lambda-parameter certificate.  This protection applies only
-- while aligning occurrence identities: Gen(Gamma,tau) still receives the
-- ordinary construction-protected set and can subtract a truly ambient
-- variable.
freshenSchemeInfoAgainstConstructionEnvPreservingWithRenames
  :: Set.Set TypeBinderIdentity
  -> Set.Set TypeBinderIdentity
  -> (NodeId -> NodeId)
  -> IntMap.IntMap TypeBinderRef
  -> Env
  -> SchemeInfo
  -> Either
      ElabError
      (SchemeInfo, [(TypeBinderRef, TypeBinderRef)])
freshenSchemeInfoAgainstConstructionEnvPreservingWithRenames lexicalIdentities excludedIdentities identityRepresentative sourceBinderRefs env schemeInfo = do
  (aligned, alignmentRenames) <-
    alignSchemeInfoToConstructionGammaPreservingWithRenames
      lexicalIdentities
      protectedIdentities
      identityRepresentative
      sourceBinderRefs
      env
      schemeInfo
  let generalized =
        generalizeSchemeInfoAgainstEnvExcept
          protectedIdentities
          identityRepresentative
          env
          aligned
  ordered <-
    orderConstructionSchemeInfoBinders
      "freshen against construction Gamma"
      generalized
  pure
    ( freshenSchemeInfoBinderNamesAgainst
        (freeTypeVarsEnvSchemesExceptIdentities protectedIdentities env)
        ordered
    , alignmentRenames
    )
  where
    protectedIdentities =
      constructionProtectedIdentities
        (envOwnsExactTypeBinderRef env)
        (envConstructionIdentityRoutes env)
        schemeInfo
        excludedIdentities

-- | Align and presentation-freshen a scheme whose complete binder spine is
-- owned by the current source boundary.  Unlike Gen(Gamma,tau), this operation
-- must not subtract a declared binder merely because construction planning
-- has an equal identity in the ambient Gamma: the source ABI is the positive
-- authority that this boundary binds it.
freshenOwnedSchemeInfoAgainstConstructionEnv
  :: Set.Set TypeBinderIdentity
  -> (NodeId -> NodeId)
  -> IntMap.IntMap TypeBinderRef
  -> Env
  -> SchemeInfo
  -> Either ElabError SchemeInfo
freshenOwnedSchemeInfoAgainstConstructionEnv ownedIdentities identityRepresentative sourceBinderRefs env schemeInfo = do
  aligned <-
    alignSchemeInfoToConstructionGammaExcept
      ownedIdentities
      identityRepresentative
      sourceBinderRefs
      env
      schemeInfo
  ordered <-
    orderConstructionSchemeInfoBinders
      "freshen source-owned scheme against construction Gamma"
      aligned
  pure
    ( freshenSchemeInfoBinderNamesAgainst
        (freeTypeVarsEnvSchemesExceptIdentities ownedIdentities env)
        ordered
    )

orderConstructionSchemeInfoBinders
  :: String
  -> SchemeInfo
  -> Either ElabError SchemeInfo
orderConstructionSchemeInfoBinders role schemeInfo = do
  orderedScheme <-
    either
      (Left . ValidationFailed . pure)
      Right
      (orderSourceProjectedSchemeBinders role (siScheme schemeInfo))
  pure
    ( rebuildSchemeInfoFromRefSubst
        schemeInfo
        orderedScheme
        (schemeInfoBinderRefSubst schemeInfo)
    )

applySchemeInfoRefRenames :: [(TypeBinderRef, TypeBinderRef)] -> SchemeInfo -> SchemeInfo
applySchemeInfoRefRenames renames schemeInfo =
  rebuildSchemeInfoFromRefSubst
    schemeInfo
      { siSourceBinderOrderRefs =
          IntMap.map
            (applyRefRenames renames)
            (siSourceBinderOrderRefs schemeInfo)
      , siConstructionBinderOrderRefs =
          IntMap.map
            (applyRefRenames renames)
            (siConstructionBinderOrderRefs schemeInfo)
      }
    (mkElabSchemeWithRefs binds' body')
    subst'
  where
    scheme0 = siScheme schemeInfo
    binderRefs = map fst (schemeBinderRefs scheme0)
    activeRenames =
      captureAvoidingBinderRenames
        (schemeBinderRefs scheme0)
        renames
    (binderRenames, externalRenames) =
      partition
        (\(oldRef, _) -> any (typeBinderRefsSameIdentity oldRef) binderRefs)
        activeRenames
    binds' = foldl' retainRenamedBinder [] renamedBinds
    renamedBinds = renameBinds [] (schemeBinderRefs scheme0)
    body' = applyTypeVarRefRenames activeRenames (schemeBody scheme0)
    subst' = IntMap.map (applyRefRenames activeRenames) (schemeInfoBinderRefSubst schemeInfo)

    retainRenamedBinder retained binder@(ref, mbBound) =
      case find (typeBinderRefsSameIdentity ref . fst) retained of
        Just (_, existingBound)
          | equivalentRenamedBounds existingBound mbBound -> retained
        Just (_, Just _)
          | mbBound == Nothing -> retained
        Just (_, Nothing)
          | Just _ <- mbBound ->
              map
                ( \existing@(existingRef, _) ->
                    if typeBinderRefsSameIdentity existingRef ref
                      then binder
                      else existing
                )
                retained
        _ -> retained ++ [binder]

    equivalentRenamedBounds left right =
      let leftTy = maybe TBottom tyToElab left
          rightTy = maybe TBottom tyToElab right
       in alphaEqType leftTy rightTy || churchAwareEqType leftTy rightTy

    renameBinds _ [] = []
    renameBinds previous ((ref, mbBound) : rest) =
      let ref' = applyRefRenames binderRenames ref
          -- Construction aliases that are free in this scheme apply to every
          -- binder bound.  Alpha-renames for scheme binders apply only after
          -- their binder has entered scope.  Treating both as the latter left
          -- S'(operated) source identities unchanged in packet bounds.
          boundRenames = externalRenames ++ previous
          mbBound' =
            fmap
              (mapBoundType (applyTypeVarRefRenames boundRenames))
              mbBound
          previous'
            | typeBinderRefsSameIdentityAndName ref ref' = previous
            | otherwise = previous ++ [(ref, ref')]
       in (ref', mbBound') : renameBinds previous' rest

-- | Keep a construction quotient from capturing a declaration dependency.
-- A binder does not scope over its own bound.  If a quotient renames @beta@
-- to an ambient @alpha@ already mentioned by that bound, applying it would
-- turn @beta >= tau[alpha]@ into the ill-founded
-- @alpha >= tau[alpha]@ and capture the ambient source identity in the body.
-- The graph nodes can still be equal in the solved shape quotient; that is
-- not evidence that these two declaration identities are equal.
captureAvoidingBinderRenames
  :: [(TypeBinderRef, Maybe BoundType)]
  -> [(TypeBinderRef, TypeBinderRef)]
  -> [(TypeBinderRef, TypeBinderRef)]
captureAvoidingBinderRenames binders =
  filter (not . binderRenameCapturesOwnBound)
  where
    binderRenameCapturesOwnBound (sourceRef, targetRef) =
      any captures binders
      where
        captures (binderRef, mbBound) =
          typeBinderRefsSameIdentity sourceRef binderRef
            && any
              (typeBinderRefsSameIdentity targetRef)
              ( maybe
                  []
                  (freeTypeVarRefsType . tyToElab)
                  mbBound
              )

-- | Publish the exact binder-order authority carried by an explicit source
-- annotation ABI.  This includes the graph-backed existential variables that
-- the annotation leaves free and the generated universal variables it
-- declares explicitly: the source ABI fixes the order of both.  Graph binders
-- from inferred schemes and compiler-created copies receive no such
-- certificate and continue to require the presolution's @<P@ order.
sourceAbiSchemeInfoFromRefSubst
  :: ElabScheme
  -> IntMap.IntMap TypeBinderRef
  -> SchemeInfo
sourceAbiSchemeInfoFromRefSubst scheme subst =
  schemeInfo
    { siSourceBinderOrderRefs =
        IntMap.filter
          ( \ref ->
              any
                (typeBinderRefsSameIdentity ref)
                sourceBinderRefs
          )
          (schemeInfoBinderRefSubst schemeInfo)
    }
  where
    schemeInfo = schemeInfoFromRefSubst scheme subst
    sourceBinderRefs = map fst (schemeBinderRefs scheme)

freshenSchemeInfoAgainstEnv :: Env -> SchemeInfo -> SchemeInfo
freshenSchemeInfoAgainstEnv = freshenSchemeInfoAgainstEnvWithRepresentative id

freshenSchemeInfoAgainstEnvWithRepresentative :: (NodeId -> NodeId) -> Env -> SchemeInfo -> SchemeInfo
freshenSchemeInfoAgainstEnvWithRepresentative identityRepresentative env schemeInfo0 =
  freshenSchemeInfoAgainstEnvWithRepresentativeExcept
    Set.empty
    identityRepresentative
    env
    schemeInfo0

freshenSchemeInfoAgainstEnvWithRepresentativeExcept
  :: Set.Set TypeBinderIdentity
  -> (NodeId -> NodeId)
  -> Env
  -> SchemeInfo
  -> SchemeInfo
freshenSchemeInfoAgainstEnvWithRepresentativeExcept excludedIdentities identityRepresentative env schemeInfo0 =
  let protectedIdentities =
        constructionProtectedIdentities
          (envOwnsExactTypeBinderRef env)
          (envConstructionIdentityRoutes env)
          schemeInfo0
          excludedIdentities
      schemeInfo =
        generalizeSchemeInfoAgainstEnvExcept
          protectedIdentities
          identityRepresentative
          env
          schemeInfo0
      reservedNames =
        freeTypeVarsEnvSchemesExceptIdentities protectedIdentities env
      scheme0 = siScheme schemeInfo
      binds = schemeBinderRefs scheme0
      body0 = schemeBody scheme0
      binderNames = map (typeBinderRefName . fst) binds
      binderDomain = Set.fromList binderNames
      renames = reverse (snd (foldl' (chooseFreshBinder binderDomain) (reservedNames, []) (map fst binds)))
      refRenames =
        [ (oldRef, renameTypeBinderRef newName oldRef)
          | (oldRef, newName) <- renames,
            typeBinderRefName oldRef /= newName
        ]
   in if null refRenames
        then schemeInfo
        else
          let binds' = renameSchemeBinds refRenames binds
              body' = applyTypeVarRefRenames refRenames body0
              scheme' = mkElabSchemeWithRefs binds' body'
              subst' = IntMap.map (applyRefRenames refRenames) (schemeInfoBinderRefSubst schemeInfo)
           in rebuildSchemeInfoFromRefSubst
                schemeInfo
                scheme'
                subst'
  where
    chooseFreshBinder binderDomain (used, acc) binder =
      let name = typeBinderRefName binder
          name' =
            if Set.member name used
              then freshNameLike name (Set.union used binderDomain)
              else name
       in (Set.insert name' used, (binder, name') : acc)

    renameSchemeBinds renames0 = go []
      where
        go _ [] = []
        go prev ((ref, mbBound) : restBinds) =
          let ref' = applyRefRenames renames0 ref
              mbBound' = fmap (mapBoundType (applyTypeVarRefRenames prev)) mbBound
              prev'
                | typeBinderRefsSameIdentityAndName ref ref' = prev
                | otherwise = prev ++ [(ref, ref')]
           in (ref', mbBound') : go prev' restBinds

applyRefRenames :: [(TypeBinderRef, TypeBinderRef)] -> TypeBinderRef -> TypeBinderRef
applyRefRenames [] ref = ref
applyRefRenames ((oldRef, newRef) : rest) ref
  | typeBinderRefsSameIdentity oldRef ref = newRef
  | otherwise = applyRefRenames rest ref

applyTypeVarRefRenames :: [(TypeBinderRef, TypeBinderRef)] -> ElabType -> ElabType
applyTypeVarRefRenames renames0 ty0 =
  foldl'
    ( \ty (oldRef, newRef) ->
        if
            typeBinderRefsSameIdentityAndName oldRef newRef
              || not
                ( any
                    (typeBinderRefsSameIdentity oldRef)
                    (freeTypeVarRefsType ty)
                )
          then ty
          else substTypeCaptureRef oldRef (TVarRef newRef) ty
    )
    ty0
    renames0

applyInstantiationRefRenames
  :: [(TypeBinderRef, TypeBinderRef)]
  -> Instantiation
  -> Instantiation
applyInstantiationRefRenames renames = go
  where
    go inst =
      case inst of
        InstId -> InstId
        InstApp ty -> InstApp (applyTypeVarRefRenames renames ty)
        InstBot ty -> InstBot (applyTypeVarRefRenames renames ty)
        InstIntro -> InstIntro
        InstElim -> InstElim
        InstAbstrRef ref -> InstAbstrRef (applyRefRenames renames ref)
        InstUnderRef ref inner ->
          InstUnderRef
            (applyRefRenames renames ref)
            (go inner)
        InstInside inner -> InstInside (go inner)
        InstSeq left right -> InstSeq (go left) (go right)

structuralRecursiveCandidateType :: StructuralRecursiveCandidate -> ElabType
structuralRecursiveCandidateType candidate =
  case candidate of
    StructuralRecursiveCandidateFromHelper ty -> ty
    StructuralRecursiveCandidateFromDirectCarrier ty -> ty

selectStructuralRecursiveCandidate :: [StructuralRecursiveCandidate] -> StructuralRecursiveCandidateSelection
selectStructuralRecursiveCandidate =
  selectUniqueCandidateBy
    ( \existing candidate ->
        alphaEqType
          (structuralRecursiveCandidateType existing)
          (structuralRecursiveCandidateType candidate)
    )

schemeHasForwardBoundReference :: ElabType -> Bool
schemeHasForwardBoundReference schemeTy =
  let (binds, _) = splitForallsRefs schemeTy
      go [] = False
      go ((_, mbBound) : rest) =
        let laterRefs = map fst rest
            boundMentionsLater =
              case mbBound of
                Just bound ->
                  any
                    (\laterRef -> any (typeBinderRefsSameIdentity laterRef) (freeTypeVarRefsType bound))
                    laterRefs
                Nothing -> False
         in boundMentionsLater || go rest
   in go binds

schemeTypeHasExplicitBound :: ElabType -> Bool
schemeTypeHasExplicitBound schemeTy =
  let (binds, _) = splitForallsRefs schemeTy
   in any (isJust . snd) binds

stripAnnExpr :: AnnExpr -> AnnExpr
stripAnnExpr annExpr =
  case annExpr of
    AAnn inner _ _ -> stripAnnExpr inner
    AExactAnn inner _ _ _ -> stripAnnExpr inner
    ALetScope inner _ _ -> stripAnnExpr inner
    AUnfold inner _ _ -> stripAnnExpr inner
    _ -> annExpr

-- | Materialize the leading lambda domains already fixed by a let's published
-- scheme.  The RHS is constructed under that scheme's Gamma, so its resolved
-- lambda binders must use the corresponding arrow domains directly instead of
-- first inventing graph-local variables that are repaired after elaboration.
-- Iso-recursive schemes are unfolded once at this boundary before the same
-- structural walk.
--
-- The map is keyed by resolved binder identity, so the authority cannot leak
-- to an unrelated nested lambda.  Source annotations remain authoritative in
-- 'ALamF'; this view supplies the missing owner information only when the
-- lambda itself is unannotated.
data ConstructedLambdaParamTraversal
  = DirectValueLambdaParamTraversal
  | CertifiedPolymorphicLambdaParamTraversal

constructedLambdaParamTypes
  :: Env
  -> ElabType
  -> AnnExpr
  -> Map.Map EnvBindingIdentityKey ElabType
constructedLambdaParamTypes =
  constructedLambdaParamTypesWith DirectValueLambdaParamTraversal

certifiedConstructedLambdaParamTypes
  :: Env
  -> ElabType
  -> AnnExpr
  -> Map.Map EnvBindingIdentityKey ElabType
certifiedConstructedLambdaParamTypes =
  constructedLambdaParamTypesWith CertifiedPolymorphicLambdaParamTraversal

constructedLambdaParamTypesWith
  :: ConstructedLambdaParamTraversal
  -> Env
  -> ElabType
  -> AnnExpr
  -> Map.Map EnvBindingIdentityKey ElabType
constructedLambdaParamTypesWith traversal env constructionTy rhsAnn =
  case stripLeadingForalls constructionTy of
    muTy@(TMuRef muRef muBody)
      | hasContractiveRecursiveWitness muTy ->
          go Map.empty (substTypeCaptureRef muRef muTy muBody) rhsAnn
    ty -> go Map.empty ty rhsAnn
  where
    stripLeadingForalls ty =
      case ty of
        TForallRef _ _ body -> stripLeadingForalls body
        _ -> ty

    go mediatorAliases expectedTy annExpr =
      case annExpr of
        ALam _ details _ _ body _ _ ->
          case expectedLambdaTy expectedTy of
            TArrow domainTy codomainTy ->
              Map.insert
                (envBindingDetailsKey details)
                domainTy
                (go mediatorAliases codomainTy body)
            _ -> Map.empty
        AApp fun arg _ _ _
          | isJust (transparentKind mediatorAliases fun) ->
              -- A validated identity/eta mediator preserves the complete type
              -- of its first argument.  Carry the published let scheme through
              -- that exact resolved occurrence so a nested lambda receives its
              -- domain before its body is elaborated.
              go mediatorAliases expectedTy arg
        ALet _ details _ _ _ _ rhs body _ ->
          let key = annBinderKey details
              mediatorAliases' =
                case transparentKind mediatorAliases rhs of
                  Just kind -> Map.insert key kind mediatorAliases
                  Nothing -> Map.delete key mediatorAliases
           in go mediatorAliases' expectedTy body
        AAnn inner _ _ -> go mediatorAliases expectedTy inner
        AExactAnn inner _ _ _ -> go mediatorAliases expectedTy inner
        ALetScope inner _ _ -> go mediatorAliases expectedTy inner
        -- An explicit source unfold changes the expected type before the
        -- lambda and therefore owns its own construction boundary.
        AUnfold {} -> Map.empty
        _ -> Map.empty

    -- Ordinary let/RHS construction owns the direct value-arrow spine only;
    -- a forall after an arrow may belong to a descendant constructor.  The
    -- certified application-result lane carries explicit authority for those
    -- intervening type abstractions and may therefore continue to the next
    -- value lambda beneath them.
    expectedLambdaTy expectedTy =
      case traversal of
        DirectValueLambdaParamTraversal -> expectedTy
        CertifiedPolymorphicLambdaParamTraversal ->
          stripLeadingForalls expectedTy

    transparentKind mediatorAliases annExpr =
      transparentMediatorKindAnn annExpr
        <|> do
          key <- directAnnReferenceKey (stripAnnExpr annExpr)
          Map.lookup key mediatorAliases
            <|> (lookupEnvBindingForKey key env >>= ebTransparentMediator)

-- | Seed lambda domains from an already prepared construction contract.  The
-- map is identity-keyed and therefore remains valid through source wrappers;
-- existing, more local construction entries retain precedence.
withEnvConstructedLambdaParamTypes :: ElabType -> AnnExpr -> Env -> Env
withEnvConstructedLambdaParamTypes constructionTy annExpr env =
  env
    { envConstructedLambdaParamTypes =
        Map.union
          (envConstructedLambdaParamTypes env)
          (constructedLambdaParamTypes env constructionTy annExpr)
    }

-- | Install only the direct lambda parameter selected by an enclosing
-- application.  Figure 15.3.5 gives the function child an exact shared
-- argument endpoint even when the application's result remains checking-only.
-- Publishing the whole provisional arrow through
-- 'withEnvConstructedLambdaParamTypes' would incorrectly promote that
-- checking codomain to construction authority; recording the direct domain
-- protects precisely the declaration already proved by the argument/Gamma
-- construction.
withDirectConstructedLambdaParamType
  :: ElabType
  -> AnnExpr
  -> Env
  -> Env
withDirectConstructedLambdaParamType domainTy annExpr env =
  case stripAnnExpr annExpr of
    ALam _ details _ _ _ _ _ ->
      env
        { envConstructedLambdaParamTypes =
            Map.insert
              (envBindingDetailsKey details)
              domainTy
              (envConstructedLambdaParamTypes env)
        , envExactApplicationLambdaParamSchemes =
            Map.insert
              (envBindingDetailsKey details)
              (exactApplicationLambdaParamSchemeInfo domainTy)
              (envExactApplicationLambdaParamSchemes env)
        }
    _ -> env

exactApplicationLambdaParamSchemeInfo :: ElabType -> SchemeInfo
exactApplicationLambdaParamSchemeInfo paramTy =
  baseSchemeInfo
    { siConstructionBinderOrderRefs =
        schemeInfoBinderRefSubst baseSchemeInfo
    }
  where
    baseSchemeInfo =
      schemeInfoFromRefSubst
        (schemeFromType paramTy)
        IntMap.empty

-- | Install the complete lambda-parameter spine certified by a direct
-- enclosing-consumer Eq-Free construction.  This is deliberately stricter
-- than the ordinary let/RHS seeding path: an existing non-Bottom construction
-- remains authoritative and must agree with the certified endpoint.  Only a
-- provisional Bottom entry may be replaced, so the certificate cannot repair
-- an independently constructed, incompatible lambda after the fact.
withCertifiedConstructedLambdaParamTypes
  :: ElabType
  -> AnnExpr
  -> Env
  -> Either ElabError Env
withCertifiedConstructedLambdaParamTypes constructionTy annExpr env = do
  let certifiedParamTypes =
        certifiedConstructedLambdaParamTypes env constructionTy annExpr
  mergedParamTypes <-
    Map.foldlWithKey'
      mergeCertifiedParamType
      (Right (envConstructedLambdaParamTypes env))
      certifiedParamTypes
  mergedParamSchemes <-
    Map.foldlWithKey'
      mergeCertifiedParamScheme
      (Right (envExactApplicationLambdaParamSchemes env))
      certifiedParamTypes
  pure
    env
      { envConstructedLambdaParamTypes = mergedParamTypes
      , envExactApplicationLambdaParamSchemes = mergedParamSchemes
      }
  where
    mergeCertifiedParamType merged key certifiedTy = do
      paramTypes <- merged
      case Map.lookup key paramTypes of
        Nothing -> pure (Map.insert key certifiedTy paramTypes)
        Just TBottom -> pure (Map.insert key certifiedTy paramTypes)
        Just existingTy
          | operationalEndpointTypesAgree existingTy certifiedTy ->
              pure paramTypes
          | otherwise ->
              Left
                ( ValidationFailed
                    [ "certified direct-lambda parameter conflicts with an existing construction"
                    , "  parameter identity: " ++ show key
                    , "  existing construction: "
                        ++ diagnosticElabType existingTy
                    , "  certified construction: "
                        ++ diagnosticElabType certifiedTy
                    ]
                )

    mergeCertifiedParamScheme merged key certifiedTy = do
      paramSchemes <- merged
      case Map.lookup key paramSchemes of
        Nothing ->
          pure
            ( Map.insert
                key
                (exactApplicationLambdaParamSchemeInfo certifiedTy)
                paramSchemes
            )
        Just existingSchemeInfo
          | operationalEndpointTypesAgree
              (schemeToType (siScheme existingSchemeInfo))
              certifiedTy -> pure paramSchemes
          | otherwise ->
              Left
                ( ValidationFailed
                    [ "certified direct-lambda parameter conflicts with an existing exact application endpoint"
                    , "  parameter identity: " ++ show key
                    , "  existing exact endpoint: "
                        ++ diagnosticElabType
                          (schemeToType (siScheme existingSchemeInfo))
                    , "  certified construction: "
                        ++ diagnosticElabType certifiedTy
                    ]
                )

directAnnReferenceKey :: AnnExpr -> Maybe BindingKey
directAnnReferenceKey annExpr =
  case annExpr of
    AResolvedVar details _ _ -> Just (ResolvedBindingKey (idDetailsIdentityKey details))
    _ -> Nothing

stripLeadingTyAbs :: XmlfTerm -> XmlfTerm
stripLeadingTyAbs term =
  case term of
    ETyAbsRef _ _ body -> stripLeadingTyAbs body
    _ -> term

-- | Complete one prepared stage of the Gamma result abstractions delayed at a
-- compiler-owned exact boundary.  Source-ABI results are consumed before
-- exact validation; packet-only results are consumed afterwards.  Packet
-- owner identity, exact-edge provenance, and the prepared stage select the
-- insertion points; term shape and inferred types are never recovery oracles.
completeCompilerExactSubtermResults
  :: CompilerExactResultStage
  -> EdgeId
  -> SubtermGeneralizations
  -> XmlfTerm
  -> Either ElabError XmlfTerm
completeCompilerExactSubtermResults =
  completeCompilerExactSubtermResultsWithBounds []

-- | Apply the same graph-to-outward substitution used to close a root term to
-- its construction certificates.  Identity matching, rather than binder
-- spelling, determines each route.
projectCompilerExactResultBoundCertificates
  :: IntMap.IntMap TypeBinderRef
  -> [CompilerExactResultBoundCertificate]
  -> [CompilerExactResultBoundCertificate]
projectCompilerExactResultBoundCertificates subst =
  map projectCertificate
  where
    renames =
      [ ( typeBinderRefFromIdentity
            (typeBinderIdentityFromNode (NodeId nodeKey))
            ("t" ++ show nodeKey)
        , outwardRef
        )
      | (nodeKey, outwardRef) <- IntMap.toList subst
      ]

    projectCertificate certificate =
      certificate
        { cerbcResultRef =
            renamePublishedRef renames (cerbcResultRef certificate)
        , cerbcBound =
            renameTypeBinderRefPayloads renames (cerbcBound certificate)
        }

completeCompilerExactSubtermResultsWithBounds
  :: [CompilerExactResultBoundCertificate]
  -> CompilerExactResultStage
  -> EdgeId
  -> SubtermGeneralizations
  -> XmlfTerm
  -> Either ElabError XmlfTerm
completeCompilerExactSubtermResultsWithBounds resultBoundCertificates stage exactEdge packets term = do
  (term', completedOwners) <- go term
  let expectedPackets =
        Map.filter
          (\packet ->
            subtermGeneralizationCompilerExactBoundary packet == Just exactEdge
              && isJust (subtermGeneralizationCompilerExactResultRef packet)
              && isJust (subtermGeneralizationCompilerExactCompletionRef packet)
              && subtermGeneralizationCompilerExactResultStage packet == Just stage
          )
          packets
      expectedOwners = Map.keysSet expectedPackets
      missingOwners = Set.toList (Set.difference expectedOwners completedOwners)
      unexpectedOwners = Set.toList (Set.difference completedOwners expectedOwners)
  case (missingOwners, unexpectedOwners) of
    ([], []) -> do
      delayedBinders <- traverse resultBinder (Map.toList expectedPackets)
      foldM installDelayedBinder term' delayedBinders
    _ ->
      Left
        ( ValidationFailed
            [ "compiler exact boundary did not consume exactly its delayed Gamma results"
            , "  exact edge: " ++ show exactEdge
            , "  missing owners: " ++ show missingOwners
            , "  unexpected owners: " ++ show unexpectedOwners
            ]
        )
  where
    go current =
      case current of
        EVarNode{} -> pure (current, Set.empty)
        ELit{} -> pure (current, Set.empty)
        ELam resolved body -> do
          (body', completed) <- go body
          let owner = idDetailsIdentityKey (resolvedVarDetails resolved)
          case Map.lookup owner packets of
            Just packet
              | subtermGeneralizationCompilerExactBoundary packet == Just exactEdge
              , subtermGeneralizationCompilerExactResultStage packet == Just stage
              , Just completionRef <- subtermGeneralizationCompilerExactCompletionRef packet ->
                  if Set.member owner completed
                    then duplicateOwner owner
                    else do
                      pure
                        ( ELam
                            resolved
                            ( if completionAlreadyApplied
                                  packet
                                  body'
                                then body'
                                else
                                  ETyInst
                                    body'
                                    (InstAbstrRef completionRef)
                            )
                        , Set.insert owner completed
                        )
            _ -> pure (ELam resolved body', completed)
        EApp fun arg -> do
          (fun', funCompleted) <- go fun
          (arg', argCompleted) <- go arg
          completed <- mergeCompleted funCompleted argCompleted
          pure (EApp fun' arg', completed)
        ELet resolved scheme rhs body -> do
          (rhs', rhsCompleted) <- go rhs
          (body', bodyCompleted) <- go body
          completed <- mergeCompleted rhsCompleted bodyCompleted
          pure
            ( ELet resolved scheme rhs' body'
            , completed
            )
        ETyAbsRef ref bound body -> do
          (body', completed) <- go body
          pure (ETyAbsRef ref bound body', completed)
        ETyInst body inst -> do
          (body', completed) <- go body
          pure (ETyInst body' inst, completed)
        ERoll ty body -> do
          (body', completed) <- go body
          pure (ERoll ty body', completed)
        EUnroll body -> do
          (body', completed) <- go body
          pure (EUnroll body', completed)

    resultBinder (owner, packet) = do
      packetResultRef <-
        case subtermGeneralizationCompilerExactResultRef packet of
          Just ref -> pure ref
          Nothing ->
            Left
              ( ValidationFailed
                  [ "compiler exact packet has no delayed Gamma result"
                  , "  exact edge: " ++ show exactEdge
                  ]
              )
      existingRef <-
        case subtermGeneralizationCompilerExactExistingRef packet of
          Just ref -> pure ref
          Nothing ->
            Left
              ( ValidationFailed
                  [ "compiler exact packet has no source construction binder"
                  , "  exact edge: " ++ show exactEdge
                  , "  packet result: " ++ show packetResultRef
                  ]
              )
      completionRef <-
        case subtermGeneralizationCompilerExactCompletionRef packet of
          Just ref -> pure ref
          Nothing ->
            Left
              ( ValidationFailed
                  [ "compiler exact packet has no semantic completion result"
                  , "  exact edge: " ++ show exactEdge
                  , "  packet result: " ++ show packetResultRef
                  ]
              )
      preparedBound <-
        case
          [ mbBound
          | (binderRef, mbBound) <-
              schemeBinderRefs
                (siScheme (subtermGeneralizationSchemeInfo packet))
          , typeBinderRefsSameIdentity binderRef packetResultRef
          ]
        of
          [Just bound] -> pure (Just bound)
          [Nothing] ->
            Left
              ( ValidationFailed
                  [ "compiler exact result abstraction has no operated bound"
                  , "  exact edge: " ++ show exactEdge
                  , "  packet result: " ++ show packetResultRef
                  , "  completion result: " ++ show completionRef
                  ]
              )
          [] ->
            Left
              ( ValidationFailed
                  [ "compiler exact result abstraction is absent from its packet"
                  , "  exact edge: " ++ show exactEdge
                  , "  packet result: " ++ show packetResultRef
                  , "  completion result: " ++ show completionRef
                  ]
              )
          _ ->
            Left
              ( ValidationFailed
                  [ "compiler exact result abstraction occurs more than once in its packet"
                  , "  exact edge: " ++ show exactEdge
                  , "  packet result: " ++ show packetResultRef
                  , "  completion result: " ++ show completionRef
                  ]
              )
      let matchingCertificates =
            [ certificate
            | certificate <- resultBoundCertificates
            , cerbcOwner certificate == owner
            , cerbcBoundary certificate == exactEdge
            , any
                (typeBinderRefsSameIdentity (cerbcResultRef certificate))
                [packetResultRef, existingRef, completionRef]
            ]
      (resultBound, resultBoundIsConstructed) <-
        case (stage, matchingCertificates) of
          (CompleteBeforeCompilerExact, [certificate]) -> do
            constructedBound <-
              case elabToBound (cerbcBound certificate) of
                Right bound -> pure bound
                Left cause ->
                  Left
                    ( ValidationFailed
                        [ "compiler exact source result has a non-bound construction certificate"
                        , "  exact edge: " ++ show exactEdge
                        , "  owner: " ++ show owner
                        , "  result: " ++ show packetResultRef
                        , "  constructed bound: " ++ show (cerbcBound certificate)
                        , "  cause: " ++ cause
                        ]
                    )
            pure (Just constructedBound, True)
          (CompleteBeforeCompilerExact, []) ->
            pure (preparedBound, False)
          (CompleteBeforeCompilerExact, certificates) ->
            Left
              ( ValidationFailed
                  [ "compiler exact source result has multiple construction certificates"
                  , "  exact edge: " ++ show exactEdge
                  , "  owner: " ++ show owner
                  , "  result: " ++ show packetResultRef
                  , "  certificates: " ++ show certificates
                  ]
              )
          (CompleteAfterCompilerExact, []) ->
            pure (preparedBound, False)
          (CompleteAfterCompilerExact, certificates) ->
            Left
              ( ValidationFailed
                  [ "packet-only compiler exact result received a source-bound construction certificate"
                  , "  exact edge: " ++ show exactEdge
                  , "  owner: " ++ show owner
                  , "  result: " ++ show packetResultRef
                  , "  certificates: " ++ show certificates
                  ]
              )
      pure
        ( existingRef
        , completionRef
        , resultBound
        , resultBoundIsConstructed
        )

    -- A surrounding exact-root scheme may already publish the delayed graph
    -- identity.  For a source-owned result, the lambda constructor has also
    -- materialized Typ(body) before this boundary runs.  That constructed
    -- declaration is stronger than the packet's provisional opened bound, so
    -- retain it when the exact identity is already present.  A packet-only
    -- result still has no declaration before this boundary and therefore uses
    -- the prepared packet bound.  Keeping the prepared spine position also
    -- preserves dependencies between interleaved root and packet quantifiers.
    installDelayedBinder current delayed@(existingRef, completionRef, delayedBound, resultBoundIsConstructed) =
      case strengthenLeadingBinder current of
        Right (True, strengthened) -> pure strengthened
        Right (False, unchanged) ->
          pure (insertAfterLeadingTypeAbstractions delayed unchanged)
        Left err -> Left err
      where
        strengthenLeadingBinder term0 =
          case term0 of
            ETyAbsRef ref mbBound body
              | typeBinderRefsSameIdentity ref existingRef
                  || typeBinderRefsSameIdentity ref completionRef -> do
                  bound <-
                    mergeDelayedBound
                      resultBoundIsConstructed
                      ref
                      mbBound
                      delayedBound
                  let body' =
                        if typeBinderRefsSameIdentity ref completionRef
                          then body
                          else renameTermTypeVars [(ref, completionRef)] body
                  pure (True, ETyAbsRef completionRef bound body')
              | otherwise -> do
                  (found, body') <- strengthenLeadingBinder body
                  pure (found, ETyAbsRef ref mbBound body')
            ETyInst body inst -> do
              (found, body') <- strengthenLeadingBinder body
              pure (found, ETyInst body' inst)
            _ -> pure (False, term0)

        mergeDelayedBound constructedBound ref existing incoming =
          case (existing, incoming) of
            (Nothing, Just _) -> pure incoming
            (Just existingBound, Just incomingBound)
              | alphaEqType (tyToElab existingBound) (tyToElab incomingBound)
                  || churchAwareEqType
                      (tyToElab existingBound)
                      (tyToElab incomingBound) ->
                  pure existing
              | constructedBound ->
                  pure incoming
              | stage == CompleteBeforeCompilerExact ->
                  pure existing
            _ ->
              Left
                ( ValidationFailed
                    [ "compiler exact completion conflicts with an existing result binder"
                    , "  exact edge: " ++ show exactEdge
                    , "  result: " ++ show ref
                    , "  existing bound: " ++ show existing
                    , "  prepared bound: " ++ show incoming
                    ]
                )

    -- A compiler-exact packet carries the identity quotient from the source
    -- construction binder to its semantic completion binder.  If the
    -- producer already ends in Hyp(existing), installing the delayed binder
    -- below will rename that exact action to Hyp(completion); adding another
    -- Hyp(completion) here would construct the result twice.
    completionAlreadyApplied packet body =
      case body of
        ETyInst _ (InstAbstrRef appliedRef) ->
          any
            (typeBinderRefsSameIdentity appliedRef)
            ( maybeToList
                (subtermGeneralizationCompilerExactExistingRef packet)
                ++ maybeToList
                  (subtermGeneralizationCompilerExactCompletionRef packet)
            )
        _ -> False

    insertAfterLeadingTypeAbstractions delayed current =
      case current of
        ETyAbsRef ref mbBound body ->
          ETyAbsRef
            ref
            mbBound
            (insertAfterLeadingTypeAbstractions delayed body)
        _ ->
          let (_, ref, mbBound, _) = delayed
           in ETyAbsRef ref mbBound current

    mergeCompleted left right =
      case Set.toList (Set.intersection left right) of
        [] -> pure (Set.union left right)
        duplicate : _ -> duplicateOwner duplicate

    duplicateOwner :: ResolvedTermIdentityKey -> Either ElabError a
    duplicateOwner owner =
      Left
        ( ValidationFailed
            [ "compiler exact boundary encountered a duplicate delayed Gamma owner"
            , "  exact edge: " ++ show exactEdge
            , "  owner: " ++ show owner
            ]
        )

annAppSpine :: AnnExpr -> (AnnExpr, [AnnExpr])
annAppSpine annExpr =
  let go args expr =
        case stripAnnExpr expr of
          AApp fun arg _ _ _ -> go (arg : args) fun
          other -> (other, args)
   in go [] annExpr

transparentMediatorSignatureFor :: BindingKey -> AnnExpr -> Maybe ([(IdDetails, NodeId)], AnnExpr)
transparentMediatorSignatureFor rootParam = transparentMediatorBody rootParam Map.empty []
  where
    transparentMediatorBody root aliases etaParams expr =
      case stripAnnExpr expr of
        ALam _param mbDetails paramNode _ body _ _
          | let paramKey = annBinderKey mbDetails,
            paramKey == root
              || Map.member paramKey aliases
              || paramKey `elem` map (annBinderKey . fst) etaParams ->
              Nothing
          | otherwise ->
              transparentMediatorBody
                root
                aliases
                (etaParams ++ [(mbDetails, paramNode)])
                body
        ALet _boundName mbDetails _ _ _ _ rhs body _
          | let boundKey = annBinderKey mbDetails,
            boundKey == root
              || Map.member boundKey aliases
              || boundKey `elem` map (annBinderKey . fst) etaParams ->
              Nothing
          | Just origin <- transparentMediatorAliasOrigin root aliases etaParams rhs ->
              transparentMediatorBody root (Map.insert (annBinderKey mbDetails) origin aliases) etaParams body
          | otherwise ->
              Nothing
        other ->
          let (funExpr, argExprs) = annAppSpine other
           in if transparentMediatorHead root aliases funExpr
                && length argExprs == length etaParams
                && and
                  ( zipWith
                      (transparentMediatorArg aliases)
                      argExprs
                      (map (annBinderKey . fst) etaParams)
                  )
                then Just (etaParams, other)
                else Nothing

    transparentMediatorAliasOrigin root aliases etaParams rhs =
      case directAnnReferenceKey (stripAnnExpr rhs) of
        Just key
          | resolvedMediatorKey aliases key
              `elem` (root : map (annBinderKey . fst) etaParams) ->
              Just (resolvedMediatorKey aliases key)
        _ -> Nothing

    transparentMediatorHead root aliases expr =
      maybe False ((== root) . resolvedMediatorKey aliases) (directAnnReferenceKey (stripAnnExpr expr))

    transparentMediatorArg aliases expr expectedParam =
      maybe False ((== expectedParam) . resolvedMediatorKey aliases) (directAnnReferenceKey (stripAnnExpr expr))

    resolvedMediatorKey aliases key =
      case Map.lookup key aliases of
        Just origin -> origin
        Nothing -> key

transparentMediatorKindAnn :: AnnExpr -> Maybe TransparentMediatorKind
transparentMediatorKindAnn annExpr =
  case stripAnnExpr annExpr of
    ALam _rootParam mbDetails _ _ body _ _ ->
      case transparentMediatorSignatureFor (annBinderKey mbDetails) body of
        Just ([], _) -> Just DirectIdentityMediator
        Just (etaParams, _) -> Just (EtaTransparentMediator (length etaParams))
        Nothing -> Nothing
    _ -> Nothing

-- | Recognize a transparent mediator together with the arguments already
-- supplied to it.  @EtaTransparentMediator n@ has one distinguished function
-- subject followed by @n@ eta arguments.  When an application node is about
-- to supply the final eta argument, the function-side spine therefore has
-- exactly @n@ arguments and its first one is the source expression whose
-- application the mediator preserves.
--
-- This is identity-bearing: a let alias is accepted only through the resolved
-- 'BindingKey' stored in 'EnvBinding'.  Display names never participate.
transparentMediatorSpine
  :: Env
  -> AnnExpr
  -> Maybe (TransparentMediatorKind, Int, Maybe AnnExpr)
transparentMediatorSpine env ann = do
  let (headAnn, suppliedArgs) = annAppSpine ann
  kind <-
    transparentMediatorKindAnn headAnn
      <|> do
        key <- directAnnReferenceKey (stripAnnExpr headAnn)
        binding <- lookupEnvBindingForKey key env
        ebTransparentMediator binding
  let etaArity =
        case kind of
          DirectIdentityMediator -> 0
          EtaTransparentMediator arity -> arity
      suppliedCount = length suppliedArgs
  guard (suppliedCount <= etaArity)
  pure
    ( kind
    , etaArity - suppliedCount
    , case suppliedArgs of
        subject : _ -> Just subject
        [] -> Nothing
    )

transparentMediatorCompletionSubject :: Env -> AnnExpr -> Maybe AnnExpr
transparentMediatorCompletionSubject env functionAnn = do
  (_, remainingArity, mbSubject) <-
    transparentMediatorSpine env functionAnn
  guard (remainingArity == 0)
  mbSubject

-- | Specialize an exact source scheme at one exact application endpoint.
-- This is the source-side counterpart of the edge computation: quantified
-- arguments are inferred from the declared arrow and every step is checked by
-- the xMLF type checker.  When the parent owns the residual result endpoint,
-- use the complete arrow as the construction target.  This lets the argument
-- determine domain-only binders while the result determines result-only
-- binders, as required for partially applied @__io_bind@.
--
-- A bounded source binder can itself contain a quantified lower bound.  Its
-- construction is therefore @Inside phi ; N@, where @phi@ specializes that
-- lower bound to the inferred argument.  Treating the inferred argument as a
-- bare @InstApp@ would skip the paper's bound computation and fail precisely
-- when a Prelude method carries a dependent bounded spine.
sourceSchemeResultAt
  :: TypeCheck.Env
  -> ElabType
  -> Maybe ElabType
  -> SchemeInfo
  -> Maybe ElabType
sourceSchemeResultAt typeEnv argumentTy mbResultTy schemeInfo =
  snd
    <$> sourceSchemeApplicationAt
      typeEnv
      argumentTy
      mbResultTy
      schemeInfo

-- | Construct both endpoints of the source arrow selected at an application.
-- Keeping the domain together with the result is significant for structural
-- recursive types: the source scheme may validate a graph-domain projection
-- while its checked arrow retains the nominal structural binder identities.
-- Returning only the result would allow the caller to combine those exact
-- result identities with an unrelated graph-domain argument.
sourceSchemeApplicationAt
  :: TypeCheck.Env
  -> ElabType
  -> Maybe ElabType
  -> SchemeInfo
  -> Maybe (ElabType, ElabType)
sourceSchemeApplicationAt typeEnv argumentTy mbResultTy schemeInfo =
  specialize (schemeToType (siScheme schemeInfo))
  where
    typesAgree left right =
      alphaEqType left right || churchAwareEqType left right

    specialize currentTy =
      let currentScheme = schemeFromType currentTy
          currentBinders = schemeBinderRefs currentScheme
          currentBody = schemeBody currentScheme
          targetTy =
            maybe
              argumentTy
              (TArrow argumentTy)
              mbResultTy
          inferenceBody =
            case mbResultTy of
              Just _ -> currentBody
              Nothing ->
                case currentBody of
                  TArrow currentDomain _ -> currentDomain
                  _ -> currentBody
          inferred =
            inferInstAppArgsFromSchemeRefsExact
              currentBinders
              inferenceBody
              targetTy
       in case schemeBody currentScheme of
            TArrow {} ->
              case inferred of
                  Just arguments -> do
                    appliedTy <-
                      foldM applySourceArgument currentTy arguments
                    exposeAppliedArrow appliedTy
                  Nothing -> eliminateBoundedPrefix currentTy
            _ -> eliminateBoundedPrefix currentTy

    exposeAppliedArrow appliedTy =
      case appliedTy of
        TForallRef _ (Just _) _ -> do
          eliminatedTy <-
            either
              (const Nothing)
              Just
              ( TypeCheck.checkInstantiation
                  typeEnv
                  appliedTy
                  InstElim
              )
          exposeAppliedArrow eliminatedTy
        TForallRef _ Nothing _ -> Nothing
        TArrow appliedDomain appliedResult
          | typesAgree appliedDomain argumentTy
          , maybe
              True
              (typesAgree appliedResult)
              mbResultTy ->
              Just (appliedDomain, appliedResult)
        _ -> Nothing

    eliminateBoundedPrefix currentTy =
      case currentTy of
        TForallRef _ (Just _) _ -> do
          eliminatedTy <-
            either
              (const Nothing)
              Just
              ( TypeCheck.checkInstantiation
                  typeEnv
                  currentTy
                  InstElim
              )
          specialize eliminatedTy
        _ -> Nothing

    applySourceArgument currentTy argumentTy' = do
      instantiation <-
        sourceArgumentInstantiation currentTy argumentTy'
      either
        (const Nothing)
        Just
        ( TypeCheck.checkInstantiation
            typeEnv
            currentTy
            instantiation
        )

    sourceArgumentInstantiation currentTy argumentTy' =
      case currentTy of
        TForallRef _ Nothing _ ->
          Just (InstApp argumentTy')
        TForallRef _ (Just bound) _
          | typesAgree argumentTy' (tyToElab bound) ->
              Just InstElim
          | otherwise -> do
              inside <-
                constructSourceInstantiation
                  (tyToElab bound)
                  argumentTy'
              pure (InstSeq (InstInside inside) InstElim)
        _ -> Nothing

    constructSourceInstantiation sourceTy targetTy
      | typesAgree sourceTy targetTy =
          Just InstId
      | TBottom <- sourceTy =
          Just (InstBot targetTy)
      | otherwise = do
          let sourceScheme = schemeFromType sourceTy
              sourceBinders = schemeBinderRefs sourceScheme
          arguments <-
            inferInstAppArgsFromSchemeRefsExact
              sourceBinders
              (schemeBody sourceScheme)
              targetTy
          (instantiation, appliedTy) <-
            foldM
              applyNestedSourceArgument
              (InstId, sourceTy)
              arguments
          guard (typesAgree appliedTy targetTy)
          pure instantiation

    applyNestedSourceArgument
      (prefix, currentTy)
      argumentTy' = do
        step <- sourceArgumentInstantiation currentTy argumentTy'
        appliedTy <-
          either
            (const Nothing)
            Just
            ( TypeCheck.checkInstantiation
                typeEnv
                currentTy
                step
            )
        pure (composeInst prefix step, appliedTy)

-- | Recover the exact source application hidden by a completed eta mediator.
-- For @apply g g@, the function-side spine proves that the result is the source
-- application @g g@; the two independently published source schemes then fix
-- both its argument and result to the closed sigma-id type.  No graph result or
-- failed type check is used as an oracle.
mediatedApplicationConstruction
  :: Env
  -> (AnnExpr -> Either ElabError (Maybe SchemeInfo))
  -> AnnExpr
  -> Either ElabError (Maybe MediatedApplicationConstruction)
mediatedApplicationConstruction env sourceSchemeFor applicationAnn =
  case stripAnnExpr applicationAnn of
    AApp functionAnn argumentAnn _ _ _ ->
      case transparentMediatorCompletionSubject env functionAnn of
        Nothing -> pure Nothing
        Just subjectAnn -> do
          mbSubjectSchemeInfo <- sourceSchemeFor subjectAnn
          mbArgumentSchemeInfo <- sourceSchemeFor argumentAnn
          pure $ do
            subjectSchemeInfo <- mbSubjectSchemeInfo
            argumentSchemeInfo <- mbArgumentSchemeInfo
            let argumentTy =
                  schemeToType (siScheme argumentSchemeInfo)
            guard (null (freeTypeVarRefsType argumentTy))
            resultTy <-
              sourceSchemeResultAt
                (typeCheckEnvFrom env)
                argumentTy
                Nothing
                subjectSchemeInfo
            guard (null (freeTypeVarRefsType resultTy))
            pure
              MediatedApplicationConstruction
                { macArgumentType = argumentTy
                , macResultType = resultTy
                }
    _ -> pure Nothing

-- | A source scheme may be observed by the solver through an opened graph
-- projection.  Prove that relationship by exact binder inference before a
-- source-owned closed scheme replaces the provisional projection.
isExactSchemeProjection :: ElabType -> ElabType -> Bool
isExactSchemeProjection closedTy projectedTy =
  alphaEqType closedTy projectedTy
    || case schemeBinderRefs closedScheme of
      [] -> False
      binders ->
        case
            inferInstAppArgsFromSchemeRefsExact
              binders
              (schemeBody closedScheme)
              projectedTy
          of
            Just arguments ->
              length arguments == length binders
                && all isGraphProjectionArgument arguments
            Nothing -> False
  where
    closedScheme = schemeFromType closedTy
    isGraphProjectionArgument argumentTy =
      case argumentTy of
        TVarRef ref -> isJust (typeBinderRefNode ref)
        _ -> False

-- | Refine the exact packet-owned result declaration before the lambda body is
-- elaborated.  The source mediator certificate is stronger than the solver's
-- opened graph projection, but it may replace that projection only after the
-- packet proves which binder this lambda owns and exact scheme inference proves
-- that the old bound is an opening of the closed source scheme.
refineMediatedLambdaConsumerScheme
  :: EdgeId
  -> PreparedSubtermGeneralization
  -> SchemeInfo
  -> MediatedApplicationConstruction
  -> Either ElabError (SchemeInfo, Maybe (TypeBinderRef, ElabType))
refineMediatedLambdaConsumerScheme bodyEdge packet schemeInfo construction =
  case matchingBinders of
    [] -> pure (schemeInfo, Nothing)
    [(resultRef, mbExistingBound)] -> do
      case mbExistingBound of
        Nothing -> pure ()
        Just existingBound
          | isExactSchemeProjection resultTy (tyToElab existingBound) ->
              pure ()
          | otherwise ->
              Left
                ( ValidationFailed
                    [ "source-proven mediated result disagrees with its packet Gamma bound"
                    , "  body edge: " ++ show bodyEdge
                    , "  result binder: " ++ show resultRef
                    , "  packet bound: " ++ show (tyToElab existingBound)
                    , "  source result: " ++ show resultTy
                    ]
                )
      resultBound <-
        case elabToBound resultTy of
          Right bound -> pure bound
          Left cause ->
            Left
              ( ValidationFailed
                  [ "source-proven mediated result is not a Gamma bound"
                  , "  body edge: " ++ show bodyEdge
                  , "  result binder: " ++ show resultRef
                  , "  source result: " ++ show resultTy
                  , "  cause: " ++ cause
                  ]
              )
      let refinedScheme =
            mkElabSchemeWithRefs
              [ if typeBinderRefsSameIdentity ref resultRef
                  then (ref, Just resultBound)
                  else binder
              | binder@(ref, _) <- schemeBinderRefs (siScheme schemeInfo)
              ]
              (schemeBody (siScheme schemeInfo))
      pure
        ( schemeInfoFromRefSubst
            refinedScheme
            (schemeInfoBinderRefSubst schemeInfo)
        , Just (resultRef, resultTy)
        )
    _ ->
      Left
        ( ValidationFailed
            [ "source-proven mediated result selects multiple packet Gamma binders"
            , "  body edge: " ++ show bodyEdge
            , "  candidates: " ++ show matchingBinders
            ]
        )
  where
    resultTy = macResultType construction
    constructionRefs =
      maybeToList
        (subtermGeneralizationConstructionResultAbstractionRef packet)
        ++ maybeToList
          (subtermGeneralizationResultAbstractionRef packet)
        ++ maybe
          []
          (\consumerIdentity ->
            schemeConsumerConstructionRefs consumerIdentity schemeInfo
          )
          (subtermGeneralizationConsumerIdentity packet)
    matchingBinders =
      [ binder
      | binder@(ref, _) <- schemeBinderRefs (siScheme schemeInfo)
      , any (typeBinderRefsSameIdentity ref) constructionRefs
      ]

installRefinedTypeBinding
  :: (TypeBinderRef, ElabType)
  -> Env
  -> Either ElabError Env
installRefinedTypeBinding (refinedRef, refinedTy) env
  | matchingRefs@(_ : _) <-
      filter
        (typeBinderRefsSameIdentity refinedRef)
        (Map.keys (envTypeBindings env)) =
      pure
        env
          { envTypeBindings =
              Map.mapWithKey
                (\ref ty ->
                  if typeBinderRefsSameIdentity ref refinedRef
                    then refinedTy
                    else ty
                )
                (envTypeBindings env)
          , envSourceRefinedGammaBounds =
              foldr
                (\ref -> Map.insert ref refinedTy)
                (envSourceRefinedGammaBounds env)
                matchingRefs
          }
  | otherwise =
      Left
        ( ValidationFailed
            [ "refined packet Gamma binder is absent from the lambda construction environment"
            , "  result binder: " ++ show refinedRef
            , "  environment binders: " ++ show (Map.keys (envTypeBindings env))
            ]
        )

elabAlg :: AlgebraContext p -> AnnExprF (AnnExpr, ElabOut) -> ElabOut
elabAlg algebraContext layer =
  case layer of
    AResolvedVarF details v _ -> mkOut $ \env ->
      maybe
        (Left (EnvLookup v))
        (Right . EVarNode . resolvedEnvBindingVar)
        (lookupEnvBindingForDetails details env)
    ALitF lit _ -> mkOut $ \_ -> Right (ELit lit)
    ALamF v mbBinderDetails paramNode lambdaScopeGen (bodyAnn, bodyOut) bodyEid lamNodeId ->
      let binderDetails = resolvedTermBinderDetails v mbBinderDetails
          f env = do
            let mAnnLambda = desugaredAnnLambdaInfo mbBinderDetails bodyAnn
                sourceAnnotatedParamTy = do
                  (_, _, annotationEdge, _) <- mAnnLambda
                  annotationExpectedTypeForEdge
                    annotationContext
                    annotationEdge
                parameterBodyAnn =
                  case mAnnLambda of
                    Just (_, _, _, innerBodyAnn) -> innerBodyAnn
                    Nothing -> bodyAnn
                descendantAnnotationBinderIdentities =
                  annotationBinderIdentities parameterBodyAnn
                descendantAnnotationBinderDeclarations =
                  annotationBinderDeclarations parameterBodyAnn
                currentLambdaAnnotationBinderIdentities =
                  Set.unions
                    [ exactSourceLambdaBinderIdentities
                        v
                        mbBinderDetails
                        paramNode
                    , case mAnnLambda of
                        Just (_, _, annotationEdge, _) ->
                          annotationEdgeBinderIdentities annotationEdge
                        Nothing -> Set.empty
                    ]
                descendantPacketSourceBinderIdentities =
                  Set.fromList
                    [ typeBinderRefIdentity ref
                    | packet <- preparedBodyPackets
                    , ref <-
                        typeBinderDeclarationRefs
                          ( schemeToType
                              ( siScheme
                                  ( subtermGeneralizationOperatedSchemeInfo
                                      packet
                                  )
                              )
                          )
                    , isJust
                        ( typeBinderIdentityGeneratedUnique
                            (typeBinderRefIdentity ref)
                        )
                    ]
                endpointProtectedBinderIdentities =
                  Set.unions
                    [ currentLambdaAnnotationBinderIdentities
                    , descendantAnnotationBinderIdentities
                    , descendantPacketSourceBinderIdentities
                    ]
                annotationBinderIdentities ann =
                  case ann of
                    AResolvedVar {} -> Set.empty
                    ALit {} -> Set.empty
                    ALam nestedName nestedDetails nestedParamNode _ nestedBody _ _ ->
                      Set.unions
                        [ exactSourceLambdaBinderIdentities
                            nestedName
                            nestedDetails
                            nestedParamNode
                        , case desugaredAnnLambdaInfo nestedDetails nestedBody of
                            Just (_, _, annotationEdge, _) ->
                              annotationEdgeBinderIdentities annotationEdge
                            Nothing -> Set.empty
                        , annotationBinderIdentities nestedBody
                        ]
                    AApp fun arg _ _ _ ->
                      Set.union
                        (annotationBinderIdentities fun)
                        (annotationBinderIdentities arg)
                    ALet _ _ _ _ _ _ rhs nestedBody _ ->
                      Set.union
                        (annotationBinderIdentities rhs)
                        (annotationBinderIdentities nestedBody)
                    AAnn inner _ annotationEdge ->
                      Set.union
                        (annotationEdgeBinderIdentities annotationEdge)
                        (annotationBinderIdentities inner)
                    ALetScope inner _ _ ->
                      annotationBinderIdentities inner
                    AUnfold inner _ _ ->
                      annotationBinderIdentities inner
                annotationBinderDeclarations ann =
                  case ann of
                    AResolvedVar {} -> []
                    ALit {} -> []
                    ALam _ nestedDetails _ _ nestedBody _ _ ->
                      case desugaredAnnLambdaInfo nestedDetails nestedBody of
                        Just (_, _, annotationEdge, _) ->
                          annotationEdgeBinderDeclarations annotationEdge
                            ++ annotationBinderDeclarations nestedBody
                        Nothing -> annotationBinderDeclarations nestedBody
                    AApp fun arg _ _ _ ->
                      annotationBinderDeclarations fun
                        ++ annotationBinderDeclarations arg
                    ALet _ _ _ _ _ _ rhs nestedBody _ ->
                      annotationBinderDeclarations rhs
                        ++ annotationBinderDeclarations nestedBody
                    AAnn inner _ annotationEdge ->
                      annotationEdgeBinderDeclarations annotationEdge
                        ++ annotationBinderDeclarations inner
                    ALetScope inner _ _ ->
                      annotationBinderDeclarations inner
                    AUnfold inner _ _ ->
                      annotationBinderDeclarations inner
                annotationEdgeBinderDeclarations annotationEdge =
                  [ binder
                  | expectedTy <-
                      maybeToList
                        ( annotationExpectedTypeForEdge
                            annotationContext
                            annotationEdge
                        )
                  , binder <- schemeBinderRefs (schemeFromType expectedTy)
                  ]
                annotationEdgeBinderIdentities annotationEdge =
                  Set.fromList
                    [ maybe
                        (typeBinderRefIdentity ref)
                        typeBinderRefIdentity
                        ( do
                            node <- typeBinderRefNode ref
                            IntMap.lookup
                              (getNodeId node)
                              (acSourceBinderRefs annotationContext)
                        )
                    | expectedTy <-
                        maybeToList
                          ( annotationExpectedTypeForEdge
                              annotationContext
                              annotationEdge
                          )
                    , ref <- typeBinderDeclarationRefs expectedTy
                    ]
                exactSourceLambdaBinderIdentities name details param =
                  case
                      ( idDetailsIsEvidence
                          (resolvedTermBinderDetails name details)
                      , IntMap.lookup
                          (getNodeId param)
                          (algExactLambdaParamSourceTypes algebraContext)
                      )
                    of
                      (True, Just sourceTy) ->
                        either
                          (const Set.empty)
                          ( Set.fromList
                              . map typeBinderRefIdentity
                              . typeBinderDeclarationRefs
                          )
                          (srcTypeToElabType algebraContext sourceTy)
                      _ -> Set.empty
                -- A provisional parameter view is not a complete boundary
                -- construction when one of its free occurrences is declared
                -- by the current source annotation (or by a descendant
                -- construction packet).  In particular, the opened @a@ seen
                -- while constructing @g : forall a. a -> a@ must not compete
                -- with the packet's closed source-owned parameter type.
                parameterTypeEscapesProtectedAnnotationScope ty =
                  any
                    ( (`Set.member` endpointProtectedBinderIdentities)
                        . typeBinderRefIdentity
                    )
                    (freeTypeVarRefsType ty)
                retainLexicalParameterType ty = do
                  guard
                    (not (parameterTypeEscapesProtectedAnnotationScope ty))
                  pure ty
                resolvedParam = algResolvedLambdaParamNode algebraContext lamNodeId
                constructedParamTy =
                  Map.lookup
                    (envBindingDetailsKey binderDetails)
                    (envConstructedLambdaParamTypes env)
                    >>= retainLexicalParameterType
                exactApplicationParamSchemeInfo =
                  Map.lookup
                    (envBindingDetailsKey binderDetails)
                    (envExactApplicationLambdaParamSchemes env)
                exactApplicationParamTy =
                  schemeToType . siScheme
                    <$> exactApplicationParamSchemeInfo
                exactEvidenceParamSourceTy =
                  if idDetailsIsEvidence binderDetails
                    then
                      IntMap.lookup
                        (getNodeId paramNode)
                        (algExactLambdaParamSourceTypes algebraContext)
                    else Nothing
                -- The solved arrow is the construction authority for a lambda.
                -- Its domain may legitimately reify as a bare internal variable;
                -- that does not make the original allocation node authoritative
                -- again.  Falling back here can disconnect the emitted binder
                -- from an enclosing application's retained arrow topology.
                paramSource = fromMaybe paramNode resolvedParam
                preparedLambdaGeneralization =
                  Map.lookup
                    (idDetailsIdentityKey binderDetails)
                    (algSubtermGeneralizations algebraContext)
                preparedBodyPackets =
                  Map.elems
                    ( subtermGeneralizationsOwnedBy
                        bodyAnn
                        (algSubtermGeneralizations algebraContext)
                    )
                preparedBodyResultOwnership =
                  subtermResultOwnershipFor
                    bodyAnn
                    (algSubtermGeneralizations algebraContext)
                preparedPacketParamTy = do
                  packet <- preparedLambdaGeneralization
                  let packetSchemeInfo =
                        subtermGeneralizationConsumerConstructionSchemeInfo packet
                  case schemeBody (siScheme packetSchemeInfo) of
                    TArrow domainTy _ -> Just domainTy
                    _ -> do
                      packetRef <-
                        IntMap.lookup
                          (getNodeId (scCanonical scopeContext paramSource))
                          (schemeInfoBinderRefSubst packetSchemeInfo)
                      if
                          any
                            (typeBinderRefsSameIdentity packetRef . fst)
                            (schemeBinderRefs (siScheme packetSchemeInfo))
                        then Just (TVarRef packetRef)
                        else Nothing
                -- The consumer-construction view may retain @Bottom@ for an
                -- unused parameter even though this lambda's own prepared
                -- Gamma bound has already introduced the exact parameter
                -- declaration.  Figure 15.3.5 checks the body under that
                -- completed @S'(n)@.  Read the domain from the packet that is
                -- identity-keyed to this lambda before elaborating the body;
                -- do not wait to retag the completed ELam afterwards.
                preparedGammaBoundParamTy = do
                  packet <- preparedLambdaGeneralization
                  leadingLambdaDomain
                    ( schemeToType
                        (subtermGeneralizationGammaBoundScheme packet)
                    )
                    >>= retainLexicalParameterType
                preparedAdministrativeParamTy = do
                  packet <- preparedLambdaGeneralization
                  (certifiedLambdaNode, certifiedParamNode, certifiedParamTy) <-
                    subtermGeneralizationSourceLambdaParameter packet
                  guard
                    ( certifiedLambdaNode == lamNodeId
                        && certifiedParamNode == paramNode
                    )
                  pure certifiedParamTy
                exactConstructionParamTy = do
                  expectedTy <-
                    envExpectedTermEndpoint env
                      >>= exactConstructionExpectedType
                  leadingLambdaDomain expectedTy
                    >>= retainLexicalParameterType
                unpairedExactConstructionParamTy = do
                  -- A directly constructed parameter already carries the
                  -- source annotation's binder identity.  An enclosing exact
                  -- endpoint may contain an alpha-fresh occurrence of that
                  -- domain, but it is not authority to replace the installed
                  -- boundary.  Use the endpoint only when no parameter
                  -- construction was paired with this lambda.
                  guard (isNothing constructedParamTy)
                  guard (isNothing preparedAdministrativeParamTy)
                  guard (isNothing preparedPacketParamTy)
                  exactConstructionParamTy
                pairedExactConstructionParamTy = do
                  constructionTy <- provisionalParamTy
                  exactTy <- exactConstructionParamTy
                  let sourceConstructionTy =
                        resolveSourceBinderAliasesInType
                          (scopeTypeBinderIdentityRepresentative scopeContext)
                          directParamSourceBinderRefs
                          constructionTy
                  guard
                    ( scopedEndpointTypesAgree
                        scopeContext
                        sourceConstructionTy
                        exactTy
                    )
                  pure exactTy
                directSourceConstructionParamTy = do
                  constructionTy <-
                    provisionalParamTy
                      <|> exactApplicationParamTy
                  let sourceConstructionTy =
                        applyTypeVarRefRenames
                          certifiedParamSourceRenames
                          ( resolveSourceBinderAliasesInType
                              (scopeTypeBinderIdentityRepresentative scopeContext)
                              (acSourceBinderRefs annotationContext)
                              constructionTy
                          )
                  -- Preparation expands each unambiguous source-binder
                  -- identity through its solved/copy nodes specifically for
                  -- reification.  Consume that identity carrier when the
                  -- lambda boundary is installed, so structured domains such
                  -- as @Option a@ and @List a@ never publish a transient
                  -- graph identity that later applications would have to
                  -- repair.  This chooses a payload identity only; ownership
                  -- decisions continue to use the direct-key set.
                  guard (sourceConstructionTy /= constructionTy)
                  retainLexicalParameterType sourceConstructionTy
                certifiedParamSourceRenames =
                  certifiedSourcePacketOccurrenceRenames
                    (acSourceBinderRefs annotationContext)
                    (envConstructionBinderRenames env)
                exactPacketConsumerParamTy = do
                  case exactPacketConsumerParamCandidates of
                    [paramTy] -> Just paramTy
                    _ -> Nothing
                exactPacketConsumerParamCandidates =
                  foldr insertDistinctParam []
                    [ paramTy
                    | packet <-
                        maybeToList preparedLambdaGeneralization
                          ++ preparedBodyPackets
                    , (_, expectedTy, _, _) <-
                        maybeToList
                          ( subtermGeneralizationExactConsumerSpecialization
                              packet
                          )
                    , candidateTy <- maybeToList (leadingLambdaDomain expectedTy)
                    , paramTy <- maybeToList (retainLexicalParameterType candidateTy)
                    , packetParamMatchesConstruction paramTy
                    ]
                packetParamMatchesConstruction paramTy =
                  case provisionalParamTy of
                    Nothing ->
                      any
                        (scopedEndpointTypesAgree scopeContext paramTy)
                        [ preparedParamTy
                        | packet <- maybeToList preparedLambdaGeneralization
                        , (_, expectedTy, _, _) <-
                            maybeToList
                              ( subtermGeneralizationExactConsumerSpecialization
                                  packet
                              )
                        , preparedParamTy <-
                            maybeToList (leadingLambdaDomain expectedTy)
                        ]
                    Just constructionTy ->
                      let sourceConstructionTy =
                            resolveSourceBinderAliasesInType
                              (scopeTypeBinderIdentityRepresentative scopeContext)
                              directParamSourceBinderRefs
                              constructionTy
                       in scopedEndpointTypesAgree
                            scopeContext
                            paramTy
                            constructionTy
                            || scopedEndpointTypesAgree
                              scopeContext
                              paramTy
                              sourceConstructionTy
                provisionalParamTy =
                  constructedParamTy
                    <|> preparedAdministrativeParamTy
                    <|> preparedGammaBoundParamTy
                    <|> preparedPacketParamTy
                directParamSourceBinderRefs =
                  IntMap.restrictKeys
                    (acSourceBinderRefs annotationContext)
                    (acDirectSourceBinderKeys annotationContext)
                insertDistinctParam paramTy paramTypes
                  | any
                      (scopedEndpointTypesAgree scopeContext paramTy)
                      paramTypes =
                      paramTypes
                  | otherwise = paramTy : paramTypes
                leadingLambdaDomain expectedTy =
                  case expectedTy of
                    TForallRef _ _ bodyTy ->
                      leadingLambdaDomain bodyTy
                    TArrow domainTy _ -> Just domainTy
                    _ -> Nothing
            exactEvidenceParamTy <-
              traverse
                (srcTypeToElabType algebraContext)
                exactEvidenceParamSourceTy
            let sourceOwnedParamBinderRefs exactTy =
                  distinctBinderRefs
                    [ occurrenceRef
                    | occurrenceRef <-
                        typeBinderDeclarationRefs exactTy
                          ++ freeTypeVarRefsType exactTy
                    , sourceRef <-
                        IntMap.elems (acSourceBinderRefs annotationContext)
                    , typeBinderRefsSameIdentity occurrenceRef sourceRef
                    ]
                exactSourceParamBoundary exactTy constructionTy =
                  ExactSourceLambdaParamBoundary
                    exactTy
                    constructionTy
                    (sourceOwnedParamBinderRefs exactTy)
                paramBoundaryAuthority =
                  case exactEvidenceParamTy of
                    Just exactTy ->
                      Just
                        (exactSourceParamBoundary exactTy constructedParamTy)
                    Nothing ->
                      case sourceAnnotatedParamTy of
                        Just exactTy ->
                          Just
                            (exactSourceParamBoundary exactTy constructedParamTy)
                        Nothing ->
                          case directSourceConstructionParamTy of
                            Just sourceTy ->
                              Just
                                (exactSourceParamBoundary sourceTy (Just sourceTy))
                            Nothing ->
                              case
                                  exactPacketConsumerParamTy
                                    <|> pairedExactConstructionParamTy
                                    <|> unpairedExactConstructionParamTy
                                of
                                Just exactTy ->
                                  Just
                                    (exactSourceParamBoundary exactTy constructedParamTy)
                                Nothing ->
                                  case exactApplicationParamTy of
                                    Just exactTy ->
                                      Just
                                        ( ExactApplicationLambdaParamBoundary
                                            exactTy
                                        )
                                    Nothing ->
                                      ConstructedLambdaParamBoundary
                                        <$> constructedParamTy
            ( installedParamTy
              , installedParamBoundaryProtectedIdentities
              , mbParamBoundaryCertificate
              , envAfterConstructedParam
              ) <-
              let consumedEnv =
                    env
                      { envConstructedLambdaParamTypes =
                          Map.delete
                            (envBindingDetailsKey binderDetails)
                            (envConstructedLambdaParamTypes env)
                      , envExactApplicationLambdaParamSchemes =
                          Map.delete
                            (envBindingDetailsKey binderDetails)
                            (envExactApplicationLambdaParamSchemes env)
                      }
               in case paramBoundaryAuthority of
                    Just authority -> do
                      ( paramTy
                        , localBinderIdentities
                        , boundaryCertificate
                        , installedEnv
                        ) <-
                        case
                            installConstructedLambdaParamBound
                              ( scopeTypeBinderIdentityRepresentative
                                  scopeContext
                                  paramSource
                              )
                              authority
                              consumedEnv
                          of
                            Right installed -> pure installed
                            Left cause ->
                              Left
                                ( ValidationFailed
                                    [ "lambda parameter boundary construction failed"
                                    , "  lambda: " ++ show lamNodeId
                                    , "  parameter: " ++ show paramNode
                                    , "  binder: " ++ show binderDetails
                                    , "  constructed parameter: "
                                        ++ show constructedParamTy
                                    , "  administrative parameter: "
                                        ++ show preparedAdministrativeParamTy
                                    , "  prepared packet parameter: "
                                        ++ show preparedPacketParamTy
                                    , "  prepared Gamma-bound parameter: "
                                        ++ show preparedGammaBoundParamTy
                                    , "  exact packet candidates: "
                                        ++ show exactPacketConsumerParamCandidates
                                    , "  exact endpoint parameter: "
                                        ++ show exactConstructionParamTy
                                    , "  selected authority: " ++ show authority
                                    , "  cause: " ++ show cause
                                    ]
                                )
                      pure
                        ( Just paramTy
                        , localBinderIdentities
                        , Just boundaryCertificate
                        , installedEnv
                        )
                    Nothing ->
                      pure (Nothing, Set.empty, Nothing, consumedEnv)
            let paramBoundaryProtectedIdentities =
                  Set.union
                    installedParamBoundaryProtectedIdentities
                    ( lambdaParamBoundaryProtectedIdentities
                        ( envLambdaParamBoundaryCertificates
                            envAfterConstructedParam
                        )
                    )
            preparedBodyGeneralization <-
              case preparedBodyPackets of
                [] -> pure Nothing
                [packet] -> pure (Just packet)
                packets ->
                  Left
                    ( ValidationFailed
                        [ "lambda body has multiple direct construction packets"
                        , "  owner: " ++ show (idDetailsIdentityKey binderDetails)
                        , "  packets: " ++ show (map subtermGeneralizationSchemeInfo packets)
                        ]
                    )
            let currentLambdaIsTransparent =
                  isJust
                    ( transparentMediatorKindAnn
                        ( ALam
                            v
                            mbBinderDetails
                            paramNode
                            lambdaScopeGen
                            bodyAnn
                            bodyEid
                            lamNodeId
                        )
                    )
                preparedConstructionPackets =
                  [ (packet, True)
                  | packet <- maybeToList preparedLambdaGeneralization
                  ]
                    ++ [ (packet, False)
                       | packet <- maybeToList preparedBodyGeneralization
                       , currentLambdaIsTransparent
                       ]
                directSourceBinderRefs =
                  IntMap.restrictKeys
                    (acSourceBinderRefs annotationContext)
                    (acDirectSourceBinderKeys annotationContext)
                -- A direct child packet can publish a construction binder in
                -- its completed scheme even when it has no compiler-exact
                -- source rename.  Enter each proved lexical layer before
                -- constructing the child so an enclosing lambda parameter and
                -- every nested occurrence use one identity-bearing type.
                -- Parent and child routes compose in order.  The parent's
                -- packet-local source quotient is active here; a direct
                -- child's quotient is not active until that child reaches its
                -- own boundary, so the parent admits only declaration-backed
                -- routes from the child's completed scheme.
                enterConstructionPacket currentEnv (packet, includePacketRoutes) = do
                  let constructionInfo =
                        completeLambdaParamBoundarySchemeInfo
                          (maybeToList mbParamBoundaryCertificate)
                          ( subtermGeneralizationConsumerConstructionSchemeInfo
                              packet
                          )
                      localSourceDeclarationRefs =
                        case preparedBodyResultOwnership of
                          Just ownership
                            | not includePacketRoutes
                            , subtermResultOwnershipPacket ownership == packet ->
                                subtermResultOwnershipLocalSourceDeclarationRefs
                                  directSourceBinderRefs
                                  ownership
                          _ -> []
                      packetRenames0 =
                        lambdaParamConstructionRenames
                          paramBoundaryProtectedIdentities
                          ( if includePacketRoutes
                              then
                                subtermGeneralizationConstructionBinderRenames
                                  packet
                              else
                                schemeConstructionAuthorityRenames
                                  directSourceBinderRefs
                                  currentEnv
                                  constructionInfo
                          )
                      -- The direct child owns these source declarations at
                      -- its exact lambda boundary.  Their sidecar identities
                      -- justify the completed packet's declaration shape,
                      -- but entering either the binder or its graph quotient
                      -- here would put the same variable in the enclosing
                      -- Gamma before the child emits its ETyAbsRef.
                      packetRenames =
                        [ rename
                        | rename@(_, outwardRef) <- packetRenames0
                        , not
                            ( any
                                (typeBinderRefsSameIdentity outwardRef)
                                localSourceDeclarationRefs
                            )
                        ]
                      constructionBinders =
                        [ binder
                        | binder@(binderRef, _) <-
                            schemeBinderRefs (siScheme constructionInfo)
                        , not
                            ( any
                                (typeBinderRefsSameIdentity binderRef)
                                localSourceDeclarationRefs
                            )
                        ]
                  alignedEnv <-
                    alignEnvToNestedConstructionBinderRenames
                      packetRenames
                      currentEnv
                  -- A transparent parent is the lexical construction scope
                  -- for its direct child's completed scheme.  Non-identity
                  -- routes alone cannot install a packet whose outward
                  -- binder deliberately keeps its graph identity, so enter
                  -- the packet's exact declarations here.  They remain
                  -- ambient to the lambda's own Gen(Gamma, tau) and are
                  -- closed once, by the enclosing let construction; exact
                  -- source declarations owned by that lambda were excluded
                  -- above.
                  pure $
                    if includePacketRoutes
                      then alignedEnv
                      else
                        extendEnvTypeScopeWithAliases
                          (schemeInfoBinderRefSubst constructionInfo)
                          constructionBinders
                          alignedEnv
            envAtLambdaBoundary <-
              foldM
                enterConstructionPacket
                envAfterConstructedParam
                preparedConstructionPackets
            let bodyElabOut =
                  case mAnnLambda of
                    Just (_, _, _, innerBodyAnn) -> para (elabAlg algebraContext) innerBodyAnn
                    Nothing -> bodyOut
            let preservedAnnotationTyRaw = sourceAnnotatedParamTy
                packetOwnsConsumerAtCurrentLambda packet =
                  case subtermGeneralizationGammaAuthority packet of
                    Just authority ->
                      gpaEdgeId authority == bodyEid
                        && gpaOwnerGen authority == lambdaScopeGen
                    Nothing ->
                      case subtermGeneralizationConsumerAuthority packet of
                        Just authority
                          | subtermConsumerAuthorityIsTopology authority ->
                              case
                                  subtermConsumerAuthorityEnclosingOwner
                                    authority
                                of
                                  Just topologyOwner ->
                                    scaEdgeId authority == bodyEid
                                      && lgoConstructor topologyOwner
                                        == LocalLambdaGamma
                                      && lgoBoundaryEdge topologyOwner
                                        == bodyEid
                                      && lgoTermNode topologyOwner
                                        == lamNodeId
                                      && lgoScope topologyOwner
                                        == GenRef lambdaScopeGen
                                  Nothing -> False
                        _ -> False
                currentLambdaPacketOwnedRefs packet
                  | packetOwnsConsumerAtCurrentLambda packet
                  =
                      map
                        fst
                        ( schemeBinderRefs
                            ( siScheme
                                ( subtermGeneralizationConsumerConstructionSchemeInfo
                                    packet
                                )
                            )
                        )
                  | otherwise = []
                packetSchemeFresheningEnv packet =
                  hideLocallyEmittedTypeBinders
                    (currentLambdaPacketOwnedRefs packet)
                    envAtLambdaBoundary
                packetSchemeSourceBinderRefs packet =
                  case subtermGeneralizationGammaAuthority packet of
                    Just authority ->
                      case
                          typeBinderIdentityNode
                            (gpaConsumerIdentity authority)
                            >>= ( \node ->
                                    IntMap.lookup
                                      (getNodeId node)
                                      (acSourceBinderRefs annotationContext)
                                )
                        of
                        Just sourceRef
                          | not
                              ( packetGammaBoundIsExactSourceAlias
                                  packet
                                  sourceRef
                              ) ->
                              -- A source sidecar identifies occurrences, not
                              -- declarations.  For a structured S'(operated),
                              -- the packet exterior is a fresh flexible
                              -- consumer whose bound merely depends on the
                              -- source occurrence.  Routing that declaration
                              -- to the source binder would turn an
                              -- instantiation result into the source forall
                              -- itself.  Only the bare-variable RaiseMerge
                              -- case is an identity alias.
                              IntMap.filter
                                ( not
                                    . typeBinderRefsSameIdentity sourceRef
                                )
                                (acSourceBinderRefs annotationContext)
                        _ -> acSourceBinderRefs annotationContext
                    Nothing -> acSourceBinderRefs annotationContext
                packetGammaBoundIsExactSourceAlias packet sourceRef =
                  case
                      schemeToType
                        (subtermGeneralizationGammaBoundScheme packet)
                    of
                    TVarRef boundRef ->
                      typeBinderRefsSameIdentity boundRef sourceRef
                    _ -> False
            let enclosingConstructionBinderRenames =
                  envConstructionBinderRenames envAtLambdaBoundary
                locallyOwnedConsumerIdentities packet =
                  Set.fromList
                    [ consumerIdentity
                    | consumerIdentity <-
                        maybeToList
                          (subtermGeneralizationConsumerIdentity packet)
                    , let consumerRef =
                            typeBinderRefFromIdentity
                              consumerIdentity
                              (typeBinderIdentityStableName consumerIdentity)
                    , packetOwnsConsumerAtCurrentLambda packet
                        || not
                          ( envOwnsExactTypeBinderRef
                              envAtLambdaBoundary
                              consumerRef
                          )
                    ]
                -- The completed packet is the preparation-time ownership
                -- proof for its declared quantifiers. Packet-local
                -- declarations shadow representative-equivalent ambient
                -- aliases.  A packet whose Gamma certificate names this exact
                -- lambda and body edge remains local even if recursive child
                -- checking installed a provisional declaration with the same
                -- identity; that provisional slot is not enclosing paper
                -- Gamma.  Other exact identities already free in the
                -- enclosing Gamma are ambient and must still be subtracted by
                -- Gen(Gamma, tau).
                packetOwnedDeclarationIdentities packet =
                  Set.fromList
                    [ typeBinderRefIdentity ref
                    | (ref, _) <-
                        schemeBinderRefs
                          ( siScheme
                              ( applySchemeInfoRefRenames
                                  enclosingConstructionBinderRenames
                                  (subtermGeneralizationSchemeInfo packet)
                              )
                          )
                    , not
                        ( envOwnsExactTypeBinderRef
                            envAtLambdaBoundary
                            ref
                        )
                    ]
                preservedAnnotationTy =
                  applyTypeVarRefRenames enclosingConstructionBinderRenames
                    <$> preservedAnnotationTyRaw
                installedConstructionParamTy =
                  applyTypeVarRefRenames enclosingConstructionBinderRenames
                    <$> installedParamTy
                administrativeParamTy =
                  applyTypeVarRefRenames enclosingConstructionBinderRenames
                    <$> preparedAdministrativeParamTy
                selectedPreparedParamTy =
                  case
                      ( administrativeParamTy
                      , installedConstructionParamTy
                      )
                    of
                      (Just (TVarRef packetRef), Just constructionTy)
                        | not
                            ( any
                                (typeBinderRefsSameIdentity packetRef)
                                (freeTypeVarRefsType constructionTy)
                            ) ->
                            -- The paired administrative packet retains only
                            -- a pending graph slot, while the enclosing
                            -- source constructor has already installed the
                            -- complete domain for this same resolved lambda.
                            -- Preserve that construction contract instead of
                            -- erasing it with the placeholder.
                            Just constructionTy
                      (Just packetTy, _) -> Just packetTy
                      (Nothing, _) -> Nothing
            paramTySurface0 <-
              case exactEvidenceParamTy of
                Just exactTy -> pure exactTy
                Nothing ->
                  case preservedAnnotationTy of
                    Just sourceTy -> pure sourceTy
                    Nothing ->
                      case selectedPreparedParamTy of
                        Just preparedTy -> pure preparedTy
                        Nothing ->
                          -- A compiler-exact endpoint is the construction
                          -- contract for this lambda spine. Its domain wins
                          -- over a provisional graph-derived parameter slot
                          -- unless source preparation retained the stronger
                          -- administrative parameter certificate above.
                          case
                              envExpectedTermEndpoint envAtLambdaBoundary
                                >>= exactConstructionExpectedType
                            of
                              Just (TArrow expectedDomain _) -> pure expectedDomain
                              _ ->
                                case installedConstructionParamTy of
                                  Just constructionTy -> pure constructionTy
                                  Nothing ->
                                    case preparedPacketParamTy of
                                      Just packetTy ->
                                        pure
                                          ( applyTypeVarRefRenames
                                              enclosingConstructionBinderRenames
                                              packetTy
                                          )
                                      Nothing ->
                                        case
                                            expectedTermEndpointType
                                              <$> envExpectedTermEndpoint envAtLambdaBoundary
                                          of
                                          Just (TArrow expectedDomain _) -> pure expectedDomain
                                          _ -> reifyNodeTypePreferringBound scopeContext paramSource
            let paramTySurface = paramTySurface0
            (_paramTyUnaligned, paramSchemeInfoUnaligned) <-
              case mAnnLambda of
                Just (_, annNodeId, _, _) ->
                  -- First, check if we have the original source annotation type
                  -- preserved from constraint generation.  This is the exact type
                  -- the user wrote (after lowering), which presolution may have
                  -- corrupted (e.g. stripping TForall inside a μ body).
                  case preservedAnnotationTy of
                    Just preservedTy -> do
                      pure
                        ( preservedTy,
                          schemeInfoFromRefSubst (schemeFromType preservedTy) IntMap.empty
                        )
                    Nothing ->
                      case generalizeAtNode scopeContext annNodeId of
                        Right (paramScheme, _subst) ->
                          let paramTy0 = case (schemeBinderRefs paramScheme, schemeBody paramScheme) of
                                ([(ref, Just bnd)], TVarRef bodyRef)
                                  | typeBinderRefsSameIdentity ref bodyRef -> tyToElab bnd
                                _ -> schemeToType paramScheme
                              -- If generalizeAtNode returned a bare TVar (over-generalized)
                              -- or a base type that disagrees with the constraint graph's
                              -- solved μ type, fall back to reifyNodeTypePreferringBound.
                              -- This handles the case where ELamAnn's desugared
                              -- annotation-let picks up the body's result type (e.g. Bool)
                              -- instead of the actual annotation type (e.g. μ Nat).
                              paramTyResolved = case paramTy0 of
                                TVarRef {} ->
                                  case reifyNodeTypePreferringBound scopeContext annNodeId of
                                    Right ty@TMuRef {} -> ty
                                    _ -> paramTy0
                                TBaseWithIdentity {} ->
                                  case reifyNodeTypePreferringBound scopeContext annNodeId of
                                    Right ty@TMuRef {} -> ty
                                    _ -> paramTy0
                                _
                                  | TMuRef {} <- paramTySurface,
                                    Just unfoldedSurface <- unfoldMuOnce paramTySurface,
                                    (alphaEqType unfoldedSurface paramTy0 || churchAwareEqType unfoldedSurface paramTy0) ->
                                      paramTySurface
                                _ -> paramTy0
                           in pure
                                ( paramTyResolved,
                                  schemeInfoFromRefSubst (schemeFromType paramTyResolved) IntMap.empty
                                )
                        Left (SchemeFreeVars _ _) ->
                          pure
                            ( paramTySurface,
                              schemeInfoFromRefSubst (schemeFromType paramTySurface) IntMap.empty
                            )
                        Left err -> Left err
                Nothing ->
                  case exactEvidenceParamTy of
                    Just exactTy ->
                      pure
                        ( exactTy,
                          schemeInfoFromRefSubst (schemeFromType exactTy) IntMap.empty
                        )
                    Nothing ->
                      case exactApplicationParamSchemeInfo of
                        Just exactSchemeInfo ->
                          pure
                            ( schemeToType (siScheme exactSchemeInfo)
                            , exactSchemeInfo
                            )
                        Nothing ->
                          pure
                            ( paramTySurface,
                              schemeInfoFromRefSubst
                                (schemeFromType paramTySurface)
                                IntMap.empty
                            )
            preparedLambdaSchemeInfo0 <-
              traverse
                ( \packet ->
                    completeLambdaParamBoundarySchemeInfo
                      (maybeToList mbParamBoundaryCertificate)
                      <$> freshenSchemeInfoAgainstConstructionEnvExcept
                        ( Set.unions
                            [ packetOwnedDeclarationIdentities packet
                            , locallyOwnedConsumerIdentities packet
                            -- The parameter boundary is already the source
                            -- constructor for these identities.  Freshening a
                            -- packet against that same boundary would split the
                            -- lambda domain from its body endpoint and only try
                            -- to reconcile the two after elaboration.
                            , paramBoundaryProtectedIdentities
                            ]
                        )
                        (scopeTypeBinderIdentityRepresentative scopeContext)
                        (packetSchemeSourceBinderRefs packet)
                        (packetSchemeFresheningEnv packet)
                        ( applySchemeInfoRefRenames
                            enclosingConstructionBinderRenames
                            ( subtermGeneralizationConsumerConstructionSchemeInfo
                                packet
                            )
                        )
                )
                preparedLambdaGeneralization
            envAtLambdaConstructionBoundary <-
              case preparedLambdaSchemeInfo0 of
                Just schemeInfo ->
                  alignEnvToNestedConstructionBinderRenames
                    ( lambdaParamConstructionRenames
                        paramBoundaryProtectedIdentities
                        ( schemeConstructionAuthorityRenames
                            directSourceBinderRefs
                            envAtLambdaBoundary
                            schemeInfo
                        )
                    )
                    envAtLambdaBoundary
                Nothing -> pure envAtLambdaBoundary
            let constructionBinderRenames =
                  envConstructionBinderRenames
                    envAtLambdaConstructionBoundary
                paramBoundaryRecoveryRenames =
                  lambdaParamBoundaryRecoveryRenames
                    ( envLambdaParamBoundaryCertificates
                        envAfterConstructedParam
                    )
                    constructionBinderRenames
                -- Method-local forall declarations remain protected below,
                -- but a free evidence identity may already have been routed
                -- by the enclosing Figure 15.3.5 construction before this
                -- lambda is entered.  Snapshot that outer proof before
                -- adding the lambda/body packets and apply it to the
                -- parameter in the same direction as its occurrences.
                -- Otherwise the body is constructed at the outward Gamma
                -- identity while the evidence binder retains the pre-route
                -- source identity.
                exactEvidenceOuterConstructionRenames =
                  case exactEvidenceParamTy of
                    Nothing -> []
                    Just exactTy ->
                      [ rename
                      | rename@(sourceRef, _) <-
                          envConstructionBinderRenames envAfterConstructedParam
                      , any
                          (typeBinderRefsSameIdentity sourceRef)
                          (freeTypeVarRefsType exactTy)
                      ]
                envWithLambdaTypeScope0 =
                  case preparedLambdaSchemeInfo0 of
                    Just schemeInfo ->
                      extendEnvTypeScopeWithAliases
                        (schemeInfoBinderRefSubst schemeInfo)
                        (schemeBinderRefs (siScheme schemeInfo))
                        envAtLambdaConstructionBoundary
                    Nothing -> envAtLambdaConstructionBoundary
            let paramSchemeInfoForConstruction =
                  applySchemeInfoRefRenames
                    ( paramBoundaryRecoveryRenames
                        ++ exactEvidenceOuterConstructionRenames
                        ++ lambdaParamConstructionRenames
                          paramBoundaryProtectedIdentities
                          constructionBinderRenames
                    )
                    paramSchemeInfoUnaligned
            paramSchemeInfo <-
              -- The packet's own result consumer is not part of the
              -- environment used to type the lambda parameter.  In
              -- particular, the source forall in @id : forall a. a -> a@
              -- remains the parameter authority; a peer graph result created
              -- for the lambda body must not capture that source identity
              -- merely because both nodes share a solved representative.
              generalizeSchemeInfoAgainstConstructionEnvPreserving
                paramBoundaryProtectedIdentities
                ( maybe
                    Set.empty
                    locallyOwnedConsumerIdentities
                    preparedLambdaGeneralization
                )
                (scopeTypeBinderIdentityRepresentative scopeContext)
                (acSourceBinderRefs annotationContext)
                envWithLambdaTypeScope0
                paramSchemeInfoForConstruction
            let paramTy = schemeToType (siScheme paramSchemeInfo)
                paramBinding =
                  (mkLocalEnvBinding v binderDetails paramSchemeInfo Nothing)
                    { ebExplicitRecursiveParam =
                        isJust mAnnLambda && hasContractiveRecursiveWitness paramTy
                    }
                installLambdaParamBinding lambdaEnv =
                  let envWithLambdaParam0 =
                        insertEnvBinding paramBinding lambdaEnv
                   in case mAnnLambda of
                        Just (mediatorDetails, _, _, _) ->
                          insertEnvBindingIdentityAlias
                            mediatorDetails
                            paramBinding
                            envWithLambdaParam0
                        Nothing -> envWithLambdaParam0
                envWithLambdaParamInitial =
                  installLambdaParamBinding envWithLambdaTypeScope0
                lambdaActiveConsumerAuthority =
                  ( preparedLambdaGeneralization
                      >>= subtermGeneralizationConsumerAuthority
                  )
                    <|> ( envActiveSubtermConstruction env
                            >>= subtermGeneralizationConsumerAuthority
                        )
                lambdaEnclosingConsumerAuthority =
                  envActiveSubtermConstruction env
                    >>= subtermGeneralizationConsumerAuthority
                lambdaActiveConsumerKey =
                  subtermConsumerAuthorityKey
                    <$> lambdaActiveConsumerAuthority
                lambdaResolvedLookup details =
                  ebSchemeInfo
                    <$> lookupEnvBindingForDetails
                      details
                      envWithLambdaParamInitial
                lambdaSourceSchemeFor =
                  sourceSchemeInfoForConstruction
                    lambdaActiveConsumerAuthority
                    lambdaEnclosingConsumerAuthority
                    annotationContext
                    (algNamedSetReify algebraContext)
                    lambdaResolvedLookup
                lambdaConstructionBodyAnn =
                  case mAnnLambda of
                    Just (_, _, _, innerBodyAnn) -> innerBodyAnn
                    Nothing -> bodyAnn
                lambdaScope = GenRef lambdaScopeGen
                lambdaOwner =
                  LocalGammaOwner
                    { lgoConstructor = LocalLambdaGamma,
                      lgoBoundaryEdge = bodyEid,
                      lgoTermNode = lamNodeId,
                      lgoScope = lambdaScope
                    }
            mediatedLambdaConstruction <-
              mediatedApplicationConstruction
                envWithLambdaParamInitial
                lambdaSourceSchemeFor
                lambdaConstructionBodyAnn
            exactLambdaBodyPacket <-
              selectExactLambdaBodyPacket
                lambdaOwner
                bodyEid
                [ preparedLambdaGeneralization
                , preparedBodyGeneralization
                ]
            let exactLambdaBodyPacketConstructionRenames =
                  maybe
                    []
                    subtermGeneralizationConstructionBinderRenames
                    exactLambdaBodyPacket
                sourceLambdaConstructionPacket = do
                  packet <- preparedLambdaGeneralization
                  (certifiedLambdaNode, _) <-
                    subtermGeneralizationSourceLambdaResultConstruction packet
                  guard (certifiedLambdaNode == lamNodeId)
                  pure packet
            (preparedLambdaSchemeInfo, mbRefinedGammaBinding) <-
              case
                  ( preparedLambdaGeneralization
                  , exactLambdaBodyPacket
                  , preparedLambdaSchemeInfo0
                  , mediatedLambdaConstruction
                  )
                of
                  ( Just packet
                    , Just exactPacket
                    , Just schemeInfo
                    , Just construction
                    )
                      | packet == exactPacket -> do
                          (refinedSchemeInfo, mbRefinedBinding) <-
                            refineMediatedLambdaConsumerScheme
                              bodyEid
                              packet
                              schemeInfo
                              construction
                          pure (Just refinedSchemeInfo, mbRefinedBinding)
                  _ -> pure (preparedLambdaSchemeInfo0, Nothing)
            preparedLambdaGeneralizationForConstruction <-
              case
                  ( preparedLambdaGeneralization
                  , preparedLambdaSchemeInfo
                  )
                of
                  (Just packet, Just schemeInfo) ->
                    Just
                      <$> resolveSubtermLocalResultAtConstruction
                        schemeInfo
                        packet
                  (Nothing, Nothing) -> pure Nothing
                  _ ->
                    Left
                      ( ValidationFailed
                          [ "prepared lambda packet and construction scheme disagree before body construction"
                          , "  packet: " ++ show preparedLambdaGeneralization
                          , "  scheme: " ++ show preparedLambdaSchemeInfo
                          ]
                      )
            envWithLambdaTypeScope <-
              case mbRefinedGammaBinding of
                Just refinedBinding ->
                  installRefinedTypeBinding
                    refinedBinding
                    envWithLambdaTypeScope0
                Nothing -> pure envWithLambdaTypeScope0
            let envWithLambdaParam =
                  installLambdaParamBinding envWithLambdaTypeScope
                mediatedBodyResultTy =
                  case (mediatedLambdaConstruction, mbRefinedGammaBinding) of
                    (Just construction, Just _) ->
                      Just (macResultType construction)
                    _ -> Nothing
                lambdaEdgeArtifacts = acEdgeArtifacts annotationContext
                preparedPacketBodyExpectedEndpoint packet =
                  selectExpectedTermEndpoint
                    (scopedTypesAgree scopeContext)
                    ("lambda packet body edge " ++ show bodyEid)
                    [ ExactConstructionExpectedTerm
                        <$> mediatedBodyResultTy
                    , packetResultExpectedEndpoint packet
                    , CheckingExpectedTerm
                        <$> topologyBodyCheckExpectedType packet
                    , packetLambdaCodomainExpectedEndpoint packet
                    ]
                packetLambdaCodomainExpectedEndpoint packet = do
                  codomainTy <- packetLambdaCodomain packet
                  let operatedTy =
                        schemeToType
                          ( siScheme
                              (subtermGeneralizationOperatedSchemeInfo packet)
                          )
                      packetConstructsCodomain =
                        scopedEndpointTypesAgree
                          scopeContext
                          codomainTy
                          operatedTy
                  pure
                    ( if packetConstructsCodomain
                        then
                          endpointOwnedByConstructionEnv
                            envWithLambdaTypeScope
                            codomainTy
                        else CheckingExpectedTerm codomainTy
                    )
                packetResultExpectedEndpoint packet =
                  ( \packetResultTy ->
                      if packetResultDeclarationIsProvisional
                          packet
                          packetResultTy
                        then CheckingExpectedTerm packetResultTy
                        else
                          endpointOwnedByConstructionEnv
                            envWithLambdaTypeScope
                            packetResultTy
                  )
                    <$> packetResultExpectedType packet
                -- A composed packet can publish a bound that still contains
                -- the Bottom placeholder of an exact, initially unbounded
                -- consumer declaration.  Its operated view is the independent
                -- post-body check that will complete that declaration.  Until
                -- Typ(body) has been constructed, this bound is checking
                -- guidance rather than a second exact downward endpoint.
                packetResultDeclarationIsProvisional packet packetResultTy =
                  case
                      ( subtermGeneralizationResultAbstractionRef packet
                      , schemeToType
                          ( siScheme
                              ( subtermGeneralizationOperatedSchemeInfo
                                  packet
                              )
                          )
                      )
                    of
                      (Just resultRef, operatedTy) ->
                        lookupBinderBound
                          resultRef
                          ( subtermGeneralizationConsumerConstructionSchemeInfo
                              packet
                          )
                          == Just Nothing
                          && typeContainsBottom packetResultTy
                          && not (typeContainsBottom operatedTy)
                      _ -> False
                typeContainsBottom ty =
                  case ty of
                    TBottom -> True
                    TVarRef _ -> False
                    TArrow domain codomain ->
                      typeContainsBottom domain
                        || typeContainsBottom codomain
                    TConWithIdentity _ _ arguments ->
                      any typeContainsBottom arguments
                    TVarAppRef _ arguments ->
                      any typeContainsBottom arguments
                    TBaseWithIdentity _ _ -> False
                    TForallRef _ mbBound body ->
                      maybe
                        False
                        (typeContainsBottom . tyToElab)
                        mbBound
                        || typeContainsBottom body
                    TMuRef _ body -> typeContainsBottom body
                -- S'(operated) is an independent expectation for checking the
                -- recursively constructed child.  It is not the consumer's
                -- Gamma bound: only the checked child source can complete that
                -- pending declaration in 'materializeConsumerBound'.
                topologyBodyCheckExpectedType packet = do
                  authority <- subtermGeneralizationConsumerAuthority packet
                  if not (subtermConsumerAuthorityIsTopology authority)
                    then Nothing
                    else do
                      let consumerIdentity = scaConsumerIdentity authority
                          directRef =
                            typeBinderRefFromIdentity
                              consumerIdentity
                              (typeBinderIdentityStableName consumerIdentity)
                          constructionInfo =
                            subtermGeneralizationConsumerConstructionSchemeInfo packet
                          constructionRef =
                            case typeBinderRefNode directRef of
                              Just consumerNode ->
                                IntMap.findWithDefault
                                  directRef
                                  (getNodeId consumerNode)
                                  (schemeInfoBinderRefSubst constructionInfo)
                              Nothing -> directRef
                      if typeBinderRefsSameIdentity directRef constructionRef
                        then
                          Just
                            ( applyTypeVarRefRenames
                                constructionBinderRenames
                                ( schemeToType
                                    ( siScheme
                                        (subtermGeneralizationOperatedSchemeInfo packet)
                                    )
                                )
                            )
                        else Nothing
                packetResultExpectedType packet = do
                  resultRef <- subtermGeneralizationResultAbstractionRef packet
                  mbBound <-
                    lookupBinderBound
                      resultRef
                      (subtermGeneralizationSchemeInfo packet)
                      <|> lookupBinderBound
                        resultRef
                        ( subtermGeneralizationConsumerConstructionSchemeInfo
                            packet
                        )
                  bound <- mbBound
                  pure (tyToElab bound)
                packetLambdaCodomain packet =
                  case schemeBody constructionScheme of
                    TArrow _ codomainTy@(TVarRef codomainRef) ->
                      case lookupBinderBound codomainRef constructionInfo of
                        Just (Just codomainBound) -> Just (tyToElab codomainBound)
                        _ -> Just codomainTy
                    TArrow _ codomainTy -> Just codomainTy
                    _ -> Nothing
                  where
                    constructionInfo =
                      subtermGeneralizationConsumerConstructionSchemeInfo packet
                    constructionScheme = siScheme constructionInfo
                expectedLambdaCodomain = go False
                  where
                    go unfoldedMu expectedTy =
                      case expectedTy of
                        TArrow _ codomainTy -> Just codomainTy
                        TForallRef _ _ bodyTy -> go unfoldedMu bodyTy
                        muTy@TMuRef {}
                          | not unfoldedMu
                          , hasContractiveRecursiveWitness muTy ->
                              unfoldMuOnce muTy >>= go True
                        _ -> Nothing
                -- An exact lambda can be published directly at a bounded
                -- ambient declaration.  Its installed Gamma bound determines
                -- the value-lambda boundary that must be constructed, while
                -- the original flexible endpoint remains the published type
                -- and is reached by the planner's terminal Hyp step.
                expectedLambdaConstructionView constructionEnv =
                  go Set.empty False
                  where
                    go visited unfoldedMu expectedTy =
                      case expectedTy of
                        TArrow domainTy codomainTy ->
                          Just (domainTy, codomainTy)
                        TForallRef _ _ bodyTy ->
                          go visited unfoldedMu bodyTy
                        TVarRef ref
                          | let identity = typeBinderRefIdentity ref
                          , not (Set.member identity visited) -> do
                              bound <-
                                TypeCheck.lookupTypeBindingRef
                                  ref
                                  (typeCheckEnvFrom constructionEnv)
                              guard
                                ( not
                                    ( scopedEndpointTypesAgree
                                        scopeContext
                                        bound
                                        TBottom
                                    )
                                )
                              go
                                (Set.insert identity visited)
                                unfoldedMu
                                bound
                        muTy@TMuRef {}
                          | not unfoldedMu
                          , hasContractiveRecursiveWitness muTy ->
                              unfoldMuOnce muTy
                                >>= go visited True
                        _ -> Nothing
                expectedLambdaConstructionDomain constructionEnv ty =
                  fst <$> expectedLambdaConstructionView constructionEnv ty
                expectedLambdaConstructionCodomain constructionEnv ty =
                  snd <$> expectedLambdaConstructionView constructionEnv ty
                exactExpectedLambdaBinderRefs =
                  maybe
                    []
                    (map fst . schemeBinderRefs . schemeFromType)
                    ( envExpectedTermEndpoint envAtLambdaConstructionBoundary
                        >>= exactConstructionExpectedType
                    )
                sourceLambdaValueConstructionBinder = do
                  SourceLambdaValueExpectedTerm construction _ <-
                    envExpectedTermEndpoint envAtLambdaConstructionBoundary
                  guard (slvcOwner construction == lambdaOwner)
                  pure (slvcParameterBinder construction)
                exactExpectedLambdaRefs =
                  maybe
                    []
                    ( \expectedTy ->
                        typeBinderDeclarationRefs expectedTy
                          ++ freeTypeVarRefsType expectedTy
                    )
                    ( envExpectedTermEndpoint envAtLambdaConstructionBoundary
                        >>= exactConstructionExpectedType
                    )
                renameTouchesExactExpectedLambdaBinder
                  (sourceRef, constructionRef) =
                    any
                      (typeBinderRefsSameIdentity sourceRef)
                      exactExpectedLambdaRefs
                      || any
                        (typeBinderRefsSameIdentity constructionRef)
                        exactExpectedLambdaRefs
                exactIdentityBodyEndpoint = do
                  guard
                    ( annExprReferenceKey bodyAnn
                        == Just (annBinderKey mbBinderDetails)
                    )
                  rawExpectedLambdaTy <-
                    envExpectedTermEndpoint envAtLambdaConstructionBoundary
                      >>= exactConstructionExpectedType
                  expectedLambdaTy <-
                    exactConstructionExpectedType
                      ( endpointRetainedByConstructionEnvExcept
                          endpointProtectedBinderIdentities
                          envWithLambdaTypeScope
                          (ExactConstructionExpectedTerm rawExpectedLambdaTy)
                      )
                  (expectedDomainTy, expectedCodomainTy) <-
                    expectedLambdaConstructionView
                      envWithLambdaTypeScope
                      expectedLambdaTy
                  guard
                    ( scopedTypesAgree
                        scopeContext
                        expectedDomainTy
                        expectedCodomainTy
                    )
                  guard
                    ( scopedTypesAgree
                        scopeContext
                        paramTy
                        expectedDomainTy
                    )
                  pure
                    (ExactConstructionExpectedTerm expectedCodomainTy)
                sourceAnnotatedBodyEndpoint = do
                  annotationEdge <- directSourceAnnotationEdge bodyAnn
                  annotationTy <-
                    annotationExpectedTypeForEdge
                      annotationContext
                      annotationEdge
                  pure
                    ( ExactConstructionExpectedTerm
                        ( applyTypeVarRefRenames
                            constructionBinderRenames
                            annotationTy
                        )
                    )
                directSourceAnnotationEdge ann =
                  case ann of
                    AAnn _ _ annotationEdge -> Just annotationEdge
                    ALetScope inner _ _ -> directSourceAnnotationEdge inner
                    _ -> Nothing
                lookupBinderBound ref schemeInfo =
                  snd
                    <$> find
                      (typeBinderRefsSameIdentity ref . fst)
                      (schemeBinderRefs (siScheme schemeInfo))
            preparedPacketBodyEndpoint <-
              case exactLambdaBodyPacket of
                Nothing -> pure Nothing
                Just packet -> preparedPacketBodyExpectedEndpoint packet
            preparedAdministrativeCurrentLambdaBodyEndpoint <-
              case preparedLambdaGeneralizationForConstruction of
                Just packet
                  | subtermGeneralizationGammaBoundHasNestedSourceDeclaration
                      (acSourceBinderRefs annotationContext)
                      packet
                      || ( isNothing
                            (subtermGeneralizationConsumerAuthority packet)
                            && isNothing
                              (subtermGeneralizationGammaAuthority packet)
                         )
                      || isJust
                        (subtermGeneralizationOpaqueResultConstruction packet)
                  , Just (certifiedLambdaNode, completedLambdaTy0) <-
                      subtermGeneralizationAdministrativeLambdaResultConstruction
                        packet
                  , certifiedLambdaNode == lamNodeId -> do
                      let completedLambdaTy =
                            applyTypeVarRefRenames
                              constructionBinderRenames
                              completedLambdaTy0
                      sourceCompletedLambdaTy <-
                        case
                            projectSourceBinderDeclarationsInBounds
                              descendantAnnotationBinderIdentities
                              (scopeTypeBinderIdentityRepresentative scopeContext)
                              (acSourceBinderRefs annotationContext)
                              completedLambdaTy
                          of
                            Left cause ->
                              Left
                                ( ValidationFailed
                                    [ "administrative source-lambda construction has ambiguous source-bound construction"
                                    , "  lambda: " ++ show lamNodeId
                                    , "  construction: " ++ show completedLambdaTy
                                    , "  cause: " ++ cause
                                    ]
                                )
                            Right lambdaTy -> pure lambdaTy
                      completedSourceLambdaTy <-
                        completeExactEndpointSourceDeclarationBounds
                          descendantAnnotationBinderDeclarations
                          envWithLambdaTypeScope
                          sourceCompletedLambdaTy
                      let completedSourceLambdaTyAtParamBoundary =
                            completeLambdaParamBoundaryType
                              (maybeToList mbParamBoundaryCertificate)
                              completedSourceLambdaTy
                      completedParamTy <-
                        case
                            leadingLambdaDomain
                              completedSourceLambdaTyAtParamBoundary
                          of
                          Just domainTy -> pure domainTy
                          Nothing ->
                            Left
                              ( ValidationFailed
                                  [ "administrative source-lambda construction has no value-arrow domain"
                                  , "  lambda: " ++ show lamNodeId
                                  , "  construction: "
                                      ++ show
                                        completedSourceLambdaTyAtParamBoundary
                                  ]
                              )
                      if
                          scopedEndpointTypesAgree
                            scopeContext
                            completedParamTy
                            paramTy
                        then do
                          completedBodyTy <-
                            case
                                expectedLambdaCodomain
                                  completedSourceLambdaTyAtParamBoundary
                              of
                              Just bodyTy -> pure bodyTy
                              Nothing ->
                                Left
                                  ( ValidationFailed
                                      [ "administrative source-lambda construction has no body endpoint"
                                      , "  lambda: " ++ show lamNodeId
                                      , "  construction: "
                                          ++ show
                                            completedSourceLambdaTyAtParamBoundary
                                      ]
                                  )
                          pure
                            ( Just
                                ( AdministrativeLambdaBodyExpectedTerm
                                    ( AdministrativeLambdaBodyConstruction
                                        { albcGammaBinders =
                                            schemeBinderRefs
                                              ( schemeFromType
                                                  completedSourceLambdaTyAtParamBoundary
                                              ),
                                          albcBodyType = completedBodyTy
                                        }
                                    )
                                    completedBodyTy
                                )
                            )
                        else
                          -- This administrative packet is still expressed at
                          -- a provisional parameter endpoint.  A published
                          -- let/recursive construction may already own a more
                          -- precise parameter.  The packet is then not a
                          -- candidate for this lambda body; the independent
                          -- exact authorities below select the endpoint.
                          pure Nothing
                _ -> pure Nothing
            certifiedAdministrativeLambdaBodyEndpoint <-
              case exactLambdaBodyPacket of
                Just packet
                  | Just (certifiedLambdaNode, completedLambdaTy) <-
                      subtermGeneralizationAdministrativeLambdaResultConstruction
                        packet
                  , certifiedLambdaNode == annNode bodyAnn ->
                      case
                          projectSourceBinderDeclarationsInBounds
                            descendantAnnotationBinderIdentities
                            (scopeTypeBinderIdentityRepresentative scopeContext)
                            (acSourceBinderRefs annotationContext)
                            completedLambdaTy
                        of
                          Left cause ->
                            Left
                              ( ValidationFailed
                                  [ "administrative Lambda(Gamma) endpoint has ambiguous source-bound construction"
                                  , "  edge: " ++ show bodyEid
                                  , "  endpoint: " ++ show completedLambdaTy
                                  , "  cause: " ++ cause
                                  ]
                              )
                          Right sourceCompletedLambdaTy ->
                            -- The packet and exact result-lambda node own the
                            -- complete downward endpoint.  Project source
                            -- declarations inside its flexible bounds now,
                            -- before the child enters Gamma; otherwise the
                            -- child sees the packet's frozen graph copy and
                            -- can only repair the bound after N/Hyp planning
                            -- has already failed.
                            ( Just
                                . ExactConstructionExpectedTerm
                            )
                              <$> completeExactEndpointSourceDeclarationBounds
                                descendantAnnotationBinderDeclarations
                                envWithLambdaTypeScope
                                sourceCompletedLambdaTy
                _ -> pure Nothing
            let preparedEnclosingLambdaEndpoint = do
                  packet <- preparedLambdaGeneralizationForConstruction
                  guard
                    ( subtermGeneralizationGammaBoundHasNestedSourceDeclaration
                        (acSourceBinderRefs annotationContext)
                        packet
                    )
                  authority <- subtermGeneralizationConsumerAuthority packet
                  enclosingOwner <-
                    subtermConsumerAuthorityEnclosingOwner authority
                  guard
                    ( lgoConstructor enclosingOwner == LocalLambdaGamma
                        && scaEdgeId authority /= bodyEid
                    )
                  resultRef <-
                    subtermGeneralizationConstructionResultAbstractionRef
                      packet
                  guard
                    ( not
                        ( any
                            (typeBinderRefsSameIdentity resultRef . fst)
                            ( schemeBinderRefs
                                ( siScheme
                                    ( subtermGeneralizationSchemeInfo
                                        packet
                                    )
                                )
                            )
                        )
                    )
                  let packetExpectedTy0 =
                        schemeToType
                          (subtermGeneralizationGammaBoundScheme packet)
                  guard (not (containsExplicitForallBound packetExpectedTy0))
                  let packetExpectedTy =
                        applyTypeVarRefRenames
                          constructionBinderRenames
                          packetExpectedTy0
                  packetParamTy <- leadingLambdaDomain packetExpectedTy
                  guard
                    ( scopedEndpointTypesAgree
                        scopeContext
                        packetParamTy
                        paramTy
                    )
                  pure (ExactConstructionExpectedTerm packetExpectedTy)
                inheritedLambdaEndpoint =
                  preparedEnclosingLambdaEndpoint
                    <|> envExpectedTermEndpoint
                      envAtLambdaConstructionBoundary
                inheritedLambdaBodyEndpoint =
                  classifyInheritedLambdaBodyEndpoint
                    . endpointRetainedByConstructionEnvExcept
                      endpointProtectedBinderIdentities
                      envWithLambdaTypeScope
                    <$> ( inheritedLambdaEndpoint
                            >>= projectExpectedTermEndpoint
                              ( expectedLambdaConstructionCodomain
                                  envWithLambdaTypeScope
                              )
                        )
                classifyInheritedLambdaBodyEndpoint endpoint =
                  case endpoint of
                    AdministrativeLambdaBodyExpectedTerm construction (TVarRef ref)
                      | Just (_, Just certifiedBound) <-
                          find
                            (typeBinderRefsSameIdentity ref . fst)
                            (albcGammaBinders construction)
                      , Just (_, installedBound) <-
                          find
                            (typeBinderRefsSameIdentity ref . fst)
                            (Map.toList (envTypeBindings envWithLambdaTypeScope))
                      , scopedEndpointTypesAgree
                          scopeContext
                          installedBound
                          (tyToElab certifiedBound) ->
                          -- This projection has reached the exact flexible
                          -- result declared by the enclosing administrative
                          -- Gamma.  Retain its certificate for the one
                          -- terminal Hyp that constructs this lambda body;
                          -- broader projections consume the marker below.
                          endpoint
                    AdministrativeLambdaBodyExpectedTerm _ ty ->
                      -- The marker authorizes construction of this returned
                      -- lambda.  Its projected codomain is an ordinary exact
                      -- endpoint owned by that lambda's construction.
                      classifyInheritedLambdaBodyEndpoint
                        (ExactConstructionExpectedTerm ty)
                    ExactConstructionExpectedTerm ty@(TVarRef ref)
                      | Just _ <- typeBinderRefNode ref
                      , Just (_, TBottom) <-
                          find
                            (typeBinderRefsSameIdentity ref . fst)
                            (Map.toList (envTypeBindings envWithLambdaTypeScope)) ->
                          -- An enclosing lambda can expose its graph result
                          -- declaration before Typ(body) has supplied that
                          -- declaration's bound.  The identity and Bottom
                          -- state make it valid checking topology, but not yet
                          -- an operational endpoint to push into the body.
                          -- Independent packet, identity-body, and source
                          -- annotation certificates remain exact candidates
                          -- in the selection below.
                          CheckingExpectedTerm ty
                    _ -> endpoint
                completedInheritedLambdaBodyEndpoint =
                  case
                      ( exactLambdaBodyPacket
                          <|> sourceLambdaConstructionPacket
                      , inheritedLambdaBodyEndpoint
                      )
                    of
                      ( Just packet
                        , Just endpoint@(ExactConstructionExpectedTerm (TVarRef endpointRef))
                        )
                          | any
                              (typeBinderRefsSameIdentity endpointRef)
                              ( catMaybes
                                  [ subtermGeneralizationResultAbstractionRef
                                      packet
                                  , subtermGeneralizationConstructionResultAbstractionRef
                                      packet
                                  ]
                              ) ->
                              Just
                                ( fromMaybe
                                    endpoint
                                    (packetResultExpectedEndpoint packet)
                                )
                      (_, endpoint) -> endpoint
                certifiedSourceLambdaBodyEndpoint = do
                  packet <- exactLambdaBodyPacket
                  (certifiedLambdaNode, completedLambdaTy) <-
                    subtermGeneralizationSourceLambdaResultConstruction packet
                  guard (certifiedLambdaNode == annNode bodyAnn)
                  -- The exact packet owner and the recorded source-lambda
                  -- node jointly certify the complete term constructed at
                  -- this body boundary.  Its packet result declaration is
                  -- the codomain produced inside that lambda, not a second
                  -- endpoint for the lambda term itself.  Requiring an
                  -- inherited endpoint here would discard the construction
                  -- precisely when the enclosing application has not yet
                  -- published one; the independent local-authority selector
                  -- below still rejects any same-boundary disagreement.
                  pure (ExactConstructionExpectedTerm completedLambdaTy)
                selectedPreparedPacketBodyEndpoint0 =
                  -- The packet result is the codomain/result declaration
                  -- constructed by Typ(body).  When the checked body is the
                  -- packet's recorded source lambda, its identity-bearing
                  -- source certificate instead owns the whole lambda term.
                  -- Select that construction before projecting the packet to
                  -- its result declaration.
                  certifiedSourceLambdaBodyEndpoint
                    <|> certifiedAdministrativeLambdaBodyEndpoint
                    <|> preparedPacketBodyEndpoint
                selectedPreparedPacketBodyEndpoint =
                  case
                      ( selectedPreparedPacketBodyEndpoint0
                      , completedInheritedLambdaBodyEndpoint
                      )
                    of
                      (Just packetEndpoint, Just inheritedEndpoint)
                        | Just inheritedTy <-
                            exactConstructionExpectedType inheritedEndpoint
                        , isJust certifiedSourceLambdaBodyEndpoint
                        , certifiedSourceLambdaSpinePlacementConstructs
                            (scopedEndpointTypesAgree scopeContext)
                            bodyAnn
                            (expectedTermEndpointType packetEndpoint)
                            inheritedTy ->
                            -- A packet certificate identifies the body
                            -- constructor, but its frozen endpoint can predate
                            -- the enclosing constructor's exact forall
                            -- placement.  At the same projected body boundary
                            -- retain the packet provenance while checking the
                            -- child at the already-constructed endpoint; the
                            -- packet-aware final constructor below still has
                            -- to certify the complete computation.
                            Just (ExactConstructionExpectedTerm inheritedTy)
                      _ -> selectedPreparedPacketBodyEndpoint0
                preparedAdministrativeBodyEndpointForSelection =
                  case
                      ( preparedAdministrativeCurrentLambdaBodyEndpoint
                      , completedInheritedLambdaBodyEndpoint
                      )
                    of
                      ( Just
                          ( AdministrativeLambdaBodyExpectedTerm
                              construction
                              _
                            )
                        , Just inheritedEndpoint
                        )
                          | Just inheritedTy <-
                              exactConstructionExpectedType inheritedEndpoint ->
                              -- The prepared administrative endpoint is the
                              -- pre-body Gamma carrier, while the enclosing
                              -- exact constructor owns the already-projected
                              -- lexical forall placement.  Preserve both
                              -- pieces of authority in one endpoint: replacing
                              -- the packet's earlier flattened type must not
                              -- discard the Gamma certificate needed by the
                              -- next returned lambda.
                              Just
                                ( AdministrativeLambdaBodyExpectedTerm
                                    construction
                                    inheritedTy
                                )
                      _ -> preparedAdministrativeCurrentLambdaBodyEndpoint
            localLambdaBodyExpectedEndpoint <-
              case
                  selectExpectedTermEndpoint
                    (scopedEndpointTypesAgree scopeContext)
                    ("local lambda body edge " ++ show bodyEid)
                    [ preparedAdministrativeBodyEndpointForSelection
                    , selectedPreparedPacketBodyEndpoint
                    , exactIdentityBodyEndpoint
                    , sourceAnnotatedBodyEndpoint
                    ]
                of
                  Right endpoint -> pure endpoint
                  Left cause ->
                    Left
                      ( ValidationFailed
                          [ "local lambda body construction authorities disagree"
                          , "  edge: " ++ show bodyEid
                          , "  prepared packet endpoint: "
                              ++ show preparedPacketBodyEndpoint
                          , "  identity-body endpoint: "
                              ++ show exactIdentityBodyEndpoint
                          , "  source-annotation endpoint: "
                              ++ show sourceAnnotatedBodyEndpoint
                          , "  cause: " ++ show cause
                          ]
                      )
            preparedLambdaBodyExpectedEndpoint <-
              let selectedEndpoint =
                    case localLambdaBodyExpectedEndpoint of
                      Nothing -> completedInheritedLambdaBodyEndpoint
                      Just localEndpoint ->
                        -- A direct packet, identity-body, or annotation
                        -- certificate owns this exact body constructor.  An
                        -- inherited endpoint is pushed into that constructor
                        -- only when the ordinary binder-spine relation proves
                        -- that both describe the same body boundary.  If it
                        -- does not, the inherited type belongs to the
                        -- enclosing lambda and is consumed when that lambda
                        -- constructs its result; treating it as a competing
                        -- child certificate projects one arrow too far.
                        case
                            selectExpectedTermEndpoint
                              (scopedEndpointTypesAgree scopeContext)
                              ("lambda body edge " ++ show bodyEid)
                              [ Just localEndpoint
                              , completedInheritedLambdaBodyEndpoint
                              ]
                          of
                            Right endpoint -> endpoint
                            Left _ -> Just localEndpoint
               in pure
                    ( mapExpectedTermEndpoint
                        ( completeLambdaParamBoundaryType
                            (maybeToList mbParamBoundaryCertificate)
                        )
                        <$> selectedEndpoint
                    )
            annotationConstructionRenames <-
              case preservedAnnotationTy of
                Nothing -> pure []
                Just annotationTy ->
                  let annotationIdentities =
                        Set.fromList
                          (map typeBinderRefIdentity (freeTypeVarRefsType annotationTy))
                      relevantSourceBinderRefs =
                        IntMap.filter
                          ( (`Set.member` annotationIdentities)
                              . typeBinderRefIdentity
                          )
                          (acSourceBinderRefs annotationContext)
                   in do
                        sourceRenames <-
                          either
                            (Left . ValidationFailed . pure)
                            Right
                            ( sourceBinderConstructionRenamesRetainingAmbiguousSources
                                (scopeTypeBinderIdentityRepresentative scopeContext)
                                relevantSourceBinderRefs
                                (envConstructionIdentityRoutes envWithLambdaTypeScope0)
                            )
                        pure
                          ( lambdaParamConstructionRenames
                              paramBoundaryProtectedIdentities
                              ( filter
                                  (not . renameTouchesExactExpectedLambdaBinder)
                                  sourceRenames
                              )
                          )
            let preservedAnnotationConstructionTy =
                  applyTypeVarRefRenames
                    ( paramBoundaryRecoveryRenames
                        ++ annotationConstructionRenames
                    )
                    <$> preservedAnnotationTy
                parameterConstructionTy =
                  applyTypeVarRefRenames
                    ( paramBoundaryRecoveryRenames
                        ++ annotationConstructionRenames
                    )
                    paramTy
            case preservedAnnotationConstructionTy of
              Just annotationConstructionTy
                | not
                    ( alphaEqType
                        annotationConstructionTy
                        parameterConstructionTy
                        || churchAwareEqType
                          annotationConstructionTy
                          parameterConstructionTy
                    ) ->
                    Left
                      ( ValidationFailed
                          [ "annotated lambda parameter changed during construction"
                          , "  annotation type: " ++ show preservedAnnotationTy
                          , "  construction-domain annotation type: "
                              ++ show annotationConstructionTy
                          , "  construction-domain parameter type: "
                              ++ show parameterConstructionTy
                          , "  constructed parameter type: " ++ show constructedParamTy
                          , "  parameter surface type: " ++ show paramTySurface
                          , "  parameter scheme: " ++ show (siScheme paramSchemeInfo)
                          , "  prepared lambda scheme: "
                              ++ show (siScheme <$> preparedLambdaSchemeInfo)
                          , "  construction aliases: "
                              ++ show
                                ( envConstructionGammaAliases
                                    envAtLambdaConstructionBoundary
                                )
                          , "  source-to-construction renames: "
                              ++ show annotationConstructionRenames
                          ]
                      )
              _ -> pure ()
            let preparedLambdaBodyExpectedEndpointAtConstruction =
                  mapExpectedTermEndpoint
                    ( applyTypeVarRefRenames
                        ( paramBoundaryRecoveryRenames
                            ++ annotationConstructionRenames
                        )
                    )
                    <$> preparedLambdaBodyExpectedEndpoint
            envWithAnnotatedLambdaParam <-
              alignEnvToNestedConstructionBinderRenames
                annotationConstructionRenames
                envWithLambdaParam
            envForBody0 <-
              case preparedLambdaGeneralizationForConstruction of
                Just packet ->
                  ( \preparedEnv ->
                      preparedEnv
                        { envExpectedTermEndpoint =
                            preparedLambdaBodyExpectedEndpointAtConstruction
                        }
                    )
                    <$> alignEnvToConstructionBinderRenames
                      ( lambdaParamConstructionRenames
                          paramBoundaryProtectedIdentities
                          (subtermGeneralizationConstructionBinderRenames packet)
                      )
                      envWithAnnotatedLambdaParam
                        { envActiveSubtermConstruction = Just packet
                        }
                Nothing ->
                  pure
                    envWithAnnotatedLambdaParam
                      { envExpectedTermEndpoint =
                          preparedLambdaBodyExpectedEndpointAtConstruction
                      }
            envForBodyWithAdministrativeGamma <-
              case preparedAdministrativeCurrentLambdaBodyEndpoint of
                Just
                  ( AdministrativeLambdaBodyExpectedTerm
                      construction
                      _
                    ) -> do
                      envAtAdministrativeSourceBounds <-
                        enterExactConstructionSourceBounds
                          descendantAnnotationBinderIdentities
                          descendantAnnotationBinderDeclarations
                          (scopeTypeBinderIdentityRepresentative scopeContext)
                          (acSourceBinderRefs annotationContext)
                          ( Just
                              ( ExactConstructionExpectedTerm
                                  ( schemeToType
                                      ( administrativeLambdaBodyConstructionScheme
                                          construction
                                      )
                                  )
                              )
                          )
                          envForBody0
                      extendEnvTypeScopeFromExactConstruction
                        ( "administrative source-lambda "
                            ++ show lamNodeId
                        )
                        (albcGammaBinders construction)
                        envAtAdministrativeSourceBounds
                Nothing -> pure envForBody0
                Just _ -> pure envForBody0
            envForBody <-
              case certifiedAdministrativeLambdaBodyEndpoint of
                Just administrativeEndpoint ->
                  -- The exact administrative packet has already proved the
                  -- complete downward Lambda(Gamma) endpoint.  Install its
                  -- source-declared bounds in the same operation that enters
                  -- the child Gamma, before Typ(body) can observe the frozen
                  -- graph presentation.
                  enterExactEndpointAmbientSourceBounds
                    descendantAnnotationBinderIdentities
                    descendantAnnotationBinderDeclarations
                    (scopeTypeBinderIdentityRepresentative scopeContext)
                    (acSourceBinderRefs annotationContext)
                    (Just administrativeEndpoint)
                    envForBodyWithAdministrativeGamma
                Nothing ->
                  case
                      ( envActiveSubtermConstruction
                          envForBodyWithAdministrativeGamma
                          >>= subtermGeneralizationConsumerAuthority
                      , preparedLambdaGeneralizationForConstruction
                      )
                    of
                      (Just authority, Nothing)
                        | Just _ <-
                            subtermConsumerAuthorityEnclosingOwner authority ->
                        -- A transparent child can inherit the enclosing
                        -- Figure 15.3.5 Gamma after its own lambda packet has
                        -- been consumed.  The active enclosing certificate is
                        -- the positive proof that an exact endpoint binder is
                        -- ambient here.  Without it, the same identity can be
                        -- a lexical forall that the child must alpha-copy
                        -- locally.
                        enterExactEndpointAmbientSourceBounds
                          descendantAnnotationBinderIdentities
                          descendantAnnotationBinderDeclarations
                          (scopeTypeBinderIdentityRepresentative scopeContext)
                          (acSourceBinderRefs annotationContext)
                          preparedLambdaBodyExpectedEndpointAtConstruction
                          envForBodyWithAdministrativeGamma
                      _ -> pure envForBodyWithAdministrativeGamma
            bodyRootRaiseMergeAuthority <-
              rootRaiseMergeAuthorityFor
                lambdaEdgeArtifacts
                bodyEid
            let bodyRootConstructionTy = do
                  authority <- bodyRootRaiseMergeAuthority
                  let exteriorNode = rrmaExterior authority
                      directExteriorBound =
                        snd
                          <$> find
                            ( (== Just exteriorNode)
                                . typeBinderRefNode
                                . fst
                            )
                            (Map.toList (envTypeBindings envForBody))
                      routedExteriorBound = do
                        routedRef <-
                          IntMap.lookup
                            (getNodeId exteriorNode)
                            (envConstructionGammaAliases envForBody)
                        snd
                          <$> find
                            ( typeBinderRefsSameIdentity routedRef
                                . fst
                            )
                            (Map.toList (envTypeBindings envForBody))
                  constructedTy <-
                    directExteriorBound <|> routedExteriorBound
                  guard (constructedTy /= TBottom)
                  pure constructedTy
                -- Figure 15.3.5 constructs the recursively elaborated body
                -- under S'(operated).  A root RaiseMerge certificate fixes
                -- which exterior owns that endpoint, and the already
                -- installed non-Bottom Gamma bound supplies its complete
                -- source-domain type.  Seed leading body lambdas before
                -- elaborating them; otherwise an exact evidence parameter can
                -- remain in its source identity domain while the body first
                -- invents graph-local parameter identities and only tries to
                -- reconcile them after type checking.
                envForConstructedBody =
                  maybe
                    envForBody
                    (\constructedTy ->
                      let bodyParamTypes =
                            constructedLambdaParamTypes
                              envForBody
                              constructedTy
                              bodyAnn
                       in envForBody
                            { envConstructedLambdaParamTypes =
                                -- This body edge is nested inside every
                                -- construction contract already in the map,
                                -- so a complete identity-keyed domain from it
                                -- is the more local authority.  A bare graph
                                -- variable is only a pending packet endpoint,
                                -- however; it cannot erase a structured
                                -- domain already fixed for the same resolved
                                -- lambda by the enclosing let construction
