                    )
                    bodyRootConstructionTy
                preferCompleteBodyParam bodyParam enclosingParam =
                  case bodyParam of
                    TVarRef bodyRef
                      | not
                          ( any
                              (typeBinderRefsSameIdentity bodyRef)
                              (freeTypeVarRefsType enclosingParam)
