                  envLambdaParamBoundaryCertificates envForBody
                    ++ maybe
                      []
                      ofcLambdaParamBoundaryCertificates
                      ( elaboratedOwnerFinalConstruction
                          bodyElaboration
                      )
                inheritedBodyConstructionRenames0 =
