              case TypeCheck.typeCheckWithEnv bodySourceTcEnv bodyStripped of
                Right ty -> pure ty
                Left err ->
                  Left
                    ( PhiInvariantError
                        ( unlines
                            [ "ALamF: lambda body source is not typable before its outgoing computation"
                            , "lambda owner=" ++ show (idDetailsIdentityKey binderDetails)
