                  case
                      authorizedBodyConsumerRoute
                        <$> authorizedOrdinaryLambdaBodyConsumerRoute
                    of
                      Just route
                        | TVarRef constructionOperatedRef <-
                            bcrConstructionOperatedType route ->
                            typeBinderRefsSameIdentity
                              constructionOperatedRef
