                                (typeBinderRefsSameIdentity operatedRef)
                                bodyTypeAbstractionRefs
                            )
                        , typeBinderRefsSameIdentity
                            constructionOperatedRef
                            (bcrConstructionRef route)
                        , not
                            ( typeBinderRefsSameIdentity
                                operatedRef
                                constructionOperatedRef
