                  requireAdministrativeCompletion
                    ( any
                        ( \(ref, mbBound) ->
                            typeBinderRefsSameIdentity
                              ref
                              constructedResultRef
                              && mbBound == snd resultBinder
                        )
                        (schemeBinderRefs completedScheme)
