                        [ subtermConsumerKey
                            edgeId
                            (lgcConsumerIdentity closure)
                        | closure <- currentApplicationClosures
                        , [_] <- [exactDirectEndpoints closure]
                        , edgeId <- NonEmpty.toList (lgcEdgeIds closure)
