                ownerSelectedEdgeKeys =
                  IntSet.fromList
                    [ getEdgeId edgeId
                    | (edgeId, _) <- requirementEdges
                    ]
                directEdgeKeys =
                  IntSet.fromList
                    [ getEdgeId edgeId
                    | (edgeId, _) <- directRequirementEdges0
