                (instantiationSiteEdgeId argSite)
                applicationRequirements
                edgeLocalRequirements
            mbActiveConsumerAuthority <-
              activeApplicationConsumerSchemeAuthority
                scopeContext
                env
                applicationScope
            (applicationSchemeInfo, applicationPlacedCopiedBinderRoutes) <-
