                        ( projectResolvedOccurrenceLookupTypes
                            recoveryRenames
                            envForApplicationAfterArgument0
                        )
            let envForApplicationAfterArgument =
                  envForApplicationAfterArgument0
                argumentValueOwnedBinderRefs =
