                failApplication details =
                  Left
                    ( PhiInvariantError
                        ( unlines
                            ( [ "AAppF: invalid constructed application"
                              , "function annotation="
                                  ++ show (annNode fAnn, annExprReferenceKey fAnn)
                              , "argument annotation="
                                  ++ show (annNode aAnn, annExprReferenceKey aAnn)
                              , "expected application type="
                                  ++ diagnosticExpectedTermEndpoint
                                    (envExpectedTermEndpoint env)
                              , "construction result endpoint="
                                  ++ diagnosticOptionalElabType
                                    applicationExpectedResultTy
                              , "active construction packet="
                                  ++ show
                                    ( (\packet ->
                                        ( subtermGeneralizationConsumerAuthority packet
                                        , subtermGeneralizationGammaAuthority packet
                                        , subtermGeneralizationResultAbstractionRef packet
                                        )
                                      )
                                        <$> envActiveSubtermConstruction env
                                    )
                              ]
                                ++ details
                            )
                        )
                    )
            argSourceTy0 <-
              requireType
                argumentSourceTypeEnv
                "argument source"
                argTerm
            let applicationMediatorArity =
                  transparentMediatorArity envForApplication fAnn
                    <|> case transparentMediatorKindAnn fAnn of
                      Just DirectIdentityMediator -> Just 0
                      Just (EtaTransparentMediator arity) -> Just arity
                      Nothing -> Nothing
                (argTermForTopology, argSourceTy) =
                  case (applicationMediatorArity, argSourceTy0) of
                    (Just arity, muTy@(TMuRef muRef muBody))
                      | arity > 0
                      , let unfoldedTy = substTypeCaptureRef muRef muTy muBody
                      , TArrow {} <- unfoldedTy ->
                          -- A validated eta mediator consumes a function.  An
                          -- iso-recursive function value reaches that domain
                          -- only through its explicit one-step unroll; make
                          -- that term/type pair the occurrence source before
                          -- constructing either edge computation.
                          (EUnroll argTerm, unfoldedTy)
                    _ -> (argTerm, argSourceTy0)
                identityApplicationArgumentEndpoint =
                  -- A direct RaiseMerge operated view is only a prospective
                  -- endpoint until the checked argument proves an actual
                  -- xMLF computation to it.  Source annotations can make the
                  -- graph view strictly provisional (notably when a bounded
                  -- forall contains a same-named lexical forall).  In that
                  -- case the syntactic identity is constructed at the exact
                  -- checked source type and the unused graph Gamma is closed
                  -- normally; it must not force the child toward an
                  -- unreachable endpoint.
                  case
                      [ candidate
                      | candidate <- identityArgumentEndpointCandidates
                      , isJust
                          ( constructExactInstantiation
                              argumentSourceTypeEnv
                              (scopedEndpointTypesAgree scopeContext)
                              argSourceTy
                              candidate
                          )
                      ]
                    of
                      candidate : _ -> Just candidate
                      [] -> Nothing
            argumentSourceSchemeInfo <-
              case
                  checkedOccurrenceSchemeInfo
                    argSourceTy
                    argumentRecoveredSourceSchemeInfo
                of
                  Left cause ->
                    Left
                      ( ValidationFailed
                          [ "application argument checked-source construction failed"
                          , "  application: " ++ show appNodeId
                          , "  argument: "
                              ++ show
                                (annNode aAnn, annExprReferenceKey aAnn)
                          , "  checked source type: "
                              ++ diagnosticElabType argSourceTy
                          , "  recovered source scheme: "
                              ++ show
                                (siScheme <$> argumentRecoveredSourceSchemeInfo)
                          , "  cause: " ++ cause
                          ]
                      )
                  Right checkedSchemeInfo ->
                    pure (Just checkedSchemeInfo)
            functionSourceSchemeInfo <-
              applicationSourceSchemeFor fAnn
            mediatedSourceConstruction <-
              mediatedApplicationConstruction
                envForApplication
                applicationSourceSchemeFor
                applicationAnn
            let semanticMetaPlacements =
                  expansionSemanticMetaParentsToIntMap
                    ( gaExpansionConstructionPlacements
                        (scGaParents scopeContext)
                    )
                resultConstructionRefs =
                  typeBinderDeclarationRefs graphResultTopologyTy
                    ++ freeTypeVarRefsType graphResultTopologyTy
                isExpansionSemanticMetaRef ref = do
                  node <- typeBinderRefNode ref
                  guard
                    ( IntMap.member
                        (getNodeId node)
                        semanticMetaPlacements
                    )
                  pure ()
                applicationSemanticMetaRefs =
                  [ ref
                  | ref <- resultConstructionRefs
                  , isJust (isExpansionSemanticMetaRef ref)
                  ]
                semanticMetaHasConstructionAuthority ref =
                  any
                    (typeBinderRefsSameIdentity ref . fst)
                    applicationBinders
                    || maybe
                      False
                      ( \node ->
                          IntMap.member
                            (getNodeId node)
                            applicationAuthorityAliases
                      )
                      (typeBinderRefNode ref)
                    || maybe
                      False
                      (/= TBottom)
                      (typeBindingLookup ref)
                -- An active consumer owns the outgoing Hyp from the
                -- application's constructed result to its flexible result
                -- variable.  The application itself must therefore be built
                -- at that variable's bound.  Requiring the function
                -- occurrence to manufacture the flexible result would apply
                -- Hyp before EApp and turn an arrow into an abstract type.
                -- The enclosing edge emits the single outgoing Hyp after the
                -- application has been constructed.
                inheritedApplicationConstructionResultTy =
                  case mbActiveConsumerAuthority of
                    Just authority ->
                      Just
                        ( normalizeApplicationType
                            (activeApplicationConsumerBound authority)
                        )
                    Nothing ->
                      applicationExpectedResultTy
                applicationConstructionResultTy =
                  inheritedApplicationConstructionResultTy
            let sourceProjectedTopology =
                  -- The edge sidecar first projects its argument occurrence
                  -- into the enclosing source graph.  An exact lambda
                  -- boundary may already have completed a parameter root in
                  -- that graph with its identity-bearing source type.  Apply
                  -- that positive construction before selecting the shared
                  -- Figure 15.3.5 endpoint; otherwise a child application
                  -- sees Graph(argument) -> Graph(parameter) but its checked
                  -- source schemes already inhabit the completed source
                  -- identity.
                  projectSourceOccurrenceThroughLambdaBoundaries
                    (scopeTypeBinderIdentityRepresentative scopeContext)
                    applicationSourceBinderRefs
                    (envLambdaParamBoundaryCertificates envForApplication)
                    argTopologyTy
                closedArgumentTopology =
                  checkedArgumentClosedTopology
                    argumentSourceSchemeInfo
                    argSourceTy
                    sourceProjectedTopology
                checkedArgumentAtBound boundTy
                  | alphaEqType argSourceTy boundTy =
                      Just argSourceTy
                  | otherwise = do
                      eliminatedArgument <-
                        eliminateCheckedBoundedPrefix argSourceTy
                      guard
                        (not (alphaEqType eliminatedArgument argSourceTy))
                      guard (alphaEqType eliminatedArgument boundTy)
                      pure eliminatedArgument
                argumentTopologyIndependentOfActiveConsumer topologyRef =
                  maybe
                    True
                    ( \authority ->
                        not
                          ( typeBinderRefsSameIdentity
                              topologyRef
                              (activeApplicationConsumerRef authority)
                          )
                    )
                    mbActiveConsumerAuthority
                localBoundArgumentTopology =
                  case
                      ( mbActiveConsumerAuthority
                      , sourceProjectedTopology
                      )
                    of
                      (_, TVarRef topologyRef) -> do
                        guard
                          ( argumentTopologyIndependentOfActiveConsumer
                              topologyRef
                          )
                        (_, Just topologyBound) <-
                          find
                            ( typeBinderRefsSameIdentity topologyRef
                                . fst
                            )
                            applicationBinders
                        let boundTy = tyToElab topologyBound
                        checkedArgument <- checkedArgumentAtBound boundTy
                        guard (not (applicationResultDependsOn topologyRef))
                        pure checkedArgument
                      _ -> Nothing
                directLocalArgumentBinder =
                  case sourceProjectedTopology of
                    TVarRef topologyRef -> do
                      guard
                        ( argumentTopologyIndependentOfActiveConsumer
                            topologyRef
                        )
                      (_, Just topologyBound) <-
                        find
                          ( typeBinderRefsSameIdentity topologyRef
                              . fst
                          )
                          applicationBinders
                      guard
                        ( alphaEqType
                            argSourceTy
                            (tyToElab topologyBound)
                        )
                      -- This application owns the exact flexible declaration,
                      -- and the checked argument is already at its bound.
                      -- Construct both occurrence computations at the
                      -- declaration itself.  If it is absent from the final
                      -- result, the completed local Gamma is eliminated below;
                      -- specializing the children directly to the bound would
                      -- erase the Figure 15.3.5 construction certificate.
                      pure (topologyRef, tyToElab topologyBound)
                    _ -> Nothing
                directLocalArgumentTopology =
                  TVarRef . fst <$> directLocalArgumentBinder
                ambientBoundArgumentTopology =
                  case
                      ( mbActiveConsumerAuthority
                      , sourceProjectedTopology
                      )
                    of
                      (_, TVarRef topologyRef) -> do
                        guard
                          ( argumentTopologyIndependentOfActiveConsumer
                              topologyRef
                          )
                        authority <-
                          find
                            ( typeBinderRefsSameIdentity topologyRef
                                . agaExactRef
                            )
                            ( IntMap.elems
                                applicationAmbientGammaAuthorities
                            )
                        let boundTy = agaBound authority
                        guard (boundTy /= TBottom)
                        checkedArgument <- checkedArgumentAtBound boundTy
                        guard (not (applicationResultDependsOn topologyRef))
                        -- This is the ambient analogue of
                        -- 'localBoundArgumentTopology'.  The exact Gamma
                        -- declaration, together with an explicit leading N
                        -- computation when the checked occurrence is bounded,
                        -- proves that the occurrence reaches the bound.  When
                        -- the result does not retain the flexible declaration,
                        -- Figure 15.3.5 constructs both children there instead
                        -- of feeding an underdetermined graph variable into
                        -- the function occurrence.
                        pure checkedArgument
                      _ -> Nothing
                -- Retaining a construction-Gamma endpoint is determined by
                -- the complete prepared result dependency, not only by the
                -- graph result after its flexible bounds have been inlined.
                -- In the K/factory application that graph view is already
                -- @forall d. d -> Int@, while the application construction
                -- scheme still records @forall d. d -> a@ under @a >= Int@.
                -- Collapsing @a@ merely because the reduced view no longer
                -- mentions it specializes the function side too early.
                --
                -- Following the already prepared Gamma bounds keeps @a@ as
                -- the shared Figure 15.3.5 endpoint.  The argument occurrence
                -- constructs @Int <= a@ with Hyp(a), and the function replay
                -- therefore reaches the exact bound required by Hyp(b).
                resultTopologyDependsOn soughtRef = go Set.empty
                  where
                    go visited ty =
                      any (refDepends visited) (freeTypeVarRefsType ty)

                    refDepends visited ref
                      | typeBinderRefsSameIdentity soughtRef ref = True
                      | Set.member refIdentity visited = False
                      | otherwise =
                          maybe
                            False
                            (go (Set.insert refIdentity visited))
                            (typeBindingLookup ref)
                      where
                        refIdentity = typeBinderRefIdentity ref
                applicationResultDependsOn topologyRef =
                  resultTopologyDependsOn topologyRef graphResultTopologyTy
                    || maybe
                      False
                      ( resultTopologyDependsOn topologyRef
                          . schemeBody
                          . siScheme
                      )
                      applicationSchemeInfo
                retainedLocalBoundArgumentForResult =
                  case (mbActiveConsumerAuthority, sourceProjectedTopology) of
                    (Nothing, TVarRef topologyRef) ->
                      case
                          find
                            (typeBinderRefsSameIdentity topologyRef . fst)
                            applicationBinders
                        of
                          Just (_, Just topologyBound) ->
                            alphaEqType argSourceTy (tyToElab topologyBound)
                              && applicationResultDependsOn topologyRef
                          _ -> False
                    _ -> False
                semanticMetaFollowsConsumedLocalGamma =
                  isJust directLocalArgumentBinder
                    && not retainedLocalBoundArgumentForResult
                applicationSemanticMetaResultTy = do
                  -- chi_e created these semantic metavariables and the exact
                  -- result topology still mentions their certified graph
                  -- keys.  The graph placement identifies the prospective
                  -- result, but an unbounded ambient placeholder is not yet
                  -- an xMLF construction endpoint.  Require a local Gamma,
                  -- construction alias, or already materialized ambient bound
                  -- before promoting it from checking topology to exact
                  -- authority.  Otherwise the recursively checked source
                  -- application completes the provisional result.
                  guard (not (null applicationSemanticMetaRefs))
                  guard
                    ( all
                        ( \ref ->
                            case isExpansionSemanticMetaRef ref of
                              Just () ->
                                semanticMetaHasConstructionAuthority ref
                              Nothing ->
                                envOwnsExactTypeBinderRef
                                  envForApplication
                                  ref
                        )
                        (freeTypeVarRefsType graphResultTopologyTy)
                    )
                  pure graphResultTopologyTy
                applicationPostGammaSemanticMetaResultTy =
                  applicationSemanticMetaResultTy
                    <|> do
                      -- A direct local argument Gamma is positive authority
                      -- for a different construction order: first build EApp
                      -- under the bounded declaration, then eliminate it with
                      -- N, and only then instantiate the source-polymorphic
                      -- result at chi_e's semantic meta.  Keeping this
                      -- endpoint out of 'applicationSemanticMetaResultTy'
                      -- prevents it from specializing the function occurrence
                      -- before EApp.
                      guard semanticMetaFollowsConsumedLocalGamma
                      guard (not (null applicationSemanticMetaRefs))
                      guard
                        ( all
                            ( \ref ->
                                isJust (isExpansionSemanticMetaRef ref)
                                  || envOwnsExactTypeBinderRef
                                    envForApplication
                                    ref
                            )
                            (freeTypeVarRefsType graphResultTopologyTy)
                        )
                      pure graphResultTopologyTy
                constructionClosedArgumentTopology = do
                  guard (isNothing mbActiveConsumerAuthority)
                  topologyBinders <-
                    either
                      (const Nothing)
                      Just
                      ( constructionGammaCompletionBinders
                          applicationBinders
                          argTermForTopology
                          sourceProjectedTopology
                      )
                  let closedTopology =
                        foldr
                          (\(ref, mbBound) body -> TForallRef ref mbBound body)
                          sourceProjectedTopology
                          topologyBinders
                  guard (not (null topologyBinders))
                  guard (alphaEqType closedTopology argSourceTy)
                  pure closedTopology
                sourceDeclaredArgumentTopology = do
                  sourceSchemeInfo <- argumentSourceSchemeInfo
                  let sourceScheme = siScheme sourceSchemeInfo
                      declaredSourceTy = schemeToType sourceScheme
                  guard (null (schemeBinderRefs sourceScheme))
                  guard (alphaEqType declaredSourceTy argSourceTy)
                  guard
                    ( alphaEqType argSourceTy sourceProjectedTopology
                        || declaredSourceCompletesProvisionalTopology
                          sourceProjectedTopology
                          argSourceTy
                    )
                  -- A monomorphic source declaration fixes the occurrence
                  -- endpoint without an InstApp choice. Preserve it when the
                  -- graph agrees, or when the declaration fills only
                  -- underdetermined Bottom holes in the same topology. In
                  -- the latter case the source declaration is the positive
                  -- construction certificate; passing those Bottom holes
                  -- into a recursively constructed function child would
                  -- manufacture an endpoint no source term inhabits.
                  pure argSourceTy
                declaredSourceCompletesProvisionalTopology provisional declared =
                  case (provisional, declared) of
                    (TBottom, _) -> True
                    (TArrow provisionalDomain provisionalCodomain, TArrow declaredDomain declaredCodomain) ->
                      declaredSourceCompletesProvisionalTopology
                        provisionalDomain
                        declaredDomain
                        && declaredSourceCompletesProvisionalTopology
                          provisionalCodomain
                          declaredCodomain
                    (TConWithIdentity provisionalIdentity _ provisionalArgs, TConWithIdentity declaredIdentity _ declaredArgs) ->
                      provisionalIdentity == declaredIdentity
                        && completeArgumentTopologies
                          (NonEmpty.toList provisionalArgs)
                          (NonEmpty.toList declaredArgs)
                    (TVarAppRef provisionalRef provisionalArgs, TVarAppRef declaredRef declaredArgs) ->
                      typeBinderRefsSameIdentity provisionalRef declaredRef
                        && completeArgumentTopologies
                          (NonEmpty.toList provisionalArgs)
                          (NonEmpty.toList declaredArgs)
                    (TForallRef provisionalRef provisionalBound provisionalBody, TForallRef declaredRef declaredBound declaredBody) ->
                      completeOptionalBounds
                        provisionalBound
                        declaredBound
                        && declaredSourceCompletesProvisionalTopology
                          provisionalBody
                          ( substTypeCaptureRef
                              declaredRef
                              (TVarRef provisionalRef)
                              declaredBody
                          )
                    (TMuRef provisionalRef provisionalBody, TMuRef declaredRef declaredBody) ->
                      declaredSourceCompletesProvisionalTopology
                        provisionalBody
                        ( substTypeCaptureRef
                            declaredRef
                            (TVarRef provisionalRef)
                            declaredBody
                        )
                    _ -> alphaEqType provisional declared
                  where
                    completeArgumentTopologies [] [] = True
                    completeArgumentTopologies (provisionalArg : provisionalRest) (declaredArg : declaredRest) =
                      declaredSourceCompletesProvisionalTopology
                        provisionalArg
                        declaredArg
                        && completeArgumentTopologies
                          provisionalRest
                          declaredRest
                    completeArgumentTopologies _ _ = False

                    completeOptionalBounds Nothing Nothing = True
                    completeOptionalBounds (Just provisionalBound) (Just declaredBound) =
                      declaredSourceCompletesProvisionalTopology
                        (tyToElab provisionalBound)
                        (tyToElab declaredBound)
                    completeOptionalBounds _ _ = False
                freezeCertifiedResultTopology ty =
                  case ty of
                    TArrow domainTy codomainTy ->
                      let (domainFrozen, frozenDomainTy) =
                            freezeCertifiedResultTopology domainTy
                          (codomainFrozen, frozenCodomainTy) =
                            freezeCertifiedResultTopology codomainTy
                       in ( domainFrozen || codomainFrozen
                          , TArrow frozenDomainTy frozenCodomainTy
                          )
                    TMuRef ref _ ->
                      case
                          typeBinderRefNode ref
                            >>= ( \node ->
                                    IntMap.lookup
                                      (getNodeId node)
                                      (frozenEndpointTypes envForApplication)
                                )
                        of
                          Just frozenTy -> (True, frozenTy)
                          Nothing -> (False, ty)
                    TVarRef ref ->
                      case
                          typeBinderRefNode ref
                            >>= ( \node ->
                                    IntMap.lookup
                                      (getNodeId node)
                                      (frozenEndpointTypes envForApplication)
                                )
                        of
                          Just frozenTy -> (True, frozenTy)
                          Nothing -> (False, ty)
                    _ -> (False, ty)
                (hasFrozenResultTopology, frozenGraphResultTopologyTy) =
                  freezeCertifiedResultTopology graphResultTopologyTy
                applicationConstructionResultHasConcreteGammaBound =
                  maybe
                    False
                    ( any
                        ( \ref ->
                            maybe
                              False
                              ( \boundTy ->
                                  boundTy /= TBottom
                                    && not
                                      (universalBottomEliminator boundTy)
                              )
                              (typeBindingLookup ref)
                        )
                        . freeTypeVarRefsType
                    )
                    applicationConstructionResultTy
                specializeConstructionGammaBounds resultTy =
                  foldl
                    ( \specialized ref ->
                        case typeBindingLookup ref of
                          Just boundTy
                            | boundTy /= TBottom
                            , not (universalBottomEliminator boundTy) ->
                                substTypeCaptureRef
                                  ref
                                  (sourceViewOfGammaBound boundTy)
                                  specialized
                          _ -> specialized
                    )
                    resultTy
                    (freeTypeVarRefsType resultTy)
                constructionResultForSource resultTy =
                  let gammaSpecializedResult =
                        if applicationConstructionResultHasConcreteGammaBound
                          then specializeConstructionGammaBounds resultTy
                          else resultTy
                      (_, frozenResult) =
                        freezeCertifiedResultTopology gammaSpecializedResult
                  -- A sibling edge publishes its checked destination before
                  -- the function child is elaborated.  Resolve those graph
                  -- references here, while constructing the source arrow,
                  -- instead of first treating them as exact variables and
                  -- repairing the application after EApp.
                   in completeLambdaParamBoundaryType
                        (envLambdaParamBoundaryCertificates envForApplication)
                        frozenResult
                applicationConstructionResultForSource =
                  constructionResultForSource
                    <$> applicationConstructionResultTy
                inheritedApplicationConstructionResultForSource =
                  constructionResultForSource
                    <$> inheritedApplicationConstructionResultTy
                -- A checked source specialization must always agree with the
                -- exact result selected for this application.  Retain the
                -- independent graph-result check when that graph endpoint has
                -- itself been frozen, or when no active consumer owns the
                -- outgoing result computation.  With an active consumer and
                -- an unfrozen bare graph variable, however, Figure 15.3.5
                -- deliberately constructs the application at the consumer's
                -- bound; requiring the source result to equal that provisional
                -- variable would discard the positive consumer certificate
                -- and force a repair only after EApp.
                validatedSourceResult sourceResult = do
                  targetResult <-
                    applicationConstructionResultForSource
                      <|> do
                        guard hasFrozenResultTopology
                        pure frozenGraphResultTopologyTy
                      <|> applicationSemanticMetaResultTy
                  guard
                    ( sourceResultAgreesAfterLocalElimination
                        sourceResult
                        targetResult
                        || sourceRefinesProvisionalEndpoint
                          targetResult
                          sourceResult
                        || sourceCompletesProvisionalSemanticResult
                    )
                  guard
                    ( not
                        ( hasFrozenResultTopology
                            || isNothing mbActiveConsumerAuthority
                        )
                        || sourceResultAgreesAfterLocalElimination
                          sourceResult
                          frozenGraphResultTopologyTy
                        || sourceRefinesProvisionalEndpoint
                          frozenGraphResultTopologyTy
                          sourceResult
                        || sourceCompletesProvisionalSemanticResult
                    )
                  pure sourceResult
                  where
                    sourceCompletesProvisionalSemanticResult =
                      isJust $ do
                        -- The graph may expose an expansion metavariable at
                        -- one instance of a checked polymorphic source result.
                        -- That instance is a downstream use, not authority to
                        -- specialize the application itself.  Prove the exact
                        -- source-to-semantic computation now so the more
                        -- general source endpoint can be selected before
                        -- constructing EApp.
                        guard
                          (isNothing applicationConstructionResultForSource)
                        guard (not hasFrozenResultTopology)
                        semanticResult <- applicationSemanticMetaResultTy
                        planExactBinderSpine
                          operationalEndpointTypesAgree
                          sourceResult
                          semanticResult
                    sourceResultAgreesAfterLocalElimination source target =
                      residualTopologyAgreesExact source target
                        || case directLocalArgumentBinder of
                          Just (localRef, localBound) ->
                            residualTopologyAgreesExact
                              (substTypeCaptureRef localRef localBound source)
                              target
                          Nothing -> False
                sourceRefinesProvisionalEndpoint provisional certified =
                  not (topologyContainsBottom certified)
                    && all
                      (not . provisionalApplicationRef)
                      (freeTypeVarRefsType certified)
                    && ( ( topologyContainsBottom provisional
                            && declaredSourceCompletesProvisionalTopology
                              provisional
                              certified
                         )
                           || ( not (null provisionalRefs)
                                  && case
                                      matchTypeRefs
                                        provisionalRefs
                                        provisional
                                        certified
                                    of
                                      Right substitution ->
                                        all
                                          (`Map.member` substitution)
                                          provisionalRefs
                                      Left _ -> False
                              )
                       )
                  where
                    provisionalRefs =
                      filter
                        provisionalApplicationRef
                        (freeTypeVarRefsType provisional)
                provisionalApplicationRef ref =
                  case typeBinderRefNode ref of
                    Nothing -> False
                    Just node ->
                      let key = getNodeId node
                       in provisionalTypeBinding ref
                            && IntMap.notMember
                              key
                              (frozenEndpointTypes envForApplication)
                            && IntMap.notMember
                              key
                              applicationAuthorityAliases
                            && IntMap.notMember
                              key
                              applicationAmbientGammaAuthorities
                            && IntMap.notMember
                              key
                              (grSourceBinderRefs applicationRequirements)
                            && not
                              ( any
                                  ( typeBinderRefsSameIdentity ref
                                      . fst
                                  )
                                  applicationBinders
                              )
                  where
                    provisionalTypeBinding candidate =
                      case typeBindingLookup candidate of
                        Nothing -> True
                        Just TBottom -> True
                        Just _ -> False
                eliminateCheckedBoundedPrefix current =
                  case current of
                    TForallRef _ (Just _) _ ->
                      case applyInstantiation current InstElim of
                        Right next -> eliminateCheckedBoundedPrefix next
                        Left _ -> Nothing
                    _ -> Just current
                boundedSourceArgument = do
                  boundedArgument <-
                    eliminateCheckedBoundedPrefix argSourceTy
                  guard (not (alphaEqType boundedArgument argSourceTy))
                  pure boundedArgument
                boundedSourceApplicationConstruction = do
                  boundedArgument <- boundedSourceArgument
                  functionSchemeInfo <- functionSourceSchemeInfo
                  (sourceDomain, sourceResult) <-
                    sourceSchemeApplicationAt
                      edgeTypeEnvBeforeFunction
                      boundedArgument
                      applicationConstructionResultForSource
                      functionSchemeInfo
                  validatedResult <- validatedSourceResult sourceResult
                  pure
                    ( preserveCertifiedStructuralEndpoint
                        sourceDomain
                        boundedArgument
                    , validatedResult
                    )
                sourceConstructedArgumentTopology = do
                  argumentSchemeInfo <- argumentSourceSchemeInfo
                  functionSchemeInfo <- functionSourceSchemeInfo
                  let closedSourceTy =
                        schemeToType (siScheme argumentSchemeInfo)
                  guard
                    ( not
                        ( null
                            (schemeBinderRefs (siScheme argumentSchemeInfo))
                        )
                    )
                  guard (alphaEqType closedSourceTy argSourceTy)
                  -- The checked argument owns this closed type tree, while
                  -- successful source specialization proves that the function
                  -- consumes that exact endpoint.  Together they construct
                  -- the paper's self-application endpoint directly, without
                  -- first opening it to a provisional graph variable.
                  _ <-
                      sourceSchemeApplicationAt
                        edgeTypeEnvBeforeFunction
                        closedSourceTy
                        applicationConstructionResultForSource
                        functionSchemeInfo
                  pure closedSourceTy
                exactArgumentTopology =
                  (macArgumentType <$> mediatedSourceConstruction)
                    <|> selectDirectLocalApplicationArgumentTopology
                      inheritedApplicationConstructionResultForSource
                      localBoundArgumentTopology
                      directLocalArgumentTopology
                    <|> closedArgumentTopology
                    <|> sourceDeclaredArgumentTopology
                    <|> (fst <$> boundedSourceApplicationConstruction)
                    <|> sourceConstructedArgumentTopology
                    <|> constructionClosedArgumentTopology
                    <|> localBoundArgumentTopology
                    <|> ambientBoundArgumentTopology
                topologyContainsBottom ty =
                  case ty of
                    TBottom -> True
                    TArrow domainTy codomainTy ->
                      topologyContainsBottom domainTy
                        || topologyContainsBottom codomainTy
                    TConWithIdentity _ _ args ->
                      any topologyContainsBottom args
                    TVarAppRef _ args ->
                      any topologyContainsBottom args
                    TForallRef _ mbBound bodyTy ->
                      maybe
                        False
                        (topologyContainsBottom . tyToElab)
                        mbBound
                        || topologyContainsBottom bodyTy
                    TMuRef _ bodyTy -> topologyContainsBottom bodyTy
                    TVarRef {} -> False
                    TBaseWithIdentity {} -> False
                sharedArgumentTopology =
                  fromMaybe sourceProjectedTopology exactArgumentTopology
                sourceSpecializationArgumentTopology =
                  case directLocalArgumentBinder of
                    Just (_, localBound) -> localBound
                    Nothing -> sharedArgumentTopology
                graphResultHasConstructionAuthority =
                  all
                    ( \graphResultRef ->
                        case typeBinderRefNode graphResultRef of
                          Nothing -> False
                          Just graphResultNode ->
                            IntMap.member
                              (getNodeId graphResultNode)
                              applicationAuthorityAliases
                    )
                    (freeTypeVarRefsType graphResultTopologyTy)
                sourceConstructedApplication =
                  ( (\construction ->
                        ( macArgumentType construction
                        , macResultType construction
                        )
                    )
                      <$> mediatedSourceConstruction
                  )
                    <|> boundedSourceApplicationConstruction
                    <|> if
                          graphResultHasConstructionAuthority
                            && isNothing directLocalArgumentBinder
                      then Nothing
                      else do
                        functionSchemeInfo <- functionSourceSchemeInfo
                        let constructSourceApplication argumentTy = do
                              (sourceDomain, sourceResult) <-
                                sourceSchemeApplicationAt
                                  edgeTypeEnvBeforeFunction
                                  argumentTy
                                  applicationConstructionResultForSource
                                  functionSchemeInfo
                                  <|> do
                                    targetResult <-
                                      applicationConstructionResultForSource
                                    sourceApplication <-
                                      sourceSchemeApplicationAt
                                        edgeTypeEnvBeforeFunction
                                        argumentTy
                                        Nothing
                                        functionSchemeInfo
                                    guard
                                      ( sourceRefinesProvisionalEndpoint
                                          targetResult
                                          (snd sourceApplication)
                                      )
                                    pure sourceApplication
                              -- A source declaration proves how its own
                              -- function specializes, but it does not by
                              -- itself own this application's graph result.
                              -- Admit that residual only when the
                              -- parent/frozen construction endpoint validates
                              -- it and its complete residual topology still
                              -- agrees with the graph result.  Terminal-result
                              -- agreement alone can otherwise route a
                              -- structural ADT eliminator through an unrelated
                              -- graph-mu spine.
                              validatedResult <-
                                validatedSourceResult sourceResult
                              pure
                                ( preserveCertifiedStructuralEndpoint
                                    sourceDomain
                                    argumentTy
                                , validatedResult
                                )
                        constructSourceApplication
                          sourceSpecializationArgumentTopology
                          <|> do
                            guard
                              ( sourceRefinesProvisionalEndpoint
                                  sourceSpecializationArgumentTopology
                                  argSourceTy
                              )
                            constructSourceApplication argSourceTy
                sourceConstructedResultTy =
                  snd <$> sourceConstructedApplication
                sourceExactConstruction = do
                  (sourceDomain, sourceResult) <-
                    sourceConstructedApplication
                  let certifiedResult =
                        case applicationConstructionResultForSource of
                          Just parentResult
                            | sourceRefinesProvisionalEndpoint
                                parentResult
                                sourceResult ->
                                -- A parent endpoint made only from unowned
                                -- Bottom-backed graph variables is a checking
                                -- shape, not a competing construction
                                -- certificate.  The checked source
                                -- specialization fills those holes here, so
                                -- retain its identity-bearing residual rather
                                -- than publishing the provisional variables
                                -- as an exact endpoint.
                                sourceResult
                            | not
                                ( alphaEqTypePreservingStructuralBinders
                                    sourceResult
                                    parentResult
                                ) ->
                                -- Source specialization proves the exact
                                -- domain and that its residual Church
                                -- representation reaches the parent's result.
                                -- It does not replace that parent certificate
                                -- with the provisional representation returned
                                -- by the graph source (for example
                                -- @mu r. Bottom -> Bottom@ for @Unit@).
                                parentResult
                          _ -> sourceResult
                  pure (Just sourceDomain, certifiedResult)
                preserveCertifiedStructuralEndpoint provisional certified
                  | ( applicationTypesAgree provisional certified
                        || churchAwareEqType provisional certified
                    )
                  , not
                      ( alphaEqTypePreservingStructuralBinders
                          provisional
                          certified
                      ) =
                      -- The checked argument owns the structural-data
                      -- endpoint.  A source specialization may alpha-rename
                      -- ordinary binders or expose one iso-recursive layer,
                      -- but it must not replace that owner with a provisional
                      -- graph-mu binder in the emitted InstApp sequence.
                      -- 'sourceSchemeApplicationAt' has already checked this
                      -- same alpha/Church relation against the argument, so
                      -- the checked argument is the construction certificate;
                      -- the function sidecar contributes applicability, not a
                      -- competing endpoint.
                      certified
                  | otherwise = provisional
                parentExactConstruction = do
                  resultTy <- applicationConstructionResultTy
                  -- A free graph variable whose ambient declaration is still
                  -- Bottom is an allocated checking result unless the
                  -- construction environment owns that exact unbounded
                  -- identity.  A checked source specialization or direct
                  -- lambda packet may independently prove a placeholder
                  -- endpoint; absent either form of evidence, do not let it
                  -- suppress the positive child construction selected below.
                  guard
                    ( isJust mbActiveConsumerAuthority
                        || all resultRefHasCompletedAuthority
                          (freeTypeVarRefsType resultTy)
                    )
                  pure (Nothing, resultTy)
                inheritedAdministrativeLambdaBodyResult = do
                  AdministrativeLambdaBodyExpectedTerm construction _ <-
                    envExpectedTermEndpoint env
                  (_, resultTy) <- parentExactConstruction
                  pure (construction, resultTy)
                resultRefHasCompletedAuthority ref =
                  ( resultRefHasAmbientGraphAuthority ref
                      && not
                        ( functionPacketOwnsUncompletedTerminalResult ref
                        )
                  )
                    || maybe
                      False
                      ( \boundTy ->
                          not
                            ( operationalEndpointTypesAgree
                                TBottom
                                boundTy
                                || universalBottomEliminator boundTy
                            )
                      )
                      (typeBindingLookup ref)
                resultRefHasAmbientGraphAuthority ref =
                  envOwnsExactTypeBinderRef envForApplication ref
                    && any
                      (typeBinderRefsSameIdentity ref)
                      ( freeTypeVarRefsType
                          frozenGraphResultTopologyTy
                      )
                functionPacketOwnsUncompletedTerminalResult ref =
                  isJust functionResultOwnership
                    && maybe
                      False
                      (terminalResultIs ref)
                      applicationConstructionResultTy
                    && maybe
                      False
                      ( \boundTy ->
                          operationalEndpointTypesAgree TBottom boundTy
                            || universalBottomEliminator boundTy
                      )
                      (typeBindingLookup ref)
                terminalResultIs soughtRef ty =
                  case ty of
                    TArrow _ codomainTy ->
                      terminalResultIs soughtRef codomainTy
                    TForallRef _ _ bodyTy ->
                      terminalResultIs soughtRef bodyTy
                    TVarRef terminalRef ->
                      typeBinderRefsSameIdentity soughtRef terminalRef
                    _ -> False
                functionResultOwnership =
                  subtermResultOwnershipForResolvedLetAlias
                    fAnn
                    (algSubtermGeneralizations algebraContext)
                parentExactConstructionForSource =
                  (\resultTy -> (Nothing, resultTy))
                    <$> applicationConstructionResultForSource
                semanticMetaExactConstruction = do
                  -- A semantic metavariable still present in the graph result
                  -- is an exact construction endpoint, but only after stronger
                  -- checked-source and enclosing-consumer certificates have
                  -- had the opportunity to select the result.  In particular,
                  -- the paper's @g g@ source specialization constructs
                  -- @sigma-id@; the graph's temporary monomorphic view must
                  -- not append a later @[t]@ to that checked application.
                  --
                  -- When the result retains a local bounded argument, the
                  -- semantic endpoint is reached only after that Gamma has
                  -- been closed and consumed.  Keep that genuine outgoing
                  -- computation in the post-Gamma lane below.
                  guard (not retainedLocalBoundArgumentForResult)
                  guard (not semanticMetaFollowsConsumedLocalGamma)
                  resultTy <- applicationSemanticMetaResultTy
                  pure (Nothing, resultTy)
                directLambdaResultConstruction =
                  directLambdaApplicationResultConstructionFor
                    directResultBinderCanBeEliminated
                    graphResultTopologyTy
                    fAnn
                    (algSubtermGeneralizations algebraContext)
                directAdministrativeLambdaResultConstruction =
                  directAdministrativeLambdaApplicationResultConstructionFor
                    directResultBinderCanBeEliminated
                    (acSourceBinderRefs annotationContext)
                    fAnn
                    (algSubtermGeneralizations algebraContext)
                directAdministrativeLambdaSourceOwnerCompletion =
                  directAdministrativeLambdaApplicationSourceOwnerCompletionFor
                    fAnn
                    (algSubtermGeneralizations algebraContext)
                directLambdaResultExactConstruction = do
                  -- A prepared result packet reached transparently from the
                  -- direct lambda body is the positive construction of the
                  -- value returned by this application.  It is needed only
                  -- when no enclosing consumer already fixes the result; in
                  -- that case the graph result is checking topology and must
                  -- not monomorphize the packet before the lambda is built.
                  -- A syntactic identity has stronger evidence: its checked
                  -- argument is the complete returned value.  Selecting the
                  -- identity lambda's provisional body packet here can
                  -- specialize that value before the enclosing owner consumes
                  -- its own result construction.
                  guard (not (identityWrapperAnn fAnn))
                  guard (isNothing parentExactConstruction)
                  construction <- directLambdaResultConstruction
                  let resultTy =
                        directLambdaApplicationResultConstructionType
                          construction
                  pure (Nothing, resultTy, construction)
                directAdministrativeLambdaResultExactConstruction = do
                  -- A prepared administrative source-lambda packet is the
                  -- positive pre-child construction of this application's
                  -- codomain.  It does not assert that the nested Gamma has
                  -- already been consumed; instead it gives the function
                  -- child its complete incoming endpoint, and the checked
                  -- owner-final certificate below must confirm or refine it.
                  guard (not (identityWrapperAnn fAnn))
                  guard (isNothing parentExactConstruction)
                  resultTy <- directAdministrativeLambdaResultConstruction
                  pure (Nothing, resultTy)
                directLambdaResultBeforeUnreachableParent = do
                  construction <- directLambdaResultConstruction
                  let resultTy =
                        directLambdaApplicationResultConstructionType
                          construction
                  (_, parentResultTy) <- parentExactConstruction
                  guard
                    ( isNothing
                        ( constructExactInstantiation
                            edgeTypeEnvBeforeFunction
                            (scopedEndpointTypesAgree scopeContext)
                            resultTy
                            parentResultTy
                        )
                    )
                  pure (Nothing, resultTy, construction)
                directResultBinderCanBeEliminated ref =
                  isNothing
                    ( TypeCheck.lookupTypeBindingRef
                        ref
                        edgeTypeEnvBeforeFunction
                    )
                markApplicationExactConstruction authority (domainTy, resultTy) =
                    ( domainTy
                    , resultTy
                    , authority
                    )
                ordinaryApplicationExact =
                  fmap
                    ( markApplicationExactConstruction
                        OrdinaryApplicationExactConstruction
                    )
                directLambdaApplicationExact =
                  fmap
                    ( \(domainTy, resultTy, construction) ->
                        ( domainTy
                        , resultTy
                        , DirectLambdaApplicationExactConstruction construction
                        )
                    )
                directAdministrativeLambdaApplicationExact =
                  fmap
                    ( markApplicationExactConstruction
                        DirectAdministrativeLambdaApplicationExactConstruction
                    )
                identityApplicationExactConstruction = do
                  guard (identityWrapperAnn fAnn)
                  let endpoint =
                        fromMaybe
                          argSourceTy
                          identityApplicationArgumentEndpoint
                      reachableParentResult = do
                        target <- applicationConstructionResultForSource
                        _ <-
                          constructExactInstantiation
                            edgeTypeEnvBeforeFunction
                            (scopedEndpointTypesAgree scopeContext)
                            endpoint
                            target
                        pure target
                  pure
                    ( Just endpoint
                    , fromMaybe endpoint reachableParentResult
                    )
                inheritedAdministrativeLambdaApplicationExact = do
                  (construction, resultTy) <-
                    inheritedAdministrativeLambdaBodyResult
                  let authority
                        | administrativeResultAwaitsOwner construction resultTy =
                            DirectAdministrativeLambdaApplicationExactConstruction
                        | otherwise = OrdinaryApplicationExactConstruction
                  pure (Nothing, resultTy, authority)
                administrativeResultAwaitsOwner construction resultTy =
                  case resultTy of
                    TVarRef resultRef ->
                      any
                        ( \(ref, mbBound) ->
                            typeBinderRefsSameIdentity ref resultRef
                              && isNothing mbBound
                        )
                        (albcGammaBinders construction)
                    _ -> False
                applicationExactConstruction
                  | isJust identityApplicationExactConstruction =
                      ordinaryApplicationExact
                        identityApplicationExactConstruction
                  | applicationConstructionResultHasConcreteGammaBound
                  , isNothing directLambdaResultConstruction
                  , isNothing directAdministrativeLambdaResultConstruction =
                      -- A bounded administrative result is constructed in
                      -- two ordered steps: first build the EApp core at the
                      -- checked source specialization (the bound), then emit
                      -- Hyp for the enclosing Gamma around that completed
                      -- result below.  Letting the inherited administrative
                      -- endpoint win here would instead require the function
                      -- occurrence itself to transport, for example,
                      -- @Bool -> Bool@ to @Bool -> a@.  No xMLF occurrence
                      -- computation performs that arrow-codomain mapping.
                      -- A direct lambda packet is different: it positively
                      -- owns the complete result construction and must retain
                      -- the inherited Gamma endpoint while its lambda is
                      -- built.  Select the lower-bound-first ordering only
                      -- when neither direct construction certificate exists.
                      nonIdentityApplicationExactConstruction
                        <|> inheritedAdministrativeLambdaApplicationExact
                  | otherwise =
                      inheritedAdministrativeLambdaApplicationExact
                        <|> nonIdentityApplicationExactConstruction
                nonIdentityApplicationExactConstruction
                  | isJust directLocalArgumentBinder =
                      ordinaryApplicationExact
                        ( (\(_sourceDomain, sourceResult) ->
                              (Nothing, sourceResult)
                          )
                            <$> sourceExactConstruction
                        )
                        <|> ordinaryApplicationExact (do
                          -- A local argument binder that disappears from the
                          -- result still shares its abstract domain between
                          -- the two children, but it does not make an
                          -- independently constructed parent result
                          -- provisional.  Supplying that result now lets a
                          -- nested function child choose all of its source
                          -- quantifiers before EApp; the local Gamma is still
                          -- closed and consumed below.  Source specialization
                          -- may certify the codomain, but the local Gamma
                          -- declaration remains the exact shared domain; do
                          -- not replace it with the source bound before the
                          -- Figure 15.3.5 abstraction/instantiation bridge is
                          -- constructed.
                          guard (not retainedLocalBoundArgumentForResult)
                          parentExactConstructionForSource)
                        <|> ordinaryApplicationExact semanticMetaExactConstruction
                        <|> directAdministrativeLambdaApplicationExact
                          directAdministrativeLambdaResultExactConstruction
                        <|> directLambdaApplicationExact
                          directLambdaResultExactConstruction
                  | retainedLocalBoundArgumentForResult = Nothing
                  | applicationConstructionResultHasConcreteGammaBound =
                      ordinaryApplicationExact sourceExactConstruction
                        -- The enclosing application owns the Gamma binder,
                        -- while this child must be constructed at its direct
                        -- lower bound.  Reusing the unspecialized parent
                        -- result here would manufacture an abstract endpoint
                        -- and ask transport to repair it after EApp.
                        <|> ordinaryApplicationExact
                          parentExactConstructionForSource
                        <|> ordinaryApplicationExact semanticMetaExactConstruction
                        <|> directAdministrativeLambdaApplicationExact
                          directAdministrativeLambdaResultExactConstruction
                        <|> directLambdaApplicationExact
                          directLambdaResultExactConstruction
                  | otherwise =
                      -- A checked source specialization carries the exact
                      -- structural identities of its result.  It has already
                      -- been validated against the complete parent/frozen
                      -- result topology above, so retain that construction
                      -- before falling back to the graph-domain presentation.
                      -- Preferring the latter would discard the positive
                      -- source certificate and later ask an application edge
                      -- to transport structurally equal but identity-distinct
                      -- recursive types.
                      ordinaryApplicationExact sourceExactConstruction
                        -- The direct lambda packet constructs this EApp's
                        -- immediate codomain, including an exact N step for a
                        -- completed packet consumer when required.  If the
                        -- inherited endpoint is unreachable from that
                        -- codomain, it belongs to a later enclosing
                        -- constructor and cannot be pushed through this EApp.
                        <|> directLambdaApplicationExact
                          directLambdaResultBeforeUnreachableParent
                        <|> ordinaryApplicationExact parentExactConstruction
                        <|> ordinaryApplicationExact semanticMetaExactConstruction
                        <|> directAdministrativeLambdaApplicationExact
                          directAdministrativeLambdaResultExactConstruction
                        <|> directLambdaApplicationExact
                          directLambdaResultExactConstruction
            let
                applicationExactSourceDomain =
                  (\(domainTy, _, _) -> domainTy)
                    =<< applicationExactConstruction
                applicationExactResultTy =
                  (\(_, resultTy, _) -> resultTy)
                    <$> applicationExactConstruction
                applicationExactResultComesFromDirectLambda =
                  case applicationExactConstruction of
                    Just (_, _, DirectLambdaApplicationExactConstruction _) ->
                      True
                    Just
                      ( _,
                        _,
                        DirectAdministrativeLambdaApplicationExactConstruction
                        ) -> True
                    _ -> False
                applicationExactResultRequiresOwnerConfirmation =
                  case applicationExactConstruction of
                    Just
                      ( _,
                        _,
                        DirectAdministrativeLambdaApplicationExactConstruction
                        ) -> True
                    _ -> False
                applicationExactResultConstructsLambdaParamSpine =
                  case applicationExactConstruction of
                    Just
                      ( _,
                        _,
                        DirectLambdaApplicationExactConstruction
                          ( DirectLambdaEnclosingConsumerEqFreeResultConstruction
                              _
                            )
                        ) -> True
                    _ -> False
                identityApplicationEndpoint =
                  fromMaybe
                    argSourceTy
                    identityApplicationArgumentEndpoint
                resultTopologyTy =
                  fromMaybe
                    preparedTopologyTy
                    applicationExactResultTy
                  where
                    -- A checked constructor or active consumer owns the
                    -- application's exact result endpoint.  The generalized
                    -- scheme is only the fallback topology when no such
                    -- construction certificate exists; preferring its body
                    -- would make children construct a provisional graph result
                    -- and repair it with Hyp after EApp.
                    --
                    -- A retained local bounded argument is the exception:
                    -- its prepared result still depends on that same Gamma
                    -- binder.  Construct the application at the packet body,
                    -- close the binder, and consume its N step below.  Pushing
                    -- the enclosing annotation endpoint through the child
                    -- first would ask the function occurrence to turn the
                    -- flexible result into its lower bound, which is not an
                    -- xMLF computation.
                    preparedTopologyTy =
                      case (applicationBinders, applicationSchemeInfo) of
                        (_ : _, Just schemeInfo) ->
                          schemeBody (siScheme schemeInfo)
                        _ -> graphResultTopologyTy
                argumentEndpointAuthority
                  | identityWrapperAnn fAnn =
                      -- Use a direct requirement only after the checked
                      -- argument certifies its construction.  Otherwise the
                      -- identity constructor itself makes the checked source
                      -- the exact shared endpoint.
                      ExactTransportEndpoint identityApplicationEndpoint
                  | Just sourceDomain <- applicationExactSourceDomain =
                      ExactTransportEndpoint sourceDomain
                  | Just checkedTopology <- exactArgumentTopology =
                      ExactTransportEndpoint checkedTopology
                  | otherwise = ReplayComputedEndpoint
                applicationFunctionOwnerWithTopology =
                  applicationFunctionOwner
                    ++ unlines
                      [ "argument source="
                          ++ diagnosticElabType argSourceTy
                      , "argument annotation="
                          ++ show
                            ( annNode aAnn
                            , annExprReferenceKey aAnn
                            )
                      , "argument graph topology="
                          ++ diagnosticElabType argTopologyTy
                      , "argument source-projected topology="
                          ++ diagnosticElabType sourceProjectedTopology
                      , "argument source-binder routes="
                          ++ show
                            [ ( ref
                              , typeBinderRefNode ref
                                  >>= ( \node ->
                                          IntMap.lookup
                                            (getNodeId node)
                                            ( grSourceBinderRefs
                                                applicationRequirements
                                            )
                                      )
                              )
                            | ref <- freeTypeVarRefsType sourceProjectedTopology
                            ]
                    , "graph result topology="
                        ++ diagnosticElabType graphResultTopologyTy
                    , "graph result source-binder routes="
                        ++ show
                          [ ( ref
                            , typeBinderRefNode ref
                                >>= ( \node ->
                                        IntMap.lookup
                                          (getNodeId node)
                                          ( grSourceBinderRefs
                                              applicationRequirements
                                          )
                                    )
                            )
                          | ref <- freeTypeVarRefsType graphResultTopologyTy
                          ]
                      , "closed argument topology="
                          ++ diagnosticOptionalElabType closedArgumentTopology
                      , "bounded source application topology="
                          ++ diagnosticOptionalElabType
                            (fst <$> boundedSourceApplicationConstruction)
                      , "source-constructed argument topology="
                          ++ diagnosticOptionalElabType
                            sourceConstructedArgumentTopology
                      , "construction-closed argument topology="
                          ++ diagnosticOptionalElabType
                            constructionClosedArgumentTopology
                      , "local-bound argument topology="
                          ++ diagnosticOptionalElabType
                            localBoundArgumentTopology
                      , "source-declared argument topology="
                          ++ diagnosticOptionalElabType
                            sourceDeclaredArgumentTopology
                      , "ambient-bound argument topology="
                          ++ diagnosticOptionalElabType
                            ambientBoundArgumentTopology
                      , "active consumer ref="
                          ++ show
                            ( activeApplicationConsumerRef
                                <$> mbActiveConsumerAuthority
                            )
                      , "topology independent of active consumer="
                          ++ show
                            ( case sourceProjectedTopology of
                                TVarRef topologyRef ->
                                  argumentTopologyIndependentOfActiveConsumer
                                    topologyRef
                                _ -> False
                            )
                      , "ambient topology authority="
                          ++ show
                            ( case sourceProjectedTopology of
                                TVarRef topologyRef ->
                                  find
                                    ( typeBinderRefsSameIdentity topologyRef
                                        . agaExactRef
                                    )
                                    ( IntMap.elems
                                        applicationAmbientGammaAuthorities
                                    )
                                _ -> Nothing
                            )
                      , "argument after leading bounded N="
                          ++ diagnosticOptionalElabType boundedSourceArgument
                      , "function source scheme info="
                          ++ show
                            ( (\schemeInfo ->
                                ( map fst
                                    (schemeBinderRefs (siScheme schemeInfo))
                                , diagnosticElabType
                                    (schemeBody (siScheme schemeInfo))
                                )
                              )
                                <$> functionSourceSchemeInfo
                            )
                      , "bounded source result before validation="
                          ++ diagnosticOptionalElabType
                            (snd <$> boundedSourceApplicationConstruction)
                      , "application construction result="
                          ++ diagnosticOptionalElabType
                            applicationConstructionResultTy
                      , "source-normalized construction result="
                          ++ diagnosticOptionalElabType
                            applicationConstructionResultForSource
                      , "frozen graph result topology="
                          ++ diagnosticElabType frozenGraphResultTopologyTy
                      , "has frozen graph result topology="
                          ++ show hasFrozenResultTopology
                      , "argument topology retained by result="
                          ++ show
                            ( case sourceProjectedTopology of
                                TVarRef topologyRef ->
                                  applicationResultDependsOn topologyRef
                                _ -> False
                            )
                      , "selected exact argument topology="
                          ++ diagnosticOptionalElabType exactArgumentTopology
                      , "source-specialization argument topology="
                          ++ diagnosticElabType
                            sourceSpecializationArgumentTopology
                      ]
            argReplayComputation <-
              mkEdgeComputation
                algebraContext
                applicationActiveConsumerAuthority
                applicationEnclosingConsumerAuthority
                edgeTypeEnvBeforeFunction
                resolvedLookup
                typeBindingLookup
                constructionAliases
                (frozenEndpointTypes envForApplication)
                argumentReplayRequirements
                ( applicationArgumentOwner
                    ++ unlines
                      [ "argument source="
                          ++ diagnosticElabType argSourceTy
                      , "argument annotation="
                          ++ show
                            ( annNode aAnn
                            , annExprReferenceKey aAnn
                            )
                      , "argument graph topology="
                          ++ diagnosticElabType argTopologyTy
                      , "argument source-projected topology="
                          ++ diagnosticElabType sourceProjectedTopology
                      , "argument source scheme="
                          ++ show (siScheme <$> argumentSourceSchemeInfo)
                      , "argument source-declared topology="
                          ++ diagnosticOptionalElabType
                            sourceDeclaredArgumentTopology
                      , "argument selected exact topology="
                          ++ diagnosticOptionalElabType exactArgumentTopology
                      ]
                )
                ApplicationArgumentOccurrence
                argumentEndpointAuthority
                aAnn
                argSite
                argSourceTy
                argTopologyTy
            let -- Figure 15.3.5 feeds the function child the shared S'(n1)
                -- endpoint, not the argument's pre-edge source T(a2).  The
                -- retained topology owns its polymorphic structure (notably
                -- the sigma-id argument of the paper's g g), while the source
                -- sidecar projects free graph references into the checked
                -- occurrence's lexical identity domain.  The independently
                -- checked argument source proves that a polymorphic topology
                -- is a value endpoint; otherwise a leading graph forall may
                -- only be a stale generalized presentation of an occurrence
                -- whose computation has already eliminated it.
                expectedFunctionDomain =
                  case applicationExactSourceDomain of
                    Just sourceDomain -> sourceDomain
                    Nothing ->
                      case exactArgumentTopology of
                        Just exactTopology ->
                          -- The selector above returns only a source, Gamma, or
                          -- mediator-backed construction certificate.  Preserve
                          -- that identity-bearing endpoint verbatim: normalizing
                          -- an exact ambient variable through its flexible bound
                          -- can turn a lexical @c@ into Bottom and make a nested
                          -- application construct an arrow no source term has.
                          exactTopology
                        Nothing ->
                          let topologyDomain =
                                normalizeApplicationType sharedArgumentTopology
                              computedDomain =
                                normalizeApplicationType
                                  (edgeComputationTarget argReplayComputation)
                              checkedArgumentSource =
                                normalizeApplicationType argSourceTy
                           in case (topologyDomain, computedDomain) of
                                (_, _)
                                  | topologyContainsBottom topologyDomain ->
                                      computedDomain
                                (_, _)
                                  | applicationTypesAgree
                                      checkedArgumentSource
                                      topologyDomain ->
                                      topologyDomain
                                (TForallRef {}, TForallRef {}) ->
                                  topologyDomain
                                (TForallRef {}, _) ->
                                  -- A leading quantifier is a value-level endpoint
                                  -- only when the argument occurrence computation
                                  -- actually constructs one.  The graph topology may
                                  -- retain a generalized presentation that the
                                  -- checked argument has already eliminated.
                                  computedDomain
                                _ -> topologyDomain
                expectedFunctionTy =
                  -- The retained application topology is sufficient to check
                  -- the recursively constructed function child even when no
                  -- parent owns an exact result certificate.  This remains a
                  -- 'CheckingExpectedTerm' below: only
                  -- 'applicationExactResultTy' may confer exact construction
                  -- authority from either the parent consumer or the checked
                  -- source application.  Without either certificate the graph
                  -- codomain remains checking-only guidance.
                  Just
                    ( TArrow
                        expectedFunctionDomain
                        resultTopologyTy
                    )
                -- A zero-local graph result whose only installed declaration
                -- is still Bottom records where the application will publish
                -- its result; it does not yet prove what the function child
                -- returns.  In the absence of an active consumer, a direct
                -- packet, or an exact construction alias, keep that result as
                -- checking topology until the checked lambda owner publishes
                -- its codomain.  Promoting it here would ask the child to
                -- construct an arbitrary polymorphic body at an unbounded
                -- variable before the body has supplied the variable's bound.
                applicationExactResultAwaitsCheckedFunction =
                  case applicationExactConstruction of
                    Just
                      ( _,
                        exactResultTy,
                        OrdinaryApplicationExactConstruction
                        ) ->
                          null applicationBinders
                            && isNothing mbActiveConsumerAuthority
                            && not (null exactResultRefs)
                            && all isUnconstructedGraphResult exactResultRefs
                          where
                            exactResultRefs =
                              freeTypeVarRefsType exactResultTy
                    _ -> False
                  where
                    isUnconstructedGraphResult ref =
                      case typeBinderRefNode ref of
                        Nothing -> False
                        Just node ->
                          IntMap.notMember
                            (getNodeId node)
                            applicationAuthorityAliases
                            && maybe
                              True
                              ( \boundTy ->
                                  operationalEndpointTypesAgree
                                    boundTy
                                    TBottom
                                    || universalBottomEliminator boundTy
                              )
                              (typeBindingLookup ref)
                expectedFunctionEndpoint =
                  if identityWrapperAnn fAnn
                    then
                      -- The identity constructor's checked argument,
                      -- transported through its direct edge, is the complete
                      -- proof for both sides of its arrow.
                      -- A parent result expectation belongs to the outgoing
                      -- application computation; pushing it into the lambda
                      -- would make the function child and the identity branch
                      -- below use different construction authorities.
                      Just
                        ( ExactConstructionExpectedTerm
                            ( TArrow
                                identityApplicationEndpoint
                                identityApplicationEndpoint
                            )
                        )
                    else
                      case applicationExactResultTy of
                        Just exactResultTy ->
                          let functionTy =
                                TArrow expectedFunctionDomain exactResultTy
                           in Just
                                ( if applicationExactResultAwaitsCheckedFunction
                                    then CheckingExpectedTerm functionTy
                                    else if applicationExactResultRequiresOwnerConfirmation
                                    then
                                      fromMaybe
                                        (CheckingExpectedTerm functionTy)
                                        ( do
                                            ( frozenOperatedType
                                              , certifiedResultTy
                                              ) <-
                                                directAdministrativeLambdaSourceOwnerCompletion
                                            guard
                                              ( scopedEndpointTypesAgree
                                                  scopeContext
                                                  certifiedResultTy
                                                  exactResultTy
                                              )
                                            pure
                                              ( AdministrativeLambdaBodyExpectedTerm
                                                  ( administrativeLambdaBodyConstructionFromScheme
                                                      ( schemeFromType
                                                          frozenOperatedType
                                                      )
                                                  )
                                                  functionTy
                                              )
                                        )
                                    else
                                      -- A parent/source/argument certificate
                                      -- already owns the complete Figure
                                      -- 15.3.5 endpoint before the function
                                      -- child is entered.
                                      ExactConstructionExpectedTerm functionTy
                                )
                        Nothing -> CheckingExpectedTerm <$> expectedFunctionTy
            envForFunction <-
              publishFrozenEndpoint
                envForApplicationAfterArgument
                (edgeComputationFrozenEndpoint argReplayComputation)
            let directConstructionDomain
                  | identityWrapperAnn fAnn =
                      Just identityApplicationEndpoint
                  | otherwise =
                      applicationExactSourceDomain
                        <|> exactArgumentTopology
                functionEnv =
                  instantiationSourceEnv
                    envForFunction
                    ApplicationFunctionOccurrence
                    fAnn
                    expectedFunctionEndpoint
                functionEnvWithDirectParam =
                  case directConstructionDomain of
                    Just exactDomain ->
                      withDirectConstructedLambdaParamType
                        exactDomain
                        fAnn
                        functionEnv
                    Nothing -> functionEnv
            functionChildEnv <-
              case
                  ( applicationExactResultConstructsLambdaParamSpine
                  , applicationExactResultTy
                  )
                of
                  (True, Just exactResultTy) ->
                    withCertifiedConstructedLambdaParamTypes
                      (TArrow expectedFunctionDomain exactResultTy)
                      fAnn
                      functionEnvWithDirectParam
                  _ -> pure functionEnvWithDirectParam
            funElaborationRaw <-
              case
                  elabDetailed
                    fOut
                    functionChildEnv
                of
                  Right elaboration -> pure elaboration
                  Left cause ->
                    Left
                      ( ValidationFailed
                          [ "application function failed under its constructed result plan"
                          , "  application: " ++ show appNodeId
                          , "  application binders: " ++ show applicationBinders
                          , "  application aliases: " ++ show applicationAliases
                          , "  graph result topology: "
                              ++ diagnosticElabType graphResultTopologyTy
                          , "  source result endpoint: "
                              ++ diagnosticOptionalElabType
                                sourceConstructedResultTy
                          , "  parent exact construction result: "
                              ++ diagnosticOptionalElabType
                                applicationConstructionResultTy
                          , "  selected exact construction result: "
                              ++ diagnosticOptionalElabType
                                applicationExactResultTy
                          , "  selected result topology: "
                              ++ diagnosticElabType resultTopologyTy
                          , "  function result packet specialization: "
                              ++ show
                                ( subtermGeneralizationExactConsumerSpecialization
                                    . subtermResultOwnershipPacket
                                    <$> subtermResultOwnershipFor
                                      fAnn
                                      (algSubtermGeneralizations algebraContext)
                                )
                          , "  function result packet: "
                              ++ show
                                ( ( \packet ->
                                      ( siScheme
                                          ( subtermGeneralizationSchemeInfo
                                              packet
                                          )
                                      , siScheme
                                          ( subtermGeneralizationOperatedSchemeInfo
                                              packet
                                          )
                                      , subtermGeneralizationGammaBoundScheme
                                          packet
                                      , subtermGeneralizationConsumerAuthority
                                          packet
                                      , subtermGeneralizationGammaAuthority packet
                                      , subtermGeneralizationSourceLambdaParameter
                                          packet
                                      , subtermGeneralizationSourceOwnerConsumerCompletion
                                          packet
                                      )
                                  )
                                    . subtermResultOwnershipPacket
                                    <$> subtermResultOwnershipFor
                                      fAnn
                                      (algSubtermGeneralizations algebraContext)
                                )
                          , "  direct lambda body result packet: "
                              ++ show
                                ( case fAnn of
                                    ALam _ _ _ _ body _ _ ->
                                      ( ( \ownership ->
                                            ( subtermResultOwnershipHasTransparentPath
                                                ownership
                                            , subtermGeneralizationConsumerAuthority
                                                ( subtermResultOwnershipPacket
                                                    ownership
                                                )
                                            , subtermGeneralizationGammaAuthority
                                                ( subtermResultOwnershipPacket
                                                    ownership
                                                )
                                            , subtermGeneralizationOpaqueResultConstruction
                                                ( subtermResultOwnershipPacket
                                                    ownership
                                                )
                                            , subtermGeneralizationSourceOwnerConsumerCompletion
                                                ( subtermResultOwnershipPacket
                                                    ownership
                                                )
                                            )
                                        )
                                          <$> subtermResultOwnershipFor
                                            body
                                            (algSubtermGeneralizations algebraContext)
                                      )
                                    _ -> Nothing
                                )
                          , "  function annotation: " ++ show fAnn
                          , "  expected function type: "
                              ++ diagnosticOptionalElabType expectedFunctionTy
                          , "  expected function endpoint: "
                              ++ diagnosticExpectedTermEndpoint
                                expectedFunctionEndpoint
                          , "  active consumer: "
                              ++ show mbActiveConsumerAuthority
                          , "  checked argument source: "
                              ++ diagnosticElabType argSourceTy
                          , "  exact argument topology: "
                              ++ diagnosticOptionalElabType exactArgumentTopology
                          , "  function source scheme: "
                              ++ show (siScheme <$> functionSourceSchemeInfo)
                          , "  cause: " ++ show cause
                          ]
                      )
            let funElaborationBeforeAmbientCompletion =
                  renameElaboratedTermBinderRefPayloads
                    (applicationSourceOccurrenceRenamesFor funElaborationRaw)
                    funElaborationRaw
            envForApplicationAfterFunctionRefinements <-
              installElaboratedBodyConsumerRefinements
                funElaborationBeforeAmbientCompletion
                envForFunction
            (funElaboration, envForApplicationAfterChildren) <-
              installElaboratedOwnerFinalAmbientConstruction
                ( IntMap.restrictKeys
                    (acSourceBinderRefs annotationContext)
                    (acDirectSourceBinderKeys annotationContext)
                )
                funElaborationBeforeAmbientCompletion
                envForApplicationAfterFunctionRefinements
            let funTerm = elaboratedTerm funElaboration
                completedDirectLambdaApplicationResultTy = do
                  (lambdaScope, lambdaEdge, lambdaNode) <-
                    case fAnn of
                      ALam _ _ _ scope _ edge node ->
                        Just (scope, edge, node)
                      _ -> Nothing
                  certificate <-
                    elaboratedOwnerFinalConstruction funElaboration
                  guard
                    ( ofcOwner certificate
                        == LocalGammaOwner
                          { lgoConstructor = LocalLambdaGamma
                          , lgoBoundaryEdge = lambdaEdge
                          , lgoTermNode = lambdaNode
                          , lgoScope = GenRef lambdaScope
                          }
                    )
                  let constructedScheme =
                        schemeFromType (ofcConstructedType certificate)
                  resultTy <-
                    case schemeBody constructedScheme of
                      TArrow _ codomainTy -> Just codomainTy
                      _ -> Nothing
                  case resultTy of
                    TVarRef resultRef ->
                      locallyCompletedResult resultRef constructedScheme certificate
                        <|> certifiedAmbientResult resultRef certificate
                    _ -> pure resultTy
                  where
                    locallyCompletedResult resultRef constructedScheme certificate = do
                      (_, Just completedBound) <-
                        find
                          (typeBinderRefsSameIdentity resultRef . fst)
                          (schemeBinderRefs constructedScheme)
                      guard
                        ( any
                            (typeBinderRefsSameIdentity resultRef . fst)
                            (ofcLocallyEmittedBinders certificate)
                        )
                      pure (tyToElab completedBound)

                    -- A direct lambda can construct its codomain at an exact
                    -- ambient Gamma declaration owned by an enclosing
                    -- application.  That declaration must remain the shared
                    -- Figure 15.3.5 result endpoint; replacing it by its lower
                    -- bound would ask the function edge to run the impossible
                    -- reverse coercion from the flexible result to the bound.
                    -- Join the owner-final use, its unique declaration
                    -- authority, and the installed child Gamma before
                    -- publishing the endpoint.  The result type alone is not
                    -- evidence.
                    certifiedAmbientResult resultRef certificate = do
                      guard
                        ( any
                            (typeBinderRefsSameIdentity resultRef)
                            (ofcUsedAmbientBinderRefs certificate)
                        )
                      [authority] <-
                        pure
                          [ candidate
                          | candidate <-
                              ofcAmbientDeclarationAuthorities certificate
                          , typeBinderRefsSameIdentity
                              resultRef
                              (agaExactRef candidate)
                          ]
                      installedBound <-
                        typeBindingLookupAfterChildren resultRef
                      guard
                        ( scopedEndpointTypesAgree
                            scopeContext
                            installedBound
                            (agaBound authority)
                        )
                      pure (TVarRef resultRef)
                completedDirectLambdaResultBeforeUnreachableSelected = do
                  -- A syntactic identity is constructed at its checked
                  -- argument endpoint.  Its lambda owner may retain a
                  -- source-annotation binder identity that is intentionally
                  -- fresh from the graph occurrence; that owner view is not
                  -- a competing application-result certificate.
                  guard (not (identityWrapperAnn fAnn))
                  completedResultTy <-
                    completedDirectLambdaApplicationResultTy
                  selectedResultTy <- applicationExactResultTy
                  guard
                    ( isNothing
                        ( constructExactInstantiation
                            edgeTypeEnvAfterChildren
                            exactLambdaEndpointTypesAgree
                            completedResultTy
                            selectedResultTy
                        )
                    )
                  pure completedResultTy
                confirmedDirectLambdaApplicationResultTy = do
                  -- The static body packet is only a prospective endpoint.
                  -- Keep it after the function child is built only when the
                    -- checked owner-final construction positively instantiates
                    -- to that exact arrow; otherwise the outgoing application
                    -- must use the endpoint actually constructed by the child.
                  guard applicationExactResultComesFromDirectLambda
                  exactResultTy <- applicationExactResultTy
                  constructedFunctionTy <-
                    ofcConstructedType
                      <$> elaboratedOwnerFinalConstruction funElaboration
                  _ <-
                    constructExactInstantiation
                      edgeTypeEnvAfterChildren
                      exactLambdaEndpointTypesAgree
                      constructedFunctionTy
                      ( TArrow
                          expectedFunctionDomain
                          exactResultTy
                      )
                  pure exactResultTy
                certifiedFunctionEndpointCompletionResult = do
                  certificate <-
                    elaboratedOwnerFinalConstruction funElaboration
                  completion <- ofcExactEndpointCompletion certificate
                  guard
                    ( eecOwner completion == ofcOwner certificate
                        || eecOwner completion
                          `elem` ofcTransparentResultOwners certificate
                    )
                  guard
                    ( scopedEndpointTypesAgree
                        scopeContext
                        (eecCompletedEndpoint completion)
                        (ofcConstructedType certificate)
                    )
                  sourceResultTy <- applicationExactResultTy
                  let sourceScheme =
                        schemeFromType (eecSourceEndpoint completion)
                      completedScheme =
                        schemeFromType (eecCompletedEndpoint completion)
                  (sourceDomainTy, certifiedSourceResultTy) <-
                    case schemeBody sourceScheme of
                      TArrow domainTy resultTy ->
                        Just (domainTy, resultTy)
                      _ -> Nothing
                  (completedDomainTy, completedResultTy) <-
                    case schemeBody completedScheme of
                      TArrow domainTy resultTy ->
                        Just (domainTy, resultTy)
                      _ -> Nothing
                  guard
                    ( scopedEndpointTypesAgree
                        scopeContext
                        sourceDomainTy
                        expectedFunctionDomain
                        && scopedEndpointTypesAgree
                          scopeContext
                          completedDomainTy
                          expectedFunctionDomain
                        && scopedEndpointTypesAgree
                          scopeContext
                          certifiedSourceResultTy
                          sourceResultTy
                    )
                  guard
                    ( not
                        ( scopedEndpointTypesAgree
                            scopeContext
                            sourceResultTy
                            completedResultTy
                        )
                    )
                  pure completedResultTy
                applicationExactResultTyAfterFunction =
                  certifiedFunctionEndpointCompletionResult
                    <|> if applicationExactResultComesFromDirectLambda
                      then
                        completedDirectLambdaApplicationResultTy
                          <|> confirmedDirectLambdaApplicationResultTy
                      else
                        case inheritedAdministrativeLambdaBodyResult of
                          Just _ ->
                            applicationExactResultTy
                              <|> completedDirectLambdaResultBeforeUnreachableSelected
                          Nothing ->
                            completedDirectLambdaResultBeforeUnreachableSelected
                              <|> applicationExactResultTy
                resultTopologyTyAfterFunction =
                  fromMaybe
                    resultTopologyTy
                    applicationExactResultTyAfterFunction
                childSourceOuterEnv =
                  hideLocallyEmittedTypeBinders
                    applicationValueOwnedBinderRefs
                    envForApplicationAfterChildren
                edgeTypeEnvAfterChildren =
                  typeCheckEnvFrom childSourceOuterEnv
                resolvedLookupAfterChildren details =
                  ebSchemeInfo
                    <$> lookupEnvBindingForDetails
                      details
                      envForApplicationAfterChildren
                typeBindingLookupAfterChildren ref =
                  snd
                    <$> find
                      (typeBinderRefsSameIdentity ref . fst)
                      ( Map.toList
                          (envTypeBindings envForApplicationAfterChildren)
                      )
                constructionAliasesAfterChildren =
                  envConstructionGammaAliases
                    envForApplicationAfterChildren
                childLocalGammaCertificates =
                  elaboratedLocalGammaConstructionCertificates funElaboration
                    ++ elaboratedLocalGammaConstructionCertificates argElaboration
                childCompilerExactResultBoundCertificates =
                  elaboratedCompilerExactResultBoundCertificates funElaboration
                    ++ elaboratedCompilerExactResultBoundCertificates argElaboration
                childBodyConsumerBoundRefinements =
                  concatMap elaboratedBodyConsumerBoundRefinements
                    [funElaboration, argElaboration]
                childLambdaParamBoundaryCertificates =
                  concatMap
                    ( maybe
                        []
                        ofcLambdaParamBoundaryCertificates
                        . elaboratedOwnerFinalConstruction
                    )
                    [funElaboration, argElaboration]
                childOwnerAmbientDeclarationAuthorities =
                  concatMap
                    ( maybe
                        []
                        ofcAmbientDeclarationAuthorities
                        . elaboratedOwnerFinalConstruction
                    )
                    [funElaboration, argElaboration]
                childAuthoritativeAmbientDeclarations =
                  concatMap
                    ( maybe
                        []
                        ofcAuthoritativeAmbientDeclarations
                        . elaboratedOwnerFinalConstruction
                    )
                    [funElaboration, argElaboration]
                childUsedSourceBinderAuthorities =
                  IntMap.unions
                    ( mapMaybe
                        ( fmap ofcUsedSourceBinderAuthorities
                            . elaboratedOwnerFinalConstruction
                        )
                        [funElaboration, argElaboration]
                    )
                childLocallyEmittedBinderRefs =
                  concatMap
                    locallyEmittedBinderRefs
                    [funElaboration, argElaboration]
                locallyEmittedBinderRefs elaboration =
                  maybe
                    []
                    ofcLocallyEmittedBinderRefs
                    (elaboratedOwnerFinalConstruction elaboration)
                    ++ [ ref
                       | certificate <-
                           elaboratedLocalGammaConstructionCertificates
                             elaboration
                       , (ref, _) <-
                           localGammaEmittedBinders
                             (lgccConstruction certificate)
                       ]
                applicationValueOwnedBinderRefs =
                  foldl'
                    appendValueOwnedBinder
                    childLocallyEmittedBinderRefs
                    ( identityArgumentValueBinderRefs
                        ++ childLexicallyBoundBinderRefs
                    )
                childLexicallyBoundBinderRefs =
                  concatMap
                    (lexicallyBoundTypeBinderRefsTerm . elaboratedTerm)
                    [funElaboration, argElaboration]
                identityArgumentValueBinderRefs
                  | identityWrapperAnn fAnn =
                      map fst
                        (schemeBinderRefs (schemeFromType argSourceTy))
                  | otherwise = []
                appendValueOwnedBinder refs ref
                  | any (typeBinderRefsSameIdentity ref) refs = refs
                  | otherwise = refs ++ [ref]
            (funTermForTopology, funComputation, argComputation) <-
              if identityWrapperAnn fAnn
                then do
                  -- A syntactic identity wrapper is valid at the exact
                  -- checked direct-argument endpoint.  A replay-only flexible target
                  -- such as @alpha >= Int@ is an outgoing edge obligation,
                  -- not the value endpoint of @(\\x. x) 1@.  Constructing both
                  -- children at @alpha@ would manufacture a local
                  -- @Lambda(alpha >= Int)@ whose binder disappears from the
                  -- rigid root scheme.  The identity constructor instead
                  -- discharges that edge at its producer and builds the
                  -- application directly at @Int@.
                  argComputation <-
                    mkEdgeComputation
                      algebraContext
                      applicationActiveConsumerAuthority
                      applicationEnclosingConsumerAuthority
                      edgeTypeEnvAfterChildren
                      resolvedLookupAfterChildren
                      typeBindingLookupAfterChildren
                      constructionAliasesAfterChildren
                      (frozenEndpointTypes envForApplicationAfterChildren)
                      argumentReplayRequirements
                      (applicationArgumentOwner ++ "identity exact-source lane\n")
                      ApplicationArgumentOccurrence
                      (ExactTransportEndpoint identityApplicationEndpoint)
                      aAnn
                      argSite
                      argSourceTy
                      argTopologyTy
                  let argumentTargetTy = edgeComputationTarget argComputation
                      funTermForTopology =
                        alignLeadingLambdasToType
                          (TArrow argumentTargetTy argumentTargetTy)
                          funTerm
                  funSourceTy <-
                    requireType
                      edgeTypeEnvAfterChildren
                      "function source"
                      funTermForTopology
                  funComputation <-
                    case
                        mkEdgeComputation
                          algebraContext
                          applicationActiveConsumerAuthority
                          applicationEnclosingConsumerAuthority
                          edgeTypeEnvAfterChildren
                          resolvedLookupAfterChildren
                          typeBindingLookupAfterChildren
                          constructionAliasesAfterChildren
                          (frozenEndpointTypes envForApplicationAfterChildren)
                          functionReplayRequirements
                          applicationFunctionOwnerWithTopology
                          ApplicationFunctionOccurrence
                          ( ExactApplicationFunctionEndpoint
                              argumentTargetTy
                              argumentTargetTy
                          )
                          fAnn
                          funSite
                          funSourceTy
                          (TArrow argumentTargetTy argumentTargetTy)
                      of
                      Right computation -> pure computation
                      Left cause ->
                        failApplication
                          [ "identity function edge construction failed"
                          , "raw function term=" ++ show funTerm
                          , "aligned function term=" ++ show funTermForTopology
                          , "aligned function source=" ++ show funSourceTy
                          , "function owner construction="
                              ++ show
                                ( elaboratedOwnerFinalConstruction
                                    funElaboration
                                )
                          , "function body-consumer refinements="
                              ++ show
                                ( elaboratedBodyConsumerBoundRefinements
                                    funElaboration
                                )
                          , "function expected endpoint="
                              ++ show
                                (envExpectedTermEndpoint functionChildEnv)
                          , "exact identity endpoint="
                              ++ show
                                (TArrow argumentTargetTy argumentTargetTy)
                          , "cause=" ++ show cause
                          ]
                  pure (funTermForTopology, funComputation, argComputation)
                else do
                  -- Figure 15.3.5 constructs both occurrence computations
                  -- independently and requires their endpoints to share one
                  -- alpha.  A reduced environment presentation can leave one
                  -- replay endpoint in the graph-source domain.  Transport
                  -- exactly that side; a monomorphic side cannot be changed,
                  -- so the construction normally has a unique direction.
                  let argRaw = argReplayComputation
                      argumentTarget = edgeComputationTarget argRaw
                  funSourceTy0 <-
                    requireType
                      edgeTypeEnvAfterChildren
                      "function source"
                      funTerm
                  (funTermForSource, funSourceTy) <-
                    applicationFunctionSource
                      edgeTypeEnvAfterChildren
                      funTerm
                      funSourceTy0
                  let functionEndpointAuthority =
                        case applicationExactResultTyAfterFunction of
                          Just resultEndpoint ->
                            -- The checked argument computation and the parent
                            -- result certificate jointly determine the whole
                            -- function arrow.  Construct against that arrow
                            -- directly; result-only or domain-only inference
                            -- can otherwise leave a later source quantifier
                            -- outside the arrow (for example @b@ in
                            -- @__io_bind@).
                            ExactApplicationFunctionEndpoint
                              expectedFunctionDomain
                              resultEndpoint
                          Nothing -> ReplayComputedEndpoint
                      functionEndpointAt argumentEndpoint =
                        case applicationExactResultTyAfterFunction of
                          Just resultEndpoint ->
                            -- Domain transport must retain the result
                            -- certificate that selected 'funRaw'.  Rebuilding
                            -- only from the argument endpoint can otherwise
                            -- specialize the source domain correctly while
                            -- reverting its codomain to the provisional graph
                            -- result.
                            ExactApplicationFunctionEndpoint
                              argumentEndpoint
                              resultEndpoint
                          Nothing ->
                            ApplicationFunctionEndpoint argumentEndpoint
                  funRaw <-
                    case
                        mkEdgeComputation
                          algebraContext
                          applicationActiveConsumerAuthority
                          applicationEnclosingConsumerAuthority
                          edgeTypeEnvAfterChildren
                          resolvedLookupAfterChildren
                          typeBindingLookupAfterChildren
                          constructionAliasesAfterChildren
                          (frozenEndpointTypes envForApplicationAfterChildren)
                          functionReplayRequirements
                          applicationFunctionOwnerWithTopology
                          ApplicationFunctionOccurrence
                          functionEndpointAuthority
                          fAnn
                          funSite
                          funSourceTy
                          (TArrow sharedArgumentTopology resultTopologyTyAfterFunction)
                      of
                        Right computation -> pure computation
                        Left cause ->
                          failApplication
                            [ "function occurrence failed at its selected exact endpoint"
                            , "function source term=" ++ show funTermForSource
                            , "function source type=" ++ show funSourceTy
                            , "function endpoint authority="
                                ++ show functionEndpointAuthority
                            , "function owner-final construction="
                                ++ show
                                  ( elaboratedOwnerFinalConstruction
                                      funElaboration
                                  )
                            , "direct lambda result construction="
                                ++ show
                                  ( directLambdaApplicationResultConstructionFor
                                      directResultBinderCanBeEliminated
                                      graphResultTopologyTy
                                      fAnn
                                      (algSubtermGeneralizations algebraContext)
                                  )
                            , "direct lambda body ownership="
                                ++ show
                                  ( case fAnn of
                                      ALam _ _ _ _ body _ _ -> do
                                        ownership <-
                                          subtermResultOwnershipFor
                                            body
                                            ( algSubtermGeneralizations
                                                algebraContext
                                            )
                                        let packet =
                                              subtermResultOwnershipPacket
                                                ownership
                                        pure
                                          ( subtermResultOwnershipHasTransparentPath
                                              ownership
                                          , subtermResultOwnershipLambdaNode
                                              ownership
                                          , siScheme
                                              ( subtermGeneralizationSchemeInfo
                                                  packet
                                              )
                                          , siScheme
                                              ( subtermGeneralizationConsumerConstructionSchemeInfo
                                                  packet
                                              )
                                          , siScheme
                                              ( subtermGeneralizationOperatedSchemeInfo
                                                  packet
                                              )
                                          , subtermGeneralizationExactConsumerSpecialization
                                              packet
                                          , subtermGeneralizationAdministrativeLambdaResultConstruction
                                              packet
                                          )
                                      _ -> Nothing
                                  )
                            , "cause=" ++ show cause
                            ]
                  let sourceFunctionScheme = schemeFromType funSourceTy
                      sourceFunctionBinderRefs =
                        map fst (schemeBinderRefs sourceFunctionScheme)
                      sourceClosedFunctionDomain =
                        case schemeBody sourceFunctionScheme of
                          TArrow sourceDomain _ ->
                            let projectedDomain =
                                  resolveSourceBinderAliasesInType
                                    (scopeTypeBinderIdentityRepresentative scopeContext)
                                    applicationSourceBinderRefs
                                    sourceDomain
                                dependsOnSourceBinder =
                                  any
                                    ( \freeRef ->
                                        any
                                          (typeBinderRefsSameIdentity freeRef)
                                          sourceFunctionBinderRefs
                                    )
                                    (freeTypeVarRefsType projectedDomain)
                             in if
                                  not dependsOnSourceBinder
                                    && null (freeTypeVarRefsType projectedDomain)
                                  then Just projectedDomain
                                  else Nothing
                          _ -> Nothing
                      -- A closed source domain is stronger than a graph replay
                      -- presentation only when both occurrence computations
                      -- can be constructed at that exact endpoint and no
                      -- complete result endpoint is already available.  This
                      -- is a positive source/edge certificate: it specializes
                      -- monomorphic consumers such as @useInt id@ without
                      -- manufacturing a local Gamma, while @g g@ is excluded
                      -- because its source domain depends on its source forall.
                      --
                      -- With a complete result certificate, reconstructing
                      -- from the domain alone is strictly weaker: it can
                      -- default a result-only source binder to Bottom and
                      -- overwrite the exact computation already selected
                      -- above (for example @mix[Bool]@ with @mix[Bottom]@).
                      sourceClosedConstruction = do
                        guard (isNothing applicationExactResultTyAfterFunction)
                        closedDomain <- sourceClosedFunctionDomain
                        argumentComputation <-
                          either
                            (const Nothing)
                            Just
                            ( mkEdgeComputation
                                algebraContext
                                applicationActiveConsumerAuthority
                                applicationEnclosingConsumerAuthority
                                edgeTypeEnvAfterChildren
                                resolvedLookupAfterChildren
                                typeBindingLookupAfterChildren
                                constructionAliasesAfterChildren
                                (frozenEndpointTypes envForApplicationAfterChildren)
                                argumentReplayRequirements
                                (applicationArgumentOwner ++ "closed source-domain lane\n")
                                ApplicationArgumentOccurrence
                                (ExactTransportEndpoint closedDomain)
                                aAnn
                                argSite
                                argSourceTy
                                sharedArgumentTopology
                            )
                        functionComputation <-
                          either
                            (const Nothing)
                            Just
                            ( mkEdgeComputation
                                algebraContext
                                applicationActiveConsumerAuthority
                                applicationEnclosingConsumerAuthority
                                edgeTypeEnvAfterChildren
                                resolvedLookupAfterChildren
                                typeBindingLookupAfterChildren
                                constructionAliasesAfterChildren
                                (frozenEndpointTypes envForApplicationAfterChildren)
                                functionReplayRequirements
                                applicationFunctionOwnerWithTopology
                                ApplicationFunctionOccurrence
                                (ApplicationFunctionEndpoint closedDomain)
                                fAnn
                                funSite
                                funSourceTy
                                (TArrow sharedArgumentTopology resultTopologyTyAfterFunction)
                            )
                        case edgeComputationTarget functionComputation of
                          TArrow functionDomain _
                            | applicationTypesAgree functionDomain closedDomain
                            , applicationTypesAgree
                                (edgeComputationTarget argumentComputation)
                                closedDomain ->
                                Just
                                  ( funTermForSource
                                  , functionComputation
                                  , argumentComputation
                                  )
                          _ -> Nothing
                  case edgeComputationTarget funRaw of
                    _
                      | Just construction <- sourceClosedConstruction ->
                          pure construction
                    TArrow functionDomain _ ->
                      if applicationTypesAgree functionDomain argumentTarget
                        then pure (funTermForSource, funRaw, argRaw)
                        else do
                          let argumentAtFunction =
                                do
                                  computation <-
                                    mkEdgeComputation
                                      algebraContext
                                      applicationActiveConsumerAuthority
                                      applicationEnclosingConsumerAuthority
                                      edgeTypeEnvAfterChildren
                                      resolvedLookupAfterChildren
                                      typeBindingLookupAfterChildren
                                      constructionAliasesAfterChildren
                                      (frozenEndpointTypes envForApplicationAfterChildren)
                                      argumentReplayRequirements
                                      (applicationArgumentOwner ++ "function-domain reconciliation lane\n")
                                      ApplicationArgumentOccurrence
                                      (ExactTransportEndpoint functionDomain)
                                      aAnn
                                      argSite
                                      argSourceTy
                                      sharedArgumentTopology
                                  if applicationTypesAgree (edgeComputationTarget computation) functionDomain
                                    then pure computation
                                    else
                                      Left
                                        ( PhiInvariantError
                                            "argument transport did not reach the function domain"
                                        )
                              functionAtArgument =
                                do
                                  computation <-
                                    mkEdgeComputation
                                      algebraContext
                                      applicationActiveConsumerAuthority
                                      applicationEnclosingConsumerAuthority
                                      edgeTypeEnvAfterChildren
                                      resolvedLookupAfterChildren
                                      typeBindingLookupAfterChildren
                                      constructionAliasesAfterChildren
                                      (frozenEndpointTypes envForApplicationAfterChildren)
                                      functionReplayRequirements
                                      applicationFunctionOwnerWithTopology
                                      ApplicationFunctionOccurrence
                                      ( functionEndpointAt
                                          (normalizeApplicationType argumentTarget)
                                      )
                                      fAnn
                                      funSite
                                      funSourceTy
                                      (TArrow sharedArgumentTopology resultTopologyTyAfterFunction)
                                  case edgeComputationTarget computation of
                                    TArrow domainTy _
                                      | applicationTypesAgree domainTy argumentTarget -> pure computation
                                    _ ->
                                      Left
                                        ( PhiInvariantError
                                            "function transport did not reach the argument endpoint"
                                        )
                              functionAtLeadingArgumentEndpoint =
                                exposeLeadingArgumentEndpoint argRaw
                                where
                                  exposeLeadingArgumentEndpoint argumentComputation =
                                    case edgeComputationTarget argumentComputation of
                                      currentTarget@TForallRef {} -> do
                                        let elimination =
                                              applicationArgumentEliminationFor
                                                currentTarget
                                            composedInstantiation =
                                              composeInst
                                                ( edgeComputationInstantiation
                                                    argumentComputation
                                                )
                                                elimination
                                        exposedTarget <-
                                          case
                                              TypeCheck.checkInstantiation
                                                edgeTypeEnvAfterChildren
                                                currentTarget
                                                elimination
                                            of
                                              Right ty -> pure ty
                                              Left err ->
                                                Left
                                                  ( PhiInvariantError
                                                      ( unlines
                                                          [ "leading application argument elimination is not admissible"
                                                          , "argument endpoint=" ++ show currentTarget
                                                          , "elimination=" ++ show elimination
                                                          , "typecheck=" ++ show err
                                                          ]
                                                      )
                                                  )
                                        composedTarget <-
                                          case
                                              TypeCheck.checkInstantiation
                                                edgeTypeEnvAfterChildren
                                                ( edgeComputationSource
                                                    argumentComputation
                                                )
                                                composedInstantiation
                                            of
                                              Right ty -> pure ty
                                              Left err ->
                                                Left
                                                  ( PhiInvariantError
                                                      ( unlines
                                                          [ "composed application argument elimination is not admissible"
                                                          , "argument source="
                                                              ++ show
                                                                ( edgeComputationSource
                                                                    argumentComputation
                                                                )
                                                          , "instantiation="
                                                              ++ show composedInstantiation
                                                          , "typecheck=" ++ show err
                                                          ]
                                                      )
                                                  )
                                        if
                                            applicationTypesAgree
                                              composedTarget
                                              exposedTarget
                                          then pure ()
                                          else
                                            Left
                                              ( PhiInvariantError
                                                  "composed argument elimination has the wrong endpoint"
                                              )
                                        let exposedArgumentComputation =
                                              argumentComputation
                                                { edgeComputationInstantiation =
                                                    composedInstantiation
                                                , edgeComputationTarget =
                                                    exposedTarget
                                                }
                                            constructFunction = do
                                              computation <-
                                                mkEdgeComputation
                                                  algebraContext
                                                  applicationActiveConsumerAuthority
                                                  applicationEnclosingConsumerAuthority
                                                  edgeTypeEnvAfterChildren
                                                  resolvedLookupAfterChildren
                                                  typeBindingLookupAfterChildren
                                                  constructionAliasesAfterChildren
                                                  (frozenEndpointTypes envForApplicationAfterChildren)
                                                  functionReplayRequirements
                                                  applicationFunctionOwnerWithTopology
                                                  ApplicationFunctionOccurrence
                                                  (functionEndpointAt exposedTarget)
                                                  fAnn
                                                  funSite
                                                  funSourceTy
                                                  (TArrow sharedArgumentTopology resultTopologyTyAfterFunction)
                                              case edgeComputationTarget computation of
                                                TArrow domainTy _
                                                  | applicationTypesAgree
                                                      domainTy
                                                      exposedTarget ->
                                                      pure
                                                        ( computation
                                                        , exposedArgumentComputation
                                                        )
                                                _ ->
                                                  Left
                                                    ( PhiInvariantError
                                                        "function transport did not reach the exposed argument endpoint"
                                                    )
                                        case constructFunction of
                                          Right constructed -> pure constructed
                                          Left cause ->
                                            case exposedTarget of
                                              TForallRef {} ->
                                                exposeLeadingArgumentEndpoint
                                                  exposedArgumentComputation
                                              _ -> Left cause
                                      _ ->
                                        Left
                                          ( PhiInvariantError
                                              "argument endpoint has no leading forall to eliminate"
                                          )
                              functionMatchesTopology =
                                applicationTypesAgree
                                  functionDomain
                                  sharedArgumentTopology
                              argumentMatchesTopology =
                                applicationTypesAgree
                                  argumentTarget
                                  sharedArgumentTopology
                              closedConsumerResult =
                                applicationExactResultTyAfterFunction
                              resultMatchesClosedConsumer computation =
                                case (closedConsumerResult, edgeComputationTarget computation) of
                                  (Just expectedTy, TArrow _ codomainTy) ->
                                    applicationTypesAgree codomainTy expectedTy
                                  _ -> False
                          case (argumentAtFunction, functionAtArgument) of
                            (Right argComputation, Left _) ->
                              pure (funTermForSource, funRaw, argComputation)
                            (Left _, Right funComputation) ->
                              pure (funTermForSource, funComputation, argRaw)
                            (Right argComputation, Right funComputation)
                              | resultMatchesClosedConsumer funRaw
                                  && not (resultMatchesClosedConsumer funComputation) ->
                                  pure (funTermForSource, funRaw, argComputation)
                              | resultMatchesClosedConsumer funComputation
                                  && not (resultMatchesClosedConsumer funRaw) ->
                                  pure (funTermForSource, funComputation, argRaw)
                              | functionMatchesTopology && not argumentMatchesTopology ->
                                  pure (funTermForSource, funRaw, argComputation)
                              | argumentMatchesTopology && not functionMatchesTopology ->
                                  pure (funTermForSource, funComputation, argRaw)
                              | otherwise ->
                                  failApplication
                                    [ "application endpoint transport is ambiguous",
                                      "function domain=" ++ show functionDomain,
                                      "argument endpoint=" ++ show argumentTarget,
                                      "topology domain=" ++ show sharedArgumentTopology
                                    ]
                            (Left argumentError, Left functionError) ->
                              case functionAtLeadingArgumentEndpoint of
                                Right (funComputation, argComputation) ->
                                  pure
                                    ( funTermForSource
                                    , funComputation
                                    , argComputation
                                    )
                                Left leadingEndpointError ->
                                  failApplication
                                    [ "neither occurrence computation can be transported to the shared application domain",
                                      "function domain=" ++ show functionDomain,
                                      "argument endpoint=" ++ show argumentTarget,
                                      "projected argument topology=" ++ show sourceProjectedTopology,
                                      "exact argument topology=" ++ show exactArgumentTopology,
                                      "source-constructed application=" ++ show sourceConstructedApplication,
                                      "function source scheme=" ++ show (siScheme <$> functionSourceSchemeInfo),
                                      "application construction result=" ++ show applicationConstructionResultTy,
                                      "application source result=" ++ show applicationConstructionResultForSource,
                                      "application result bindings="
                                        ++ show
                                          [ (ref, typeBindingLookupAfterChildren ref)
                                          | ref <-
                                              maybe
                                                []
                                                freeTypeVarRefsType
                                                applicationConstructionResultTy
                                          ],
                                      "argument transport=" ++ show argumentError,
                                      "function transport=" ++ show functionError,
                                      "leading argument endpoint transport="
                                        ++ show leadingEndpointError
                                    ]
                    replayTarget -> do
                      -- A non-arrow function replay has not yet consumed the
                      -- source scheme's leading quantifiers.  Its body still
                      -- owns the prospective arrow domain.  Construct the
                      -- argument at that domain when possible, then instantiate
                      -- the function at the same endpoint.  This matters for a
                      -- vacuous source quantifier: replay may introduce
                      -- @forall a. alpha@ on the argument edge, but eliminating
                      -- the function's @a@ exposes @alpha@, not that quantified
                      -- presentation.
                      let sourceScheme = schemeFromType funSourceTy
                          sourceBinderRefs = map fst (schemeBinderRefs sourceScheme)
                          domainDependsOnSourceBinder sourceDomain =
                            any
                              ( \freeRef ->
                                  any
                                    (typeBinderRefsSameIdentity freeRef)
                                    sourceBinderRefs
                              )
                              (freeTypeVarRefsType sourceDomain)
                          -- Figure 15.3.5 requires the function and argument
                          -- computations to meet at one value endpoint.  A
                          -- let-generalized argument can retain a leading
                          -- flexible forall after edge replay, while the
                          -- function's value domain has an arrow (or another
                          -- rigid head) below its own source quantifiers.  The
                          -- whole forall is not such a value endpoint: expose
                          -- the first endpoint that the source domain can
                          -- specialize to by constructing the paper's N
                          -- computation on the argument occurrence.
                          --
                          -- This selection is structural.  It does not try a
                          -- term, type-check it, and repair the result: exact
                          -- source-scheme inference decides whether the
                          -- current endpoint is consumable, and each otherwise
                          -- admissible step is the leading-forall elimination
                          -- rule itself.
                          exposeArgumentEndpoint sourceDomain = go
                            where
                              sourceBinders = schemeBinderRefs sourceScheme

                              go computation
                                | Just _ <-
                                    inferInstAppArgsFromSchemeRefsExact
                                      sourceBinders
                                      (schemeBody sourceScheme)
                                      ( TArrow
                                          (edgeComputationTarget computation)
                                          resultTopologyTyAfterFunction
                                      )
                                      <|> inferInstAppArgsFromSchemeRefsExact
                                        sourceBinders
                                        sourceDomain
                                        (edgeComputationTarget computation) =
                                    pure computation
                                | TForallRef {} <- edgeComputationTarget computation = do
                                    eliminatedTarget <-
                                      case
                                          TypeCheck.checkInstantiation
                                            edgeTypeEnvAfterChildren
                                            (edgeComputationTarget computation)
                                            InstElim
                                        of
                                          Left err ->
                                            failApplication
                                              [ "canonical application argument elimination is not admissible",
                                                "source domain=" ++ show sourceDomain,
                                                "argument endpoint="
                                                  ++ show (edgeComputationTarget computation),
                                                "typecheck=" ++ show err
                                              ]
                                          Right ty -> pure ty
                                    let eliminatedComputation =
                                          computation
                                            { edgeComputationInstantiation =
                                                composeInst
                                                  (edgeComputationInstantiation computation)
                                                  InstElim,
                                              edgeComputationTarget = eliminatedTarget
                                            }
                                    composedTarget <-
                                      case
                                          TypeCheck.checkInstantiation
                                            edgeTypeEnvAfterChildren
                                            (edgeComputationSource computation)
                                            (edgeComputationInstantiation eliminatedComputation)
                                        of
                                          Left err ->
                                            failApplication
                                              [ "canonical application argument computation does not apply",
                                                "source domain=" ++ show sourceDomain,
                                                "argument source="
                                                  ++ show (edgeComputationSource computation),
                                                "argument instantiation="
                                                  ++ show
                                                    ( edgeComputationInstantiation
                                                        eliminatedComputation
                                                    ),
                                                "typecheck=" ++ show err
                                              ]
                                          Right ty -> pure ty
                                    if applicationTypesAgree composedTarget eliminatedTarget
                                      then go eliminatedComputation
                                      else
                                        failApplication
                                          [ "canonical application argument computation has the wrong endpoint",
                                            "source domain=" ++ show sourceDomain,
                                            "constructed endpoint=" ++ show composedTarget,
                                            "expected endpoint=" ++ show eliminatedTarget
                                          ]
                                | otherwise =
                                    failApplication
                                      [ "application argument has no endpoint consumable by the function source domain",
                                        "source domain=" ++ show sourceDomain,
                                        "argument endpoint="
                                          ++ show (edgeComputationTarget computation)
                                      ]
                          constructAtArgument argComputation = do
                            let constructedArgumentTarget =
                                  edgeComputationTarget argComputation
                            funComputation <-
                              mkEdgeComputation
                                algebraContext
                                applicationActiveConsumerAuthority
                                applicationEnclosingConsumerAuthority
                                edgeTypeEnvAfterChildren
                                resolvedLookupAfterChildren
                                typeBindingLookupAfterChildren
                                constructionAliasesAfterChildren
                                (frozenEndpointTypes envForApplicationAfterChildren)
                                functionReplayRequirements
                                applicationFunctionOwnerWithTopology
                                ApplicationFunctionOccurrence
                                (functionEndpointAt constructedArgumentTarget)
                                fAnn
                                funSite
                                funSourceTy
                                (TArrow sharedArgumentTopology resultTopologyTyAfterFunction)
                            case edgeComputationTarget funComputation of
                              TArrow domainTy _
                                | applicationTypesAgree domainTy constructedArgumentTarget ->
                                    pure (funTermForSource, funComputation, argComputation)
                                | otherwise ->
                                    failApplication
                                      [ "function computation did not retain the constructed argument endpoint",
                                        "function domain=" ++ show domainTy,
                                        "argument destination=" ++ show constructedArgumentTarget
                                      ]
                              transportedTarget ->
                                failApplication
                                  [ "function computation with a non-arrow replay endpoint did not transport to the argument endpoint",
                                    "function site=" ++ show funSite,
                                    "argument site=" ++ show argSite,
                                    "replay endpoint=" ++ show replayTarget,
                                    "transported endpoint=" ++ show transportedTarget,
                                    "argument replay endpoint=" ++ show argumentTarget,
                                    "application topology endpoint=" ++ show sharedArgumentTopology
                                  ]
                          constructArgumentAtExactEndpoint endpoint =
                            mkEdgeComputation
                              algebraContext
                              applicationActiveConsumerAuthority
                              applicationEnclosingConsumerAuthority
                              edgeTypeEnvAfterChildren
                              resolvedLookupAfterChildren
                              typeBindingLookupAfterChildren
                              constructionAliasesAfterChildren
                              (frozenEndpointTypes envForApplicationAfterChildren)
                              argumentReplayRequirements
                              (applicationArgumentOwner ++ "non-arrow exact-endpoint lane\n")
                              ApplicationArgumentOccurrence
                              (ExactTransportEndpoint endpoint)
                              aAnn
                              argSite
                              argSourceTy
                              sharedArgumentTopology
                      argComputation <-
                        case schemeBody sourceScheme of
                          TArrow sourceDomain _
                            | domainDependsOnSourceBinder sourceDomain
                            , Just _ <-
                                inferInstAppArgsFromSchemeRefsExact
                                  (schemeBinderRefs sourceScheme)
                                  sourceDomain
                                  (edgeComputationTarget argRaw) ->
                                -- The occurrence edge already publishes the
                                -- shared Gamma endpoint (for example Unit ->
                                -- alpha via Hyp).  Retain that computation
                                -- before considering the concrete source.
                                pure argRaw
                            | domainDependsOnSourceBinder sourceDomain
                            , Just _ <-
                                inferInstAppArgsFromSchemeRefsExact
                                  (schemeBinderRefs sourceScheme)
                                  sourceDomain
                                  argSourceTy ->
                                -- The checked occurrence itself determines
                                -- the source binder arguments.  Construct at
                                -- that exact endpoint instead of asking a
                                -- still-bare graph variable to recover them.
                                constructArgumentAtExactEndpoint argSourceTy
                            | domainDependsOnSourceBinder sourceDomain ->
                                exposeArgumentEndpoint sourceDomain argRaw
                            | otherwise ->
                                constructArgumentAtExactEndpoint sourceDomain
                          _ ->
                            failApplication
                              [ "function source scheme does not expose an arrow body",
                                "function source=" ++ show funSourceTy
                              ]
                      constructAtArgument argComputation
            let closesArgumentRequirement requirement =
                  instantiationSiteEdgeId argSite
                    `elem` NonEmpty.toList (rgbEdgeIds requirement)
                    && case
                        IntMap.lookup
                          (getNodeId (rgbExteriorNode requirement))
                          edgeLocalAliases
                      of
                        Nothing -> False
                        Just routedRef ->
                          case
                              find
                                (typeBinderRefsSameIdentity routedRef . fst)
                                edgeLocalBinders
                            of
                              Just (_, mbCurrentBound) ->
                                sourceEndpointClosesApplicationGammaBound
                                  (edgeComputationTarget argComputation)
                                  ( resolveSourceBinderAliasesInTypeExcept
                                      Set.empty
                                      (scCanonical scopeContext)
                                      applicationSourceBinderRefs
                                      (maybe TBottom tyToElab mbCurrentBound)
                                  )
                              Nothing -> False
                identityArgumentClosesDirectBound =
                  identityWrapperAnn fAnn
                    && any
                      closesArgumentRequirement
                      (grRequiredGammaBinders edgeLocalRequirements)
                constructedDirectExactRequirementEdges
                  | isJust identityApplicationArgumentEndpoint
                      || identityArgumentClosesDirectBound =
                      [ ( edgeId
                        , if edgeId == instantiationSiteEdgeId argSite
                            then
                              Just
                                ( RootEdgeExactOperated
                                    (edgeComputationTarget argComputation)
                                )
                            else mbEndpoint
                        )
                      | (edgeId, mbEndpoint) <-
                          constructionDirectExactRequirementEdges
                      ]
                  | otherwise =
                      constructionDirectExactRequirementEdges
                constructedDirectRequirementEdges =
                  [ (edgeId, rootEdgeExactEndpointType <$> mbEndpoint)
                  | (edgeId, mbEndpoint) <-
                      constructedDirectExactRequirementEdges
                  ]
            -- The checked argument source can still carry leading bounded
            -- foralls that the direct occurrence eliminates.  Its completed
            -- edge computation is therefore the first exact certificate for
            -- S(operated).  Rebuild the edge requirement with that tagged
            -- endpoint before final Gamma construction; updating only the
            -- binder and then repairing a stale requirement at claim time
            -- would lose the Figure 15.3.5 construction invariant.
            constructedEdgeLocalRequirementsBeforeNested0 <-
              case
                  generalizationRequirementsForRootExactEdgesInConstruction
                    applicationActiveConsumerKeys
                    ( envGeneralizationAmbientTypeBinderRefs
                        env
                    )
                    applicationAmbientGammaAuthorities
                    (scopeTypeBinderIdentityRepresentative scopeContext)
                    (scCanonical scopeContext)
                    (scGaParents scopeContext)
                    (scPresolutionView scopeContext)
                    applicationEdgeArtifacts
                    applicationSourceBinderRefs
                    (algSubtermGeneralizations algebraContext)
                    constructedDirectExactRequirementEdges
                of
                  Right requirements -> pure requirements
                  Left cause ->
                    Left
                      ( ValidationFailed
                          [ "application constructed direct-edge Gamma planning failed"
                          , "  application: " ++ show appNodeId
                          , "  owner: " ++ show applicationOwner
                          , "  constructed direct edges: "
                              ++ show constructedDirectExactRequirementEdges
                          , "  cause: " ++ show cause
                          ]
                      )
            let constructedEdgeLocalRequirementsAtOccurrence =
                  placeCurrentGammaRequirementsAt
                    applicationScope
                    constructedEdgeLocalRequirementsBeforeNested0
            (_, constructedEdgeLocalRequirements0) <-
              case mbNestedArgumentCertificate of
                Just (nestedOwner, nestedCertificate) ->
                  inheritNestedApplicationResidualReplayAuthority
                    nestedOwner
                    nestedCertificate
                    applicationRequirementsAtOccurrence
                    constructedEdgeLocalRequirementsAtOccurrence
                Nothing ->
                  pure
                    ( applicationRequirementsAtOccurrence
                    , constructedEdgeLocalRequirementsAtOccurrence
                    )
            let constructedEdgeLocalRequirements =
                  retainOwnedEdgeLocalRequirements
                    constructedEdgeLocalRequirements0
            constructedOwnerSelectedBinders <-
              refineApplicationGammaBindersAtExactDirectEndpoints
                CheckedDirectEndpoint
                (scCanonical scopeContext)
                applicationSourceBinderRefs
                constructedDirectRequirementEdges
                constructedEdgeLocalRequirements
                ownerSelectedAliases
                ownerSelectedBinders
            constructedEdgeLocalBinders <-
              refineApplicationGammaBindersAtExactDirectEndpoints
                CheckedDirectEndpoint
                (scCanonical scopeContext)
                applicationSourceBinderRefs
                constructedDirectRequirementEdges
                constructedEdgeLocalRequirements
                edgeLocalAliases
                edgeLocalBinders
            constructedApplicationBinders <-
              mergeConstructionBinderBoundsByProvenance
                "application Gamma after direct-edge construction"
                ( map
                    (\binder -> (ConstructionLocalGammaBound, binder))
                    constructedOwnerSelectedBinders
                    ++ map
                      (\binder -> (ConstructionExactEndpoint, binder))
                      constructedEdgeLocalBinders
                )
            edgeComputationBinders <-
              mergeConstructionBinderSources
                "application occurrence computations"
                (edgeComputationEnclosingBinders funComputation)
                (edgeComputationEnclosingBinders argComputation)
            applicationConstructionBinders0 <-
              mergeConstructionBinderSources
                "application Gamma and result-polymorphic source"
                constructedApplicationBinders
                edgeComputationBinders
            let applicationConstructionBindersForChildRefinements
                  | identityWrapperAnn fAnn =
                      -- The identity application consumes its argument as one
                      -- exact polymorphic value.  Binders already published
                      -- by that checked child belong to the value's type, not
                      -- to the enclosing application's Gamma.  The child's
                      -- owner-final certificate is the construction proof;
                      -- do not rediscover this distinction from the final
                      -- type shape.
                      [ binder
                      | binder@(ref, _) <- applicationConstructionBinders0
                      , not
                          ( any
                              (typeBinderRefsSameIdentity ref)
                              applicationValueOwnedBinderRefs
                          )
                      ]
                  | otherwise = applicationConstructionBinders0
                envForApplicationConstruction0 =
                  hideLocallyEmittedTypeBinders
                    applicationValueOwnedBinderRefs
                    ( extendEnvTypeScope
                        edgeComputationBinders
                        ( extendEnvTypeScopeWithAliases
                            applicationAliases
                            constructedApplicationBinders
                            envForApplicationAfterChildren
                        )
                    )
            ( applicationConstructionBindersAfterArgumentRefinements
              , envForApplicationConstructionAfterArgumentRefinements
              , ambientEnvAfterArgumentRefinements
              ) <-
              installElaboratedBodyConsumerConstruction
                applicationOwner
                []
                argElaboration
                applicationConstructionBindersForChildRefinements
                envForApplicationConstruction0
                envForApplicationAfterChildren
            ( applicationConstructionBindersAfterChildRefinements
              , envForApplicationConstructionWithChildRefinements
              , _
              ) <-
              installElaboratedBodyConsumerConstruction
                applicationOwner
                []
                funElaboration
                applicationConstructionBindersAfterArgumentRefinements
                envForApplicationConstructionAfterArgumentRefinements
                ambientEnvAfterArgumentRefinements
            let envForApplicationConstruction =
                  -- Descendant refinement certificates may complete a
                  -- declaration which is local to a child value.  The
                  -- refinement is valid inside that child, but must not
                  -- re-open the same identity around the child's ETyAbs at the
                  -- parent application boundary.
                  hideLocallyEmittedTypeBinders
                    applicationValueOwnedBinderRefs
                    envForApplicationConstructionWithChildRefinements
                inheritedBodyConsumerDeclaration ref =
                  any
                    ( \certificate ->
                        bodyConsumerBoundRefinementTargetsAny
                          [ref]
                          certificate
                          && not
                            ( bodyConsumerBoundRefinementEmittedBy
                                applicationOwner
                                certificate
                            )
                    )
                    childBodyConsumerBoundRefinements
                applicationConstructionBinders =
                  [ binder
                  | binder@(ref, _) <-
                      applicationConstructionBindersAfterChildRefinements
                  , not (inheritedBodyConsumerDeclaration ref)
                  ]
                edgeTypeEnvForApplication =
                  typeCheckEnvFrom envForApplicationConstruction
            (parameterTy, resultTy) <-
              case edgeComputationTarget funComputation of
                TArrow domainTy codomainTy -> pure (domainTy, codomainTy)
                targetTy ->
                  failApplication
                    [ "function edge destination is not an arrow",
                      "destination=" ++ show targetTy
                    ]
            let funApplied =
                  instantiate funTermForTopology funComputation
                argApplied = instantiate argTermForTopology argComputation
                applicationBoundaryRecoveryRenames =
                  lambdaParamBoundaryRecoveryRenames
                    ( envLambdaParamBoundaryCertificates
                        envForApplicationConstruction
                    )
                    ( envConstructionBinderRenames
                        envForApplicationConstruction
                    )
            if
                applicationTypesAgree
                  parameterTy
                  (edgeComputationTarget argComputation)
              then pure ()
              else
                failApplication
                  [ "function domain does not equal argument edge destination",
                    "function source=" ++ show (edgeComputationSource funComputation),
                    "function instantiation=" ++ show (edgeComputationInstantiation funComputation),
                    "function domain=" ++ show parameterTy,
                    "argument source=" ++ show (edgeComputationSource argComputation),
                    "argument instantiation=" ++ show (edgeComputationInstantiation argComputation),
                    "argument destination=" ++ show (edgeComputationTarget argComputation)
                  ]
            let app =
                  renameTermTypeBinderRefPayloads
                    applicationBoundaryRecoveryRenames
                    (EApp funApplied argApplied)
                resultTyAtBoundary =
                  applyTypeVarRefRenames
                    applicationBoundaryRecoveryRenames
                    resultTy
            checkedTy <-
              requireType
                edgeTypeEnvForApplication
                ( unlines
                    [ "constructed application"
                    , "application node=" ++ show appNodeId
                    , "function instantiation="
                        ++ diagnosticShown
                          (edgeComputationInstantiation funComputation)
                    , "argument instantiation="
                        ++ diagnosticShown
                          (edgeComputationInstantiation argComputation)
                    , "argument source="
                        ++ diagnosticElabType
                          (edgeComputationSource argComputation)
                    , "argument target="
                        ++ diagnosticElabType
                          (edgeComputationTarget argComputation)
                    ]
                )
                app
            if operationalEndpointTypesAgree checkedTy resultTyAtBoundary
              then pure ()
              else
                failApplication
                  [ "type checker disagrees with the constructed edge topology",
                    "checked type=" ++ diagnosticElabType checkedTy,
                    "function codomain="
                      ++ diagnosticElabType resultTyAtBoundary
                  ]
            -- Figure 15.3.5 publishes @Lambda(Gamma_g)@ around the complete
            -- application construction.  When the exact result computation
            -- is a Hyp naming one of those local declarations, emit it before
            -- selecting the surviving Gamma spine.  The Hyp then makes its
            -- declaration live and the surrounding ETyAbs binds it.  Applying
            -- the same computation after Gamma completion would instead let
            -- the declaration be classified as consumed and leave a free Hyp
            -- in the exported term.
            ( applicationBeforeGammaCompletion
              , applicationTypeBeforeGammaCompletion
              , preGammaApplicationResultConstruction
              ) <-
                case applicationConstructionResultTy of
                  Just constructionResultTy
                    | not
                        ( null
                            [ localRef
                            | (localRef, _) <- applicationConstructionBinders
                            , any
                                (typeBinderRefsSameIdentity localRef)
                                (freeTypeVarRefsType constructionResultTy)
                            ]
                        ) ->
                      case
                          constructExactInstantiation
                            edgeTypeEnvForApplication
                            operationalEndpointTypesAgree
                            checkedTy
                            constructionResultTy
                        of
                        Just InstId ->
                          pure
                            ( app
                            , checkedTy
                            , Just
                                CheckedResultEndpointConstruction
                                  { crecOwner = applicationOwner
                                  , crecSourceType = checkedTy
                                  , crecComputation = InstId
                                  , crecTargetType = constructionResultTy
                                  }
                            )
                        Just resultInstantiation -> do
                          let constructedApplication =
                                ETyInst app resultInstantiation
                          constructedTy <-
                            case
                                typeCheckConstructedOpenTermWithBaseEnv
                                  edgeTypeEnvForApplication
                                  constructedApplication
                              of
                                Right ty -> pure ty
                                Left err ->
                                  failApplication
                                    [ "pre-Gamma application result computation is not typable"
                                    , "application source=" ++ show checkedTy
                                    , "construction result="
                                        ++ show constructionResultTy
                                    , "instantiation="
                                        ++ show resultInstantiation
                                    , "typecheck=" ++ show err
                                    ]
                          unless
                            ( operationalEndpointTypesAgree
                                constructedTy
                                constructionResultTy
                            )
                            ( failApplication
                                [ "pre-Gamma application result computation reached the wrong endpoint"
                                , "expected=" ++ show constructionResultTy
                                , "actual=" ++ show constructedTy
                                ]
                            )
                          pure
                            ( constructedApplication
                            , constructedTy
                            , Just
                                CheckedResultEndpointConstruction
                                  { crecOwner = applicationOwner
                                  , crecSourceType = checkedTy
                                  , crecComputation = resultInstantiation
                                  , crecTargetType = constructedTy
                                  }
                            )
                        Nothing -> pure (app, checkedTy, Nothing)
                  _ -> pure (app, checkedTy, Nothing)
            let identityApplicationForwardsConstructedArgument =
                  case elaboratedOwnerFinalConstruction argElaboration of
                    Just argumentCertificate ->
                      identityWrapperAnn fAnn
                        && edgeComputationInstantiation funComputation == InstId
                        && edgeComputationInstantiation argComputation == InstId
                        && operationalEndpointTypesAgree
                          (ofcConstructedType argumentCertificate)
                          checkedTy
                    Nothing -> False
            completionBinders <-
              case
                  ( envApplicationSourceOccurrence env
                  , identityApplicationForwardsConstructedArgument
                  )
                of
                  (Just _, False) ->
                    -- An application used as an outer edge source must retain
                    -- its prepared Gamma, including positional vacuous
                    -- binders.  A syntactic identity whose two occurrence
                    -- computations are both identity is different: the
                    -- argument's owner-final certificate already constructs
                    -- the complete returned value.  In that exact lane only
                    -- the binders live in the term, result, or their bounds
                    -- belong to this application boundary.
                    orderConstructionGammaBinders
                      "application source occurrence"
                      applicationConstructionBinders
                      checkedTy
                  _ ->
                    constructionGammaCompletionBinders
                      applicationConstructionBinders
                      applicationBeforeGammaCompletion
                      applicationTypeBeforeGammaCompletion
            let completedApplication =
                  foldr
                    (\(ref, mbBound) body -> ETyAbsRef ref mbBound body)
                    applicationBeforeGammaCompletion
                    completionBinders
                expectedApplicationType =
                  foldr
                    (\(ref, mbBound) body -> TForallRef ref mbBound body)
                    applicationTypeBeforeGammaCompletion
                    completionBinders
                completedApplicationOuterEnv =
                  hideLocallyEmittedTypeBinders
                    (map fst completionBinders)
                    envForApplicationConstruction
                completedApplicationTypeEnv =
                  typeCheckEnvFrom completedApplicationOuterEnv
                typeCheckApplicationConstruction term =
                  typeCheckConstructedOpenTermWithBaseEnv
                    ( restrictTypeCheckEnvToFreeTermBindings
                        term
                        completedApplicationTypeEnv
                    )
                    term
            completedType <-
              case
                  typeCheckApplicationConstruction completedApplication
                of
                Right ty -> pure ty
                Left err ->
                  failApplication
                    [ "completed Figure 15.3.5 application is not typable in its outer environment",
                      "application Γ scheme=" ++ show (siScheme <$> applicationSchemeInfo),
                      "completion binders=" ++ show completionBinders,
                      "application construction binders="
                        ++ show applicationConstructionBinders,
                      "edge-computation binders="
                        ++ show edgeComputationBinders,
                      "value-owned binder refs="
                        ++ show applicationValueOwnedBinderRefs,
                      "function computation="
                        ++ show
                          ( edgeComputationSource funComputation
                          , edgeComputationInstantiation funComputation
                          , edgeComputationTarget funComputation
                          , edgeComputationEnclosingBinders funComputation
                          ),
                      "argument computation="
                        ++ show
                          ( edgeComputationSource argComputation
                          , edgeComputationInstantiation argComputation
                          , edgeComputationTarget argComputation
                          , edgeComputationEnclosingBinders argComputation
                          ),
                      "completed term=" ++ show completedApplication,
                      "typecheck=" ++ show err
                    ]
            if applicationTypesAgree completedType expectedApplicationType
              then pure ()
              else
                failApplication
                  [ "completed Figure 15.3.5 application does not have its prepared scheme"
                  , "checked type=" ++ show completedType
                  , "prepared type=" ++ show expectedApplicationType
                  ]
            let sourceCompletionEndpoint =
                  case preGammaApplicationResultConstruction of
                    Just _ -> Nothing
                    Nothing ->
                      ( do
                          guard
                            ( retainedLocalBoundArgumentForResult
                                || isJust directLocalArgumentTopology
                            )
                          sourceFunctionSchemeInfo <- functionSourceSchemeInfo
                          sourceSchemeResultAt
                            edgeTypeEnvAfterChildren
                            argSourceTy
                            applicationConstructionResultTy
                            sourceFunctionSchemeInfo
                      )
                        <|> do
                          -- A direct lambda has no environment binding from
                          -- which to recover a source scheme.  When its checked
                          -- application result is already exact and the local
                          -- bounded argument does not occur there, that exact
                          -- result is the positive endpoint for the same N
                          -- elimination.  'consumeCompletedGammaAtBounds' still
                          -- validates every eliminated binder and the final
                          -- endpoint with the xMLF type checker.
